NAVER_BLOG_ENDPOINT = "https://openapi.naver.com/v1/search/blog.json"

# 상품 메타데이터(쇼핑 검색 API 결과)를 키워드/상품 기준으로 간단히 메모리 캐시
METADATA_CACHE_TTL_HOURS = 6
PRODUCT_METADATA_CACHE: dict[str, tuple[datetime, ProductMetadata]] = {}


def _infer_smartstore_mall_name(product_url: str | None) -> str | None:
    """
    smartstore.naver.com/<mall>/products/<id> 형태에서 mall 을 추출한다.
    (UI의 '판매처' 표시 안정성을 위해 URL에서 best-effort로 유추)
    """
    try:
        u = urlparse(str(product_url or ""))
        host = (u.netloc or "").lower()
        if host.endswith("smartstore.naver.com"):
            parts = [p for p in (u.path or "").split("/") if p]
            if len(parts) >= 2 and parts[1] == "products":
                return parts[0]
            if len(parts) >= 1:
                return parts[0]
    except Exception:
        pass
    return None


def _normalize_product_title(title: str | None, *, mall_name: str | None = None) -> str | None:
    text = str(title or "").strip()
    if not text:
        return None

    mall = str(mall_name or "").strip()
    if mall:
        mall_variants: list[str] = []
        for candidate in (mall, mall.replace(" ", "")):
            candidate = str(candidate or "").strip()
            if candidate and candidate not in mall_variants:
                mall_variants.append(candidate)
        for variant in mall_variants:
            sep_pattern = r"(?:\s*[:|/\-·]\s*|\s+)"
            text = re.sub(
                rf"{sep_pattern}{re.escape(variant)}\s*$",
                "",
                text,
                flags=re.IGNORECASE,
            ).strip()

    generic_tail = re.match(r"^(?P<head>.+?)\s*[:|]\s*(?P<tail>[A-Za-z가-힣\s]{2,14})\s*$", text)
    if generic_tail:
        head = str(generic_tail.group("head") or "").strip()
        tail = str(generic_tail.group("tail") or "").strip()
        if head and len(head) >= 8 and tail and not re.search(r"\d", tail):
            text = head

    text = re.sub(r"\s+", " ", text).strip()
    return text or None


def _extract_og_metadata_from_html(*, html_text: str) -> tuple[str | None, str | None]:
    """
    HTML에서 og:title / og:image 를 best-effort로 추출한다.
    - 외부 의존성(BeautifulSoup) 없이 regex로만 처리(가볍고 안정적)
    """
    text = html_text or ""

    def pick(prop: str) -> str | None:
        m = re.search(
            rf'<meta[^>]+property=[\'"]{re.escape(prop)}[\'"][^>]+content=[\'"]([^\'"]+)[\'"]',
            text,
            flags=re.IGNORECASE,
        )
        if m:
            return unescape(m.group(1)).strip() or None
        m2 = re.search(
            rf'<meta[^>]+name=[\'"]{re.escape(prop)}[\'"][^>]+content=[\'"]([^\'"]+)[\'"]',
            text,
            flags=re.IGNORECASE,
        )
        if m2:
            return unescape(m2.group(1)).strip() or None
        return None

    return (pick("og:title"), pick("og:image"))


def _extract_og_site_name_from_html(*, html_text: str) -> str | None:
    text = html_text or ""
    m = re.search(
        r'<meta[^>]+property=[\'"]og:site_name[\'"][^>]+content=[\'"]([^\'"]+)[\'"]',
        text,
        flags=re.IGNORECASE,
    )
    if m:
        return unescape(m.group(1)).strip() or None
    m2 = re.search(
        r'<meta[^>]+name=[\'"]og:site_name[\'"][^>]+content=[\'"]([^\'"]+)[\'"]',
        text,
        flags=re.IGNORECASE,
    )
    if m2:
        return unescape(m2.group(1)).strip() or None
    return None


def _fetch_product_og_metadata(product_url: str) -> ProductMetadata | None:
    """
    상품 상세 URL을 직접 호출해 og:title/og:image 기반 메타데이터를 만든다.
    - 키워드 검색 결과(shop.json)에 의존하지 않아 '다른 상품으로 오염'되는 문제를 방지한다.
    """
    url = (product_url or "").strip()
    if not url or not (url.startswith("http://") or url.startswith("https://")):
        return None
    try:
        resp = requests.get(
            url,
            headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                "Referer": "https://search.shopping.naver.com/",
            },
            timeout=6,
        )
    except Exception:
        return None
    if resp.status_code >= 400:
        return None
    title, image = _extract_og_metadata_from_html(html_text=resp.text or "")
    site_name = _extract_og_site_name_from_html(html_text=resp.text or "") or _infer_smartstore_mall_name(url)
    title = _normalize_product_title(title, mall_name=site_name)
    if not title and not image:
        return None
    return ProductMetadata(
        title=title,
        image_url=image,
        site_name=site_name,
        price=None,
        product_id=None,
    )

