app = FastAPI(title="ERP2 Analytics API", version="0.1.0")
_register_shopping_search_debug_routes(app)

# ---- Auth middleware (Firebase ID token) ----
# NAS 운영: REQUIRE_FIREBASE_AUTH=1 + FIREBASE_PROJECT_ID=<projectId>
# allowlist는 운영/검증/문서 용도만 무인증으로 남긴다.
_AUTH_ALLOW_PREFIXES: list[str] = [
    "/health",
    "/version",
    "/api/version",
    # UI 자동 설정(내 PC IP 탐지)용: 인증 전에도 접근 가능해야 한다.
    "/search-rank/page-metrics/client-ip",
    # NAS 환경에서 브라우저 IP를 172.*로만 보게 되는 경우가 있어,
    # CDP(9223) 응답을 스캔해 "실제 PC IP"를 자동 탐지한다.
    "/search-rank/page-metrics/discover-host-cdp",
    "/docs",
    "/openapi.json",
    "/redoc",
]

_ANALYTICS_COLLECTOR_TOKEN = str(os.getenv("ANALYTICS_COLLECTOR_TOKEN") or "").strip() or secrets.token_urlsafe(32)


def _valid_collector_worker_token(request: Request) -> bool:
    expected = _ANALYTICS_COLLECTOR_TOKEN
    if not expected:
        return False
    supplied = str(
        request.headers.get("x-analytics-collector-token")
        or request.headers.get("x-erp2-collector-token")
        or ""
    ).strip()
    return bool(supplied) and hmac.compare_digest(supplied, expected)


@app.middleware("http")
async def firebase_auth_middleware(request: Request, call_next):
    if not is_firebase_auth_required():
        return await call_next(request)

    # 운영에서 REQUIRE_FIREBASE_AUTH=1로 켠 경우, FIREBASE_PROJECT_ID가 없으면
    # 이는 "인증 실패"가 아니라 "구성 오류"이므로 503으로 명확히 반환한다.
    # (버전관리 화면에서 원인 추적이 가능하도록 detail 문자열은 기존과 동일하게 유지)
    try:
        if not str(get_firebase_project_id() or "").strip():
            return JSONResponse(status_code=503, content={"error": "misconfigured", "message": "firebase_project_id_missing"})
    except Exception:
        # 구성 확인 실패 시에도 아래 verify에서 원인 메시지가 반환된다.
        pass

    path = str(getattr(request, "url", None).path if getattr(request, "url", None) else request.scope.get("path") or "")
    for p in _AUTH_ALLOW_PREFIXES:
        if path == p or path.startswith(p + "/"):
            return await call_next(request)
    if _valid_collector_worker_token(request):
        try:
            request.state.claims = {"sub": "analytics-collector-worker", "role": "collector_worker"}
        except Exception:
            pass
        return await call_next(request)

    try:
        # 성공 시 claims 반환:
        # - 이후 라우트에서 권한/역할 검증을 위해 request.state에 보관한다.
        claims = verify_firebase_id_token_from_headers(dict(request.headers))
    except Exception as e:
        msg = str(e) or "unauthorized"
        return JSONResponse(status_code=401, content={"error": "unauthorized", "message": msg})

    try:
        request.state.claims = claims
    except Exception:
        # 일부 테스트/환경에서 state가 없거나 실패할 수 있어도 요청 처리는 지속한다.
        pass

    return await call_next(request)

# CORS 설정
# - 기본값(로컬 개발): localhost/127.0.0.1 의 어떤 포트에서든 접근 허용 (web 포트가 바뀌어도 깨지지 않게)
# - 운영/고정 환경: CORS_ORIGINS="https://example.com,https://admin.example.com" 처럼 명시적으로 지정 권장
cors_origins_raw = (os.getenv("CORS_ORIGINS", "") or "").strip()
if cors_origins_raw == "*":
    cors_allow_origins = ["*"]
    cors_allow_origin_regex = None
elif cors_origins_raw:
    cors_allow_origins = [o.strip() for o in cors_origins_raw.split(",") if o.strip()]
    cors_allow_origin_regex = None
else:
    cors_allow_origins = []
    cors_allow_origin_regex = r"^https?://(localhost|127\.0\.0\.1)(:\d+)?$"

app.add_middleware(
    CORSMiddleware,
    allow_origins=cors_allow_origins,
    allow_origin_regex=cors_allow_origin_regex,
    allow_credentials=False,
    allow_methods=["*"],
    allow_headers=["*"],
)


def get_db() -> Session:
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


# A-1 Trace(감사/재현) API 라우트 등록
# - get_db 의존성 정의 이후에 등록해야 한다.
register_a1_trace_routes(app, get_db_dep=get_db)
register_qna_routes(app, get_db_dep=get_db)
register_menu_sync_routes(app, get_db_dep=get_db)


