def _ads_searchword_report_cdp_url(date_from: date, date_to: date) -> str:
    meta = COLLECTION_TASK_REGISTRY.get("ads_searchword_daily") or {}
    base_url = str(meta.get("report_url") or "").strip()
    if not base_url:
        raise HTTPException(status_code=500, detail="ads_searchword_report_url_missing")
    sep = "&" if "?" in base_url else "?"
    # Host Agent가 읽는 내부 메타 파라미터다. 브라우저에는 이 파라미터를 제거한 순수 보고서 URL로 진입한다.
    return (
        f"{base_url}{sep}"
        f"analyticsSearchwordDateFrom={date_from.isoformat()}"
        f"&analyticsSearchwordDateTo={date_to.isoformat()}"
    )


def _ads_searchword_report_cdp_urls_7day_chunks(date_from: date, date_to: date) -> list[str]:
    urls: list[str] = []
    cur_to = date_to
    while cur_to >= date_from:
        cur_from = max(date_from, cur_to - timedelta(days=6))
        urls.append(_ads_searchword_report_cdp_url(cur_from, cur_to))
        cur_to = cur_from - timedelta(days=1)
