def _gfa_report_cdp_urls_month_chunks(ad_account_no: str, date_from: date, date_to: date) -> list[str]:
    urls: list[str] = []
    cur_to = date_to
    while cur_to >= date_from:
        cur_from = max(date_from, date(cur_to.year, cur_to.month, 1))
        for ad_unit in GFA_REPORT_REQUIRED_UNITS:
            urls.append(_gfa_report_cdp_url(ad_account_no, cur_from, cur_to, ad_unit=ad_unit))
        cur_to = cur_from - timedelta(days=1)
    return urls


def _gfa_month_range_for_date(d: date, min_date: date, max_date: date) -> tuple[date, date]:
    start = max(min_date, date(d.year, d.month, 1))
    next_month = date(d.year + 1, 1, 1) if d.month == 12 else date(d.year, d.month + 1, 1)
    end = min(max_date, next_month - timedelta(days=1))
    return start, end


def _gfa_missing_report_cdp_urls(db: Session, ad_account_no: str, date_from: date, date_to: date) -> tuple[list[str], list[date], list[tuple[date, date]]]:
    missing_units_by_date = _collection_gfa_performance_missing_units(db, date_from, date_to, require_payload=True)
    missing_dates = sorted(missing_units_by_date.keys())
    missing_segments = _collection_contiguous_date_segments(missing_dates)
    report_ranges: list[tuple[date, date, str]] = []
    seen: set[tuple[date, date, str]] = set()
    for missing_date, missing_units in missing_units_by_date.items():
        seg_from, seg_to = _gfa_month_range_for_date(missing_date, date_from, date_to)
        for ad_unit in sorted(missing_units):
            key = (seg_from, seg_to, ad_unit)
            if key not in seen:
                seen.add(key)
                report_ranges.append(key)
    report_ranges.sort(key=lambda x: (x[1], x[2]), reverse=True)
    urls = [
        _gfa_report_cdp_url(ad_account_no, seg_from, seg_to, ad_unit=ad_unit)
        for seg_from, seg_to, ad_unit in report_ranges
    ]
    return urls, missing_dates, missing_segments


def _ads_creative_missing_report_cdp_urls(db: Session, date_from: date, date_to: date) -> tuple[list[str], list[date], list[tuple[date, date]]]:
    missing_dates = _collection_table_missing_dates(
        db,
        "naver_ad_creative_daily",
        date_from,
        date_to,
        source="creative_upload",
    )
    missing_segments = _collection_contiguous_date_segments(missing_dates)
    report_ranges = sorted(
        {_ads_searchword_aligned_7day_period(day, date_to) for day in missing_dates},
        key=lambda x: x[1],
        reverse=True,
    )
    urls: list[str] = []
    for seg_from, seg_to in report_ranges:
        urls.append(_ads_creative_report_cdp_url(seg_from, seg_to))
    return urls, missing_dates, missing_segments


def _collection_contiguous_date_segments(dates: list[date]) -> list[tuple[date, date]]:
    uniq = sorted({d for d in dates if isinstance(d, date)})
    if not uniq:
        return []
    segments: list[tuple[date, date]] = []
    start = uniq[0]
    prev = uniq[0]
    for cur in uniq[1:]:
        if cur == prev + timedelta(days=1):
            prev = cur
            continue
        segments.append((start, prev))
        start = cur
        prev = cur
    segments.append((start, prev))
    return segments


def _ads_searchword_aligned_7day_period(day: date, anchor_to: date) -> tuple[date, date]:
    # Naver Ads UI is driven by "recent 7 days" followed by previous-period clicks.
    # Align old missing dates to the same 7-day windows so the UI can reach them
    # by period movement, even when only a partial week is missing.
    diff_days = max(0, (anchor_to - day).days)
    bucket = diff_days // 7
    period_to = anchor_to - timedelta(days=bucket * 7)
    period_from = period_to - timedelta(days=6)
    return period_from, period_to


def _ads_searchword_missing_report_cdp_urls(db: Session, date_from: date, date_to: date) -> tuple[list[str], list[date], list[tuple[date, date]]]:
    missing_dates = _collection_table_missing_dates(
        db,
        "naver_ad_searchword_daily",
        date_from,
        date_to,
        source="ui_csv_upload",
    )
    missing_segments = _collection_contiguous_date_segments(missing_dates)
    report_ranges = sorted(
        {_ads_searchword_aligned_7day_period(day, date_to) for day in missing_dates},
        key=lambda x: x[1],
        reverse=True,
    )
    urls: list[str] = []
    for seg_from, seg_to in report_ranges:
        urls.append(_ads_searchword_report_cdp_url(seg_from, seg_to))
    return urls, missing_dates, missing_segments


