# ----------------------------
# Admin: 버전관리(ERP 스타일)
# - 목적: UI에서 "버전 라벨" 저장 + 백업(설정 스냅샷 다운로드)
# - 버전 라벨은 "배포 태그(imageTag)"와 별개로, 운영자가 관리하는 표시용 문자열이다.
# - backup은 전체 스택(docker save/볼륨) 백업이 아니라, UI/설정 스냅샷을 zip으로 다운로드한다.
# ----------------------------

_APP_VERSION_KEY = "app:version_label"
_SALES_SYNC_DIAGNOSTIC_JOB_NAME = "sales:commerce:sync-diagnostic"
_DIRECT_ORDER_UNSUPPORTED_UNTIL_KEY = "sales:commerce:direct-order:unsupported-until"


def _get_app_version_label(db: Session) -> str:
    row = db.query(AppSetting).filter(AppSetting.key == _APP_VERSION_KEY).one_or_none()
    v = str(row.value or "").strip() if row else ""
    if v:
        return v
    # default: 현재 이미지 태그(증거)로 채운다.
    return str((_ANALYTICS_API_IMAGE_TAG or "").strip() or "1.0.0")


def _set_app_version_label(db: Session, version: str) -> str:
    v = str(version or "").strip()
    if not v:
        raise HTTPException(status_code=400, detail="version_required")
    row = db.query(AppSetting).filter(AppSetting.key == _APP_VERSION_KEY).one_or_none()
    if row is None:
        db.add(AppSetting(key=_APP_VERSION_KEY, value=v))
    else:
        row.value = v
    db.commit()
    return v


def _get_app_setting_value(db: Session, key: str) -> str:
    row = db.query(AppSetting).filter(AppSetting.key == str(key or "")).one_or_none()
    return str(row.value or "").strip() if row else ""


def _set_app_setting_value(db: Session, *, key: str, value: str) -> str:
    k = str(key or "").strip()
    if not k:
        raise HTTPException(status_code=400, detail="app_setting_key_required")
    row = db.query(AppSetting).filter(AppSetting.key == k).one_or_none()
    if row is None:
        db.add(AppSetting(key=k, value=str(value or "")))
    else:
        row.value = str(value or "")
    db.commit()
    return str(value or "")


def _delete_app_setting_value(db: Session, key: str) -> None:
    row = db.query(AppSetting).filter(AppSetting.key == str(key or "")).one_or_none()
    if row is None:
        return
    db.delete(row)
    db.commit()


