@app.post("/admin/users", response_model=dict)
def admin_create_user_route(payload: AdminUserCreatePayload, request: Request):
    actor_roles = require_role_level(request, minimum="ops_admin")
    is_super = "superadmin" in set(actor_roles or [])
    requested = list(payload.roles or [])
    if not requested and payload.role:
        requested = [str(payload.role)]
    if not requested:
        raise HTTPException(status_code=400, detail="validation_error")
    # superadmin 부여는 superadmin만 가능
    req_lower = {str(x or "").strip().lower() for x in requested}
    if ("superadmin" in req_lower or "admin" in req_lower) and not is_super:
        raise HTTPException(status_code=403, detail="forbidden")
    return admin_create_user(
        email=str(payload.email or "").strip(),
        password=str(payload.password or ""),
        display_name=(str(payload.displayName).strip() if payload.displayName else None),
        roles=[str(x or "").strip() for x in requested],
    )


@app.post("/admin/users/{uid}/role", response_model=dict)
def admin_set_role_route(uid: str, payload: AdminUserRolePayload, request: Request):
    actor_roles = require_role_level(request, minimum="ops_admin")
    is_super = "superadmin" in set(actor_roles or [])
    requested = list(payload.roles or [])
    if not requested and payload.role:
        requested = [str(payload.role)]
    if not requested:
        raise HTTPException(status_code=400, detail="validation_error")
    req_lower = {str(x or "").strip().lower() for x in requested}
    if ("superadmin" in req_lower or "admin" in req_lower) and not is_super:
        raise HTTPException(status_code=403, detail="forbidden")
    # 기존 custom claims는 최대한 유지(roles/role만 덮어씀)
    admin_set_roles(uid, roles=[str(x or "").strip() for x in requested], merge=True)
    return {"ok": True}


@app.post("/admin/users/{uid}/disable", response_model=dict)
def admin_set_disabled_route(uid: str, payload: AdminUserDisablePayload, request: Request):
    require_role_level(request, minimum="ops_admin")
    admin_set_disabled(uid, disabled=bool(payload.disabled))
    return {"ok": True}


@app.post("/admin/users/{uid}/password", response_model=dict)
def admin_set_password_route(uid: str, payload: AdminUserPasswordPayload, request: Request):
    require_role_level(request, minimum="ops_admin")
    pw = str(payload.password or "")
