class ApiSettingsPayload(BaseModel):
    # 1) 네이버 쇼핑 OpenAPI
    NAVER_KEY: str | None = None
    NAVER_SECRET: str | None = None

    # 2) 네이버 SearchAD
    AD_CUST_ID: str | None = None
    AD_KEY: str | None = None
    AD_SEC: str | None = None

    # 3) 네이버 CLIENT (추후 확장용)
    NAVER_CLIENT_ID: str | None = None
    NAVER_CLIENT_SECRET: str | None = None

    # 4) 네이버 커머스 API
    NAVER_COMMERCE_CLIENT_ID: str | None = None
    NAVER_COMMERCE_CLIENT_SECRET: str | None = None

    # 5) chatGPT
    OPENAI_API_KEY: str | None = None


_MASKED_API_SETTING_VALUE = "********"
_SENSITIVE_API_SETTING_KEYS = {
    "NAVER_KEY",
    "NAVER_SECRET",
    "AD_KEY",
    "AD_SEC",
    "NAVER_CLIENT_ID",
    "NAVER_CLIENT_SECRET",
    "NAVER_COMMERCE_CLIENT_ID",
    "NAVER_COMMERCE_CLIENT_SECRET",
    "OPENAI_API_KEY",
}


def _mask_api_settings_for_read(data: dict[str, str] | None) -> dict[str, str]:
    masked: dict[str, str] = {}
    src = data if isinstance(data, dict) else {}
    for k in _API_SETTINGS_PUBLIC_KEYS:
        v = str(src.get(k, "") or "").strip()
        if (k in _SENSITIVE_API_SETTING_KEYS) and v:
            masked[k] = _MASKED_API_SETTING_VALUE
        else:
            masked[k] = v
    return masked


