@app.post("/settings/ai/restore-latest", response_model=dict)
def restore_ai_settings_latest(db: Session = Depends(get_db)):
    """
    최근 A-1 분석 로그(ai_decision_log)의 입력 스냅샷에서 규칙(rule_pack)을 추출해
    AI 세팅(app_settings: ai:settings)을 복구한다.
    """
    restored = False
    try:
        restored = bool(_restore_ai_settings_from_latest_log(db))
    except Exception:
        restored = False
    # 응답에 최소한의 진단 정보를 포함(프론트에서 "왜 안 됨?"을 바로 표시)
    info = {"source": ("ai_decision_log" if restored else "none")}
    try:
        cur = _get_ai_settings(db) or {}
        info["current_common_len"] = len(str((cur or {}).get("common_rules") or ""))
        info["current_rules_count"] = len((cur or {}).get("rule_packs") or [])
    except Exception:
        pass
    return {"ok": True, "restored": restored, **info}


@app.get("/settings/ai/status", response_model=dict)
def ai_settings_status(db: Session = Depends(get_db)):
    """
    AI 세팅이 "사라진 것처럼 보이는" 문제 진단용.
    - 현재 저장 상태(길이/개수)
    - 복구 원본 존재 여부(최근 A-1 로그 유무)
    """
    out: dict = {"ok": True}
    try:
        cur = _get_ai_settings(db) or {}
        out["common_len"] = len(str((cur or {}).get("common_rules") or ""))
        out["analysis_rules_count"] = len((cur or {}).get("rule_packs") or [])
    except Exception:
        out["common_len"] = None
        out["analysis_rules_count"] = None
    try:
        from db import AiDecisionLog

        latest = (
            db.query(AiDecisionLog)
            .filter(AiDecisionLog.analysis_type == "A-1")
            .order_by(AiDecisionLog.created_at.desc())
            .limit(1)
            .one_or_none()
        )
        out["latest_a1_log_exists"] = bool(latest is not None)
        out["latest_a1_log_id"] = (str(getattr(latest, "log_id", "") or "") if latest is not None else None)
        out["latest_a1_log_at"] = (str(getattr(latest, "created_at", "") or "") if latest is not None else None)
    except Exception:
        out["latest_a1_log_exists"] = None
        out["latest_a1_log_id"] = None
        out["latest_a1_log_at"] = None
    return out


