def _ai_json_dumps(obj: object, *, limit: int | None = None) -> str:
    s = json.dumps(obj, ensure_ascii=False, separators=(",", ":"), default=str)
    if limit is not None and len(s) > limit:
        return s[:limit] + "…"
    return s


def _ai_hash_inputs(obj: object) -> str:
    try:
        raw = json.dumps(obj, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")
    except Exception:
        raw = str(obj).encode("utf-8", errors="ignore")
    return hashlib.sha256(raw).hexdigest()


def _parse_ymd_date(s: str | None) -> date | None:
    """
    YYYY-MM-DD 문자열을 date로 파싱한다(엄격).
    - 실패 시 None
    """
    txt = str(s or "").strip()
    if not txt:
        return None
    m = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", txt)
    if not m:
        return None
    try:
        y = int(m.group(1))
        mm = int(m.group(2))
        dd = int(m.group(3))
        return date(y, mm, dd)
    except Exception:
        return None


def _resolve_a1_date_range(
    *,
    days: int | None,
    date_from: str | None,
    date_to: str | None,
    max_days: int = 90,
) -> tuple[date, date, int]:
    """
    A-1 분석의 기간 입력을 단일 규칙으로 정규화한다.
    - date_from/date_to가 모두 있으면 이를 우선(YYYY-MM-DD, inclusive)
    - 아니면 days 기반으로 (today - days + 1) ~ today
    """
    df = _parse_ymd_date(date_from)
    dt = _parse_ymd_date(date_to)
    if (df is None) ^ (dt is None):
        raise HTTPException(status_code=400, detail="date_from and date_to must be provided together (YYYY-MM-DD)")
    if df is not None and dt is not None:
        if dt < df:
            df, dt = dt, df
        span = int((dt - df).days + 1)
        if span < 1:
            raise HTTPException(status_code=400, detail="date range is empty")
        if span > int(max_days):
            raise HTTPException(status_code=400, detail=f"date range too large (max {int(max_days)} days)")
        return (df, dt, span)

    d0 = int(days or 30)
    if d0 < 7:
        raise HTTPException(status_code=400, detail="days must be >= 7")
    if d0 > int(max_days):
        raise HTTPException(status_code=400, detail=f"days too large (max {int(max_days)})")
    today = _today_kst()
    return (today - timedelta(days=d0 - 1), today, d0)


def _a1_compute_rank_summary(
    db: Session,
    *,
    product_url: str,
    keyword: str,
    days: int | None = None,
    date_from: date | None = None,
    date_to: date | None = None,
) -> dict:
    """
    A-1(오가닉 순위 분석) 입력 요약을 생성한다.
    - 데이터 소스: tracked_product_rank_daily (excel/text/openapi/crawl_category)
    """
    u = str(product_url or "").strip()
    kw = str(keyword or "").strip()
    if not u or not kw:
        raise HTTPException(status_code=400, detail="product_url and keyword are required")

    if (date_from is None) ^ (date_to is None):
        raise HTTPException(status_code=400, detail="date_from/date_to must be provided together")
    if date_from is not None and date_to is not None:
        # 사용자 지정 기간(inclusive)
        if date_to < date_from:
            date_from, date_to = date_to, date_from
        today = date_to
        date_from0 = date_from
        days0 = int((today - date_from0).days + 1)
    else:
        days0 = int(days or 30)
        today = _today_kst()
        date_from0 = today - timedelta(days=days0 - 1)

    filters = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=u)
    rows = (
        db.query(TrackedProductRankDaily)
        .filter(
            or_(*filters),
            TrackedProductRankDaily.keyword == kw,
            TrackedProductRankDaily.date >= date_from0,
            TrackedProductRankDaily.date <= today,
        )
        .order_by(TrackedProductRankDaily.date.asc())
        .all()
    )

    by_date: dict[str, int] = {}
    src_by_date: dict[str, str] = {}
    for r in rows:
        d = str(getattr(r, "date", "") or "")
        rk = int(getattr(r, "rank", 0) or 0)
        by_date[d] = rk
        src_by_date[d] = str(getattr(r, "source", "") or "")

    missing_rank_value = 999

    # 날짜축 구성(결측 포함)
    dates: list[str] = []
    series: list[dict] = []
    cur = date_from0
    while cur <= today:
        ds = str(cur)
        dates.append(ds)
        rk = by_date.get(ds, 0)
        # 정책: 미노출/결측은 999로 취급(규칙 기반 판정/이상치 탐지용)
        rk_norm = missing_rank_value if (rk is None or int(rk) <= 0) else int(rk)
        series.append({"date": ds, "rank": rk_norm, "rank_raw": rk, "source": src_by_date.get(ds) or None})
        cur += timedelta(days=1)

    def pick(offset_days: int) -> int | None:
        idx = len(series) - 1 - offset_days
        if idx < 0 or idx >= len(series):
            return None
        v = series[idx]["rank"]
        try:
            return int(v)
        except Exception:
            return None

    def pick_valid(offset_days: int) -> int | None:
        """
        결측(999)을 제외한 값만 반환한다.
        - 반환이 None이면 해당 offset 지점에 유효한 순위가 없음을 의미한다.
        """
        v = pick(offset_days)
        if v is None:
            return None
        try:
            iv = int(v)
        except Exception:
            return None
        return None if iv >= missing_rank_value else iv

    r0 = pick(0)
    r1 = pick(1)
    r7 = pick(7)
    r14 = pick(14)
    r0v = pick_valid(0)
    r1v = pick_valid(1)
    r7v = pick_valid(7)
    r14v = pick_valid(14)

    def delta(a: int | None, b: int | None) -> int | None:
        if a is None or b is None:
            return None
        return int(a) - int(b)

    # 최근 14일 통계
    last14_all = [int(x["rank"]) for x in series[-14:] if x.get("rank") is not None]
    last14_valid = [int(x["rank"]) for x in series[-14:] if x.get("rank") is not None and int(x["rank"]) < missing_rank_value]
    # avg/vol은 유효값 기준으로 계산한다(결측 999가 섞이면 평균/변동이 왜곡됨)
    avg14 = float(sum(last14_valid) / max(1, len(last14_valid))) if last14_valid else None
    # 표준편차
    vol14 = None
    if last14_valid and len(last14_valid) >= 2:
        m = sum(last14_valid) / len(last14_valid)
        vol14 = math.sqrt(sum((x - m) ** 2 for x in last14_valid) / (len(last14_valid) - 1))

    # down_days_14d: 전일 대비 "악화(+3 이상)" 일수
    down_days_14d = 0
    improve_days_7d = 0
    big_drop_days_7d = 0  # 전일 대비 +30 이상
    for i in range(1, len(series)):
        prev = int(series[i - 1]["rank"])
        curv = int(series[i]["rank"])
        # 결측(999) 구간은 변동/악화일 계산에서 제외한다(999→1 같은 점프가 왜곡을 만든다)
        if prev >= missing_rank_value or curv >= missing_rank_value:
            continue
        diff = curv - prev
        if i >= len(series) - 14:
            if diff >= 3:
                down_days_14d += 1
        if i >= len(series) - 7:
            if (prev - curv) >= 3:
                improve_days_7d += 1
            if diff >= 30:
                big_drop_days_7d += 1

    # 월검색량(가능하면 manual meta 우선)
    sv = None
    try:
        mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=u)
        mk = (
            db.query(TrackedProductManualKeyword)
            .filter(or_(*mk_filters), TrackedProductManualKeyword.keyword == kw, TrackedProductManualKeyword.is_active.is_(True))
            .order_by(TrackedProductManualKeyword.updated_at.desc())
            .limit(1)
            .one_or_none()
        )
        if mk is not None and getattr(mk, "monthly_search_volume", None) is not None:
            sv = int(getattr(mk, "monthly_search_volume"))
    except Exception:
        pass
    if sv is None:
        try:
            tk_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=u)
            tk = (
                db.query(TrackedProductKeyword)
                .filter(or_(*tk_filters), TrackedProductKeyword.keyword == kw, TrackedProductKeyword.is_active.is_(True))
                .order_by(TrackedProductKeyword.created_at.desc())
                .limit(1)
                .one_or_none()
            )
            if tk is not None and getattr(tk, "monthly_search_volume", None) is not None:
                sv = int(getattr(tk, "monthly_search_volume"))
        except Exception:
            pass

    # 데이터 품질(검증/판단 신뢰도에 직결)
    valid_days_14d = 0
    missing_days_14d = 0
    missing_999_days_14d = 0
    src_counts: dict[str, int] = {}
    for x in series[-14:]:
        rr = x.get("rank_raw")
        try:
            rr_i = int(rr) if rr is not None else 0
        except Exception:
            rr_i = 0
        if rr_i > 0:
            valid_days_14d += 1
        else:
            missing_days_14d += 1
        try:
            if int(x.get("rank") or 0) == missing_rank_value:
                missing_999_days_14d += 1
        except Exception:
            pass
        src = str(x.get("source") or "").strip() or "unknown"
        src_counts[src] = int(src_counts.get(src, 0) or 0) + 1
    missing_ratio_14d = (float(missing_days_14d) / 14.0) if 14 > 0 else 0.0

    return {
        "date_range": {"from": str(date_from0), "to": str(today), "days": int(days0)},
        "product_url": u,
        "keyword": kw,
        "search_volume_month": sv,
        "rank_series": series,  # LLM 입력 크기 제한은 상위에서 적용
        "metrics": {
            "rank_latest": r0,
            "rank_prev_1d": r1,
            "rank_prev_7d": r7,
            "rank_prev_14d": r14,
            # NOTE: delta/avg/vol은 유효값 기준으로 제공한다(결측 999가 섞이면 왜곡).
            "rank_change_1d": delta(r0v, r1v),
            "rank_change_7d": delta(r0v, r7v),
            "rank_change_14d": delta(r0v, r14v),
            # UI/검증에서 '결측 포함 원본'도 필요하면 참고용으로 제공
            "rank_latest_valid": r0v,
            "rank_prev_7d_valid": r7v,
            "rank_prev_14d_valid": r14v,
            "avg_rank_14d": None if avg14 is None else round(float(avg14), 4),
            "rank_volatility_14d": None if vol14 is None else round(float(vol14), 4),
            "avg_rank_14d_all": (None if not last14_all else round(float(sum(last14_all) / max(1, len(last14_all))), 4)),
            "down_days_14d": int(down_days_14d),
            "improve_days_7d": int(improve_days_7d),
            "big_drop_days_7d": int(big_drop_days_7d),
            "valid_days_14d": int(valid_days_14d),
            "missing_days_14d": int(missing_days_14d),
            "missing_ratio_14d": round(float(missing_ratio_14d), 4),
            "missing_999_days_14d": int(missing_999_days_14d),
            "sources_14d": src_counts,
        },
    }


def _a1_classify(metrics: dict, *, series: list[dict], search_volume_month: int | None) -> tuple[str, float | None, list[str], list[str], list[str]]:
    """
    A-1 규칙(현재 합의된 현실 수치)을 코드로 고정 적용해 판정을 안정화한다.
    - GPT는 "설명/액션 보강"에만 사용하고, 판정 자체는 규칙 엔진이 우선한다.
    """
    avg14 = metrics.get("avg_rank_14d")
    vol14 = metrics.get("rank_volatility_14d")
    down14 = int(metrics.get("down_days_14d") or 0)
    down7 = int(metrics.get("down_days_7d") or 0)
    improve7 = int(metrics.get("improve_days_7d") or 0)
    latest = metrics.get("rank_latest")

    # 유효 데이터(999 제외) 비율로 confidence 기본값 산정
    last14 = series[-14:] if isinstance(series, list) else []
    valid14 = sum(1 for x in last14 if int(x.get("rank") or 999) < 999)
    base_conf = None
    try:
        base_conf = max(0.0, min(1.0, valid14 / 14.0))
    except Exception:
        base_conf = None

    rules_triggered: list[str] = []
    top_drivers: list[str] = []
    action_queue: list[str] = []

    # 데이터가 거의 없으면 UNCERTAIN
    if valid14 < 7 or (latest is not None and int(latest) >= 999):
        rules_triggered.append("insufficient_rank_data")
        top_drivers.append("최근 14일 유효 순위 데이터가 부족하거나(999/결측) 미노출이 많음")
        if search_volume_month is not None:
            top_drivers.append(f"월검색량: {int(search_volume_month):,} (참고)")
        action_queue.extend(["데이터 수집(최소 14일) 보강", "키워드/상품 URL 등록 상태 점검", "필요 시 SEO/상품 메타 개선 후 재측정"])
        return ("UNCERTAIN", base_conf, rules_triggered, top_drivers, action_queue)

    # STABLE
    try:
        if (avg14 is not None and float(avg14) <= 3.0) and (vol14 is not None and float(vol14) <= 1.2) and down14 <= 2:
            rules_triggered.append("stable:avg<=3&vol<=1.2&down14<=2")
            top_drivers.append("최근 14일 평균 순위가 상위권(≤3)으로 안정적")
            top_drivers.append("변동성(표준편차)이 낮고(≤1.2) 악화일이 적음")
            action_queue.extend(["현상 유지(리스크 모니터링)", "리뷰/평점/상품정보 유지관리", "경쟁 상품 변동 감시"])
            return ("STABLE", max(base_conf or 0.0, 0.75), rules_triggered, top_drivers, action_queue)
    except Exception:
        pass

    # WEAK
    try:
        if (avg14 is not None and float(avg14) >= 11.0) and improve7 == 0:
            rules_triggered.append("weak:avg>=11&improve7==0")
            top_drivers.append("최근 14일 평균 순위가 낮고(≥11) 개선 신호가 없음")
            action_queue.extend(["상품 메타/카테고리/대표키워드 정합성 점검", "콘텐츠/리뷰 확보 계획 수립", "SEO/광고 테스트로 유입 신호 만들기"])
            return ("WEAK", max(base_conf or 0.0, 0.65), rules_triggered, top_drivers, action_queue)
    except Exception:
        pass

    # UNSTABLE
    try:
        if (
            (avg14 is not None and 4.0 <= float(avg14) <= 10.0)
            or (vol14 is not None and float(vol14) >= 2.0)
            or (down7 >= 3)
        ):
            rules_triggered.append("unstable:avg4~10|vol>=2.0|down7>=3")
            top_drivers.append("최근 14일 평균/변동성 기준으로 불안정 구간")
            if down7 >= 3:
                top_drivers.append("최근 7일 중 전일 대비 악화(≥+3) 발생이 잦음")
            action_queue.extend(["원인 분해(가격/재고/리뷰/경쟁/노출지면)", "변동 구간에 맞춘 SEO/광고 개입 테스트", "키워드/상품 매칭(카테고리/속성) 재점검"])
            return ("UNSTABLE", max(base_conf or 0.0, 0.6), rules_triggered, top_drivers, action_queue)
    except Exception:
        pass

    # 그 외
    rules_triggered.append("default:moderate")
    top_drivers.append("규칙 기반 분류 상 STABLE/UNSTABLE/WEAK에 명확히 속하지 않음")
    action_queue.extend(["추세 관찰(7~14일)", "필요 시 키워드/상품 메타 미세조정", "데이터 수집 지속"])
    return ("UNCERTAIN", base_conf, rules_triggered, top_drivers, action_queue)


def _a1_default_thresholds() -> dict:
    return {
        "uncertain": {"min_valid_days_14d": 7, "missing_rank_value": 999},
        "stable": {"avg_rank_14d_max": 3.0, "rank_volatility_14d_max": 1.2, "down_days_14d_max": 2},
        "unstable": {
            "avg_rank_14d_min": 4.0,
            "avg_rank_14d_max": 10.0,
            "rank_volatility_14d_min": 2.0,
            "drop_7d_min": 3,
            # drop 정의(전일 대비 악화 n 이상을 "drop"으로 보는지) - 기본 +3
            "drop_delta_min": 3,
        },
        "weak": {"avg_rank_14d_min": 11.0, "improve_days_7d_eq": 0},
    }


def _ai_ops_default_thresholds() -> dict:
    return {
        "qna_barrier_high": 70.0,
        "review_risk_high": 65.0,
        "growth": {
            "organic_strength_min": 80.0,
            "sales_growth_min": 60.0,
            "review_risk_max": 45.0,
            "qna_barrier_max": 45.0,
        },
        "defense": {
            "organic_strength_max": 55.0,
        },
    }


def _ai_ops_default_scope() -> dict:
    return {
        "mall_names": [],
    }


def _merge_nested_dict(base: dict, override: dict) -> dict:
    out = copy.deepcopy(base if isinstance(base, dict) else {})
    if not isinstance(override, dict):
        return out
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(out.get(key), dict):
            out[key] = _merge_nested_dict(out.get(key) or {}, value)
        else:
            out[key] = value
    return out


def _a1_parse_thresholds(rule_pack: dict) -> dict:
    """
    A-1 규칙은 언제든 변경될 수 있으므로, AI 세팅의 rules 텍스트에서 임계값을 파싱한다.
    - 우선순위:
      1) rules에 JSON(thresholds)이 있으면 그 값을 사용
      2) 텍스트(예: avg_rank_14d ≤ 3 AND ...)에서 정규식으로 추출
      3) 누락된 값은 기본값 유지
    """
    cfg = _a1_default_thresholds()
    raw = str((rule_pack or {}).get("rules") or "").strip()
    if not raw:
        return cfg

    # 1) JSON 우선
    if "{" in raw and "}" in raw:
        try:
            j = json.loads(raw)
            th = j.get("thresholds") if isinstance(j, dict) else None
            if isinstance(th, dict):
                out = copy.deepcopy(cfg)
                for k in ("uncertain", "stable", "unstable", "weak"):
                    if isinstance(th.get(k), dict):
                        out[k].update(th[k])  # type: ignore[index]
                return out
        except Exception:
            pass

    # 2) 텍스트 파싱(한글/기호 혼용 허용)
    t = raw.replace("≤", "<=").replace("≥", ">=").replace("＝", "=")
    t = t.replace("–", "-").replace("—", "-")

    def f1(pat: str) -> float | None:
        try:
            m = re.search(pat, t, flags=re.IGNORECASE)
            if not m:
                return None
            return float(m.group(1))
        except Exception:
            return None

    def i1(pat: str) -> int | None:
        v = f1(pat)
        if v is None:
            return None
        try:
            return int(v)
        except Exception:
            return None

    out = copy.deepcopy(cfg)

    # STABLE: avg_rank_14d <= X, rank_volatility_14d <= Y, down_days_14d <= Z
    v = f1(r"avg[_ ]?rank[_ ]?14d\s*(?:<=)\s*([0-9]+(?:\.[0-9]+)?)")
    if v is not None:
        out["stable"]["avg_rank_14d_max"] = v
    v = f1(r"rank[_ ]?volatility[_ ]?14d\s*(?:<=)\s*([0-9]+(?:\.[0-9]+)?)")
    if v is not None:
        out["stable"]["rank_volatility_14d_max"] = v
    v_i = i1(r"down[_ ]?days[_ ]?14d\s*(?:<=)\s*([0-9]+(?:\.[0-9]+)?)")
    if v_i is not None:
        out["stable"]["down_days_14d_max"] = v_i

    # UNSTABLE: avg_rank_14d 4~10 / 4-10, rank_volatility_14d >= X, drop_7d >= N
    try:
        m = re.search(r"avg[_ ]?rank[_ ]?14d\s*([0-9]+(?:\.[0-9]+)?)\s*[\~\-]\s*([0-9]+(?:\.[0-9]+)?)", t, flags=re.IGNORECASE)
        if m:
            out["unstable"]["avg_rank_14d_min"] = float(m.group(1))
            out["unstable"]["avg_rank_14d_max"] = float(m.group(2))
    except Exception:
        pass
    v = f1(r"rank[_ ]?volatility[_ ]?14d\s*(?:>=)\s*([0-9]+(?:\.[0-9]+)?)")
    if v is not None:
        out["unstable"]["rank_volatility_14d_min"] = v
    v_i = i1(r"(?:drop|down)[_ ]?7d\s*(?:>=)\s*([0-9]+(?:\.[0-9]+)?)")
    if v_i is not None:
        out["unstable"]["drop_7d_min"] = v_i
    v_i = i1(r"(?:drop|down)[_ ]?delta\s*(?:>=)\s*([0-9]+(?:\.[0-9]+)?)")
    if v_i is not None:
        out["unstable"]["drop_delta_min"] = v_i

    # WEAK: avg_rank_14d >= X AND improve_days_7d = 0
    v = f1(r"avg[_ ]?rank[_ ]?14d\s*(?:>=)\s*([0-9]+(?:\.[0-9]+)?)")
    if v is not None:
        out["weak"]["avg_rank_14d_min"] = v
    v_i = i1(r"improve[_ ]?days[_ ]?7d\s*(?:=)\s*([0-9]+(?:\.[0-9]+)?)")
    if v_i is not None:
        out["weak"]["improve_days_7d_eq"] = v_i

    # UNCERTAIN: valid_days_14d < N (옵션)
    v_i = i1(r"valid[_ ]?days[_ ]?14d\s*(?:<)\s*([0-9]+(?:\.[0-9]+)?)")
    if v_i is not None:
        out["uncertain"]["min_valid_days_14d"] = max(1, v_i)

    return out


def _a1_classify_dynamic(
    metrics: dict,
    *,
    series: list[dict],
    search_volume_month: int | None,
    thresholds: dict,
) -> tuple[str, float | None, list[str], list[str], list[str]]:
    """
    규칙(임계값)이 AI 세팅에서 변경될 수 있으므로 thresholds를 받아 판정한다.
    """
    cfg = thresholds or _a1_default_thresholds()
    unc = cfg.get("uncertain") or {}
    st = cfg.get("stable") or {}
    un = cfg.get("unstable") or {}
    wk = cfg.get("weak") or {}

    avg14 = metrics.get("avg_rank_14d")
    vol14 = metrics.get("rank_volatility_14d")
    down14 = int(metrics.get("down_days_14d") or 0)
    improve7 = int(metrics.get("improve_days_7d") or 0)
    latest = metrics.get("rank_latest")

    # down_days_7d가 없으면 series로 계산(규칙 기반)
    down7 = int(metrics.get("down_days_7d") or 0)
    if down7 <= 0 and isinstance(series, list) and len(series) >= 2:
        dd_min = int(un.get("drop_delta_min") or 3)
        missing_val = int(unc.get("missing_rank_value") or 999)
        dd = 0
        for i in range(max(1, len(series) - 7), len(series)):
            prev = int(series[i - 1].get("rank") or missing_val)
            curv = int(series[i].get("rank") or missing_val)
            # 결측(999) 구간은 악화일 계산에서 제외(999 점프가 down7을 왜곡함)
            if prev >= missing_val or curv >= missing_val:
                continue
            if curv - prev >= dd_min:
                dd += 1
        down7 = dd
        metrics["down_days_7d"] = int(down7)

    # 유효 데이터(999 제외) 비율로 confidence 기본값 산정
    missing_val = int(unc.get("missing_rank_value") or 999)
    last14 = series[-14:] if isinstance(series, list) else []
    valid14 = sum(1 for x in last14 if int(x.get("rank") or missing_val) < missing_val)
    base_conf = None
    try:
        base_conf = max(0.0, min(1.0, valid14 / 14.0))
    except Exception:
        base_conf = None

    rules_triggered: list[str] = []
    top_drivers: list[str] = []
    action_queue: list[str] = []

    min_valid = int(unc.get("min_valid_days_14d") or 7)
    if valid14 < min_valid or (latest is not None and int(latest) >= missing_val):
        rules_triggered.append(f"insufficient_rank_data:valid14<{min_valid}")
        top_drivers.append("최근 14일 유효 순위 데이터가 부족하거나(999/결측) 미노출이 많음")
        if search_volume_month is not None:
            top_drivers.append(f"월검색량: {int(search_volume_month):,} (참고)")
        action_queue.extend(["데이터 수집(최소 14일) 보강", "키워드/상품 URL 등록 상태 점검", "필요 시 SEO/상품 메타 개선 후 재측정"])
        return ("UNCERTAIN", base_conf, rules_triggered, top_drivers, action_queue)

    # STABLE
    try:
        amax = float(st.get("avg_rank_14d_max") or 3.0)
        vmax = float(st.get("rank_volatility_14d_max") or 1.2)
        dmax = int(st.get("down_days_14d_max") or 2)
        if (avg14 is not None and float(avg14) <= amax) and (vol14 is not None and float(vol14) <= vmax) and down14 <= dmax:
            rules_triggered.append(f"stable:avg<={amax}&vol<={vmax}&down14<={dmax}")
            top_drivers.append(f"최근 14일 평균 순위가 안정 범위(≤{amax})")
            top_drivers.append(f"변동성(표준편차) ≤ {vmax}, 악화일 ≤ {dmax}")
            action_queue.extend(["현상 유지(리스크 모니터링)", "리뷰/평점/상품정보 유지관리", "경쟁 상품 변동 감시"])
            return ("STABLE", max(base_conf or 0.0, 0.75), rules_triggered, top_drivers, action_queue)
    except Exception:
        pass

    # WEAK
    try:
        amin = float(wk.get("avg_rank_14d_min") or 11.0)
        ieq = int(wk.get("improve_days_7d_eq") or 0)
        if (avg14 is not None and float(avg14) >= amin) and improve7 == ieq:
            rules_triggered.append(f"weak:avg>={amin}&improve7=={ieq}")
            top_drivers.append(f"최근 14일 평균 순위가 낮음(≥{amin})")
            action_queue.extend(["상품 메타/카테고리/대표키워드 정합성 점검", "콘텐츠/리뷰 확보 계획 수립", "SEO/광고 테스트로 유입 신호 만들기"])
            return ("WEAK", max(base_conf or 0.0, 0.65), rules_triggered, top_drivers, action_queue)
    except Exception:
        pass

    # UNSTABLE
    try:
        rmin = float(un.get("avg_rank_14d_min") or 4.0)
        rmax = float(un.get("avg_rank_14d_max") or 10.0)
        vmin = float(un.get("rank_volatility_14d_min") or 2.0)
        dmin = int(un.get("drop_7d_min") or 3)
        if (
            (avg14 is not None and rmin <= float(avg14) <= rmax)
            or (vol14 is not None and float(vol14) >= vmin)
            or (down7 >= dmin)
        ):
            rules_triggered.append(f"unstable:avg{rmin}~{rmax}|vol>={vmin}|down7>={dmin}")
            top_drivers.append("최근 14일 평균/변동성/악화일 기준으로 불안정 구간")
            if down7 >= dmin:
                top_drivers.append(f"최근 7일 악화일(≥+{int(un.get('drop_delta_min') or 3)})이 기준 이상")
            action_queue.extend(["원인 분해(가격/재고/리뷰/경쟁/노출지면)", "변동 구간에 맞춘 SEO/광고 개입 테스트", "키워드/상품 매칭(카테고리/속성) 재점검"])
            return ("UNSTABLE", max(base_conf or 0.0, 0.6), rules_triggered, top_drivers, action_queue)
    except Exception:
        pass

    rules_triggered.append("default:moderate")
    top_drivers.append("규칙 기반 분류 상 STABLE/UNSTABLE/WEAK에 명확히 속하지 않음")
    action_queue.extend(["추세 관찰(7~14일)", "필요 시 키워드/상품 메타 미세조정", "데이터 수집 지속"])
    return ("UNCERTAIN", base_conf, rules_triggered, top_drivers, action_queue)


@app.post("/ai/analyze/organic-rank/a1/portfolio", response_model=AiAnalyzeOrganicRankA1PortfolioResponse)
def ai_analyze_organic_rank_a1_portfolio(req: AiAnalyzeOrganicRankA1PortfolioRequest, db: Session = Depends(get_db)):
    """
    A-1 포트폴리오 분석:
    - "내 상품 추적"의 상품 리스트(TrackedProductKeyword) + "수기 입력 키워드(후보)"(TrackedProductManualKeyword) 전체를 대상으로
      규칙 기반 판정(STABLE/UNSTABLE/WEAK/UNCERTAIN)을 계산하고,
      GPT로 포트폴리오 요약/우선순위 액션을 생성한다.
    """
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise HTTPException(status_code=400, detail="OPENAI_API_KEY not configured (설정 > API 세팅에서 등록)")

    date_from0, date_to0, days = _resolve_a1_date_range(
        days=int(req.days or 30),
        date_from=getattr(req, "date_from", None),
        date_to=getattr(req, "date_to", None),
        max_days=90,
    )

    max_items = int(req.max_items or 200)
    if max_items < 1:
        max_items = 1
    if max_items > 500:
        max_items = 500

    # 1) 대상: 수기 키워드(후보) 활성 목록
    mk_rows = (
        db.query(TrackedProductManualKeyword)
        .filter(TrackedProductManualKeyword.is_active.is_(True))
        .order_by(TrackedProductManualKeyword.product_url.asc(), TrackedProductManualKeyword.keyword.asc())
        .all()
    )
    pairs: list[tuple[str, str]] = []
    for r in mk_rows:
        u = str(getattr(r, "product_url", "") or "").strip()
        kw = str(getattr(r, "keyword", "") or "").strip()
        if not u or not kw:
            continue
        pairs.append((u, kw))

    # "수기 키워드가 없다"면 추적 키워드로 폴백(최소 동작)
    if not pairs:
        tk_rows = (
            db.query(TrackedProductKeyword)
            .filter(TrackedProductKeyword.is_active.is_(True))
            .order_by(TrackedProductKeyword.product_url.asc(), TrackedProductKeyword.keyword.asc())
            .all()
        )
        for r in tk_rows:
            u = str(getattr(r, "product_url", "") or "").strip()
            kw = str(getattr(r, "keyword", "") or "").strip()
            if not u or not kw:
                continue
            pairs.append((u, kw))

    # 안전장치: 너무 많으면 앞부분만(사용자가 범위를 줄이도록 유도)
    pairs = pairs[:max_items]

    ai_settings = _get_ai_settings(db) or {}
    rule_pack = _a1_pick_rule_text(ai_settings)
    thresholds = _a1_parse_thresholds(rule_pack)

    items: list[AiAnalyzeOrganicRankA1Item] = []
    cnt = {"total": 0, "STABLE": 0, "UNSTABLE": 0, "WEAK": 0, "UNCERTAIN": 0}

    for (u, kw) in pairs:
        s = _a1_compute_rank_summary(db, product_url=u, keyword=kw, days=days)
        metrics = dict(s.get("metrics") or {})
        series = list(s.get("rank_series") or [])
        sv = s.get("search_volume_month")
        # 프론트에서 "광고 여부/키워드 판단"을 빠르게 할 수 있도록 metrics에 포함(호환성 유지)
        try:
            metrics["search_volume_month"] = (int(sv) if sv is not None else None)
        except Exception:
            metrics["search_volume_month"] = None
        decision, confidence, rules_triggered, top_drivers, action_queue = _a1_classify_dynamic(
            metrics,
            series=series,
            search_volume_month=(int(sv) if sv is not None else None),
            thresholds=thresholds,
        )
        cnt["total"] += 1
        cnt[decision] = int(cnt.get(decision, 0)) + 1

        items.append(
            AiAnalyzeOrganicRankA1Item(
                product_url=u,
                keyword=kw,
                decision=decision,
                confidence=confidence,
                rules_triggered=rules_triggered,
                top_drivers=top_drivers[:3],
                action_queue=action_queue[:3],
                metrics=metrics,
            )
        )

    # 정렬: WEAK/UNSTABLE/UNCERTAIN 우선 + avg_rank_14d(큰 값) 우선
    def _prio(d: str) -> int:
        return {"WEAK": 0, "UNSTABLE": 1, "UNCERTAIN": 2, "STABLE": 3}.get(str(d or ""), 9)

    items.sort(
        key=lambda x: (
            _prio(x.decision),
            float((x.metrics or {}).get("avg_rank_14d") or 999.0),
        )
    )

    inputs_snapshot = {
        "analysis_type": "A-1",
        "rules": rule_pack,
        "computed_counts": cnt,
        "computed_items": [
            {
                "product_url": it.product_url,
                "keyword": it.keyword,
                "decision": it.decision,
                "confidence": it.confidence,
                "rules_triggered": it.rules_triggered,
                "top_drivers": it.top_drivers,
                "action_queue": it.action_queue,
                "metrics": it.metrics,
            }
            for it in items[: min(80, len(items))]
        ],
        "requested_at": datetime.utcnow().isoformat() + "Z",
    }
    inputs_hash = _ai_hash_inputs(inputs_snapshot)

    question = str(req.question or "").strip() or (
        "A-1 규칙(정의/목적/입력/규칙/출력)을 기준으로, "
        "전체 포트폴리오를 요약하고(상태 분포), "
        "UNSTABLE/WEAK/UNCERTAIN 우선순위 Top 10과 "
        "실행 액션(1~3순위)을 제시해줘."
    )

    # (중요) 설정의 inputs(JSON)/outputs(출력 템플릿)을 LLM이 확실히 준수하도록
    # 규칙 문서를 별도 메시지로 명시적으로 제공한다.
    rules_doc = _a1_rules_markdown(rule_pack, limit=14000)

    system = (
        "너는 이커머스 오가닉(검색/쇼핑) 순위 분석가다.\n"
        "반드시 제공된 규칙 텍스트(정의/목적/입력/규칙/출력)와 계산된 결과만 근거로 판단한다.\n"
        "규칙에 없는 개념을 임의로 추가하지 않는다.\n"
        "출력은 '규칙 문서'의 출력(템플릿)을 최우선으로 따른다.\n"
        "템플릿이 비어있으면 한국어 Markdown으로:\n"
        "1) 요약(상태 분포)\n"
        "2) 우선순위 Top(WEAK/UNSTABLE/UNCERTAIN)\n"
        "3) 주요 원인 패턴(규칙/지표 근거)\n"
        "4) 액션 큐(1~3순위)\n"
    )

    payload = {
        "model": (str(req.model or "").strip() or OPENAI_DEFAULT_MODEL),
        "temperature": 0.2,
        "messages": [
            {"role": "system", "content": system},
            {"role": "user", "content": "다음은 적용 규칙 문서이다.\n" + rules_doc},
            {"role": "user", "content": "다음은 규칙/계산 결과 요약(JSON)이다.\n" + _ai_json_dumps(inputs_snapshot, limit=16000)},
            {"role": "user", "content": question},
        ],
    }

    content = ""
    portfolio_error: str | None = None
    try:
        resp = requests.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
            json=payload,
            timeout=60,
        )
        if int(resp.status_code) != 200:
            portfolio_error = f"OpenAI 실패({resp.status_code}) {_safe_err_text(resp)}".strip()
        else:
            try:
                j = resp.json() or {}
                choices = j.get("choices") or []
                msg = (choices[0] or {}).get("message") if isinstance(choices, list) and choices else None
                content = str((msg or {}).get("content") or "").strip()
            except Exception:
                content = ""
            if not content:
                portfolio_error = "OpenAI 응답에 content가 없습니다."
    except Exception as e:
        portfolio_error = f"OpenAI 요청 실패: {e}"

    # OpenAI 실패 시에도 규칙 기반 결과(items/counts)는 반환한다(구조적 안정성).
    if portfolio_error:
        content = (
            "## 포트폴리오 요약 생성 실패\n"
            f"- 원인: {portfolio_error}\n\n"
            "규칙 기반 판정 결과는 아래 표를 참고하세요.\n"
        )

    # (옵션) 포트폴리오 로그도 저장(재현/감사)
    try:
        if not portfolio_error:
            pid = str(uuid.uuid4())
            db.add(
                AiDecisionLog(
                    log_id=pid,
                    analysis_type="A-1",
                    entity_type="PORTFOLIO",
                    entity_id="A-1:portfolio",
                    inputs_hash=inputs_hash,
                    inputs_json=_ai_json_dumps(inputs_snapshot),
                    decision=None,
                    rules_triggered=None,
                    confidence=None,
                    recommended_actions=None,
                    analysis_text=content,
                )
            )
            db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass

    return AiAnalyzeOrganicRankA1PortfolioResponse(
        ok=True,
        analysis_type="A-1",
        rules_used={**rule_pack, "parsed_thresholds": thresholds},
        counts=cnt,
        items=items,
        portfolio_analysis=content,
        portfolio_error=portfolio_error,
        inputs_hash=inputs_hash,
    )


def _a1_product_title(db: Session, *, product_url: str) -> str:
    u = str(product_url or "").strip()
    if not u:
        return "(제목 미수집)"
    try:
        filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=u)
        meta = db.query(TrackedProductMeta).filter(or_(*filters)).limit(1).one_or_none()
        t = str(getattr(meta, "title", "") or "").strip() if meta is not None else ""
        return t or "(제목 미수집)"
    except Exception:
        return "(제목 미수집)"


def _a1_band_counts_from_ranks(ranks: list[int | None]) -> dict:
    """
    상품 상태용 밴드 카운트.
    - rank는 1이 최상, 숫자가 작을수록 좋다.
    - 999 이상은 '미노출/결측'으로 취급한다.
    """
    c = {
        "top_1_3": 0,
        "top_4_6": 0,
        "top_7_10": 0,
        "other_11_plus": 0,
        "missing": 0,
        "total": 0,
    }
    for r0 in ranks or []:
        if r0 is None:
            c["missing"] += 1
            c["total"] += 1
            continue
        try:
            r = int(r0)
        except Exception:
            c["missing"] += 1
            c["total"] += 1
            continue
        c["total"] += 1
        if r <= 0 or r >= 999:
            c["missing"] += 1
        elif 1 <= r <= 3:
            c["top_1_3"] += 1
        elif 4 <= r <= 6:
            c["top_4_6"] += 1
        elif 7 <= r <= 10:
            c["top_7_10"] += 1
        else:
            c["other_11_plus"] += 1
    return c


def _a1_status_tier_from_counts(counts: dict) -> str:
    """
    사용자 정의 등급:
    1) 1~3위 키워드 >= 5 -> VERY_STABLE
    2) 4~6위 키워드 >= 5 -> STABLE(집중 관리 필요)
    3) 7~10위 키워드 >= 5 -> RISK(매출 집중 관리 필요)
    4) 그 외 -> NEED_GROWTH
    """
    try:
        top3 = int(counts.get("top_1_3") or 0)
        mid6 = int(counts.get("top_4_6") or 0)
        top10 = int(counts.get("top_7_10") or 0)
    except Exception:
        top3, mid6, top10 = 0, 0, 0
    if top3 >= 5:
        return "VERY_STABLE"
    if mid6 >= 5:
        return "STABLE"
    if top10 >= 5:
        return "RISK"
    return "NEED_GROWTH"


def _a1_status_rank(tier: str) -> int:
    return {"NEED_GROWTH": 0, "RISK": 1, "STABLE": 2, "VERY_STABLE": 3}.get(str(tier or ""), 0)


@app.post("/ai/analyze/organic-rank/a1/products", response_model=AiAnalyzeOrganicRankA1ProductsResponse)
def ai_analyze_organic_rank_a1_products(req: AiAnalyzeOrganicRankA1ProductsRequest, db: Session = Depends(get_db)):
    """
    A-1 상품 중심 요약:
    - 기존 포트폴리오(키워드 중심) 결과를 product_url 기준으로 그룹핑하여,
      상품명(TrackedProductMeta.title) + 핵심 지표만 반환한다.
    - GPT 호출 없음(빠른 탐색/상세 진입용).
    """
    date_from0, date_to0, days = _resolve_a1_date_range(
        days=int(req.days or 30),
        date_from=getattr(req, "date_from", None),
        date_to=getattr(req, "date_to", None),
        max_days=90,
    )

    max_products = int(req.max_products or 200)
    if max_products < 1:
        max_products = 1
    if max_products > 500:
        max_products = 500
    max_kw = int(req.max_keywords_per_product or 30)
    if max_kw < 1:
        max_kw = 1
    if max_kw > 200:
        max_kw = 200

    # 1) 대상 상품: "내 상품 추적"(tracked_product_keyword)에서 활성화된 상품 URL만 사용한다.
    # - 수기 키워드(tracked_product_manual_keyword)는 '상품이 등록된 이후' 확장 메타이므로,
    #   등록되지 않은(또는 삭제된) 상품이 남아있더라도 A-1 상품 리스트에는 노출되면 안 된다.
    tk_urls_raw = (
        db.query(TrackedProductKeyword.product_url)
        .filter(TrackedProductKeyword.is_active.is_(True))
        .order_by(TrackedProductKeyword.created_at.desc())
        .all()
    )
    active_products: list[str] = []
    seen_p = set()
    for (u0,) in tk_urls_raw or []:
        u = str(u0 or "").strip()
        if not u:
            continue
        # smartstore URL은 base로 정규화(쿼리/NaPm 차이 제거)
        u = _canonicalize_smartstore_base_url(u) or u
        if u in seen_p:
            continue
        seen_p.add(u)
        active_products.append(u)

    by_product: dict[str, list[str]] = {}
    for u in active_products[:max_products]:
        # 키워드: 수기 키워드가 있으면 우선 사용, 없으면 tracked_product_keyword를 사용
        kws: list[str] = []
        try:
            mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=u)
            mk_rows = (
                db.query(TrackedProductManualKeyword.keyword)
                .filter(or_(*mk_filters), TrackedProductManualKeyword.is_active.is_(True))
                .order_by(TrackedProductManualKeyword.keyword.asc())
                .all()
            )
            kws = [str(x[0] or "").strip() for x in mk_rows if str(x[0] or "").strip()]
        except Exception:
            kws = []
        if not kws:
            try:
                tk_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=u)
                tk_rows = (
                    db.query(TrackedProductKeyword.keyword)
                    .filter(or_(*tk_filters), TrackedProductKeyword.is_active.is_(True))
                    .order_by(TrackedProductKeyword.keyword.asc())
                    .all()
                )
                kws = [str(x[0] or "").strip() for x in tk_rows if str(x[0] or "").strip()]
            except Exception:
                kws = []
        if kws:
            by_product[u] = kws[:max_kw]

    # 2) 규칙(임계값) 준비
    ai_settings = _get_ai_settings(db) or {}
    rule_pack = _a1_pick_rule_text(ai_settings)
    thresholds = _a1_parse_thresholds(rule_pack)

    # 3) 상품별로 키워드 일부만 계산(요약용)
    def _prio(d: str) -> int:
        return {"WEAK": 0, "UNSTABLE": 1, "UNCERTAIN": 2, "STABLE": 3}.get(str(d or ""), 9)

    products: list[A1ProductSummary] = []
    for u in sorted(by_product.keys())[:max_products]:
        kws = [k for k in by_product.get(u, []) if str(k).strip()]
        # 중복 제거(순서 유지)
        seen = set()
        kws2: list[str] = []
        for k in kws:
            if k in seen:
                continue
            seen.add(k)
            kws2.append(k)
        kws2 = kws2[:max_kw]

        # 키워드별 지표 계산
        kw_rows: list[dict] = []
        for kw in kws2:
            s = _a1_compute_rank_summary(db, product_url=u, keyword=kw, date_from=date_from0, date_to=date_to0, days=days)
            metrics = dict(s.get("metrics") or {})
            series = list(s.get("rank_series") or [])
            sv = s.get("search_volume_month")
            try:
                metrics["search_volume_month"] = (int(sv) if sv is not None else None)
            except Exception:
                metrics["search_volume_month"] = None
            decision, confidence, _rt, _td, _aq = _a1_classify_dynamic(
                metrics,
                series=series,
                search_volume_month=(int(sv) if sv is not None else None),
                thresholds=thresholds,
            )
            try:
                d7 = int(metrics.get("rank_change_7d")) if metrics.get("rank_change_7d") is not None else None
            except Exception:
                d7 = None
            try:
                latest = int(metrics.get("rank_latest")) if metrics.get("rank_latest") is not None else None
            except Exception:
                latest = None
            try:
                down7 = int(metrics.get("down_days_7d")) if metrics.get("down_days_7d") is not None else None
            except Exception:
                down7 = None
            kw_rows.append(
                {
                    "keyword": kw,
                    "decision": decision,
                    "confidence": confidence,
                    "rank_change_7d": d7,
                    "rank_latest": latest,
                    "down_days_7d": down7,
                    "metrics": metrics,
                }
            )

        # rollup(상품 단위)
        decision_rollup = "UNCERTAIN"
        if kw_rows:
            decision_rollup = sorted([str(x.get("decision") or "UNCERTAIN") for x in kw_rows], key=_prio)[0]
        valid_latest = [int(x.get("rank_latest")) for x in kw_rows if isinstance(x.get("rank_latest"), int) and int(x.get("rank_latest")) < 999]
        latest_best = min(valid_latest) if valid_latest else None
        latest_worst = max(valid_latest) if valid_latest else None
        avg14_vals = []
        for x in kw_rows:
            m = x.get("metrics") or {}
            try:
                v = float(m.get("avg_rank_14d")) if m.get("avg_rank_14d") is not None else None
            except Exception:
                v = None
            if v is not None and v < 999:
                avg14_vals.append(v)
        metrics_rollup = {
            "best_rank_latest": latest_best,
            "worst_rank_latest": latest_worst,
            "avg_rank_14d_mean": (sum(avg14_vals) / len(avg14_vals)) if avg14_vals else None,
            "keywords_computed": len(kw_rows),
        }

        # --- 상품 상태(요구사항: 매우 안정적/안정적/위험/성장 필요) ---
        # 현재 rank band
        ranks_curr: list[int | None] = []
        for x in kw_rows:
            rk = x.get("rank_latest")
            ranks_curr.append(rk if isinstance(rk, int) else None)
        band_counts = _a1_band_counts_from_ranks(ranks_curr)
        status_tier = _a1_status_tier_from_counts(band_counts)

        # 전주 대비(7d) 추정: prev_rank = latest - delta_7d (delta 계산 가능 키워드만)
        ranks_prev: list[int | None] = []
        for x in kw_rows:
            latest0 = x.get("rank_latest")
            d70 = x.get("rank_change_7d")
            if not isinstance(latest0, int) or latest0 <= 0 or latest0 >= 999:
                ranks_prev.append(None)
                continue
            if not isinstance(d70, int):
                ranks_prev.append(None)
                continue
            prev = int(latest0) - int(d70)
            if prev <= 0 or prev >= 999:
                ranks_prev.append(None)
            else:
                ranks_prev.append(prev)
        band_counts_prev = _a1_band_counts_from_ranks(ranks_prev)
        status_prev_tier = _a1_status_tier_from_counts(band_counts_prev) if int(band_counts_prev.get("total") or 0) > 0 else None
        status_change = None
        if status_prev_tier is None:
            status_change = "UNKNOWN"
        else:
            a = _a1_status_rank(status_prev_tier)
            b = _a1_status_rank(status_tier)
            status_change = "FLAT" if a == b else ("UP" if b > a else "DOWN")

        # top movers: |Δ7d| 큰 순
        movers = [x for x in kw_rows if isinstance(x.get("rank_change_7d"), int)]
        movers.sort(key=lambda x: abs(int(x.get("rank_change_7d") or 0)), reverse=True)
        top_movers: list[A1ProductTopMover] = []
        for x in movers[:5]:
            top_movers.append(
                A1ProductTopMover(
                    keyword=str(x.get("keyword") or ""),
                    rank_latest=(x.get("rank_latest") if isinstance(x.get("rank_latest"), int) else None),
                    rank_change_7d=(x.get("rank_change_7d") if isinstance(x.get("rank_change_7d"), int) else None),
                    down_days_7d=(x.get("down_days_7d") if isinstance(x.get("down_days_7d"), int) else None),
                    decision=str(x.get("decision") or ""),
                )
            )

        products.append(
            A1ProductSummary(
                product_url=u,
                product_title=_a1_product_title(db, product_url=u),
                keyword_count=len(by_product.get(u, []) or []),
                decision_rollup=str(decision_rollup),
                status_tier=status_tier,
                status_prev_tier=status_prev_tier,
                status_change=status_change,
                band_counts=band_counts,
                band_counts_prev=band_counts_prev,
                metrics_rollup=metrics_rollup,
                top_movers=top_movers,
            )
        )

    # 정렬: WEAK/UNSTABLE/UNCERTAIN 우선 + worst_rank_latest(큰 값) 우선
    products.sort(
        key=lambda p: (
            _prio(p.decision_rollup),
            float((p.metrics_rollup or {}).get("worst_rank_latest") or 999.0),
        )
    )

    return AiAnalyzeOrganicRankA1ProductsResponse(
        ok=True,
        analysis_type="A-1",
        days=days,
        rules_used={**rule_pack, "parsed_thresholds": thresholds},
        product_count=len(products),
        products=products,
    )


@app.get("/ai/analyze/organic-rank/a1/product/detail", response_model=AiAnalyzeOrganicRankA1ProductDetailResponse)
def ai_analyze_organic_rank_a1_product_detail(
    product_url: str = Query(...),
    days: int = Query(30, ge=7, le=90),
    date_from: str | None = Query(None, description="YYYY-MM-DD (optional, overrides days)"),
    date_to: str | None = Query(None, description="YYYY-MM-DD (optional, overrides days)"),
    limit_keywords: int = Query(200, ge=1, le=1000),
    db: Session = Depends(get_db),
):
    """
    A-1 상품 상세(키워드 진단):
    - 최근 순위 변동 키워드(상승/하락)
    - 최근 이슈 지속적 키워드(악화일/변동성 기반)
    - 특정/TopN/전체는 프론트가 필터링할 수 있도록 원본 리스트를 충분히 반환
    """
    u = str(product_url or "").strip()
    if not u:
        raise HTTPException(status_code=400, detail="product_url is required")

    date_from0, date_to0, days0 = _resolve_a1_date_range(days=int(days or 30), date_from=date_from, date_to=date_to, max_days=90)

    # 대상 키워드(수기 우선)
    mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=u)
    mk_rows = (
        db.query(TrackedProductManualKeyword)
        .filter(or_(*mk_filters), TrackedProductManualKeyword.is_active.is_(True))
        .order_by(TrackedProductManualKeyword.keyword.asc())
        .limit(limit_keywords)
        .all()
    )
    kws = [str(getattr(r, "keyword", "") or "").strip() for r in mk_rows if str(getattr(r, "keyword", "") or "").strip()]
    if not kws:
        tk_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=u)
        tk_rows = (
            db.query(TrackedProductKeyword)
            .filter(or_(*tk_filters), TrackedProductKeyword.is_active.is_(True))
            .order_by(TrackedProductKeyword.keyword.asc())
            .limit(limit_keywords)
            .all()
        )
        kws = [str(getattr(r, "keyword", "") or "").strip() for r in tk_rows if str(getattr(r, "keyword", "") or "").strip()]

    # 규칙(임계값) 준비
    ai_settings = _get_ai_settings(db) or {}
    rule_pack = _a1_pick_rule_text(ai_settings)
    thresholds = _a1_parse_thresholds(rule_pack)

    keyword_details: list[dict] = []
    for kw in kws:
        s = _a1_compute_rank_summary(db, product_url=u, keyword=kw, date_from=date_from0, date_to=date_to0, days=days0)
        metrics = dict(s.get("metrics") or {})
        series = list(s.get("rank_series") or [])
        sv = s.get("search_volume_month")
        try:
            metrics["search_volume_month"] = (int(sv) if sv is not None else None)
        except Exception:
            metrics["search_volume_month"] = None

        decision, confidence, rules_triggered, top_drivers, action_queue = _a1_classify_dynamic(
            metrics,
            series=series,
            search_volume_month=(int(sv) if sv is not None else None),
            thresholds=thresholds,
        )

        # trend/issue score(상품 상세에서 빠르게 정렬)
        try:
            d7 = int(metrics.get("rank_change_7d")) if metrics.get("rank_change_7d") is not None else None
        except Exception:
            d7 = None
        trend = "UNKNOWN"
        if isinstance(d7, int):
            if d7 >= 3:
                trend = "DOWN"
            elif d7 <= -3:
                trend = "UP"
            else:
                trend = "FLAT"
        try:
            down7 = int(metrics.get("down_days_7d")) if metrics.get("down_days_7d") is not None else 0
        except Exception:
            down7 = 0
        issue_score = int(down7) * 10 + (int(d7) if isinstance(d7, int) and d7 > 0 else 0)

        series_14 = [{"date": x.get("date"), "rank": x.get("rank")} for x in (series[-14:] if isinstance(series, list) else [])]

        keyword_details.append(
            {
                "keyword": kw,
                "decision": decision,
                "confidence": confidence,
                "rules_triggered": rules_triggered,
                "top_drivers": top_drivers,
                "action_queue": action_queue,
                "metrics": metrics,
                "trend": trend,
                "issue_score": issue_score,
                "rank_series_14d": series_14,
            }
        )

    # 프리셋 리스트(키워드만)
    def _d7_opt(v: dict) -> int | None:
        """
        유효한 Δ7d만 사용한다.
        - 결측/미노출(999)로 인해 delta 계산이 불가능한 경우 None
        """
        try:
            x = (v.get("metrics") or {}).get("rank_change_7d")
            return int(x) if x is not None else None
        except Exception:
            return None

    # (중요) 상승/하락 Top은 "유효한 Δ7d"가 계산 가능한 키워드만 포함한다.
    with_delta = [v for v in keyword_details if _d7_opt(v) is not None]

    # 상승: Δ7d가 가장 작은 것(음수=개선)부터
    movers_up = sorted(with_delta, key=lambda v: int(_d7_opt(v) or 0))[:10]
    # 하락: Δ7d가 가장 큰 것(양수=악화)부터
    movers_down = sorted(with_delta, key=lambda v: int(_d7_opt(v) or 0), reverse=True)[:10]
    issues = sorted(keyword_details, key=lambda v: int(v.get("issue_score") or 0), reverse=True)[:10]

    return AiAnalyzeOrganicRankA1ProductDetailResponse(
        ok=True,
        analysis_type="A-1",
        days=int(days0),
        product_url=u,
        product_title=_a1_product_title(db, product_url=u),
        keyword_count=len(keyword_details),
        keywords=keyword_details,
        movers_up=[str(x.get("keyword") or "") for x in movers_up if str(x.get("keyword") or "").strip()],
        movers_down=[str(x.get("keyword") or "") for x in movers_down if str(x.get("keyword") or "").strip()],
        issues_persistent=[str(x.get("keyword") or "") for x in issues if str(x.get("keyword") or "").strip()],
    )


@app.post("/ai/analyze/organic-rank/a1/product/gpt", response_model=AiAnalyzeOrganicRankA1ProductGptResponse)
def ai_analyze_organic_rank_a1_product_gpt(req: AiAnalyzeOrganicRankA1ProductGptRequest, db: Session = Depends(get_db)):
    """
    A-1 상품 단위 GPT 의뢰 + Trace 생성.
    - (상품) 한 상품(product_url)에 대해 여러 키워드를 묶어 현재 상태/이슈/우선 액션을 생성한다.
    - (검증) 최종 제안은 Trace로 역추적(규칙/원본/요약) 가능해야 한다.
    """
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise HTTPException(status_code=400, detail="OPENAI_API_KEY not configured (설정 > API 세팅에서 등록)")

    date_from0, date_to0, days = _resolve_a1_date_range(
        days=int(req.days or 30),
        date_from=getattr(req, "date_from", None),
        date_to=getattr(req, "date_to", None),
        max_days=90,
    )

    u = str(req.product_url or "").strip()
    if not u:
        raise HTTPException(status_code=400, detail="product_url is required")

    # 1) 키워드 선택
    mode = str(req.keyword_mode or "topN").strip().lower()
    if mode not in ("specific", "topn", "all"):
        mode = "topn"
    top_n = int(req.top_n or 10)
    if top_n < 1:
        top_n = 1
    if top_n > 50:
        top_n = 50

    # 후보 키워드(수기 우선)
    mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=u)
    mk_rows = (
        db.query(TrackedProductManualKeyword)
        .filter(or_(*mk_filters), TrackedProductManualKeyword.is_active.is_(True))
        .order_by(TrackedProductManualKeyword.keyword.asc())
        .limit(1000)
        .all()
    )
    all_kws = [str(getattr(r, "keyword", "") or "").strip() for r in mk_rows if str(getattr(r, "keyword", "") or "").strip()]
    if not all_kws:
        tk_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=u)
        tk_rows = (
            db.query(TrackedProductKeyword)
            .filter(or_(*tk_filters), TrackedProductKeyword.is_active.is_(True))
            .order_by(TrackedProductKeyword.keyword.asc())
            .limit(1000)
            .all()
        )
        all_kws = [str(getattr(r, "keyword", "") or "").strip() for r in tk_rows if str(getattr(r, "keyword", "") or "").strip()]

    all_kws = [k for k in all_kws if k]
    # 중복 제거(순서 유지)
    seen = set()
    uniq_kws: list[str] = []
    for k in all_kws:
        if k in seen:
            continue
        seen.add(k)
        uniq_kws.append(k)

    selected_kws: list[str] = []
    if mode == "specific":
        req_kws = req.keywords or []
        for k in req_kws:
            k0 = str(k or "").strip()
            if not k0:
                continue
            if k0 not in selected_kws:
                selected_kws.append(k0)
        # 사용자가 지정한 키워드가 목록에 없더라도 분석은 허용(수집/매칭 문제 진단에 유리)
        selected_kws = selected_kws[:50]
    elif mode == "all":
        selected_kws = uniq_kws[:50]
    else:
        # topN: 먼저 모든 키워드의 issue_score(가벼운 계산)로 상위 N개 선택
        # - 비용: _a1_compute_rank_summary는 DB 조회이므로, 전체가 너무 많으면 상위 일부만
        candidates = uniq_kws[:200]

        ai_settings0 = _get_ai_settings(db) or {}
        rule_pack0 = _a1_pick_rule_text(ai_settings0)
        thresholds0 = _a1_parse_thresholds(rule_pack0)
        scored: list[tuple[int, str]] = []
        for kw in candidates:
            s = _a1_compute_rank_summary(db, product_url=u, keyword=kw, date_from=date_from0, date_to=date_to0, days=days)
            metrics = dict(s.get("metrics") or {})
            series = list(s.get("rank_series") or [])
            sv = s.get("search_volume_month")
            try:
                metrics["search_volume_month"] = (int(sv) if sv is not None else None)
            except Exception:
                metrics["search_volume_month"] = None
            _d, _c, _rt, _td, _aq = _a1_classify_dynamic(
                metrics,
                series=series,
                search_volume_month=(int(sv) if sv is not None else None),
                thresholds=thresholds0,
            )
            try:
                d7 = int(metrics.get("rank_change_7d")) if metrics.get("rank_change_7d") is not None else 0
            except Exception:
                d7 = 0
            try:
                down7 = int(metrics.get("down_days_7d")) if metrics.get("down_days_7d") is not None else 0
            except Exception:
                down7 = 0
            issue_score = int(down7) * 10 + (int(d7) if int(d7) > 0 else 0)
            scored.append((issue_score, kw))
        scored.sort(key=lambda x: x[0], reverse=True)
        selected_kws = [kw for _s, kw in scored[:top_n]]

    if not selected_kws:
        raise HTTPException(status_code=400, detail="선택 가능한 키워드가 없습니다. 먼저 '내 상품 추적/수기 키워드'를 등록하세요.")

    product_title = _a1_product_title(db, product_url=u)

    # 2) 규칙/요약 생성(선택된 키워드에 대해)
    ai_settings = _get_ai_settings(db) or {}
    rule_pack = _a1_pick_rule_text(ai_settings)
    thresholds = _a1_parse_thresholds(rule_pack)

    kw_summaries: list[dict] = []
    for kw in selected_kws:
        summary = _a1_compute_rank_summary(db, product_url=u, keyword=kw, date_from=date_from0, date_to=date_to0, days=days)
        series = list(summary.get("rank_series") or [])
        series_small = [{"date": x.get("date"), "rank": x.get("rank")} for x in series]
        summary_small = dict(summary)
        summary_small["rank_series"] = series_small

        m = dict((summary_small.get("metrics") or {}))
        try:
            d7 = int(m.get("rank_change_7d")) if m.get("rank_change_7d") is not None else None
        except Exception:
            d7 = None
        trend_dir = "UNKNOWN"
        if d7 is not None:
            if d7 >= 3:
                trend_dir = "DOWN"
            elif d7 <= -3:
                trend_dir = "UP"
            else:
                trend_dir = "FLAT"

        # 데이터 품질
        valid14 = int(m.get("valid_days_14d") or 0)
        miss14 = int(m.get("missing_days_14d") or 0)
        miss_ratio = float(m.get("missing_ratio_14d") or 0.0)
        dq = "GOOD"
        if valid14 < 7:
            dq = "BAD"
        elif miss_ratio >= 0.3:
            dq = "WARN"

        # 간단 광고 후보(키워드별)
        sv = summary_small.get("search_volume_month")
        try:
            sv_i = int(sv) if sv is not None else None
        except Exception:
            sv_i = None
        try:
            avg14 = float(m.get("avg_rank_14d")) if m.get("avg_rank_14d") is not None else None
        except Exception:
            avg14 = None
        should_ads = False
        ads_reason = ""
        if dq == "BAD":
            should_ads = False
            ads_reason = "데이터 품질이 낮아(측정 불가/결측 많음) 광고 판단을 보류"
        else:
            if (avg14 is not None and avg14 >= 7.0) and (sv_i is not None and sv_i >= 500) and trend_dir in ("DOWN", "FLAT"):
                should_ads = True
                ads_reason = "7~20위권이며 검색량이 충분하고 최근 개선 신호가 약함"
            if d7 is not None and d7 >= 10 and (sv_i is not None and sv_i >= 200):
                should_ads = True
                ads_reason = "최근 7일 순위 하락 폭이 커서 방어/회복을 위한 광고 테스트가 필요"

        # 규칙 기반 분류도 포함(상품 단위 GPT에 근거 제공)
        metrics = dict(m)
        series_full = list(summary.get("rank_series") or [])
        decision, confidence, rules_triggered, top_drivers, action_queue = _a1_classify_dynamic(
            metrics,
            series=series_full,
            search_volume_month=sv_i,
            thresholds=thresholds,
        )

        kw_summaries.append(
            {
                "keyword": kw,
                "decision": decision,
                "confidence": confidence,
                "rules_triggered": rules_triggered,
                "top_drivers": top_drivers[:3],
                "action_queue": action_queue[:3],
                "summary": summary_small,
                "derived": {
                    "trend": {"direction": trend_dir, "delta_7d": d7},
                    "data_quality": {"level": dq, "valid_days_14d": valid14, "missing_days_14d": miss14, "missing_ratio_14d": miss_ratio},
                    "ad_recommendation": {"should_run_ads": bool(should_ads), "keyword": kw, "reason": ads_reason},
                },
            }
        )

    # 3) 결정론 액션 템플릿(상품 단위)
    # - 다수 키워드에서 공통적으로 적용 가능한 템플릿만 뽑는다.
    any_bad = any(((x.get("derived") or {}).get("data_quality") or {}).get("level") == "BAD" for x in kw_summaries)
    any_ads = any(bool(((x.get("derived") or {}).get("ad_recommendation") or {}).get("should_run_ads")) for x in kw_summaries)
    # 우선 광고 키워드는 ads 후보 중 'issue score'가 큰 것부터
    def _issue_score(x: dict) -> int:
        try:
            m = ((x.get("summary") or {}).get("metrics") or {})
            d7 = int(m.get("rank_change_7d") or 0)
        except Exception:
            d7 = 0
        try:
            down7 = int(m.get("down_days_7d") or 0)
        except Exception:
            down7 = 0
        return int(down7) * 10 + (int(d7) if int(d7) > 0 else 0)

    ads_kw = None
    ads_reason = ""
    if any_ads:
        cand = [x for x in kw_summaries if bool(((x.get("derived") or {}).get("ad_recommendation") or {}).get("should_run_ads"))]
        cand.sort(key=_issue_score, reverse=True)
        if cand:
            ads_kw = str(cand[0].get("keyword") or "").strip() or None
            ads_reason = str((((cand[0].get("derived") or {}).get("ad_recommendation") or {}).get("reason") or "")).strip()

    action_hints: list[dict] = []
    if any_bad:
        action_hints.append(
            {
                "title": "데이터 수집/매칭 정상화",
                "why": "선택 키워드 중 결측(999/미노출)이 많아 현재 상태를 신뢰하기 어려움",
                "how": "키워드/상품 URL 정규화 확인 → 최근 14일 순위 수집을 먼저 확보",
                "priority": "P0",
                "evidence_refs": ["node:RankRowsQuery", "node:RulesDoc", "node:KeywordSelection"],
            }
        )
    action_hints.append(
        {
            "title": "키워드별 변동/이슈 상위 항목부터 원인 분해",
            "why": "상품 단위로는 '어떤 키워드에서' 문제가 나는지 분해가 핵심",
            "how": "상승/하락/지속 이슈 키워드 TopN을 기준으로 가격/재고/리뷰/경쟁/지면 변화 요인을 분해",
            "priority": "P1",
            "evidence_refs": ["node:RankSummary", "node:RankRowsQuery", "node:RulesDoc"],
        }
    )
    if any_ads and ads_kw:
        action_hints.append(
            {
                "title": "광고 테스트(키워드 집행)",
                "why": ads_reason or "광고를 통해 방어/회복 신호를 빠르게 확인할 필요가 있음",
                "how": f"우선 키워드 '{ads_kw}'로 소액 테스트 후(CTR/CVR) 확장/축소 판단",
                "priority": "P0",
                "evidence_refs": ["node:RankSummary", "node:RankRowsQuery", "node:RulesDoc"],
            }
        )
    else:
        action_hints.append(
            {
                "title": "오가닉 방어(메타/콘텐츠/리뷰)",
                "why": "현재 데이터로는 광고 전환보다 오가닉 방어/개선이 우선",
                "how": "상품명/카테고리/속성 정합성 + 리뷰/상세페이지 신뢰요소 강화",
                "priority": "P1",
                "evidence_refs": ["node:RankSummary", "node:RulesDoc"],
            }
        )

    derived = {"product": {"product_url": u, "product_title": product_title}, "keywords": kw_summaries, "action_hints": action_hints}
    inputs_snapshot = {"analysis_type": "A-1_PRODUCT", "rules": rule_pack, "derived": derived, "requested_at": datetime.utcnow().isoformat() + "Z"}

    question = str(req.question or "").strip() or (
        "상품 단위로 현재 상태를 요약하고(키워드별 상승/하락/지속이슈), "
        "광고 vs 오가닉 방어 중 우선순위를 판단한 뒤, "
        "즉시 실행 가능한 우선 액션 3개를 제안해줘."
    )
    rules_doc = _a1_rules_markdown(rule_pack, limit=14000)

    system = (
        "너는 이커머스 오가닉(검색/쇼핑) 순위 데이터 분석가다.\n"
        "반드시 주어진 규칙/데이터만 근거로 판단하고, 근거 없는 추측은 금지한다.\n"
        "출력은 반드시 JSON 한 덩어리로만 반환한다(설명 텍스트/마크다운 금지).\n"
        "결정론 derived(action_hints/data_quality/trend/ad_recommendation)는 사용자가 검증할 기준이므로 최대한 존중하라.\n"
        "JSON 스키마:\n"
        "{"
        "\"decision\":\"STABLE|UNSTABLE|WEAK|UNCERTAIN\","
        "\"confidence\":0~1,"
        "\"rules_triggered\":[\"...\"] ,"
        "\"recommended_actions\":[{\"title\":string,\"why\":string,\"how\":string,\"priority\":\"P0|P1|P2\",\"evidence_refs\":[string]}],"
        "\"analysis_markdown\":\"...\""
        "}\n"
        "analysis_markdown에는 사람이 읽을 요약을 Markdown으로 써라.\n"
        "evidence_refs는 가능한 한 node:RankRowsQuery, node:RulesDoc 를 포함하라.\n"
    )

    thread_msgs: list[dict] = []
    try:
        raw_thread = (req.thread or [])[-20:]
        for m in raw_thread:
            role = str(getattr(m, "role", "") or "").strip().lower()
            content = str(getattr(m, "content", "") or "").strip()
            if role not in ("user", "assistant"):
                continue
            if not content:
                continue
            if len(content) > 6000:
                content = content[:6000] + "…"
            thread_msgs.append({"role": role, "content": content})
    except Exception:
        thread_msgs = []

    payload = {
        "model": (str(req.model or "").strip() or OPENAI_DEFAULT_MODEL),
        "temperature": 0.2,
        "messages": [
            {"role": "system", "content": system},
            {"role": "user", "content": "다음은 적용 규칙 문서이다.\n" + rules_doc},
            {"role": "user", "content": "다음은 상품/키워드 요약(JSON)이다.\n" + _ai_json_dumps(inputs_snapshot, limit=12000)},
            *thread_msgs,
            {"role": "user", "content": question},
        ],
    }

    try:
        resp = requests.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
            json=payload,
            timeout=60,
        )
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"OpenAI 요청 실패: {e}")
    if int(resp.status_code) != 200:
        raise HTTPException(status_code=502, detail=f"OpenAI 실패({resp.status_code}) {_safe_err_text(resp)}".strip())

    try:
        j = resp.json() or {}
        choices = j.get("choices") or []
        msg = (choices[0] or {}).get("message") if isinstance(choices, list) and choices else None
        content = str((msg or {}).get("content") or "").strip()
    except Exception:
        content = ""
    if not content:
        raise HTTPException(status_code=502, detail="OpenAI 응답에 content가 없습니다.")

    decision = None
    confidence = None
    rules_triggered: list[str] = []
    recommended_actions: list[dict] = []
    analysis_markdown = content
    try:
        obj = json.loads(content)
        if isinstance(obj, dict):
            decision = str(obj.get("decision") or "").strip() or None
            try:
                confidence = float(obj.get("confidence")) if obj.get("confidence") is not None else None
            except Exception:
                confidence = None
            rt = obj.get("rules_triggered") or []
            if isinstance(rt, list):
                rules_triggered = [str(x).strip() for x in rt if str(x).strip()]
            ra = obj.get("recommended_actions") or []
            if isinstance(ra, list):
                for a in ra:
                    if not isinstance(a, dict):
                        continue
                    title = str(a.get("title") or "").strip()
                    if not title:
                        continue
                    why = str(a.get("why") or "").strip()
                    how = str(a.get("how") or "").strip()
                    pr = str(a.get("priority") or "").strip().upper() or "P1"
                    ev = a.get("evidence_refs") if isinstance(a.get("evidence_refs"), list) else ["node:RankRowsQuery", "node:RulesDoc"]
                    recommended_actions.append({"title": title, "why": why, "how": how, "priority": pr, "evidence_refs": ev})
            am = str(obj.get("analysis_markdown") or "").strip()
            if am:
                analysis_markdown = am
    except Exception:
        pass

    if not recommended_actions:
        recommended_actions = [x for x in (action_hints or []) if isinstance(x, dict)]

    # 4) Trace 저장(상품 단위)
    trace_run_id: str | None = None
    trace_sku_id: str | None = None
    try:
        run = create_run(
            db,
            analysis_type="A-1",
            run_date=_today_kst(),
            surface="organic_rank_product",
            action_version="A1_PRODUCT_V1",
            model=(str(req.model or "").strip() or OPENAI_DEFAULT_MODEL),
            status="SUCCESS",
        )
        trace_run_id = str(getattr(run, "run_id", "") or "") or None
        trace_sku_id = u
        if trace_run_id:
            # Product meta
            pm_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps({"product_url": u, "product_title": product_title}))
            n_pm = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="ProductMeta",
                title="상품 메타",
                summary_md="상품명/URL 스냅샷",
                sort_key=15,
                tags={"alias": "ProductMeta"},
                blob=pm_blob,
            )
            # Keyword selection
            ks_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps({"keyword_mode": mode, "selected_keywords": selected_kws, "days": days}))
            n_ks = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="KeywordSelection",
                title="키워드 선택",
                summary_md="상품 상세에서 선택된 키워드 범위/모드",
                sort_key=12,
                tags={"alias": "KeywordSelection"},
                blob=ks_blob,
            )
            # Rules
            rules_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps(rule_pack))
            n_rules = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="RulesDoc",
                title="규칙 문서(A-1)",
                summary_md="AI 세팅 기반 규칙/임계값 스냅샷",
                sort_key=20,
                tags={"alias": "RulesDoc"},
                blob=rules_blob,
            )

            # Rank rows (combined IN query)
            date_from = _today_kst() - timedelta(days=days - 1)
            canonical_base = _canonicalize_smartstore_base_url(u)
            kw_params: dict[str, object] = {}
            kw_placeholders: list[str] = []
            for i, kw in enumerate(selected_kws):
                kname = f"kw{i}"
                kw_placeholders.append(f":{kname}")
                kw_params[kname] = kw
            in_sql = ", ".join(kw_placeholders) if kw_placeholders else "''"
            qsql = (
                "SELECT date, product_url, keyword, rank, source "
                "FROM tracked_product_rank_daily "
                f"WHERE keyword IN ({in_sql}) "
                "AND date >= :date_from AND date <= :date_to "
                "AND (product_url = :u OR product_url = :canonical_base) "
                "ORDER BY date ASC, keyword ASC"
            )
            qparams = {"date_from": str(date_from), "date_to": str(_today_kst()), "u": u, "canonical_base": canonical_base, **kw_params}
            rows = []
            try:
                resq = db.execute(text(qsql), qparams)
                for r in resq.mappings().all():
                    rows.append({k: r.get(k) for k in sorted(r.keys())})
            except Exception:
                rows = []
            rows_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps(rows))
            n_rows = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="RankRowsQuery",
                title="순위 원본 조회(tracked_product_rank_daily)",
                summary_md="선택 키워드 전체 원본 스냅샷(검증 가능)",
                sort_key=10,
                tags={"alias": "RankRowsQuery"},
                query_sql=qsql,
                query_params=qparams,
                blob=rows_blob,
            )

            # Summary
            sum_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps({"product": {"product_url": u, "product_title": product_title}, "keywords": kw_summaries}))
            n_sum = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="RankSummary",
                title="상품 요약/키워드 요약",
                summary_md="키워드별 요약 지표/시계열(축약)",
                sort_key=30,
                tags={"alias": "RankSummary"},
                blob=sum_blob,
            )

            # Action hints
            ah_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps(action_hints))
            n_h = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="ActionHints",
                title="결정론 액션 템플릿",
                summary_md="지표/규칙 기반 우선 액션 후보",
                sort_key=40,
                tags={"alias": "ActionHints"},
                blob=ah_blob,
            )

            # GPT output
            gpt_obj = {
                "decision": decision,
                "confidence": confidence,
                "rules_triggered": rules_triggered,
                "recommended_actions": recommended_actions,
                "analysis_markdown": analysis_markdown,
                "derived": derived,
            }
            gpt_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps(gpt_obj))
            n_g = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="GptOutput",
                title="GPT 결과(JSON)",
                summary_md="추천 액션/설명(구조화)",
                sort_key=50,
                tags={"alias": "GptOutput"},
                blob=gpt_blob,
            )

            # Final
            final_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps({"decision": decision, "recommended_actions": recommended_actions}))
            n_f = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="FinalRecommendation",
                title="최종 제안",
                summary_md=f"결정 {decision or '-'} / 액션 {len(recommended_actions)}개",
                sort_key=0,
                tags={"alias": "FinalRecommendation"},
                blob=final_blob,
            )

            create_edge(db, run_id=trace_run_id, from_node_id=n_f.node_id, to_node_id=n_g.node_id, edge_type="uses", label="GPT")
            create_edge(db, run_id=trace_run_id, from_node_id=n_f.node_id, to_node_id=n_h.node_id, edge_type="uses", label="템플릿")
            create_edge(db, run_id=trace_run_id, from_node_id=n_h.node_id, to_node_id=n_sum.node_id, edge_type="derives_from", label="지표")
            create_edge(db, run_id=trace_run_id, from_node_id=n_sum.node_id, to_node_id=n_rows.node_id, edge_type="derives_from", label="원본")
            create_edge(db, run_id=trace_run_id, from_node_id=n_rows.node_id, to_node_id=n_rules.node_id, edge_type="derives_from", label="규칙")
            create_edge(db, run_id=trace_run_id, from_node_id=n_sum.node_id, to_node_id=n_pm.node_id, edge_type="derives_from", label="상품")
            create_edge(db, run_id=trace_run_id, from_node_id=n_rows.node_id, to_node_id=n_ks.node_id, edge_type="derives_from", label="키워드선택")
    except Exception:
        trace_run_id = None
        trace_sku_id = None

    return AiAnalyzeOrganicRankA1ProductGptResponse(
        ok=True,
        analysis_type="A-1",
        days=days,
        product_url=u,
        product_title=product_title,
        keyword_mode=mode,
        selected_keywords=selected_kws,
        decision=decision,
        confidence=confidence,
        rules_triggered=rules_triggered,
        recommended_actions=recommended_actions,
        analysis_markdown=str(analysis_markdown or ""),
        trace_run_id=trace_run_id,
        trace_sku_id=trace_sku_id,
    )


def _a1_pick_rule_text(ai_settings: dict) -> dict:
    """
    저장된 AI 세팅에서 A-1(또는 A1) 규칙을 찾는다.
    """
    common = str((ai_settings or {}).get("common_rules") or "")
    # v2 우선: rule_packs
    fmt = str((ai_settings or {}).get("format_version") or "").strip().lower()
    if fmt == "v2":
        packs = (ai_settings or {}).get("rule_packs") or []
        if not isinstance(packs, list):
            packs = []
        picked_pack: dict | None = None
        for p in packs:
            rid = str((p or {}).get("id") or "").strip().upper().replace(" ", "").replace("_", "").replace("-", "")
            if rid == "A1":
                if isinstance(p, dict):
                    picked_pack = p
                break
        picked_pack = picked_pack or {}
        a1 = (picked_pack.get("a1") if isinstance(picked_pack, dict) else None) or {}
        tmpl = (a1.get("prompt_templates") if isinstance(a1, dict) else None) or {}
        th = (a1.get("thresholds") if isinstance(a1, dict) else None) or _a1_default_thresholds()
        # v2는 thresholds를 구조화로 들고 있으므로, 기존 파서/로그 호환을 위해 rules를 JSON로 생성한다.
        try:
            rules_text = json.dumps({"thresholds": th}, ensure_ascii=False, indent=2)
        except Exception:
            rules_text = json.dumps({"thresholds": _a1_default_thresholds()}, ensure_ascii=False)
        return {
            "common_rules": common,
            "rule_id": str(picked_pack.get("id") or "A-1"),
            "title": str(picked_pack.get("title") or ""),
            "overview": "",
            "purpose": "",
            "inputs": str((tmpl or {}).get("inputs_json") or ""),
            "rules": rules_text,
            "outputs": str((tmpl or {}).get("outputs_template") or ""),
            # v2 원본도 함께 포함(디버깅/재현/Trace에 유리)
            "config_v2": a1 if isinstance(a1, dict) else {},
        }

    # v1(legacy): analysis_rules
    rules = (ai_settings or {}).get("analysis_rules") or []
    picked = None
    for r in rules:
        rid = str((r or {}).get("id") or "").strip().upper().replace(" ", "")
        if rid in ("A-1", "A1"):
            picked = r
            break
    picked = picked or {}
    return {
        "common_rules": common,
        "rule_id": str(picked.get("id") or "A-1"),
        "title": str(picked.get("title") or ""),
        "overview": str(picked.get("overview") or ""),
        "purpose": str(picked.get("purpose") or ""),
        "inputs": str(picked.get("inputs") or ""),
        "rules": str(picked.get("rules") or ""),
        "outputs": str(picked.get("outputs") or ""),
    }


def _ai_ops_pick_rule_pack(ai_settings: dict, *, mall_name: str | None = None) -> dict:
    fmt = str((ai_settings or {}).get("format_version") or "").strip().lower()
    packs = (ai_settings or {}).get("rule_packs") or []
    if fmt != "v2" or not isinstance(packs, list):
        return {"rule_id": "AI_OPS", "title": "", "scope": _ai_ops_default_scope(), "thresholds": _ai_ops_default_thresholds()}

    normalized_mall = _ai_ops_normalize_name(mall_name)
    global_pack: dict | None = None
    scoped_pack: dict | None = None
    for pack in packs:
        if not isinstance(pack, dict) or not bool((pack or {}).get("enabled", True)):
            continue
        ai_ops = pack.get("ai_ops")
        if not isinstance(ai_ops, dict):
            continue
        scope = ai_ops.get("scope") if isinstance(ai_ops.get("scope"), dict) else {}
        scope_malls = [
            _ai_ops_normalize_name(item)
            for item in ((scope or {}).get("mall_names") or [])
            if str(item or "").strip()
        ]
        scope_malls = [item for item in scope_malls if item]
        if scope_malls and normalized_mall and normalized_mall in scope_malls:
            scoped_pack = pack
            break
        if not scope_malls and global_pack is None:
            global_pack = pack
    picked_pack = scoped_pack or global_pack or {}
    ai_ops = (picked_pack.get("ai_ops") if isinstance(picked_pack, dict) else None) or {}
    scope = _merge_nested_dict(_ai_ops_default_scope(), (ai_ops.get("scope") if isinstance(ai_ops, dict) else None) or {})
    thresholds = _merge_nested_dict(_ai_ops_default_thresholds(), (ai_ops.get("thresholds") if isinstance(ai_ops, dict) else None) or {})
    return {
        "rule_id": str((picked_pack or {}).get("id") or "AI_OPS"),
        "title": str((picked_pack or {}).get("title") or ""),
        "scope": scope,
        "thresholds": thresholds,
    }


def _ai_ops_resolve_thresholds(ai_settings: dict, *, mall_name: str | None = None) -> dict:
    picked = _ai_ops_pick_rule_pack(ai_settings, mall_name=mall_name)
    thresholds = picked.get("thresholds") if isinstance(picked, dict) else None
    return _merge_nested_dict(_ai_ops_default_thresholds(), thresholds if isinstance(thresholds, dict) else {})


def _a1_rules_markdown(rule_pack: dict, *, limit: int = 12000) -> str:
    """
    LLM에 '규칙 문서'를 명시적으로 전달하기 위한 마크다운 텍스트.
    - 사용자가 AI 세팅에 저장한 inputs(JSON 포함)/outputs(출력 템플릿)을 확실히 반영하도록 한다.
    """

    def _clip(s: object, n: int) -> str:
        try:
            t = str(s or "")
        except Exception:
            t = ""
        t = t.strip()
        if n is not None and n > 0 and len(t) > n:
            return t[:n] + "…"
        return t

    common = _clip((rule_pack or {}).get("common_rules"), 6000)
    rid = _clip((rule_pack or {}).get("rule_id"), 200)
    title = _clip((rule_pack or {}).get("title"), 800)
    overview = _clip((rule_pack or {}).get("overview"), 4000)
    purpose = _clip((rule_pack or {}).get("purpose"), 4000)
    inputs = _clip((rule_pack or {}).get("inputs"), 6000)
    rules = _clip((rule_pack or {}).get("rules"), 6000)
    outputs = _clip((rule_pack or {}).get("outputs"), 6000)
    cfg2 = (rule_pack or {}).get("config_v2") or {}

    def _clip_json(obj: object, n: int) -> str:
        try:
            s = json.dumps(obj, ensure_ascii=False, indent=2)
        except Exception:
            s = ""
        s = (s or "").strip()
        if n is not None and n > 0 and len(s) > n:
            return s[:n] + "…"
        return s if s else "(없음)"

    md = (
        "## 공통 규칙\n"
        f"{common if common else '(없음)'}\n\n"
        "## A-1 규칙\n"
        f"- rule_id: {rid or 'A-1'}\n"
        f"- title: {title}\n\n"
        "### 개요\n"
        f"{overview if overview else '(없음)'}\n\n"
        "### 목적\n"
        f"{purpose if purpose else '(없음)'}\n\n"
        "### 입력(설정에 저장된 원문)\n"
        f"{inputs if inputs else '(없음)'}\n\n"
        "### 규칙(임계값/판정 기준)\n"
        f"{rules if rules else '(없음)'}\n\n"
        "### 출력(설정에 저장된 템플릿)\n"
        f"{outputs if outputs else '(없음)'}\n"
    )
    # v2 확장 섹션: 운영자가 조정하는 “기준 숫자”를 규칙 문서에 명시
    if isinstance(cfg2, dict) and cfg2:
        md += "\n\n### v2 확장(지면/전략/품질지수)\n"
        md += "#### 지면 기준(surfaces)\n"
        md += f"{_clip_json((cfg2 or {}).get('surfaces') or {}, 4000)}\n\n"
        md += "#### SKU 전략 기준(sku_strategy)\n"
        md += f"{_clip_json((cfg2 or {}).get('sku_strategy') or {}, 4000)}\n\n"
        md += "#### 품질지수 목표(quality_targets)\n"
        md += f"{_clip_json((cfg2 or {}).get('quality_targets') or {}, 4000)}\n"
    if limit is not None and limit > 0 and len(md) > limit:
        return md[:limit] + "…"
    return md


@app.post("/ai/analyze/organic-rank/a1", response_model=AiAnalyzeOrganicRankA1Response)
def ai_analyze_organic_rank_a1(req: AiAnalyzeOrganicRankA1Request, db: Session = Depends(get_db)):
    """
    A-1. 오가닉(검색/쇼핑) 순위 분석:
    - 설정(AI 세팅)에서 공통 규칙 + A-1 규칙을 읽는다.
    - tracked_product_rank_daily 기반으로 30일 히스토리/지표 요약을 만든다.
    - OpenAI로 분석한다.
    - 판단 로그를 DB(ai_decision_log)에 저장하고 반환한다.
    """
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise HTTPException(status_code=400, detail="OPENAI_API_KEY not configured (설정 > API 세팅에서 등록)")

    days = int(req.days or 30)
    if days < 7:
        raise HTTPException(status_code=400, detail="days must be >= 7")
    if days > 90:
        raise HTTPException(status_code=400, detail="days too large (max 90)")

    u = str(req.product_url or "").strip()
    kw = str(req.keyword or "").strip()
    if not u or not kw:
        raise HTTPException(status_code=400, detail="product_url and keyword are required")

    ai_settings = _get_ai_settings(db) or {}
    rule_pack = _a1_pick_rule_text(ai_settings)
    summary = _a1_compute_rank_summary(db, product_url=u, keyword=kw, days=days)

    # LLM 입력 크기 제한(안전): rank_series는 최대 90일이지만, payload에는 핵심만 포함
    series = list(summary.get("rank_series") or [])
    # 날짜/순위만 유지
    series_small = [{"date": x.get("date"), "rank": x.get("rank")} for x in series]
    summary_small = dict(summary)
    summary_small["rank_series"] = series_small

    # 결정론 파생(사용자 검증/행동결정용)
    m = dict((summary_small.get("metrics") or {}))
    try:
        d7 = int(m.get("rank_change_7d")) if m.get("rank_change_7d") is not None else None
    except Exception:
        d7 = None
    try:
        d1 = int(m.get("rank_change_1d")) if m.get("rank_change_1d") is not None else None
    except Exception:
        d1 = None
    trend_dir = "UNKNOWN"
    if d7 is not None:
        if d7 >= 3:
            trend_dir = "DOWN"  # 순위 숫자 증가 = 악화
        elif d7 <= -3:
            trend_dir = "UP"  # 순위 숫자 감소 = 개선
        else:
            trend_dir = "FLAT"
    # 데이터 품질
    valid14 = int(m.get("valid_days_14d") or 0)
    miss14 = int(m.get("missing_days_14d") or 0)
    miss_ratio = float(m.get("missing_ratio_14d") or 0.0)
    data_quality_level = "GOOD"
    dq_reasons: list[str] = []
    if valid14 < 7:
        data_quality_level = "BAD"
        dq_reasons.append(f"최근 14일 유효 데이터가 부족({valid14}/14)")
    elif miss_ratio >= 0.3:
        data_quality_level = "WARN"
        dq_reasons.append(f"최근 14일 결측 비율이 높음({miss14}/14)")

    # 광고/오가닉 결정(결정론, 기본 휴리스틱)
    # - 이 값은 이후 AI 세팅(v2)에 기준을 추가해 정교화 가능
    sv = summary_small.get("search_volume_month")
    try:
        sv_i = int(sv) if sv is not None else None
    except Exception:
        sv_i = None
    avg14 = None
    try:
        avg14 = float(m.get("avg_rank_14d")) if m.get("avg_rank_14d") is not None else None
    except Exception:
        avg14 = None

    should_run_ads = False
    ads_reason = ""
    if data_quality_level == "BAD":
        should_run_ads = False
        ads_reason = "데이터 품질이 낮아(측정 불가/결측 많음) 광고 판단을 보류"
    else:
        if (avg14 is not None and avg14 >= 7.0) and (sv_i is not None and sv_i >= 500):
            # 7~20위권(성장 여지) + 검색량 충분
            if trend_dir in ("DOWN", "FLAT"):
                should_run_ads = True
                ads_reason = "7~20위권이며 검색량이 충분하고 최근 개선 신호가 약함"
        if d7 is not None and d7 >= 10 and (sv_i is not None and sv_i >= 200):
            should_run_ads = True
            ads_reason = "최근 7일 순위 하락 폭이 커서 방어/회복을 위한 광고 테스트가 필요"

    action_hints = []
    # 데이터 품질이 BAD면 우선 수집/매칭 개선
    if data_quality_level == "BAD":
        action_hints.append(
            {
                "title": "데이터 수집/매칭 정상화",
                "why": "순위 데이터 결측이 많아 현재 상태를 신뢰하기 어려움",
                "how": "키워드/상품 URL 정규화 확인 → 최근 14일 순위 수집을 먼저 확보",
                "priority": "P0",
                "evidence_refs": ["node:RankRowsQuery", "node:RulesDoc"],
            }
        )
    else:
        action_hints.append(
            {
                "title": "최근 추세 점검 및 원인 분해",
                "why": f"최근 7일 추세: {trend_dir} (Δ7d={d7})",
                "how": "가격/재고/리뷰/경쟁/지면 변화(광고 슬롯) 요인을 분해",
                "priority": "P1",
                "evidence_refs": ["node:RankRowsQuery", "node:RulesDoc"],
            }
        )
        if should_run_ads:
            action_hints.append(
                {
                    "title": "광고 테스트(키워드 집행)",
                    "why": ads_reason,
                    "how": f"우선 키워드 '{kw}'로 소액 테스트 후(CTR/CVR) 확장/축소 판단",
                    "priority": "P0",
                    "evidence_refs": ["node:RankRowsQuery", "node:RulesDoc"],
                }
            )
        else:
            action_hints.append(
                {
                    "title": "오가닉 방어(메타/콘텐츠/리뷰)",
                    "why": "현재 데이터로는 광고 전환보다 오가닉 방어/개선이 우선",
                    "how": "상품명/카테고리/속성 정합성 + 리뷰/상세페이지 신뢰요소 강화",
                    "priority": "P1",
                    "evidence_refs": ["node:RankRowsQuery", "node:RulesDoc"],
                }
            )

    derived = {
        "trend": {"direction": trend_dir, "delta_7d": d7, "delta_1d": d1},
        "data_quality": {"level": data_quality_level, "valid_days_14d": valid14, "missing_days_14d": miss14, "missing_ratio_14d": miss_ratio, "reasons": dq_reasons},
        "ad_recommendation": {"should_run_ads": bool(should_run_ads), "keyword": kw, "reason": ads_reason},
        "action_hints": action_hints,
    }

    inputs_snapshot = {
        "analysis_type": "A-1",
        "rules": rule_pack,
        "data": summary_small,
        "derived": derived,
        "requested_at": datetime.utcnow().isoformat() + "Z",
    }
    inputs_hash = _ai_hash_inputs(inputs_snapshot)

    entity_type = "SKU"
    entity_id = f"{u}||{kw}"

    # NOTE: 단건 분석은 "검증(Trace)"가 핵심이므로, 캐시가 있어도 trace를 생성해야 한다.
    # 따라서 캐시 단축 반환은 사용하지 않는다(비용이 크면 향후 '캐시 사용 + trace 생성'으로 최적화 가능).

    question = (str(req.question or "").strip() or "A-1 규칙에 따라 현재 상태(STABLE/UNSTABLE/WEAK/UNCERTAIN)를 판정하고, 주요 원인 3개와 우선 액션 3개를 제시해줘.")
    rules_doc = _a1_rules_markdown(rule_pack, limit=14000)
    system = (
        "너는 이커머스 오가닉(검색/쇼핑) 순위 데이터 분석가다.\n"
        "반드시 주어진 규칙/데이터만 근거로 판단하고, 근거 없는 추측은 금지한다.\n"
        "출력은 반드시 JSON 한 덩어리로만 반환한다(설명 텍스트/마크다운 금지).\n"
        "결정론 derived(action_hints/data_quality/trend/ad_recommendation)는 사용자가 검증할 기준이므로 최대한 존중하라.\n"
        "JSON 스키마:\n"
        "{"
        "\"decision\":\"STABLE|UNSTABLE|WEAK|UNCERTAIN\","
        "\"confidence\":0~1,"
        "\"rules_triggered\":[\"...\"] ,"
        "\"trend\":{\"direction\":\"UP|DOWN|FLAT|UNKNOWN\",\"delta_7d\":number|null,\"delta_1d\":number|null},"
        "\"ad_recommendation\":{\"should_run_ads\":boolean,\"keywords\":[{\"keyword\":string,\"priority\":\"P0|P1|P2\",\"why\":string,\"evidence_refs\":[string]}]},"
        "\"recommended_actions\":[{\"title\":string,\"why\":string,\"how\":string,\"priority\":\"P0|P1|P2\",\"evidence_refs\":[string]}],"
        "\"analysis_markdown\":\"...\""
        "}\n"
        "analysis_markdown에는 사람이 읽을 요약을 Markdown으로 써라.\n"
        "analysis_markdown은 '규칙 문서'의 출력(템플릿)이 있으면 그 형식을 따른다.\n"
        "evidence_refs는 가능한 한 node:RankRowsQuery, node:RulesDoc 를 포함하라.\n"
    )

    thread_msgs: list[dict] = []
    try:
        raw_thread = (req.thread or [])[-20:]
        for m in raw_thread:
            role = str(getattr(m, "role", "") or "").strip().lower()
            content = str(getattr(m, "content", "") or "").strip()
            if role not in ("user", "assistant"):
                continue
            if not content:
                continue
            if len(content) > 6000:
                content = content[:6000] + "…"
            thread_msgs.append({"role": role, "content": content})
    except Exception:
        thread_msgs = []

    payload = {
        "model": (str(req.model or "").strip() or OPENAI_DEFAULT_MODEL),
        "temperature": 0.2,
        "messages": [
            {"role": "system", "content": system},
            {"role": "user", "content": "다음은 적용 규칙 문서이다.\n" + rules_doc},
            {"role": "user", "content": "다음은 공통 규칙/개별 규칙과 데이터 요약(JSON)이다.\n" + _ai_json_dumps(inputs_snapshot, limit=12000)},
            *thread_msgs,
            {"role": "user", "content": question},
        ],
    }

    try:
        resp = requests.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
            json=payload,
            timeout=60,
        )
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"OpenAI 요청 실패: {e}")

    if int(resp.status_code) != 200:
        raise HTTPException(status_code=502, detail=f"OpenAI 실패({resp.status_code}) {_safe_err_text(resp)}".strip())

    try:
        j = resp.json() or {}
        choices = j.get("choices") or []
        msg = (choices[0] or {}).get("message") if isinstance(choices, list) and choices else None
        content = str((msg or {}).get("content") or "").strip()
    except Exception:
        content = ""
    if not content:
        raise HTTPException(status_code=502, detail="OpenAI 응답에 content가 없습니다.")

    # JSON 파싱(실패 시 최소 폴백)
    decision = None
    confidence = None
    rules_triggered: list[str] = []
    actions: list[str] = []
    recommended_actions_v2: list[dict] = []
    analysis_markdown = content
    try:
        obj = json.loads(content)
        if isinstance(obj, dict):
            decision = str(obj.get("decision") or "").strip() or None
            try:
                confidence = float(obj.get("confidence")) if obj.get("confidence") is not None else None
            except Exception:
                confidence = None
            rt = obj.get("rules_triggered") or []
            if isinstance(rt, list):
                rules_triggered = [str(x).strip() for x in rt if str(x).strip()]
            ra2 = obj.get("recommended_actions") or []
            if isinstance(ra2, list):
                for a in ra2:
                    if not isinstance(a, dict):
                        continue
                    title = str(a.get("title") or "").strip()
                    if not title:
                        continue
                    why = str(a.get("why") or "").strip()
                    how = str(a.get("how") or "").strip()
                    pr = str(a.get("priority") or "").strip().upper() or "P1"
                    ev = a.get("evidence_refs") if isinstance(a.get("evidence_refs"), list) else ["node:RankRowsQuery", "node:RulesDoc"]
                    recommended_actions_v2.append({"title": title, "why": why, "how": how, "priority": pr, "evidence_refs": ev})
                actions = [str(x.get("title") or "").strip() for x in recommended_actions_v2 if str(x.get("title") or "").strip()]
            am = str(obj.get("analysis_markdown") or "").strip()
            if am:
                analysis_markdown = am
    except Exception:
        pass

    # LLM이 비우거나 실패해도 UX/검증이 끊기지 않도록 결정론 action_hints로 보강
    if not recommended_actions_v2:
        recommended_actions_v2 = [x for x in (action_hints or []) if isinstance(x, dict)]
        actions = [str(x.get("title") or "").strip() for x in recommended_actions_v2 if str(x.get("title") or "").strip()]

    log_id = str(uuid.uuid4())
    try:
        db.add(
            AiDecisionLog(
                log_id=log_id,
                analysis_type="A-1",
                entity_type=entity_type,
                entity_id=entity_id,
                inputs_hash=inputs_hash,
                inputs_json=_ai_json_dumps(inputs_snapshot),
                decision=decision,
                rules_triggered=_ai_json_dumps(rules_triggered),
                confidence=confidence,
                recommended_actions=_ai_json_dumps(actions),
                analysis_text=str(analysis_markdown or ""),
            )
        )
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass

    # --- Trace 저장(역추적 검증) ---
    trace_run_id: str | None = None
    trace_sku_id: str | None = None
    try:
        run = create_run(
            db,
            analysis_type="A-1",
            run_date=_today_kst(),
            surface="organic_rank",
            action_version="A1_ITEM_V1",
            model=(str(req.model or "").strip() or OPENAI_DEFAULT_MODEL),
            status="SUCCESS",
        )
        trace_run_id = str(getattr(run, "run_id", "") or "") or None
        trace_sku_id = entity_id
        if trace_run_id:
            # Rules
            rules_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps(rule_pack))
            n_rules = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="RulesDoc",
                title="규칙 문서(A-1)",
                summary_md="AI 세팅 기반 규칙/임계값 스냅샷",
                sort_key=20,
                tags={"alias": "RulesDoc"},
                blob=rules_blob,
            )
            # Raw rank rows (verify)
            date_from = _today_kst() - timedelta(days=days - 1)
            canonical_base = _canonicalize_smartstore_base_url(u)
            qsql = "SELECT date, product_url, keyword, rank, source FROM tracked_product_rank_daily WHERE keyword = :kw AND date >= :date_from AND date <= :date_to AND (product_url = :u OR product_url = :canonical_base)"
            qparams = {"kw": kw, "date_from": date_from, "date_to": _today_kst(), "u": u, "canonical_base": canonical_base}
            rows = []
            try:
                resq = db.execute(text(qsql), qparams)
                for r in resq.mappings().all():
                    rows.append({k: r.get(k) for k in sorted(r.keys())})
            except Exception:
                rows = []
            rows_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps(rows))
            n_rows = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="RankRowsQuery",
                title="순위 원본 조회(tracked_product_rank_daily)",
                summary_md="오가닉 순위 원본 스냅샷(검증 가능)",
                sort_key=10,
                tags={"alias": "RankRowsQuery"},
                query_sql=qsql,
                query_params=qparams,
                blob=rows_blob,
            )
            # Summary
            sum_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps(summary_small))
            n_sum = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="RankSummary",
                title="요약 지표/시계열(축약)",
                summary_md="rank_latest/avg14/vol14/변동/결측 등",
                sort_key=30,
                tags={"alias": "RankSummary"},
                blob=sum_blob,
            )
            # Action hints
            ah_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps(action_hints))
            n_h = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="ActionHints",
                title="결정론 액션 템플릿",
                summary_md="지표/규칙 기반 우선 액션 후보",
                sort_key=40,
                tags={"alias": "ActionHints"},
                blob=ah_blob,
            )
            # GPT output (structured)
            gpt_obj = {
                "decision": decision,
                "confidence": confidence,
                "rules_triggered": rules_triggered,
                "recommended_actions": recommended_actions_v2,
                "analysis_markdown": analysis_markdown,
                "derived": derived,
            }
            gpt_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps(gpt_obj))
            n_g = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="GptOutput",
                title="GPT 결과(JSON)",
                summary_md="추천 액션/설명(구조화)",
                sort_key=50,
                tags={"alias": "GptOutput"},
                blob=gpt_blob,
            )
            # Final node
            final_blob = upsert_blob(db, content_type="json", content_text=canonical_json_dumps({"decision": decision, "recommended_actions": recommended_actions_v2}))
            n_f = create_node(
                db,
                run_id=trace_run_id,
                sku_id=trace_sku_id,
                node_type="FinalRecommendation",
                title="최종 제안",
                summary_md=f"결정 {decision or '-'} / 액션 {len(recommended_actions_v2)}개",
                sort_key=0,
                tags={"alias": "FinalRecommendation"},
                blob=final_blob,
            )
            create_edge(db, run_id=trace_run_id, from_node_id=n_f.node_id, to_node_id=n_g.node_id, edge_type="uses", label="GPT")
            create_edge(db, run_id=trace_run_id, from_node_id=n_f.node_id, to_node_id=n_h.node_id, edge_type="uses", label="템플릿")
            create_edge(db, run_id=trace_run_id, from_node_id=n_h.node_id, to_node_id=n_sum.node_id, edge_type="derives_from", label="지표")
            create_edge(db, run_id=trace_run_id, from_node_id=n_sum.node_id, to_node_id=n_rows.node_id, edge_type="derives_from", label="원본")
            create_edge(db, run_id=trace_run_id, from_node_id=n_rows.node_id, to_node_id=n_rules.node_id, edge_type="derives_from", label="규칙")
    except Exception:
        trace_run_id = None
        trace_sku_id = None

    return AiAnalyzeOrganicRankA1Response(
        ok=True,
        analysis_type="A-1",
        entity_type=entity_type,
        entity_id=entity_id,
        log_id=log_id,
        decision=decision,
        confidence=confidence,
        rules_triggered=rules_triggered,
        recommended_actions=actions,
        analysis=str(analysis_markdown or ""),
        summary=summary_small,
        trace_run_id=trace_run_id,
        trace_sku_id=trace_sku_id,
    )


@app.get("/ai/analyze/organic-rank/a1/latest", response_model=AiAnalyzeOrganicRankA1Response)
def ai_analyze_organic_rank_a1_latest(
    product_url: str = Query(...),
    keyword: str = Query(...),
    db: Session = Depends(get_db),
):
    u = str(product_url or "").strip()
    kw = str(keyword or "").strip()
    if not u or not kw:
        raise HTTPException(status_code=400, detail="product_url and keyword are required")

    entity_type = "SKU"
    entity_id = f"{u}||{kw}"
    row = (
        db.query(AiDecisionLog)
        .filter(AiDecisionLog.analysis_type == "A-1", AiDecisionLog.entity_id == entity_id)
        .order_by(AiDecisionLog.created_at.desc())
        .limit(1)
        .one_or_none()
    )
    if row is None:
        return AiAnalyzeOrganicRankA1Response(
            ok=True,
            analysis_type="A-1",
            entity_type=entity_type,
            entity_id=entity_id,
            log_id=None,
            analysis="",
            summary={},
        )

    try:
        rt = json.loads(getattr(row, "rules_triggered", "") or "[]") if getattr(row, "rules_triggered", None) else []
    except Exception:
        rt = []
    try:
        ra = json.loads(getattr(row, "recommended_actions", "") or "[]") if getattr(row, "recommended_actions", None) else []
    except Exception:
        ra = []
    summary = {}
    try:
        snap = json.loads(getattr(row, "inputs_json", "") or "{}")
        summary = (snap or {}).get("data") or {}
    except Exception:
        summary = {}

    return AiAnalyzeOrganicRankA1Response(
        ok=True,
        analysis_type="A-1",
        entity_type=entity_type,
        entity_id=entity_id,
        log_id=str(getattr(row, "log_id", "") or ""),
        decision=str(getattr(row, "decision", None) or None),
        confidence=(float(getattr(row, "confidence", 0.0)) if getattr(row, "confidence", None) is not None else None),
        rules_triggered=[str(x) for x in (rt or []) if str(x).strip()],
        recommended_actions=[str(x) for x in (ra or []) if str(x).strip()],
        analysis=str(getattr(row, "analysis_text", "") or ""),
        summary=summary,
    )


@app.post("/ai/a1/batch/run", response_model=A1BatchRunResponse)
def ai_a1_batch_run(req: A1BatchRunRequest, db: Session = Depends(get_db)):
    """
    A-1 전일 배치:
    - (자동화) sku_event_daily에서 HIGH/CRITICAL SKU만 선별
    - (자동화) payload_json 구성(상태/이벤트/근거 수치)
    - (GPT) 원인 후보/추천 액션 생성(단정 금지)
    - gpt_action_daily 저장
    """
    target_date = req.date or (_today_kst() - timedelta(days=1))
    surface = str(req.surface or "").strip() or "mobile_integrated"

    key = _get_api_setting("OPENAI_API_KEY")
    if (not str(key or "").strip()) and (not bool(req.dry_run)):
        raise HTTPException(status_code=400, detail="OPENAI_API_KEY not configured (설정 > API 세팅에서 등록)")

    r = run_a1_batch(db, api_key=str(key or ""), req=req, target_date=target_date)

    return A1BatchRunResponse(
        ok=True,
        date=target_date.isoformat(),
        surface=surface,
        target_skus=len(r.target_skus),
        processed=int(r.processed or 0),
        saved=int(r.saved or 0),
        failed=int(r.failed or 0),
        items=[{"sku_id": x.get("sku_id"), "status": x.get("status"), "error": x.get("error")} for x in (r.items or [])],
        trace_run_id=str(getattr(r, "trace_run_id", None) or "") or None,
    )


