def _safe_err_text(resp: requests.Response, limit: int = 300) -> str:
    try:
        t = str(resp.text or "")
    except Exception:
        return ""
    t = t.replace("\n", " ").replace("\r", " ").strip()
    if len(t) > limit:
        return t[:limit] + "…"
    return t


NAVER_COMMERCE_TOKEN_URL = "https://api.commerce.naver.com/external/v1/oauth2/token"
NAVER_COMMERCE_TOKEN_URL_NO_EXTERNAL = "https://api.commerce.naver.com/v1/oauth2/token"
NAVER_COMMERCE_API_BASE = "https://api.commerce.naver.com/external"

# 커머스 API 토큰은 짧은 TTL을 갖는 경우가 많아, best-effort 캐시를 둔다.
_NAVER_COMMERCE_TOKEN_CACHE: dict = {"token": None, "fetched_at": 0.0}


def _naver_commerce_get_access_token_cached(*, force_refresh: bool = False) -> str | None:
    cid = _get_api_setting("NAVER_COMMERCE_CLIENT_ID")
    csec = _get_api_setting("NAVER_COMMERCE_CLIENT_SECRET")
    if not cid or not csec:
        return None
    now = float(time.time())
    try:
        token = str((_NAVER_COMMERCE_TOKEN_CACHE.get("token") or "")).strip()
        fetched_at = float(_NAVER_COMMERCE_TOKEN_CACHE.get("fetched_at") or 0.0)
    except Exception:
        token = ""
        fetched_at = 0.0
    # 문서에 expires_in이 명시되지 않아, 운영에서 안전한 보수값(약 15분)로 캐시한다.
    if (not force_refresh) and token and (now - fetched_at) < 15 * 60:
        return token
    tok, meta = _naver_commerce_fetch_access_token(token_url=NAVER_COMMERCE_TOKEN_URL, client_id=cid, client_secret=csec)
    if tok:
        _NAVER_COMMERCE_TOKEN_CACHE["token"] = tok
        _NAVER_COMMERCE_TOKEN_CACHE["fetched_at"] = now
        return tok
    # 토큰 발급 실패 시 캐시는 비운다.
    _NAVER_COMMERCE_TOKEN_CACHE["token"] = None
    _NAVER_COMMERCE_TOKEN_CACHE["fetched_at"] = 0.0
    _ = meta
    return None


def _raise_naver_commerce_token_error(meta: dict | None) -> None:
    info = meta if isinstance(meta, dict) else {}
    status_code = info.get("status_code")
    try:
        sc = int(status_code) if status_code is not None else 502
    except Exception:
        sc = 502
    sc = max(400, min(599, sc))
    msg = str(info.get("message") or "naver_commerce_token_failed").strip() or "naver_commerce_token_failed"
    if sc == 403 and _looks_like_ip_not_allowed(msg):
        raise HTTPException(
            status_code=403,
            detail="GW.IP_NOT_ALLOWED: 커머스 API 센터에서 허용 IP에 현재 실행 환경의 공인 IP를 추가해야 합니다.",
        )
    raise HTTPException(status_code=sc, detail=msg)


def _naver_commerce_require_access_token(*, force_refresh: bool = False) -> str:
    cid = _get_api_setting("NAVER_COMMERCE_CLIENT_ID")
    csec = _get_api_setting("NAVER_COMMERCE_CLIENT_SECRET")
    if not cid or not csec:
        raise HTTPException(status_code=400, detail="NAVER_COMMERCE_CLIENT_ID/SECRET not configured")

    now = float(time.time())
    try:
        token = str((_NAVER_COMMERCE_TOKEN_CACHE.get("token") or "")).strip()
        fetched_at = float(_NAVER_COMMERCE_TOKEN_CACHE.get("fetched_at") or 0.0)
    except Exception:
        token = ""
        fetched_at = 0.0
    if (not force_refresh) and token and (now - fetched_at) < 15 * 60:
        return token

    tok, meta = _naver_commerce_fetch_access_token(
        token_url=NAVER_COMMERCE_TOKEN_URL,
        client_id=cid,
        client_secret=csec,
    )
    if tok:
        _NAVER_COMMERCE_TOKEN_CACHE["token"] = tok
        _NAVER_COMMERCE_TOKEN_CACHE["fetched_at"] = now
        return tok

    _NAVER_COMMERCE_TOKEN_CACHE["token"] = None
    _NAVER_COMMERCE_TOKEN_CACHE["fetched_at"] = 0.0
    _raise_naver_commerce_token_error(meta)
    raise HTTPException(status_code=502, detail="naver_commerce_token_failed")


def _naver_commerce_get_json(*, path: str, access_token: str, timeout_sec: float = 8.0) -> tuple[int | None, dict | None, str | None]:
    """
    커머스 API GET(JSON) best-effort 래퍼.
    - 반환: (status_code, json_dict_or_none, error_text_or_none)
    """
    p = str(path or "").strip()
    if not p.startswith("/"):
        p = "/" + p
    url = NAVER_COMMERCE_API_BASE.rstrip("/") + p
    try:
        resp = requests.get(
            url,
            headers={"Authorization": f"Bearer {access_token}", "Accept": "application/json"},
            timeout=float(timeout_sec),
        )
    except Exception as e:
        return None, None, f"request_failed: {type(e).__name__}: {e}"
    try:
        sc = int(resp.status_code)
    except Exception:
        sc = None
    if sc != 200:
        # 401은 GW.AUTHN(토큰 만료)일 수 있어 호출자에서 재시도할 수 있다.
        return sc, None, _safe_err_text(resp)
    try:
        j = resp.json()
    except Exception:
        j = None
    return sc, j if isinstance(j, dict) else ({"_raw": j} if j is not None else None), None


def _naver_commerce_unwrap_product_obj(j: dict | None) -> dict | None:
    if not isinstance(j, dict):
        return None
    # 문서/버전별 wrapper 차이를 best-effort로 흡수
    for k in ("originProduct", "origin_product", "channelProduct", "channel_product", "product"):
        v = j.get(k)
        if isinstance(v, dict):
            return v
    return j


def _parse_iso_date_only(value: object) -> date | None:
    """
    커머스 API는 ISO8601(+09:00) 형태가 많아, date 부분만 추출한다.
    """
    s = str(value or "").strip()
    if not s:
        return None
    # "YYYY-MM-DD" 또는 "YYYY-MM-DDTHH:MM:SS..." 모두 지원
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})", s)
    if not m:
        return None
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except Exception:
        return None


def _map_commerce_product_to_page_meta(j: dict | None) -> dict:
    """
    커머스 API 상품 응답을 page-metrics(meta)로 매핑한다.
    - title/price/registered_date/delivery 만 다룬다(나머지는 기존 크롤링/다른 API 유지).
    """
    obj = _naver_commerce_unwrap_product_obj(j)
    if not isinstance(obj, dict):
        return {}
    title = str(obj.get("name") or "").strip() or None
    price = obj.get("salePrice")
    try:
        price_i = int(price) if price is not None else None
    except Exception:
        price_i = None
    # saleStartDate가 실제 등록일과 다를 수 있으나, page-metrics에서 '등록일'은 best-effort이므로 date 부분만 사용한다.
    reg = _parse_iso_date_only(obj.get("saleStartDate") or obj.get("createdDate") or obj.get("created_at"))

    delivery = None
    try:
        fee_type = (
            (((obj.get("deliveryInfo") or {}) if isinstance(obj.get("deliveryInfo"), dict) else {}).get("deliveryFee") or {})
            if isinstance(((obj.get("deliveryInfo") or {}) if isinstance(obj.get("deliveryInfo"), dict) else {}).get("deliveryFee"), dict)
            else {}
        ).get("deliveryFeeType")
        ft = str(fee_type or "").strip().upper()
        if ft == "FREE":
            delivery = "무료배송"
        elif ft == "CONDITIONAL_FREE":
            delivery = "조건부 무료"
        elif ft == "CHARGE":
            delivery = "유료배송"
        elif ft:
            delivery = f"배송({ft})"
    except Exception:
        delivery = None

    out = {}
    if title:
        out["title"] = title
    if price_i is not None:
        out["price"] = price_i
    if reg is not None:
        out["registered_date"] = reg
    if delivery:
        out["delivery"] = delivery
    return out


def _naver_commerce_fetch_product_page_meta(product_url: str) -> dict:
    """
    SmartStore URL(/products/<id>) → 커머스 API 상품 메타(title/price/registered_date/delivery) best-effort.
    실패해도 page-metrics 전체 수집이 막히지 않도록 항상 dict를 반환한다.
    """
    pid = _extract_product_id_path_only(product_url)
    if not pid:
        return {}
    token = _naver_commerce_get_access_token_cached()
    if not token:
        return {}

    # NOTE:
    # - SmartStore URL의 /products/<id> 값이 originProductNo인지 channelProductNo인지는 환경/스토어에 따라 다를 수 있어,
    #   404를 흡수하며 후보 endpoint를 순차 탐색한다(구조적 안전장치).
    candidates = [
        f"/v2/products/origin-products/{pid}",
        f"/v2/products/channel-products/{pid}",
        f"/v1/products/origin-products/{pid}",
        f"/v1/products/channel-products/{pid}",
    ]
    last_err = None
    for path in candidates:
        sc, j, err = _naver_commerce_get_json(path=path, access_token=token, timeout_sec=6.5)
        if sc == 200 and isinstance(j, dict):
            return _map_commerce_product_to_page_meta(j)
        # 토큰 만료(GW.AUTHN) 가능성 → 1회 강제 refresh 후 재시도
        if sc == 401 and ("GW.AUTHN" in (err or "") or "AUTHN" in (err or "")):
            token2 = _naver_commerce_get_access_token_cached(force_refresh=True)
            if token2 and token2 != token:
                sc2, j2, err2 = _naver_commerce_get_json(path=path, access_token=token2, timeout_sec=6.5)
                if sc2 == 200 and isinstance(j2, dict):
                    return _map_commerce_product_to_page_meta(j2)
                last_err = err2 or err
                continue
        if sc == 404:
            continue
        last_err = err
    _ = last_err
    return {}


def _naver_commerce_client_secret_sign(*, client_id: str, client_secret: str, timestamp_ms: int) -> str:
    """
    Naver Commerce API 전자서명 생성(공식 문서 기준).
    - password = "{client_id}_{timestamp_ms}"
    - salt = client_secret (bcrypt salt 형태: "$2a$10$..." 등)
    - hashed = bcrypt.hashpw(password, salt)
    - client_secret_sign = base64(hashed)
    """
    cid = str(client_id or "").strip()
    csec = str(client_secret or "").strip()
    ts = int(timestamp_ms)
    if not cid or not csec:
        raise ValueError("client_id/client_secret required")
    if ts <= 0:
        raise ValueError("timestamp_ms must be > 0")

    # 커머스 API client_secret은 "bcrypt salt" 형태여야 한다.
    # 예: $2a$10$abcdefghijklmnopqrstuv (총 29 chars)
    try:
        ok_salt = bool(re.match(r"^\$2[abxy]?\$\d{2}\$[./A-Za-z0-9]{22}$", csec))
    except Exception:
        ok_salt = False
    if not ok_salt:
        raise ValueError("client_secret must be bcrypt salt like '$2a$10$abcdefghijklmnopqrstuv' (29 chars)")

    try:
        import bcrypt  # type: ignore
    except Exception as e:
        raise ValueError(f"bcrypt_not_available: {e}")

    password = f"{cid}_{ts}".encode("utf-8")
    salt = csec.encode("utf-8")
    hashed = bcrypt.hashpw(password, salt)
    return base64.b64encode(hashed).decode("utf-8")


def _naver_commerce_fetch_access_token(
    *,
    token_url: str,
    client_id: str,
    client_secret: str,
    timeout_sec: float = 10.0,
) -> tuple[str | None, dict]:
    """
    커머스 API 토큰 발급을 수행한다.
    - 반환: (access_token or None, meta)
    - meta에는 민감정보(token)는 포함하지 않는다.
    """
    cid = str(client_id or "").strip()
    csec = str(client_secret or "").strip()
    url = str(token_url or "").strip()
    if not cid or not csec:
        return None, {"ok": False, "status_code": 400, "message": "missing_client_id_or_secret"}
    if not url:
        return None, {"ok": False, "status_code": 400, "message": "missing_token_url"}

    ts_ms = int(time.time() * 1000)
    try:
        sign = _naver_commerce_client_secret_sign(client_id=cid, client_secret=csec, timestamp_ms=ts_ms)
    except Exception as e:
        msg = str(e)
        code = 500 if ("bcrypt_not_available" in msg) else 400
        return None, {"ok": False, "status_code": code, "message": f"signature_error: {e}"}

    try:
        resp = requests.post(
            url,
            data={
                "client_id": cid,
                "timestamp": str(ts_ms),
                "grant_type": "client_credentials",
                "type": "SELF",
                "client_secret_sign": sign,
            },
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            timeout=float(timeout_sec),
        )
    except Exception as e:
        return None, {"ok": False, "status_code": None, "message": f"request_failed: {e}"}

    if resp.status_code != 200:
        return None, {
            "ok": False,
            "status_code": int(resp.status_code),
            "message": f"token_failed({resp.status_code}) {_safe_err_text(resp)}".strip(),
        }

    try:
        j = resp.json() or {}
    except Exception:
        j = {}
    token = str((j or {}).get("access_token") or "").strip()
    if not token:
        return None, {"ok": False, "status_code": 502, "message": "token_ok_but_access_token_missing"}
    return token, {"ok": True, "status_code": 200, "message": "ok"}


def _probe_http(
    *,
    method: str,
    url: str,
    token: str,
    timeout_sec: float = 10.0,
    allow_json: bool = True,
) -> dict:
    """
    외부 엔드포인트를 1회 호출하고, 상태/오류코드만 요약한다. (응답 전문/토큰 노출 금지)
    """
    m = str(method or "GET").upper()
    u = str(url or "").strip()
    t = str(token or "").strip()
    if not u:
        return {"ok_path": False, "status_code": None, "message": "missing_url"}
    if not t:
        return {"ok_path": False, "status_code": None, "message": "missing_token"}

    try:
        resp = requests.request(
            m,
            u,
            headers={"Authorization": f"Bearer {t}"},
            timeout=float(timeout_sec),
        )
    except Exception as e:
        return {"ok_path": False, "status_code": None, "message": f"request_failed: {e}"}

    code = int(resp.status_code)
    body_code = None
    if allow_json:
        try:
            j = resp.json()
            if isinstance(j, dict):
                body_code = j.get("code")
        except Exception:
            body_code = None

    # "경로가 유효"한지 판별: 404만 강하게 부정. (401/403/400/405는 경로 존재 가능)
    ok_path = code != 404
    return {
        "ok_path": bool(ok_path),
        "status_code": code,
        "body_code": (str(body_code) if body_code is not None else None),
        "message": _safe_err_text(resp),
    }


def probe_naver_commerce_reviews_endpoints() -> dict:
    """
    (진단) 커머스 리뷰 API 경로 유효성 점검.
    - 토큰 발급 URL(/external 포함/미포함) 둘 다 시도
    - base URL도 둘 다 시도하여 404 여부로 경로 유효성을 판단
    - 토큰은 절대 반환하지 않는다.
    """
    cid = _get_api_setting("NAVER_COMMERCE_CLIENT_ID")
    csec = _get_api_setting("NAVER_COMMERCE_CLIENT_SECRET")
    if not cid or not csec:
        return {"ok": False, "error": "NAVER_COMMERCE_CLIENT_ID/SECRET not configured"}

    token1, meta1 = _naver_commerce_fetch_access_token(
        token_url=NAVER_COMMERCE_TOKEN_URL, client_id=cid, client_secret=csec
    )
    token2, meta2 = _naver_commerce_fetch_access_token(
        token_url=NAVER_COMMERCE_TOKEN_URL_NO_EXTERNAL, client_id=cid, client_secret=csec
    )
    token = token1 or token2

    out = {
        "ok": bool(token),
        "token": {
            "external": {"url": NAVER_COMMERCE_TOKEN_URL, **(meta1 or {})},
            "no_external": {"url": NAVER_COMMERCE_TOKEN_URL_NO_EXTERNAL, **(meta2 or {})},
        },
        "calls": [],
    }
    if not token:
        return out

    # NOTE:
    # - token은 api.commerce.naver.com/external에서 정상 발급된다.
    # - 리소스는 external 포함/미포함 또는 다른 호스트(api.shop.naver.com)로 갈리는 사례가 있어
    #   여러 후보 base를 함께 점검한다.
    base_candidates = [
        "https://api.commerce.naver.com/external",
        "https://api.commerce.naver.com",
        "https://api.shop.naver.com",
    ]

    # 많은 후보를 확인하므로, 외부 호출은 병렬 + 짧은 타임아웃으로 수행해
    # "경로 존재(404 여부)"를 빠르게 판단한다.
    jobs: list[dict] = []

    def _add(name: str, method: str, path: str) -> None:
        for base in base_candidates:
            jobs.append(
                {
                    "name": name,
                    "method": method,
                    "url": base.rstrip("/") + "/" + path.lstrip("/"),
                }
            )

    # 사용자 제공 경로 기준으로 확인
    _add("reviews_list", "GET", "/v1/contents/reviews")
    # 상세 조회는 임의 reviewNo로(존재하지 않아도 404/400/403로 경로 자체는 판별 가능)
    _add("reviews_detail", "GET", "/v1/contents/reviews/0")
    # 답글 등록은 side-effect를 피하기 위해 GET으로 405/404 여부만 확인
    _add("reviews_replies_probe", "GET", "/v1/contents/reviews/0/replies")

    # 교정 후보(판매자 서비스 계열)
    _add("seller_services_reviews", "GET", "/v1/seller-services/reviews")
    _add("seller_services_reviews_page_probe", "GET", "/v1/seller-services/reviews?page=1&size=1")

    # 교정 후보(결제/주문(pay-order) 통합 계열)
    _add("pay_order_product_reviews", "GET", "/v1/pay-order/seller/product-reviews")
    _add("pay_order_product_reviews_page_probe", "GET", "/v1/pay-order/seller/product-reviews?page=1&size=1")
    # 답변 API로 추정되는 경로는 GET으로만 probe (POST 금지)
    _add("pay_order_product_review_reply_probe", "GET", "/v1/pay-order/seller/product-reviews/0/reply")

    # execute jobs (parallel)
    try:
        import concurrent.futures as _cf

        def _run(j: dict) -> dict:
            r = _probe_http(method=j["method"], url=j["url"], token=token, timeout_sec=6.0)
            return {**j, **r}

        results: list[dict] = []
        with _cf.ThreadPoolExecutor(max_workers=8) as ex:
            futs = [ex.submit(_run, j) for j in jobs]
            for f in _cf.as_completed(futs, timeout=25.0):
                try:
                    results.append(f.result(timeout=0.1))
                except Exception as e:
                    results.append(
                        {
                            "name": "unknown",
                            "method": "GET",
                            "url": "",
                            "ok_path": False,
                            "status_code": None,
                            "body_code": None,
                            "message": f"probe_failed: {e}",
                        }
                    )
        # stable order for readability
        out["calls"] = sorted(results, key=lambda x: (str(x.get("name") or ""), str(x.get("url") or "")))
    except Exception as e:
        out["calls"] = [{"ok_path": False, "status_code": None, "message": f"probe_executor_failed: {e}"}]

    return out


@app.get("/settings/api/validate/naver-openapi", response_model=ApiValidateResult)
def validate_naver_openapi():
    """
    네이버 쇼핑 OpenAPI(client id/secret) 유효성 검증.
    - shop.json을 최소 파라미터로 1회 호출해 200 여부를 확인한다.
    """
    service = "naver-openapi"
    try:
        headers = _naver_openapi_headers()
    except HTTPException as e:
        return ApiValidateResult(ok=False, service=service, status_code=e.status_code, message=str(e.detail))

    try:
        resp = requests.get(
            "https://openapi.naver.com/v1/search/shop.json",
            headers=headers,
            params={"query": "테스트", "display": 1},
            timeout=10,
        )
        if resp.status_code == 200:
            return ApiValidateResult(ok=True, service=service, status_code=200, message="정상(200)")
        return ApiValidateResult(
            ok=False,
            service=service,
            status_code=int(resp.status_code),
            message=f"실패({resp.status_code}) {_safe_err_text(resp)}".strip(),
        )
    except Exception as e:
        return ApiValidateResult(ok=False, service=service, status_code=None, message=f"요청 실패: {e}")


@app.get("/settings/api/validate/naver-commerce", response_model=ApiValidateResult)
def validate_naver_commerce():
    """
    네이버 커머스 API 유효성 검증.
    - OAuth2 Client Credentials 토큰 발급을 1회 시도해 200 여부 + access_token 존재를 확인한다.
    - 전자서명(client_secret_sign)은 bcrypt 기반으로 생성한다.
    """
    service = "naver-commerce"
    cid = _get_api_setting("NAVER_COMMERCE_CLIENT_ID")
    csec = _get_api_setting("NAVER_COMMERCE_CLIENT_SECRET")
    if not cid or not csec:
        return ApiValidateResult(
            ok=False,
            service=service,
            status_code=400,
            message="NAVER_COMMERCE_CLIENT_ID/SECRET not configured",
        )

    ts_ms = int(time.time() * 1000)
    try:
        sign = _naver_commerce_client_secret_sign(client_id=cid, client_secret=csec, timestamp_ms=ts_ms)
    except Exception as e:
        msg = str(e)
        # 입력값 문제는 400으로 내려 혼선을 줄인다.
        code = 500 if ("bcrypt_not_available" in msg) else 400
        return ApiValidateResult(ok=False, service=service, status_code=code, message=f"signature_error: {e}")

    try:
        resp = requests.post(
            NAVER_COMMERCE_TOKEN_URL,
            data={
                "client_id": cid,
                "timestamp": str(ts_ms),
                "grant_type": "client_credentials",
                "type": "SELF",
                "client_secret_sign": sign,
            },
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            timeout=10,
        )
        if resp.status_code == 200:
            try:
                j = resp.json() or {}
            except Exception:
                j = {}
            token = str((j or {}).get("access_token") or "").strip()
            if not token:
                return ApiValidateResult(
                    ok=False,
                    service=service,
                    status_code=502,
                    message="실패(200) access_token missing",
                )
            return ApiValidateResult(ok=True, service=service, status_code=200, message="정상(200)")
        return ApiValidateResult(
            ok=False,
            service=service,
            status_code=int(resp.status_code),
            message=f"실패({resp.status_code}) {_safe_err_text(resp)}".strip(),
        )
    except Exception as e:
        return ApiValidateResult(ok=False, service=service, status_code=None, message=f"요청 실패: {e}")


@app.get("/settings/api/validate/naver-commerce/reviews", response_model=dict)
def validate_naver_commerce_reviews_endpoints():
    """
    (요청) 네이버 커머스 리뷰 API 엔드포인트 경로 유효성 확인.
    - 토큰 발급 및 GET 호출을 실제로 수행한다.
    - 토큰은 반환하지 않는다.
    """
    return probe_naver_commerce_reviews_endpoints()


