@app.post("/reviews/collect-now", response_model=ReviewCollectResponse)
def collect_reviews_now(
    req: ReviewCollectRequest,
    db: Session = Depends(get_db),
):
    """
    상품 상세 리뷰 탭에서 리뷰/답글 원문을 즉시 수집해 저장한다.
    - 1차 버전은 "최신순 기준 최근 여러 페이지" 수집에 집중한다.
    - 신규/기존 판정은 review_key 기반 upsert 로 처리한다.
    """
    items = _collect_smartstore_reviews_text(
        product_url=req.product_url,
        max_pages=req.max_pages,
        max_items=req.max_items,
    )
    stats = _upsert_review_raw_items(db, product_url=req.product_url, items=items)
    return ReviewCollectResponse(
        product_url=str(req.product_url or "").strip(),
        fetched=stats["fetched"],
        saved_reviews=stats["saved_reviews"],
        saved_replies=stats["saved_replies"],
        skipped=stats["skipped"],
        detail=None,
    )


@app.post("/reviews/collect-tracked", response_model=ReviewCollectTrackedResponse)
def collect_reviews_for_tracked_products(
    req: ReviewCollectTrackedRequest,
    db: Session = Depends(get_db),
):
    """
    `내 상품 추적`에 등록된 활성 상품들을 대상으로 리뷰/답글 원문을 배치 수집한다.
    - product_url 이 주어지면 해당 추적 상품만 대상으로 제한한다.
    - 결과는 상품별 상세(items) + 전체 집계로 함께 반환한다.
    """
    date_from_value = req.date_from
    date_to_value = req.date_to or _today_kst()
    if date_from_value is not None and date_to_value is not None and date_from_value > date_to_value:
        date_from_value, date_to_value = date_to_value, date_from_value
    target_urls = _list_active_tracked_product_urls(
        db,
        product_url=None,
        max_targets=req.max_targets,
    )
    if not target_urls:
        return ReviewCollectTrackedResponse(
            total_targets=0,
            processed_targets=0,
            date_from=date_from_value,
            date_to=date_to_value,
            fetched=0,
            saved_reviews=0,
            saved_replies=0,
            skipped=0,
            items=[],
            detail="no_tracked_products",
        )

    items_out: list[ReviewCollectResponse] = []
    total_fetched = 0
    total_saved_reviews = 0
    total_saved_replies = 0
    total_skipped = 0
    for product_url in target_urls:
        target_meta = _lookup_review_target_meta(db, product_url)
        product_title = str((target_meta or {}).get("title") or "").strip() or None
        try:
            collected = _collect_smartstore_reviews_text(
                product_url=product_url,
                max_pages=req.max_pages,
                max_items=req.max_items,
                date_from=date_from_value,
                date_to=date_to_value,
            )
            stats = _upsert_review_raw_items(db, product_url=product_url, items=collected)
            fetched = int(stats["fetched"])
            saved_reviews = int(stats["saved_reviews"])
            saved_replies = int(stats["saved_replies"])
            skipped = int(stats["skipped"])
            total_saved = saved_reviews + saved_replies
            if total_saved > 0:
                status = "done"
                status_label = "완료"
                detail = f"수집 완료 {total_saved}건"
            else:
                status = "skipped"
                status_label = "신규 없음"
                detail = "수집 완료 0건"
            total_fetched += fetched
            total_saved_reviews += saved_reviews
            total_saved_replies += saved_replies
            total_skipped += skipped
        except Exception as e:
            fetched = 0
            saved_reviews = 0
            saved_replies = 0
            skipped = 0
            status = "failed"
            status_label = "실패"
            detail = str(getattr(e, "detail", None) or str(e) or "collect_failed")
        items_out.append(
            ReviewCollectResponse(
                product_url=product_url,
                product_title=product_title,
                status=status,
                status_label=status_label,
                fetched=fetched,
                saved_reviews=saved_reviews,
                saved_replies=saved_replies,
                skipped=skipped,
                detail=detail,
            )
        )

    return ReviewCollectTrackedResponse(
        total_targets=len(target_urls),
        processed_targets=len(items_out),
        date_from=date_from_value,
        date_to=date_to_value,
        fetched=total_fetched,
        saved_reviews=total_saved_reviews,
        saved_replies=total_saved_replies,
        skipped=total_skipped,
        items=items_out,
        detail=None,
    )


