def _ai_ops_ads_action_candidate(row: NaverAdKeywordDaily) -> dict | None:
    cost = int(getattr(row, "cost", 0) or 0)
    clicks = int(getattr(row, "clicks", 0) or 0)
    purchase_conversions = int(getattr(row, "purchase_conversions", 0) or 0)
    purchase_revenue = int(getattr(row, "purchase_revenue", 0) or 0)
    roas = float(getattr(row, "roas", 0.0) or 0.0)
    ctr = float(getattr(row, "ctr", 0.0) or 0.0)

    action_bucket = ""
    recommended_action = ""
    top_issue = ""
    priority = "P3"
    approval_recommendation = "HOLD"
    approval_recommendation_reason = ""

    if cost >= 10000 and clicks >= 5 and purchase_conversions <= 0:
        action_bucket = "STOP"
        recommended_action = "비효율 키워드 중단"
        top_issue = "비용이 누적되지만 실제 구매 전환이 없습니다."
        priority = "P1"
        approval_recommendation = "APPROVE"
        approval_recommendation_reason = "고비용 무구매 키워드라 즉시 중단 테스트를 권장합니다."
    elif purchase_conversions >= 2 and roas >= 250.0:
        action_bucket = "SCALE"
        recommended_action = "증액 테스트"
        top_issue = "실구매 전환과 ROAS가 모두 우수해 예산 확대 후보입니다."
        priority = "P1"
        approval_recommendation = "APPROVE"
        approval_recommendation_reason = "구매 전환과 ROAS가 모두 좋아 바로 증액 실험해볼 만합니다."
    elif clicks >= 8 and ctr >= 3.0 and purchase_conversions <= 0:
        action_bucket = "TEST"
        recommended_action = "랜딩/소재 테스트"
        top_issue = "유입 반응은 있으나 구매 전환이 없어 상세/소재 테스트가 필요합니다."
        priority = "P2"
        approval_recommendation = "REVIEW"
        approval_recommendation_reason = "중단보다 랜딩/소재 보정 실험을 먼저 검토하는 편이 안전합니다."
    else:
        return None

    return {
        "date": getattr(row, "date", None).isoformat() if getattr(row, "date", None) else None,
        "campaign_name": str(getattr(row, "campaign_name", "") or ""),
        "adgroup_name": str(getattr(row, "adgroup_name", "") or ""),
        "keyword": str(getattr(row, "keyword", "") or ""),
        "campaign_kind": getattr(row, "campaign_kind", None),
        "impressions": int(getattr(row, "impressions", 0) or 0),
        "clicks": clicks,
        "cost": cost,
        "purchase_conversions": purchase_conversions,
        "purchase_revenue": purchase_revenue,
        "ctr": round(ctr, 2),
        "roas": round(roas, 2),
        "action_bucket": action_bucket,
        "top_issue": top_issue,
        "recommended_action": recommended_action,
        "priority": priority,
        "approval_recommendation": approval_recommendation,
        "approval_recommendation_reason": approval_recommendation_reason,
    }


def _ai_ops_latest_rank_by_keyword(db: Session, *, target_date: date) -> dict[str, int]:
    rows = (
        db.query(NaverProductRankDaily.keyword, func.min(NaverProductRankDaily.rank))
        .filter(NaverProductRankDaily.date == target_date)
        .group_by(NaverProductRankDaily.keyword)
        .all()
    )
    out: dict[str, int] = {}
    for keyword, rank in rows:
        key = str(keyword or "").strip()
        if not key:
            continue
        try:
            out[key] = int(rank or 0)
        except Exception:
            continue
    return out


