def _ai_ops_home_effective_priority(
    row: DecisionProductHealthDaily,
    *,
    operation_learning_item: dict | None,
) -> tuple[float, str]:
    base_score = float(getattr(row, "priority_score", 0.0) or 0.0)
    if not operation_learning_item:
        return round(base_score, 2), "기본 우선순위 유지"
    verified_count = int(operation_learning_item.get("verified_count") or 0)
    improvement_rate = float(operation_learning_item.get("improvement_rate") or 0.0)
    avg_purchase_conversions_delta = float(operation_learning_item.get("avg_purchase_conversions_delta") or 0.0)
    avg_roas_delta = float(operation_learning_item.get("avg_roas_delta") or 0.0)
    if verified_count <= 0:
        return round(base_score, 2), "기본 우선순위 유지"
    boost = 0.0
    boost += improvement_rate * 12.0
    boost += min(verified_count, 5) * 2.0
    boost += max(0.0, avg_purchase_conversions_delta) * 2.0
    boost += max(0.0, avg_roas_delta / 30.0)
    return (
        round(base_score + boost, 2),
        f"운영 학습 가중치 +{round(boost)}점: 검증 {verified_count}건 / 개선율 {int(round(improvement_rate * 100))}%",
    )


def _ai_ops_home_action_bucket(row: DecisionProductHealthDaily) -> str:
    policy_type = str(getattr(row, "policy_type", "") or "").strip().upper()
    if policy_type == "AD_GROWTH":
        return "BUDGET_INCREASE"
    if policy_type in {"AD_DEFENSE", "AD_EFFICIENCY", "VOC_IMPROVEMENT_PRIORITY"}:
        if policy_type == "VOC_IMPROVEMENT_PRIORITY":
            return "VOC_IMPROVEMENT"
        return "BUDGET_DECREASE"
    if policy_type == "FAQ_CONTENT_IMPROVEMENT":
        return "FAQ_CONTENT_IMPROVEMENT"
    if policy_type == "SALES_FOCUS":
        return "SALES_FOCUS"
    return policy_type or "UNCLASSIFIED"


def _serialize_ai_ops_home_item(
    row: DecisionProductHealthDaily,
    *,
    operation_learning_item: dict | None,
    display_product_name: str | None = None,
) -> dict:
    effective_priority_score, priority_reason = _ai_ops_home_effective_priority(
        row,
        operation_learning_item=operation_learning_item,
    )
    return {
        "sku_id": str(getattr(row, "sku_id", "") or ""),
        "product_name": display_product_name if display_product_name is not None else getattr(row, "product_name", None),
        "policy_type": getattr(row, "policy_type", None),
        "action_bucket": _ai_ops_home_action_bucket(row),
        "top_issue": getattr(row, "top_issue", None),
        "recommended_action_primary": getattr(row, "recommended_action_primary", None),
        "priority_score": float(getattr(row, "priority_score", 0.0) or 0.0),
        "effective_priority_score": effective_priority_score,
        "priority_reason": priority_reason,
        "operation_learning_summary": operation_learning_item or {},
    }


def _ai_ops_latest_health_date(db: Session) -> date | None:
    return db.query(func.max(DecisionProductHealthDaily.date)).scalar()


def _ai_ops_iso_date(value: date | None) -> str | None:
    return value.isoformat() if value is not None else None


def _ai_ops_days_stale(snapshot_date: date | None) -> int | None:
    if snapshot_date is None:
        return None
    try:
        return max(0, (_today_kst() - snapshot_date).days)
    except Exception:
        return None


def _ai_ops_freshness_payload(db: Session) -> dict:
    health_date = _ai_ops_latest_health_date(db)
    ads_date = _ai_ops_latest_ads_date(db)
    sales_date = _ai_ops_latest_sales_date(db)
    return {
        "health_as_of": _ai_ops_iso_date(health_date),
        "ads_as_of": _ai_ops_iso_date(ads_date),
        "sales_as_of": _ai_ops_iso_date(sales_date),
        "health_days_stale": _ai_ops_days_stale(health_date),
        "ads_days_stale": _ai_ops_days_stale(ads_date),
        "sales_days_stale": _ai_ops_days_stale(sales_date),
        "health_missing": health_date is None,
        "ads_missing": ads_date is None,
        "sales_missing": sales_date is None,
    }


def _ai_ops_source_screen_from_scope(source_scope: object) -> str:
    scope0 = str(source_scope or "").strip().lower()
    mapping = {
        "ai-ops-home": "home",
        "ai-ops-products": "products",
        "ai-ops-reviews": "reviews",
        "ai-ops-qna": "qna",
        "ai-ops-ads": "ads",
        "ai-ops-ads-budget": "ads",
        "ai-ops-sales": "sales",
        "ai-ops-policy-compare": "policies",
    }
    return mapping.get(scope0, scope0.replace("ai-ops-", "") or "unknown")


def _ai_ops_action_bucket_from_policy_type(policy_type: object) -> str | None:
    policy_type0 = str(policy_type or "").strip().upper()
    if not policy_type0:
        return None
    if policy_type0 == "AD_GROWTH":
        return "BUDGET_INCREASE"
    if policy_type0 in {"AD_DEFENSE", "AD_EFFICIENCY"}:
        return "BUDGET_DECREASE"
    if policy_type0 == "VOC_IMPROVEMENT_PRIORITY":
        return "VOC_IMPROVEMENT"
    if policy_type0 == "FAQ_CONTENT_IMPROVEMENT":
        return "FAQ_CONTENT_IMPROVEMENT"
    if policy_type0 == "SALES_FOCUS":
        return "SALES_FOCUS"
    return policy_type0


def _ai_ops_reviewer_context(
    request: Request | None,
    *,
    reviewer: object = None,
    reviewer_role: object = None,
) -> tuple[str, str | None]:
    request_headers = request.headers if request is not None else {}
    reviewer0 = (
        str(reviewer or "").strip()
        or str(request_headers.get("x-ai-ops-reviewer") or "").strip()
        or str(request_headers.get("x-reviewer") or "").strip()
        or "ai-ops-system"
    )
    reviewer_role0 = (
        str(reviewer_role or "").strip()
        or str(request_headers.get("x-ai-ops-reviewer-role") or "").strip()
        or str(request_headers.get("x-reviewer-role") or "").strip()
        or None
    )
    return reviewer0, reviewer_role0


def _ai_ops_append_audit_entry(
    payload: dict,
    *,
    event: str,
    actor: str,
    actor_role: str | None = None,
    note: str | None = None,
    status: str | None = None,
) -> dict:
    payload0 = dict(payload or {})
    audit_trail = payload0.get("audit_trail") if isinstance(payload0.get("audit_trail"), list) else []
    audit_trail = [entry for entry in audit_trail if isinstance(entry, dict)]
    audit_trail.append(
        {
            "event": str(event or "").strip().upper() or "UPDATED",
            "actor": str(actor or "").strip() or "ai-ops-system",
            "actor_role": str(actor_role or "").strip() or None,
            "note": str(note or "").strip() or None,
            "status": str(status or "").strip().upper() or None,
            "at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(),
        }
    )
    payload0["audit_trail"] = audit_trail[-30:]
    payload0["last_actor"] = str(actor or "").strip() or "ai-ops-system"
    payload0["last_actor_role"] = str(actor_role or "").strip() or None
    return payload0


def _ai_ops_target_identifier(
    *,
    action_type: str,
    entity_type: str,
    entity_id: str,
    payload: dict,
) -> dict:
    identifier = payload.get("target_identifier") if isinstance(payload.get("target_identifier"), dict) else {}
    identifier = dict(identifier)
    identifier.setdefault("entity_type", entity_type)
    identifier.setdefault("entity_id", entity_id)
    if action_type in {"QUEUE_PRIMARY_ACTION", "QUEUE_POLICY_COMPARE_ACTION"}:
        identifier.setdefault("sku_id", payload.get("sku_id") or entity_id)
    if action_type in {"QUEUE_AD_BUDGET_ACTION", "QUEUE_AD_KEYWORD_ACTION"}:
        identifier.setdefault("campaign_name", payload.get("campaign_name"))
        identifier.setdefault("adgroup_name", payload.get("adgroup_name"))
        identifier.setdefault("keyword", payload.get("keyword"))
    if action_type == "QUEUE_SALES_ACTION":
        identifier.setdefault("product_id", payload.get("product_id") or entity_id)
        identifier.setdefault("product_name", payload.get("product_name"))
    if action_type == "QUEUE_POLICY_COMPARE_ACTION":
        identifier.setdefault("target_policy_pack_id", payload.get("target_policy_pack_id"))
    return {key: value for key, value in identifier.items() if value not in (None, "")}


def _ai_ops_evidence_ref(
    *,
    action_type: str,
    source_scope: str,
    entity_id: str,
    payload: dict,
    db: Session,
) -> dict:
    evidence_ref = payload.get("evidence_ref") if isinstance(payload.get("evidence_ref"), dict) else {}
    evidence_ref = dict(evidence_ref)
    evidence_ref.setdefault("source_scope", source_scope)
    evidence_ref.setdefault("source_screen", _ai_ops_source_screen_from_scope(source_scope))
    evidence_ref.setdefault("entity_id", entity_id)
    evidence_ref.setdefault("action_type", action_type)
    evidence_ref.setdefault("health_as_of", _ai_ops_iso_date(_ai_ops_latest_health_date(db)))
    evidence_ref.setdefault("ads_as_of", _ai_ops_iso_date(_ai_ops_latest_ads_date(db)))
    evidence_ref.setdefault("sales_as_of", _ai_ops_iso_date(_ai_ops_latest_sales_date(db)))
    return {key: value for key, value in evidence_ref.items() if value not in (None, "")}


def _ai_ops_normalize_queue_payload(
    *,
    db: Session,
    source_scope: object,
    entity_type: object,
    entity_id: object,
    action_type: object,
    payload: dict | None,
    actor: str,
    actor_role: str | None,
    event: str,
    status: str,
    note: str | None = None,
) -> dict:
    source_scope0 = str(source_scope or "ai-ops").strip() or "ai-ops"
    entity_type0 = str(entity_type or "sku").strip() or "sku"
    entity_id0 = str(entity_id or "").strip()
    action_type0 = str(action_type or "").strip().upper()
    payload0 = dict(payload or {})
    action_bucket = (
        str(payload0.get("action_bucket") or "").strip().upper()
        or str(payload0.get("action_kind") or "").strip().upper()
        or _ai_ops_action_bucket_from_policy_type(payload0.get("policy_type"))
        or None
    )
    payload0["schema_version"] = "ai_ops_action_v1"
    payload0["source_scope"] = source_scope0
    payload0["source_screen"] = _ai_ops_source_screen_from_scope(source_scope0)
    payload0["entity_type"] = entity_type0
    payload0["entity_id"] = entity_id0
    payload0["action_type"] = action_type0
    if action_bucket:
        payload0["action_bucket"] = action_bucket
    if not str(payload0.get("title") or "").strip():
        payload0["title"] = f"{action_type0} {entity_id0}".strip()
    payload0["target_identifier"] = _ai_ops_target_identifier(
        action_type=action_type0,
        entity_type=entity_type0,
        entity_id=entity_id0,
        payload=payload0,
    )
    payload0["evidence_ref"] = _ai_ops_evidence_ref(
        action_type=action_type0,
        source_scope=source_scope0,
        entity_id=entity_id0,
        payload=payload0,
        db=db,
    )
    return _ai_ops_append_audit_entry(
        payload0,
        event=event,
        actor=actor,
        actor_role=actor_role,
        note=note,
        status=status,
    )


@app.post("/ai/ops/product-health/rebuild", response_model=dict)
def ai_ops_product_health_rebuild(payload: AiOpsProductHealthRebuildRequest, db: Session = Depends(get_db)):
    target_date = _today_kst()
    date_text = str(payload.date or "").strip()
    if date_text:
        try:
            target_date = datetime.strptime(date_text, "%Y-%m-%d").date()
        except Exception:
            raise HTTPException(status_code=400, detail="date must be YYYY-MM-DD")
    saved = _rebuild_ai_ops_product_health(target_date=target_date, db=db)
    return {"ok": True, "date": target_date.isoformat(), "saved": int(saved)}


@app.get("/ai/ops/home", response_model=dict)
def ai_ops_home(db: Session = Depends(get_db)):
    latest_date = _ai_ops_latest_health_date(db)
    pending_action_count = (
        db.query(ActionQueueItem).filter(ActionQueueItem.status == "PENDING").count()
    )
    operation_learning_items = _ai_ops_policy_operation_learning_items(db)
    operation_verified_count = sum(int(item.get("verified_count") or 0) for item in operation_learning_items)
    operation_improved_count = sum(int(item.get("improved_count") or 0) for item in operation_learning_items)
    operation_improvement_rate = round((operation_improved_count / operation_verified_count), 4) if operation_verified_count > 0 else 0.0
    top_operation_learning = operation_learning_items[0] if operation_learning_items else {}
    top_operation_policy_type = str((top_operation_learning or {}).get("policy_type") or "").strip().upper()
    top_operation_label = (
        "예산 증액"
        if top_operation_policy_type == "AD_GROWTH"
        else "광고 방어"
        if top_operation_policy_type == "AD_DEFENSE"
        else "운영"
    )
    operation_learning_note = (
        f"{top_operation_label} 학습 {int((top_operation_learning or {}).get('verified_count') or 0)}건 검증 / 개선율 "
        f"{int(round(float((top_operation_learning or {}).get('improvement_rate') or 0.0) * 100))}%"
        if top_operation_learning
        else "운영 학습 없음"
    )
    if latest_date is None:
        return {
            "ok": True,
            "summary": {
                "snapshot_date": None,
                "urgent_count": 0,
                "pending_action_count": int(pending_action_count or 0),
                "high_priority_voc_count": 0,
                "growth_opportunity_count": 0,
                "faq_gap_count": 0,
                "avg_data_quality_score": 0.0,
                "operation_verified_count": int(operation_verified_count or 0),
                "operation_improvement_rate": operation_improvement_rate,
                "operation_learning_note": operation_learning_note,
                "action_bucket_counts": {},
            },
            "items": [],
        }

    rows = (
        db.query(DecisionProductHealthDaily)
        .filter(DecisionProductHealthDaily.date == latest_date)
        .order_by(DecisionProductHealthDaily.priority_score.desc(), DecisionProductHealthDaily.sku_id.asc())
        .all()
    )
    operation_learning_map = _ai_ops_policy_operation_learning_map(db)
    display_name_by_sku = _ai_ops_display_name_overrides(db, rows)
    home_items = [
        _serialize_ai_ops_home_item(
            row,
            operation_learning_item=operation_learning_map.get(str(getattr(row, "policy_type", "") or "").strip()),
            display_product_name=display_name_by_sku.get(str(getattr(row, "sku_id", "") or "").strip()),
        )
        for row in rows
    ]
    home_items = sorted(
        home_items,
        key=lambda item: (
            float(item.get("effective_priority_score") or 0.0),
            float(item.get("priority_score") or 0.0),
            str(item.get("sku_id") or ""),
        ),
        reverse=True,
    )
    action_bucket_counts: dict[str, int] = {}
    for item in home_items:
        bucket = str(item.get("action_bucket") or "").strip()
        if not bucket:
            continue
        action_bucket_counts[bucket] = int(action_bucket_counts.get(bucket) or 0) + 1
    urgent_count = len(rows)
    high_priority_voc_count = sum(
        1 for row in rows if "VOC" in str(getattr(row, "policy_type", "") or "").upper()
    )
    growth_opportunity_count = sum(
        1 for row in rows if "GROWTH" in str(getattr(row, "policy_type", "") or "").upper()
    )
    faq_gap_count = sum(
        1
        for row in rows
        if str(getattr(row, "policy_type", "") or "").upper() == "FAQ_CONTENT_IMPROVEMENT"
    )
    avg_data_quality_score = (
        round(sum(float(getattr(row, "data_quality_score", 0.0) or 0.0) for row in rows) / urgent_count, 4)
        if urgent_count > 0
        else 0.0
    )

    return {
        "ok": True,
        "summary": {
            "snapshot_date": latest_date.isoformat(),
            "urgent_count": int(urgent_count),
            "pending_action_count": int(pending_action_count or 0),
            "high_priority_voc_count": int(high_priority_voc_count),
            "growth_opportunity_count": int(growth_opportunity_count),
            "faq_gap_count": int(faq_gap_count),
            "avg_data_quality_score": avg_data_quality_score,
            "operation_verified_count": int(operation_verified_count or 0),
            "operation_improvement_rate": operation_improvement_rate,
            "operation_learning_note": operation_learning_note,
            "action_bucket_counts": action_bucket_counts,
        },
        "items": home_items[:10],
        "freshness": _ai_ops_freshness_payload(db),
    }


def _ai_ops_latest_health_rows_for_policy_types(db: Session, *, policy_types: list[str]) -> tuple[date | None, list[DecisionProductHealthDaily]]:
    latest_date = _ai_ops_latest_health_date(db)
    if latest_date is None:
        return None, []
    normalized = {str(policy_type or "").strip().upper() for policy_type in policy_types if str(policy_type or "").strip()}
    rows = (
        db.query(DecisionProductHealthDaily)
        .filter(DecisionProductHealthDaily.date == latest_date)
        .order_by(DecisionProductHealthDaily.priority_score.desc(), DecisionProductHealthDaily.sku_id.asc())
        .all()
    )
    return latest_date, [
        row for row in rows if str(getattr(row, "policy_type", "") or "").strip().upper() in normalized
    ]


def _ai_ops_latest_decision_log_by_entity(db: Session, *, entity_ids: list[str]) -> dict[str, AiDecisionLog]:
    entity_ids0 = [str(entity_id or "").strip() for entity_id in entity_ids if str(entity_id or "").strip()]
    if not entity_ids0:
        return {}
    rows = (
        db.query(AiDecisionLog)
        .filter(
            AiDecisionLog.analysis_type == "AI_OPS_PRODUCT_HEALTH",
            AiDecisionLog.entity_type == "SKU",
            AiDecisionLog.entity_id.in_(entity_ids0),
        )
        .order_by(AiDecisionLog.created_at.desc(), AiDecisionLog.log_id.desc())
        .all()
    )
    by_entity: dict[str, AiDecisionLog] = {}
    for row in rows:
        entity_id = str(getattr(row, "entity_id", "") or "").strip()
        if entity_id and entity_id not in by_entity:
            by_entity[entity_id] = row
    return by_entity


def _ai_ops_qna_stats_by_sku(db: Session, *, rows: list[DecisionProductHealthDaily]) -> dict[str, dict]:
    if not rows:
        return {}
    product_ids = {
        str(int(getattr(row, "product_id_catalog", 0) or 0))
        for row in rows
        if int(getattr(row, "product_id_catalog", 0) or 0) > 0
    }
    candidate_names: dict[str, set[str]] = {}
    for row in rows:
        sku_id = str(getattr(row, "sku_id", "") or "").strip()
        names = {
            _ai_ops_normalize_name(getattr(row, "product_name", None)),
            _ai_ops_normalize_name(getattr(row, "top_issue", None)),
        }
        candidate_names[sku_id] = {name for name in names if name}
    pairs = (
        db.query(CommerceQnaRaw, CommerceQnaAnalysis)
        .join(CommerceQnaAnalysis, CommerceQnaAnalysis.qna_key == CommerceQnaRaw.qna_key)
        .filter(CommerceQnaRaw.qna_kind == "product")
        .all()
    )
    stats: dict[str, dict] = {}
    for row in rows:
        sku_id = str(getattr(row, "sku_id", "") or "").strip()
        if not sku_id:
            continue
        matched: list[tuple[CommerceQnaRaw, CommerceQnaAnalysis]] = []
        product_id = str(int(getattr(row, "product_id_catalog", 0) or 0)) if int(getattr(row, "product_id_catalog", 0) or 0) > 0 else ""
        for raw_row, analysis_row in pairs:
            raw_product_no = str(getattr(raw_row, "product_no", "") or "").strip()
            raw_product_name = _ai_ops_normalize_name(getattr(raw_row, "product_name", None))
            if product_id and raw_product_no and raw_product_no == product_id:
                matched.append((raw_row, analysis_row))
                continue
            if raw_product_name and raw_product_name in candidate_names.get(sku_id, set()):
                matched.append((raw_row, analysis_row))
        prepurchase_count = sum(
            1
            for _, analysis_row in matched
            if str(getattr(analysis_row, "purchase_stage", "") or "").strip().upper() == "PRE_PURCHASE"
        )
        total_count = len(matched)
        issue_tags: list[str] = []
        for _, analysis_row in matched:
            for value in (
                getattr(analysis_row, "inquiry_type", None),
                getattr(analysis_row, "inquiry_subtype", None),
                getattr(analysis_row, "primary_need", None),
            ):
                text0 = str(value or "").strip()
                if text0 and text0 not in issue_tags:
                    issue_tags.append(text0)
        stats[sku_id] = {
            "count": total_count,
            "prepurchase_count": prepurchase_count,
            "prepurchase_question_ratio": round((prepurchase_count / total_count), 4) if total_count > 0 else None,
            "faq_gap_count": sum(1 for _, analysis_row in matched if bool(getattr(analysis_row, "faq_candidate_flag", False))),
            "quality_issue_count": sum(1 for _, analysis_row in matched if bool(getattr(analysis_row, "quality_issue_flag", False))),
            "complaint_count": sum(1 for _, analysis_row in matched if bool(getattr(analysis_row, "complaint_flag", False))),
            "issue_tags": issue_tags[:6],
        }
    return stats


def _ai_ops_collect_action_proposals(
    *,
    rows: list[DecisionProductHealthDaily],
    log_by_entity: dict[str, AiDecisionLog],
    default_owner: str,
) -> list[dict]:
    grouped: dict[str, dict] = {}
    for row in rows:
        sku_id = str(getattr(row, "sku_id", "") or "").strip()
        action_bucket = _ai_ops_action_bucket_from_policy_type(getattr(row, "policy_type", None)) or "UNCLASSIFIED"
        recommended_actions = []
        decision_log = log_by_entity.get(sku_id)
        if decision_log is not None:
            recommended_actions = [str(value).strip() for value in _json_loads_list(getattr(decision_log, "recommended_actions", None)) if str(value).strip()]
        primary_action = str(getattr(row, "recommended_action_primary", "") or "").strip()
        if primary_action:
            recommended_actions.append(primary_action)
        for title in recommended_actions:
            item = grouped.setdefault(
                title,
                {
                    "title": title,
                    "action_bucket": action_bucket,
                    "expected_effect": str(getattr(row, "top_issue", "") or "").strip() or None,
                    "owner": default_owner,
                    "_priority": float(getattr(row, "priority_score", 0.0) or 0.0),
                },
            )
            item["_priority"] = max(float(item.get("_priority") or 0.0), float(getattr(row, "priority_score", 0.0) or 0.0))
    items = list(grouped.values())
    items.sort(key=lambda item: (float(item.get("_priority") or 0.0), str(item.get("title") or "")), reverse=True)
    return [
        {
            "title": item.get("title"),
            "action_bucket": item.get("action_bucket"),
            "expected_effect": item.get("expected_effect"),
            "owner": item.get("owner"),
        }
        for item in items[:8]
    ]


@app.get("/ai/ops/products", response_model=dict)
def ai_ops_products(
    limit: int = Query(default=50, ge=1, le=200),
    policy_type: str | None = Query(default=None),
    policy_pack_id: str | None = Query(default=None),
    db: Session = Depends(get_db),
):
    latest_date = _ai_ops_latest_health_date(db)
    if latest_date is None:
        return {"ok": True, "summary": {"snapshot_date": None, "total_items": 0, "policy_pack_ids": []}, "items": []}

    query = db.query(DecisionProductHealthDaily).filter(DecisionProductHealthDaily.date == latest_date)
    if str(policy_type or "").strip():
        query = query.filter(DecisionProductHealthDaily.policy_type == str(policy_type).strip())

    all_rows = query.order_by(DecisionProductHealthDaily.priority_score.desc(), DecisionProductHealthDaily.sku_id.asc()).all()
    policy_pack_ids = sorted({pack_id for pack_id in (_ai_ops_policy_pack_id_from_row(row) for row in all_rows) if pack_id})
    policy_pack_id0 = str(policy_pack_id or "").strip()
    filtered_rows = [
        row for row in all_rows if not policy_pack_id0 or _ai_ops_policy_pack_id_from_row(row) == policy_pack_id0
    ]
    rows = filtered_rows[: int(limit)]
    total_items = len(filtered_rows)
    display_name_by_sku = _ai_ops_display_name_overrides(db, rows)
    return {
        "ok": True,
        "summary": {
            "snapshot_date": latest_date.isoformat(),
            "total_items": int(total_items or 0),
            "policy_pack_ids": policy_pack_ids,
            "selected_policy_pack_id": policy_pack_id0 or None,
        },
        "items": [
            _serialize_product_health_row(
                row,
                display_product_name=display_name_by_sku.get(str(getattr(row, "sku_id", "") or "").strip()),
            )
            for row in rows
        ],
        "freshness": _ai_ops_freshness_payload(db),
    }


@app.get("/ai/ops/reviews/summary", response_model=dict)
def ai_ops_reviews_summary(db: Session = Depends(get_db)):
    latest_date, rows = _ai_ops_latest_health_rows_for_policy_types(db, policy_types=["VOC_IMPROVEMENT_PRIORITY"])
    negative_ratios = []
    reply_improvement_count = 0
    for row in rows:
        evidence = _json_loads_dict(getattr(row, "evidence_json", None))
        review_snapshot = (evidence.get("review") if isinstance(evidence.get("review"), dict) else {}) or {}
        ratio = review_snapshot.get("low_rating_ratio")
        if ratio is not None:
            try:
                negative_ratios.append(float(ratio))
            except Exception:
                pass
        if float(getattr(row, "review_risk_score", 0.0) or 0.0) < 55.0:
            reply_improvement_count += 1
    return {
        "ok": True,
        "summary": {
            "snapshot_date": _ai_ops_iso_date(latest_date),
            "total_products": len(rows),
            "urgent_count": sum(1 for row in rows if float(getattr(row, "review_risk_score", 0.0) or 0.0) >= 65.0),
            "reply_improvement_count": int(reply_improvement_count),
            "hold_count": sum(1 for row in rows if float(getattr(row, "review_risk_score", 0.0) or 0.0) < 40.0),
            "avg_negative_ratio": round(sum(negative_ratios) / len(negative_ratios), 4) if negative_ratios else None,
        },
        "freshness": _ai_ops_freshness_payload(db),
    }


