@app.post("/ai/ops/execution/run", response_model=dict)
def ai_ops_execution_run(payload: AiOpsExecutionRunRequest, request: Request, db: Session = Depends(get_db)):
    actor, actor_role = _ai_ops_reviewer_context(request, reviewer=payload.actor, reviewer_role=payload.actor_role)
    queue_ids = [str(queue_id or "").strip() for queue_id in (payload.queue_ids or []) if str(queue_id or "").strip()]
    query = db.query(ActionQueueItem)
    if queue_ids:
        query = query.filter(ActionQueueItem.queue_id.in_(queue_ids))
    else:
        query = query.filter(ActionQueueItem.status == "APPROVED")
    rows = query.order_by(ActionQueueItem.updated_at.asc(), ActionQueueItem.created_at.asc(), ActionQueueItem.queue_id.asc()).limit(int(payload.limit)).all()

    processed_items: list[dict] = []
    skipped_count = 0
    for item in rows:
        current_status = str(getattr(item, "status", "") or "").strip().upper()
        if current_status not in {"APPROVED", "DONE"}:
            skipped_count += 1
            continue
        queue_payload = _json_loads_dict(getattr(item, "payload_json", None))
        execution_block = queue_payload.get("execution") if isinstance(queue_payload.get("execution"), dict) else {}
        last_result = execution_block.get("last_result") if isinstance(execution_block.get("last_result"), dict) else {}
        execution_result = build_execution_result(
            queue_id=str(getattr(item, "queue_id", "") or ""),
            action_type=str(getattr(item, "action_type", "") or ""),
            payload=queue_payload,
            actor=actor,
            actor_role=actor_role,
            dry_run=bool(payload.dry_run),
        )
        if (
            str(last_result.get("execution_key") or "").strip()
            and str(last_result.get("execution_key") or "").strip() == str(execution_result.get("execution_key") or "").strip()
            and current_status == "DONE"
        ):
            skipped_count += 1
            continue
        history = execution_block.get("history") if isinstance(execution_block.get("history"), list) else []
        history = [entry for entry in history if isinstance(entry, dict)]
        history.append(execution_result)
        queue_payload["execution"] = {
            "adapter": execution_result.get("adapter"),
            "last_result": execution_result,
            "history": history[-20:],
        }
        queue_payload = _ai_ops_append_audit_entry(
            queue_payload,
            event="EXECUTED",
            actor=actor,
            actor_role=actor_role,
            note=str(execution_result.get("summary") or "").strip() or None,
            status=str(execution_result.get("status") or "DONE"),
        )
        item.payload_json = json.dumps(queue_payload, ensure_ascii=False)
        item.status = _normalize_ai_ops_action_status(execution_result.get("status"))
        item.reviewer = str(getattr(item, "reviewer", "") or "").strip() or actor
        item.updated_at = datetime.now(ZoneInfo("Asia/Seoul"))
        db.add(item)
        processed_items.append({"queue_id": str(getattr(item, "queue_id", "") or ""), "_item": item})
    db.commit()
    response_items = []
    for entry in processed_items:
        item = entry.get("_item")
        if item is None:
            continue
        db.refresh(item)
        response_items.append({"queue_id": entry.get("queue_id"), "item": _serialize_action_queue_item(item, db=db)})
    return {
        "ok": True,
        "summary": {
            "requested_count": len(queue_ids) if queue_ids else len(rows),
            "processed_count": len(response_items),
            "skipped_count": int(skipped_count or 0),
            "dry_run": bool(payload.dry_run),
        },
        "items": response_items,
    }


@app.get("/ai/ops/logs", response_model=dict)
def ai_ops_logs(
    limit: int = Query(default=50, ge=1, le=200),
    policy_pack_id: str | None = Query(default=None),
    db: Session = Depends(get_db),
):
    latest_date = _ai_ops_latest_health_date(db)
    if latest_date is None:
        return {"ok": True, "summary": {"snapshot_date": None, "total_items": 0, "policy_pack_ids": []}, "items": []}

    all_rows = (
        db.query(DecisionProductHealthDaily)
        .filter(DecisionProductHealthDaily.date == latest_date)
        .order_by(DecisionProductHealthDaily.priority_score.desc(), DecisionProductHealthDaily.sku_id.asc())
        .all()
    )
    policy_pack_ids = sorted({pack_id for pack_id in (_ai_ops_policy_pack_id_from_row(row) for row in all_rows) if pack_id})
    policy_pack_id0 = str(policy_pack_id or "").strip()
    rows = [
        row for row in all_rows if not policy_pack_id0 or _ai_ops_policy_pack_id_from_row(row) == policy_pack_id0
    ][: int(limit)]
    sku_ids = [str(getattr(row, "sku_id", "") or "").strip() for row in rows if str(getattr(row, "sku_id", "") or "").strip()]

    latest_logs: dict[str, AiDecisionLog] = {}
    if sku_ids:
        log_rows = (
            db.query(AiDecisionLog)
            .filter(
                AiDecisionLog.analysis_type == "AI_OPS_PRODUCT_HEALTH",
                AiDecisionLog.entity_id.in_(sku_ids),
            )
            .order_by(AiDecisionLog.created_at.desc())
            .all()
        )
        for log_row in log_rows:
            entity_id = str(getattr(log_row, "entity_id", "") or "").strip()
            if entity_id and entity_id not in latest_logs:
                latest_logs[entity_id] = log_row

    latest_actions: dict[str, ActionQueueItem] = {}
    if sku_ids:
        action_rows = (
            db.query(ActionQueueItem)
            .filter(ActionQueueItem.entity_type == "sku", ActionQueueItem.entity_id.in_(sku_ids))
            .order_by(ActionQueueItem.updated_at.desc(), ActionQueueItem.created_at.desc())
            .all()
        )
        for action_row in action_rows:
            entity_id = str(getattr(action_row, "entity_id", "") or "").strip()
            if entity_id and entity_id not in latest_actions:
                latest_actions[entity_id] = action_row

    display_name_by_sku = _ai_ops_display_name_overrides(db, rows)
    items = [
        _serialize_ai_ops_log_item(
            db=db,
            row=row,
            decision_log=latest_logs.get(str(getattr(row, "sku_id", "") or "").strip()),
            latest_action=latest_actions.get(str(getattr(row, "sku_id", "") or "").strip()),
            display_product_name=display_name_by_sku.get(str(getattr(row, "sku_id", "") or "").strip()),
        )
        for row in rows
    ]
    return {
        "ok": True,
        "summary": {
            "snapshot_date": latest_date.isoformat(),
            "total_items": len(items),
            "policy_pack_ids": policy_pack_ids,
            "selected_policy_pack_id": policy_pack_id0 or None,
        },
        "items": items,
    }


@app.get("/ai/ops/policies", response_model=dict)
def ai_ops_policies(
    db: Session = Depends(get_db),
):
    latest_date = _ai_ops_latest_health_date(db)
    ai_settings = _get_ai_settings(db) or {}
    if latest_date is None:
        return {
            "ok": True,
            "summary": {
                "snapshot_date": None,
                "total_skus": 0,
                "policy_count": 0,
                "rule_pack_count": len((ai_settings or {}).get("rule_packs") or []),
                "format_version": str((ai_settings or {}).get("format_version") or ""),
                "common_rules_len": len(str((ai_settings or {}).get("common_rules") or "")),
            },
            "learning_items": [],
            "items": [],
        }

    rows = (
        db.query(DecisionProductHealthDaily)
        .filter(DecisionProductHealthDaily.date == latest_date)
        .order_by(DecisionProductHealthDaily.priority_score.desc(), DecisionProductHealthDaily.sku_id.asc())
        .all()
    )
    display_name_by_sku = _ai_ops_display_name_overrides(db, rows)
    grouped: dict[str, list[DecisionProductHealthDaily]] = {}
    for row in rows:
        key = str(getattr(row, "policy_type", "") or "").strip() or "UNCLASSIFIED"
        grouped.setdefault(key, []).append(row)

    items = [
        _serialize_ai_ops_policy_item(policy_rows, display_name_by_sku=display_name_by_sku)
        for _, policy_rows in sorted(
            grouped.items(),
            key=lambda item: (
                len(item[1]),
                sum(float(getattr(row, "priority_score", 0.0) or 0.0) for row in item[1]),
            ),
            reverse=True,
        )
    ]
    learning_items = _ai_ops_policy_learning_items(db)
    return {
        "ok": True,
        "summary": {
            "snapshot_date": latest_date.isoformat(),
            "total_skus": len(rows),
            "policy_count": len(items),
            "rule_pack_count": len((ai_settings or {}).get("rule_packs") or []),
            "format_version": str((ai_settings or {}).get("format_version") or ""),
            "common_rules_len": len(str((ai_settings or {}).get("common_rules") or "")),
        },
        "learning_items": learning_items,
        "items": items,
    }


@app.get("/ai/ops/policies/compare", response_model=dict)
def ai_ops_policies_compare(
    sku_id: str | None = Query(default=None),
    db: Session = Depends(get_db),
):
    latest_date = _ai_ops_latest_health_date(db)
    ai_settings = _get_ai_settings(db) or {}
    if latest_date is None:
        return {
            "ok": True,
            "summary": {
                "snapshot_date": None,
                "selected_sku_id": None,
                "selected_product_name": None,
                "current_policy_pack_id": None,
            },
            "candidates": [],
            "items": [],
        }
    rows = (
        db.query(DecisionProductHealthDaily)
        .filter(DecisionProductHealthDaily.date == latest_date)
        .order_by(DecisionProductHealthDaily.priority_score.desc(), DecisionProductHealthDaily.sku_id.asc())
        .all()
    )
    display_name_by_sku = _ai_ops_display_name_overrides(db, rows)
    if not rows:
        return {
            "ok": True,
            "summary": {
                "snapshot_date": latest_date.isoformat(),
                "selected_sku_id": None,
                "selected_product_name": None,
                "current_policy_pack_id": None,
            },
            "candidates": [],
            "items": [],
        }
    requested_sku_id = str(sku_id or "").strip()
    selected_row = None
    if requested_sku_id:
        for row in rows:
            if str(getattr(row, "sku_id", "") or "").strip() == requested_sku_id:
                selected_row = row
                break
        if selected_row is None:
            raise HTTPException(status_code=404, detail="sku_id not found in latest AI Ops snapshot")
    else:
        selected_row = rows[0]
    selected_row = selected_row or rows[0]
    rule_packs = _ai_ops_list_rule_packs(ai_settings)
    learning_map = _ai_ops_policy_learning_map(db)
    operation_learning_map = _ai_ops_policy_operation_learning_map(db)
    compare_items = [
        _serialize_ai_ops_policy_compare_item(
            selected_row,
            rule_pack=rule_pack,
            learning_item=learning_map.get(str((rule_pack.get("rule_id") if isinstance(rule_pack, dict) else "") or "AI_OPS")),
            operation_learning_item=operation_learning_map.get(
                _ai_ops_compare_policy_type_for_rule_pack(selected_row, rule_pack=rule_pack)
            ),
        )
        for rule_pack in rule_packs
    ]
    compare_items = sorted(
        compare_items,
        key=lambda item: float(item.get("recommendation_score") or 0.0),
        reverse=True,
    )
    if compare_items:
        compare_items[0]["recommended"] = True
    recommended_policy_pack_id = str((compare_items[0].get("policy_pack_id") if compare_items else "") or "").strip() or None
    return {
        "ok": True,
        "summary": {
            "snapshot_date": latest_date.isoformat(),
            "selected_sku_id": str(getattr(selected_row, "sku_id", "") or ""),
            "selected_product_name": display_name_by_sku.get(str(getattr(selected_row, "sku_id", "") or "").strip())
            or getattr(selected_row, "product_name", None),
            "current_policy_pack_id": _ai_ops_policy_pack_id_from_row(selected_row),
            "recommended_policy_pack_id": recommended_policy_pack_id,
        },
        "candidates": [
            _serialize_ai_ops_policy_compare_candidate(
                row,
                display_product_name=display_name_by_sku.get(str(getattr(row, "sku_id", "") or "").strip()),
            )
            for row in rows[:30]
        ],
        "items": compare_items,
    }


@app.post("/ai/ops/policies/compare/actions", response_model=dict)
def ai_ops_policy_compare_action_create(
    payload: AiOpsPolicyCompareActionCreateRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    latest_date, selected_row = _ai_ops_latest_snapshot_row(db, sku_id=payload.sku_id)
    if latest_date is None or selected_row is None:
        raise HTTPException(status_code=404, detail="sku_id not found in latest AI Ops snapshot")

    ai_settings = _get_ai_settings(db) or {}
    rule_packs = _ai_ops_list_rule_packs(ai_settings)
    target_rule_pack = _ai_ops_find_rule_pack(rule_packs, rule_id=payload.target_policy_pack_id)
    if target_rule_pack is None:
        raise HTTPException(status_code=404, detail="target_policy_pack_id not found")

    compare_item = _serialize_ai_ops_policy_compare_item(selected_row, rule_pack=target_rule_pack)
    if bool(compare_item.get("matches_current_pack")):
        raise HTTPException(status_code=400, detail="target_policy_pack_id matches current policy pack")
    action_priority, approval_recommendation, approval_recommendation_reason = _ai_ops_compare_action_recommendation(
        recommendation_score=compare_item.get("recommendation_score"),
        base_priority_score=getattr(selected_row, "priority_score", 0.0),
        matches_current_pack=bool(compare_item.get("matches_current_pack")),
    )

    current_policy_pack_id = _ai_ops_policy_pack_id_from_row(selected_row) or "AI_OPS"
    queue_payload = {
        "title": f"[{str(compare_item.get('policy_pack_title') or compare_item.get('policy_pack_id') or 'AI_OPS')}] {str(compare_item.get('recommended_action_primary') or '운영 액션 검토')}",
        "snapshot_date": latest_date.isoformat(),
        "product_name": getattr(selected_row, "product_name", None),
        "sku_id": str(getattr(selected_row, "sku_id", "") or ""),
        "current_policy_pack_id": current_policy_pack_id,
        "current_policy_type": getattr(selected_row, "policy_type", None),
        "current_top_issue": getattr(selected_row, "top_issue", None),
        "current_recommended_action": getattr(selected_row, "recommended_action_primary", None),
        "target_policy_pack_id": compare_item.get("policy_pack_id"),
        "target_policy_pack_title": compare_item.get("policy_pack_title"),
        "target_policy_type": compare_item.get("policy_type"),
        "target_top_issue": compare_item.get("top_issue"),
        "target_recommended_action": compare_item.get("recommended_action_primary"),
        "target_recommendation_score": compare_item.get("recommendation_score"),
        "target_recommendation_reason": compare_item.get("recommendation_reason"),
        "approval_recommendation": approval_recommendation,
        "approval_recommendation_reason": approval_recommendation_reason,
        "target_rules_triggered": compare_item.get("rules_triggered") or [],
        "target_scope": compare_item.get("scope") or {},
        "target_thresholds": compare_item.get("thresholds") or {},
        "changed_fields": [
            field_name
            for field_name in ("policy_type", "top_issue", "recommended_action_primary")
            if (
                {
                    "policy_type": getattr(selected_row, "policy_type", None),
                    "top_issue": getattr(selected_row, "top_issue", None),
                    "recommended_action_primary": getattr(selected_row, "recommended_action_primary", None),
                }.get(field_name)
                != {
                    "policy_type": compare_item.get("policy_type"),
                    "top_issue": compare_item.get("top_issue"),
                    "recommended_action_primary": compare_item.get("recommended_action_primary"),
                }.get(field_name)
            )
        ],
    }
    actor, actor_role = _ai_ops_reviewer_context(request)
    normalized_payload = _ai_ops_normalize_queue_payload(
        db=db,
        source_scope="ai-ops-policy-compare",
        entity_type="sku",
        entity_id=str(getattr(selected_row, "sku_id", "") or ""),
        action_type="QUEUE_POLICY_COMPARE_ACTION",
        payload=queue_payload,
        actor=actor,
        actor_role=actor_role,
        event="QUEUED",
        status="PENDING",
    )
    item = ActionQueueItem(
        queue_id=str(uuid.uuid4()),
        source_scope="ai-ops-policy-compare",
        entity_type="sku",
        entity_id=str(getattr(selected_row, "sku_id", "") or ""),
        action_type="QUEUE_POLICY_COMPARE_ACTION",
        payload_json=json.dumps(normalized_payload, ensure_ascii=False),
        priority=action_priority,
        status="PENDING",
    )
    db.add(item)
    db.commit()
    db.refresh(item)
    return {"ok": True, "item": _serialize_action_queue_item(item, db=db)}


@app.post("/ai/analyze/ads", response_model=AiAnalyzeAdsResponse)
def ai_analyze_ads(req: AiAnalyzeAdsRequest, db: Session = Depends(get_db)):
    """
    analytics DB(캠페인/광고그룹 분석 메뉴) 데이터를 서버가 읽어서 GPT로 분석해주는 엔드포인트.
    - DB → (기간 제한/요약) → OpenAI → 분석 결과 반환
    """
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise HTTPException(status_code=400, detail="OPENAI_API_KEY not configured (설정 > API 세팅에서 등록)")

    level = str(req.level or "").strip().lower()
    if level not in ("campaign", "adgroup"):
        raise HTTPException(status_code=400, detail="level must be campaign|adgroup")

    src = str(req.source or "creative").strip().lower()
    if src not in ("keyword", "creative"):
        raise HTTPException(status_code=400, detail="source must be keyword|creative")

    date_from, date_to = _ai_ads_date_range(req.date_from, req.date_to)
    prev_from, prev_to = _ai_ads_prev_range(date_from, date_to)

    # 메뉴3과 동일하게 daily 엔드포인트 로직을 재사용(= 동일한 집계 정의)
    if level == "campaign":
        curr_daily = list_campaign_daily(date_from=date_from, date_to=date_to, campaign=None, source=src, limit=2000, offset=0, db=db)
        prev_daily = list_campaign_daily(date_from=prev_from, date_to=prev_to, campaign=None, source=src, limit=2000, offset=0, db=db)
    else:
        camp = (str(req.campaign or "").strip() or None)
        curr_daily = list_adgroup_daily(
            date_from=date_from,
            date_to=date_to,
            campaign=camp,
            adgroup=None,
            source=src,
            limit=2000,
            offset=0,
            db=db,
        )
        prev_daily = list_adgroup_daily(
            date_from=prev_from,
            date_to=prev_to,
            campaign=camp,
            adgroup=None,
            source=src,
            limit=2000,
            offset=0,
            db=db,
        )

    curr_agg = _ai_agg_rows(list(curr_daily or []), level=level)
    prev_agg = _ai_agg_rows(list(prev_daily or []), level=level)

    # 요약(LLM 입력은 반드시 제한)
    top_n = 30
    summary = {
        "level": level,
        "source": src,
        "range": {"from": str(date_from), "to": str(date_to)},
        "prev_range": {"from": str(prev_from), "to": str(prev_to)},
        "counts": {
            "curr_daily_rows": len(list(curr_daily or [])),
            "prev_daily_rows": len(list(prev_daily or [])),
            "curr_items": len(curr_agg),
            "prev_items": len(prev_agg),
        },
        "top_curr_by_cost": curr_agg[:top_n],
        "top_prev_by_cost": prev_agg[:top_n],
    }

    question = (str(req.question or "").strip() or "아래 데이터를 요약하고, 문제점/기회요인/개선안을 제시해줘.")
    system = (
        "너는 퍼포먼스 마케팅 데이터 분석가다.\n"
        "주어진 집계 데이터를 기반으로만 판단하고, 근거 없는 단정은 피한다.\n"
        "출력은 한국어로, 간결한 Markdown으로:\n"
        "1) 요약\n2) 성과 좋은 항목 Top\n3) 문제/리스크(이상치 포함)\n4) 액션 아이템(우선순위)\n"
    )

    # 이어서 질문을 위한 thread 정제/제한(토큰 폭증 방지)
    thread_msgs: list[dict] = []
    try:
        raw_thread = req.thread or []
        # 너무 길면 비용/지연이 커지므로 최근 20개만 사용
        raw_thread = raw_thread[-20:]
        for m in raw_thread:
            role = str(getattr(m, "role", "") or "").strip().lower()
            content = str(getattr(m, "content", "") or "").strip()
            if role not in ("user", "assistant"):
                # system 등은 서버가 관리하므로 무시
                continue
            if not content:
                continue
            # 메시지 1개 길이 제한(안전)
            if len(content) > 6000:
                content = content[:6000] + "…"
            thread_msgs.append({"role": role, "content": content})
    except Exception:
        thread_msgs = []

    payload = {
        "model": (str(req.model or "").strip() or OPENAI_DEFAULT_MODEL),
        "temperature": 0.2,
        "messages": [
            {"role": "system", "content": system},
            {
                "role": "user",
                "content": "다음은 analytics DB에서 조회한 캠페인/광고그룹 집계 요약(JSON)이다.\n"
                + json.dumps(summary, ensure_ascii=False),
            },
            *thread_msgs,
            {"role": "user", "content": question},
        ],
    }

    try:
        resp = requests.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
            json=payload,
            timeout=60,
        )
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"OpenAI 요청 실패: {e}")

    if int(resp.status_code) != 200:
        raise HTTPException(status_code=502, detail=f"OpenAI 실패({resp.status_code}) {_safe_err_text(resp)}".strip())

    try:
        j = resp.json() or {}
        choices = j.get("choices") or []
        msg = (choices[0] or {}).get("message") if isinstance(choices, list) and choices else None
        content = str((msg or {}).get("content") or "").strip()
    except Exception:
        content = ""

    if not content:
        raise HTTPException(status_code=502, detail="OpenAI 응답에 content가 없습니다.")

    return AiAnalyzeAdsResponse(
        ok=True,
        analysis=content,
        meta={"level": level, "source": src, "range": {"from": str(date_from), "to": str(date_to)}},
        summary=summary,
    )


