class AdsPurgeRequest(BaseModel):
    mode: str | None = "single"  # single | range
    date: str | None = None
    date_from: str | None = None
    date_to: str | None = None
    kinds: list[str] | None = None  # ["keyword","searchword","creative"] (미지정 시 모두)
    campaigns: list[str] | None = None
    adgroups: list[str] | None = None
    key: str | None = None  # 삭제키(서버 env ADS_PURGE_KEY 설정 시 필수)


@app.post("/ads/purge", response_model=dict)
def purge_ads(req: AdsPurgeRequest):
    """
    일자 단위로 데이터를 삭제 후 재수집하기 위한 endpoint.

    - 서버 env `ADS_PURGE_KEY`가 설정되어 있으면, req.key가 일치해야 한다.
    - mode=single: date (없으면 에러)
    - mode=range: date_from/date_to (최대 31일)
    """
    purge_key = str(os.getenv("ADS_PURGE_KEY") or "").strip()
    if purge_key:
        if str(req.key or "").strip() != purge_key:
            raise HTTPException(status_code=403, detail="invalid purge key")

    def _is_ymd(s: str) -> bool:
        return bool(re.match(r"^\d{4}-\d{2}-\d{2}$", (s or "").strip()))

    mode = (req.mode or "single").strip().lower()
    kinds = tuple((req.kinds or ["keyword", "searchword", "creative"]))
    if not kinds:
        kinds = ("keyword", "searchword", "creative")

    if mode == "single":
        d = str(req.date or "").strip()
        if not _is_ymd(d):
            raise HTTPException(status_code=400, detail="date must be YYYY-MM-DD")
        df = d
        dt = d
    elif mode == "range":
        df = str(req.date_from or "").strip()
        dt = str(req.date_to or "").strip()
        if not _is_ymd(df) or not _is_ymd(dt):
            raise HTTPException(status_code=400, detail="date_from/date_to must be YYYY-MM-DD")
    else:
        raise HTTPException(status_code=400, detail="mode must be single|range")

    start = datetime.strptime(df, "%Y-%m-%d").date()
    end = datetime.strptime(dt, "%Y-%m-%d").date()
    if start > end:
        start, end = end, start
    if (end - start).days + 1 > 31:
        raise HTTPException(status_code=400, detail="date range too large (max 31 days)")

    scope_camps = [str(x or "").strip() for x in (req.campaigns or []) if str(x or "").strip()]
    # purge도 선행 '#' 유무 혼재를 고려해 variants로 확장
    if scope_camps:
        scope_camps = _expand_campaign_names(set(scope_camps))
    scope_grps = [str(x or "").strip() for x in (req.adgroups or []) if str(x or "").strip()]

    deleted = {"keyword": 0, "searchword": 0, "creative": 0}
    processed: list[dict] = []
    cur = start
    while cur <= end:
        d0 = cur
        try:
            from db import SessionLocal
            from db import NaverAdKeywordDaily, NaverAdSearchwordDaily, NaverAdCreativeDaily

            with SessionLocal() as s:
                if "keyword" in kinds:
                    q = s.query(NaverAdKeywordDaily).filter(NaverAdKeywordDaily.date == d0)
                    if scope_camps:
                        q = q.filter(NaverAdKeywordDaily.campaign_name.in_(scope_camps))
                    if scope_grps:
                        q = q.filter(NaverAdKeywordDaily.adgroup_name.in_(scope_grps))
                    deleted["keyword"] += int(q.delete(synchronize_session=False) or 0)

                if "searchword" in kinds:
                    q = s.query(NaverAdSearchwordDaily).filter(NaverAdSearchwordDaily.date == d0)
                    if scope_camps:
                        q = q.filter(NaverAdSearchwordDaily.campaign_name.in_(scope_camps))
                    if scope_grps:
                        q = q.filter(NaverAdSearchwordDaily.adgroup_name.in_(scope_grps))
                    deleted["searchword"] += int(q.delete(synchronize_session=False) or 0)

                if "creative" in kinds:
                    q = s.query(NaverAdCreativeDaily).filter(NaverAdCreativeDaily.date == d0)
                    if scope_camps:
                        q = q.filter(NaverAdCreativeDaily.campaign_name.in_(scope_camps))
                    if scope_grps:
                        q = q.filter(NaverAdCreativeDaily.adgroup_name.in_(scope_grps))
                    deleted["creative"] += int(q.delete(synchronize_session=False) or 0)

                s.commit()

            processed.append({"date": d0.strftime("%Y-%m-%d"), "ok": True})
        except Exception as e:
            processed.append({"date": d0.strftime("%Y-%m-%d"), "ok": False, "error": str(e)})
        cur = cur + timedelta(days=1)

    return {
        "ok": all(bool(x.get("ok")) for x in processed),
        "from": start.strftime("%Y-%m-%d"),
        "to": end.strftime("%Y-%m-%d"),
        "kinds": list(kinds),
        "scope": {"campaigns": scope_camps or None, "adgroups": scope_grps or None},
        "deleted": deleted,
        "processed": processed,
    }


class AdsValidateFixRequest(BaseModel):
    date_from: str
    date_to: str | None = None
    campaigns: list[str] | None = None  # 캠페인명(표시명) 범위
    adgroups: list[str] | None = None  # 광고그룹명(표시명) 범위
    max_groups_per_day: int | None = 80  # 일자당 검사할 그룹 상한(비용 상위순)
    dry_run: bool | None = False  # true면 수집은 하지 않고 비교만


@app.post("/ads/validate-fix", response_model=dict)
def ads_validate_fix(req: AdsValidateFixRequest):
    """
    정합성 검사 + 누락 그룹만 재수집(보정)
    - 기준: /ncc/ads(기대 소재ID) vs DB(naver_ad_creative_daily에 저장된 소재ID)
    - 누락이 있으면 해당 (캠페인, 광고그룹)만 scope로 /ads/collect(creative)와 동일 로직을 실행한다.
    """
    def _is_ymd(s: str) -> bool:
        return bool(re.match(r"^\d{4}-\d{2}-\d{2}$", (s or "").strip()))

    df = str(req.date_from or "").strip()
    dt = str(req.date_to or "").strip() if req.date_to else df
    if not _is_ymd(df) or not _is_ymd(dt):
        raise HTTPException(status_code=400, detail="date_from/date_to must be YYYY-MM-DD")

    start = datetime.strptime(df, "%Y-%m-%d").date()
    end = datetime.strptime(dt, "%Y-%m-%d").date()
    if start > end:
        start, end = end, start
    if (end - start).days + 1 > 31:
        raise HTTPException(status_code=400, detail="date range too large (max 31 days)")

    scope_camps = {str(x or "").strip() for x in (req.campaigns or []) if str(x or "").strip()}
    if scope_camps:
        scope_camps = set(_expand_campaign_names(scope_camps))
    scope_grps = {str(x or "").strip() for x in (req.adgroups or []) if str(x or "").strip()}
    max_groups = max(1, min(int(req.max_groups_per_day or 80), 300))
    dry_run = bool(req.dry_run)

    # 1) SearchAd 메타에서 (campaignName, adgroupName) -> adgroupId(s) 매핑
    #    - DB/UI는 leading '#' 유무가 혼재할 수 있어, 정규화(leading '#')를 무시하고 양쪽 variant로 매핑한다.
    def _norm_name(x: str) -> str:
        return str(x or "").strip().lstrip("#").strip()

    def _name_variants(x: str) -> list[str]:
        b = _norm_name(x)
        if not b:
            return []
        return [b, f"#{b}"]
    try:
        resp_g = _searchad_get("/ncc/adgroups", timeout=25.0)
        groups = resp_g.json() if resp_g.status_code < 400 else []
    except Exception:
        groups = []

    name_to_gids: dict[tuple[str, str], list[str]] = {}
    # campaign_name_map을 포함한 메타 로딩(캐시)
    try:
        _, _, _, campaign_status_by_name, _ = _searchad_build_meta(include_keywords=False)
    except Exception:
        campaign_status_by_name = {}
    # _searchad_build_meta 내부에서 campaign_name_map을 직접 반환하지 않으므로, 여기서는 /ncc/campaigns로 직접 가져온다.
    try:
        resp_c = _searchad_get("/ncc/campaigns", timeout=25.0)
        camps = resp_c.json() if resp_c.status_code < 400 else []
    except Exception:
        camps = []
    cid_to_name: dict[str, str] = {}
    if isinstance(camps, list):
        for c in camps:
            if isinstance(c, dict):
                cid = str(c.get("nccCampaignId") or "").strip()
                nm = str(c.get("name") or "").strip()
                if cid and nm:
                    cid_to_name[cid] = nm

    if isinstance(groups, list):
        for g in groups:
            if not isinstance(g, dict):
                continue
            gid = str(g.get("nccAdgroupId") or "").strip()
            gnm = str(g.get("name") or "").strip()
            cid = str(g.get("nccCampaignId") or "").strip()
            cnm = str(cid_to_name.get(cid, "") or "").strip()
            if not gid or not gnm or not cnm:
                continue
            for c0 in _name_variants(cnm):
                for g0 in _name_variants(gnm):
                    key = (c0, g0)
                    arr = name_to_gids.get(key) or []
                    if gid not in arr:
                        arr.append(gid)
                    name_to_gids[key] = arr

    processed: list[dict] = []
    cur = start
    totals = {"days": 0, "groups_checked": 0, "groups_mismatch": 0, "groups_fixed": 0, "groups_skipped_not_ready": 0}

    from db import SessionLocal, NaverAdCreativeDaily

    while cur <= end:
        dt0 = cur
        totals["days"] += 1

        # 2) DB에서 해당 날짜의 (campaign, adgroup) 후보를 비용 상위순으로 가져온다.
        with SessionLocal() as s:
            q = (
                s.query(
                    NaverAdCreativeDaily.campaign_name.label("campaign_name"),
                    NaverAdCreativeDaily.adgroup_name.label("adgroup_name"),
                    func.sum(NaverAdCreativeDaily.cost).label("cost"),
                )
                .filter(NaverAdCreativeDaily.date == dt0)
                .group_by(NaverAdCreativeDaily.campaign_name, NaverAdCreativeDaily.adgroup_name)
                .order_by(func.sum(NaverAdCreativeDaily.cost).desc())
            )
            if scope_camps:
                q = q.filter(NaverAdCreativeDaily.campaign_name.in_(sorted(list(scope_camps))))
            if scope_grps:
                q = q.filter(NaverAdCreativeDaily.adgroup_name.in_(sorted(list(scope_grps))))
            candidates = q.limit(max_groups).all()

        day_items: list[dict] = []
        for r in candidates:
            camp = str(r.campaign_name or "").strip()
            grp = str(r.adgroup_name or "").strip()
            if not camp or not grp:
                continue

            # 이름 매칭은 '#' 유무를 모두 허용
            gids = []
            for c0 in _name_variants(camp):
                for g0 in _name_variants(grp):
                    gids = name_to_gids.get((c0, g0)) or []
                    if gids:
                        break
                if gids:
                    break
            expected_ids: set[str] = set()
            missing_ids: list[str] = []

            # stored ids
            with SessionLocal() as s2:
                stored_ids = {
                    str(x[0]).strip()
                    for x in (
                        s2.query(NaverAdCreativeDaily.creative_id)
                        .filter(NaverAdCreativeDaily.date == dt0)
                        .filter(NaverAdCreativeDaily.campaign_name == camp)
                        .filter(NaverAdCreativeDaily.adgroup_name == grp)
                        .distinct()
                        .all()
                    )
                    if str(x[0]).strip()
                }

            # expected ids (SearchAd /ncc/ads)
            try:
                if gids:
                    ads_meta = _searchad_build_ads_meta_by_adgroup(gids)
                    expected_ids = {str(k).strip() for k in (ads_meta or {}).keys() if str(k or "").strip()}
            except Exception:
                expected_ids = set()

            if expected_ids:
                missing_ids = sorted(list(expected_ids - stored_ids))

            mismatch = bool(expected_ids) and (len(missing_ids) > 0)
            totals["groups_checked"] += 1
            if mismatch:
                totals["groups_mismatch"] += 1

            fixed = False
            skipped_not_ready = False
            error = None
            if mismatch and (not dry_run):
                try:
                    _collect_searchad_daily(
                        dt0.strftime("%Y-%m-%d"),
                        kinds=("creative",),
                        scope_campaigns=[camp],
                        scope_adgroups=[grp],
                        verify_missing=True,
                        max_retries=1,
                    )
                    fixed = True
                    totals["groups_fixed"] += 1
                except HTTPException as he:
                    if he.status_code == 503 and "REPORT_NOT_READY" in str(he.detail or ""):
                        skipped_not_ready = True
                        totals["groups_skipped_not_ready"] += 1
                        try:
                            _REPORT_NOT_READY_SCHED.enqueue(
                                date=dt0.strftime("%Y-%m-%d"),
                                kinds=("creative",),
                                scope_campaigns=[camp],
                                scope_adgroups=[grp],
                                verify_missing=True,
                                max_retries=1,
                            )
                        except Exception:
                            pass
                    else:
                        error = str(he.detail or "")
                except Exception as e:
                    error = str(e)

            # after count
            stored_after = None
            if mismatch and fixed:
                try:
                    with SessionLocal() as s3:
                        stored_after = int(
                            s3.query(NaverAdCreativeDaily.creative_id)
                            .filter(NaverAdCreativeDaily.date == dt0)
                            .filter(NaverAdCreativeDaily.campaign_name == camp)
                            .filter(NaverAdCreativeDaily.adgroup_name == grp)
                            .distinct()
                            .count()
                        )
                except Exception:
                    stored_after = None

            day_items.append(
                {
                    "date": dt0.strftime("%Y-%m-%d"),
                    "campaign": camp,
                    "adgroup": grp,
                    "expected_count": len(expected_ids) if expected_ids else None,
                    "stored_count": len(stored_ids),
                    "missing_count": len(missing_ids),
                    "missing_sample": missing_ids[:20],
                    "fixed": fixed,
                    "skipped_report_not_ready": skipped_not_ready,
                    "stored_after": stored_after,
                    "error": error,
                }
            )

        processed.append({"date": dt0.strftime("%Y-%m-%d"), "items": day_items})
        cur = cur + timedelta(days=1)

    return {
        "ok": True,
        "dry_run": dry_run,
        "from": start.strftime("%Y-%m-%d"),
        "to": end.strftime("%Y-%m-%d"),
        "scope": {"campaigns": sorted(list(scope_camps)) if scope_camps else None, "adgroups": sorted(list(scope_grps)) if scope_grps else None},
        "totals": totals,
        "processed": processed,
        "note": "expected_count는 SearchAd /ncc/ads 기준이며, 캠페인/광고그룹명 매칭이 불가하면 None일 수 있습니다.",
    }


class AdsSearchwordAdvancedReportUploadPayload(BaseModel):
    date_from: str = Field(..., description="YYYY-MM-DD")
    date_to: str = Field(..., description="YYYY-MM-DD")
    report: Dict[str, Any] = Field(default_factory=dict)


def _advanced_report_payload_to_searchword_df(
    payload: dict,
    *,
    date_from: str,
    date_to: str,
) -> tuple[pd.DataFrame, list[str], int]:
    head = payload.get("head")
    body = payload.get("body")
    if not isinstance(head, list):
        head = []
    if not isinstance(body, list):
        body = []

    raw_rows: list[dict] = []
    for item in body:
        if isinstance(item, dict):
            raw_rows.append(dict(item))
        elif isinstance(item, list):
            raw_rows.append({str(k): (item[i] if i < len(item) else None) for i, k in enumerate(head)})

    try:
        campaign_name_map, adgroup_name_map, _kw, _camp_st, _grp_st = _searchad_build_meta(include_keywords=False)
    except Exception:
        campaign_name_map, adgroup_name_map = {}, {}

    campaign_ids = {str(r.get("nccCampaignId") or "").strip() for r in raw_rows if str(r.get("nccCampaignId") or "").strip()}
    adgroup_ids = {str(r.get("nccAdgroupId") or "").strip() for r in raw_rows if str(r.get("nccAdgroupId") or "").strip()}
    campaign_name_map, adgroup_name_map, _ = _refresh_light_meta_if_unknown_ids(
        campaign_ids=campaign_ids,
        adgroup_ids=adgroup_ids,
        campaign_name_map=campaign_name_map,
        adgroup_name_map=adgroup_name_map,
    )

    VAT_RATE = 1.1

    def _to_int(v: object) -> int:
        try:
            if v is None or isinstance(v, bool):
                return int(v or 0)
            if isinstance(v, (int, float)):
                return int(round(float(v)))
            s = re.sub(r"[^\d.\-]", "", str(v or "").replace(",", "").strip())
            return int(round(float(s))) if s else 0
        except Exception:
            return 0

    def _to_float(v: object) -> float:
        try:
            if v is None or isinstance(v, bool):
                return float(int(v or 0))
            if isinstance(v, (int, float)):
                return float(v)
            s = re.sub(r"[^\d.\-]", "", str(v or "").replace(",", "").strip())
            return float(s) if s else 0.0
        except Exception:
            return 0.0

    def _norm_ymd(v: object) -> str:
        s = str(v or "").strip()
        m = re.match(r"^(\d{4})(\d{2})(\d{2})$", s)
        if m:
            return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
        m2 = re.match(r"^(\d{4})[-.](\d{1,2})[-.](\d{1,2})\.?$", s)
        if m2:
            return f"{m2.group(1)}-{m2.group(2).zfill(2)}-{m2.group(3).zfill(2)}"
        return ""

    out_rows: list[dict] = []
    processed_dates: set[str] = set()
    for row in raw_rows:
        ymd = _norm_ymd(row.get("ymd") or row.get("date") or row.get("일별"))
        if not ymd:
            continue
        processed_dates.add(ymd)
        camp_id = str(row.get("nccCampaignId") or "").strip()
        grp_id = str(row.get("nccAdgroupId") or "").strip()
        searchword = str(row.get("expKeyword") or row.get("searchword") or row.get("query") or row.get("keywordId") or "").strip()
        if not searchword:
            continue

        imp = _to_int(row.get("impCnt"))
        clk = _to_int(row.get("clkCnt"))
        cost = int(round(_to_float(row.get("salesAmt")) * VAT_RATE))
        conv = _to_int(row.get("ccnt") or row.get("convCnt"))
        rev = _to_int(row.get("convAmt"))
        purchase_conv = _to_int(row.get("purchaseCcnt") or row.get("purchaseConvCnt"))
        purchase_rev = _to_int(row.get("purchaseConvAmt"))
        ctr = (clk / imp * 100.0) if imp > 0 else _to_float(row.get("ctr"))
        cpc = (cost / clk) if clk > 0 else _to_float(row.get("cpc"))
        cvr = (conv / clk * 100.0) if clk > 0 else _to_float(row.get("crto"))
        roas = (rev / cost * 100.0) if cost > 0 else _to_float(row.get("ror"))

        out_rows.append(
            {
                "캠페인": campaign_name_map.get(camp_id, camp_id),
                "광고 그룹": adgroup_name_map.get(grp_id, grp_id),
                "캠페인유형": str(row.get("nccCampaignTp") or "").strip(),
                "검색어": searchword,
                "키워드": searchword,
                "일별": ymd,
                "노출수": imp,
                "클릭수": clk,
                "클릭률(%)": round(ctr, 2),
                "총비용(원)": cost,
                "전환수": conv,
                "구매전환수": purchase_conv,
                "전환율(%)": round(cvr, 2),
                "전환매출액(원)": rev,
                "구매전환매출액(원)": purchase_rev,
                "ROAS(%)": round(roas, 2),
                "CPC(원)": round(cpc, 0),
            }
        )

    df = pd.DataFrame(out_rows)
    return df, sorted(processed_dates), len(raw_rows)


@app.post("/ads/searchwords/advanced-report-upload", response_model=dict)
def upload_searchword_advanced_report(payload: AdsSearchwordAdvancedReportUploadPayload):
    date_from = str(payload.date_from or "").strip()
    date_to = str(payload.date_to or "").strip()
    if not (re.match(r"^\d{4}-\d{2}-\d{2}$", date_from) and re.match(r"^\d{4}-\d{2}-\d{2}$", date_to)):
        raise HTTPException(status_code=400, detail="date_from/date_to must be YYYY-MM-DD")

    report = dict(payload.report or {})
    time_range = report.get("timeRange") if isinstance(report.get("timeRange"), dict) else {}
    since = str(time_range.get("since") or "").strip()
    until = str(time_range.get("until") or "").strip()
    if since and since != date_from.replace("-", ""):
        raise HTTPException(status_code=400, detail={"error": "searchword_report_date_mismatch", "expected_from": date_from, "actual_since": since})
    if until and until != date_to.replace("-", ""):
        raise HTTPException(status_code=400, detail={"error": "searchword_report_date_mismatch", "expected_to": date_to, "actual_until": until})

    df_norm, processed_dates, raw_rows = _advanced_report_payload_to_searchword_df(report, date_from=date_from, date_to=date_to)
    out_of_range = [ymd for ymd in processed_dates if ymd < date_from or ymd > date_to]
    if out_of_range:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "searchword_report_date_mismatch",
                "expected_from": date_from,
                "expected_to": date_to,
                "processed_dates": processed_dates,
            },
        )

    inserted_total = 0
    inserted_by_date: dict[str, int] = {}
    for ymd in processed_dates:
        part = df_norm[df_norm["일별"] == ymd].copy() if ("일별" in df_norm.columns and not df_norm.empty) else pd.DataFrame([])
        n = upsert_searchword_daily_from_df(part, ymd, source="ui_csv_upload")
        inserted_total += int(n or 0)
        inserted_by_date[ymd] = int(n or 0)

    return {
        "ok": True,
        "date_from": date_from,
        "date_to": date_to,
        "timeRange": time_range,
        "processed_dates": processed_dates,
        "raw_rows": raw_rows,
        "inserted_by_date": inserted_by_date,
        "insertedSearchword": int(inserted_total or 0),
    }


@app.post("/ads/searchwords/upload", response_model=dict)
async def upload_searchword_csv(
    date: str = Query(..., description="YYYY-MM-DD"),
    date_from: Optional[str] = Query(None, description="자동 수집 검증용 시작일 YYYY-MM-DD"),
    date_to: Optional[str] = Query(None, description="자동 수집 검증용 종료일 YYYY-MM-DD"),
    file: UploadFile = File(...),
):
    """
    SearchAd API가 검색어 리포트를 제공하지 않는 계정(400/11001 등) 대응용 폴백.
    네이버 광고 UI에서 다운로드한 '검색어 보고서' CSV를 업로드하면
    `naver_ad_searchword_daily`에 upsert 한다.
    """
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", (date or "").strip()):
        raise HTTPException(status_code=400, detail="date must be YYYY-MM-DD")

    content = await file.read()
    if not content:
        raise HTTPException(status_code=400, detail="empty file")

    df_raw = _read_ui_searchword_csv_bytes_raw_df(content=content, filename=getattr(file, "filename", None))
    fallback_ymd = str(df_raw.attrs.get("title_ymd") or df_raw.attrs.get("filename_ymd") or date).strip()
    df_norm = _normalize_ui_searchword_csv_to_df(df_raw, date_ymd=fallback_ymd)
    day_values = df_norm["일별"].tolist() if ("일별" in df_norm.columns) else []
    processed_dates = sorted({str(v or "").strip() for v in day_values if str(v or "").strip()})
    expected_from = str(date_from or "").strip()
    expected_to = str(date_to or "").strip()
    if expected_from or expected_to:
        if not (re.match(r"^\d{4}-\d{2}-\d{2}$", expected_from) and re.match(r"^\d{4}-\d{2}-\d{2}$", expected_to)):
            raise HTTPException(status_code=400, detail="date_from/date_to must be YYYY-MM-DD")
        if "일별" in df_norm.columns:
            date_values = df_norm["일별"].astype(str).str.strip()
            df_norm = df_norm[(date_values >= expected_from) & (date_values <= expected_to)].copy()
            day_values = df_norm["일별"].tolist() if ("일별" in df_norm.columns) else []
            processed_dates = sorted({str(v or "").strip() for v in day_values if str(v or "").strip()})
        elif fallback_ymd < expected_from or fallback_ymd > expected_to:
            raise HTTPException(
                status_code=400,
                detail={
                    "error": "searchword_report_date_mismatch",
                    "expected_from": expected_from,
                    "expected_to": expected_to,
                    "processed_dates": [fallback_ymd],
                    "message": "다운로드한 검색어 보고서의 날짜를 확인할 수 없거나 요청 기간 밖입니다.",
                },
            )
    _assert_post_cutover_conversion_headers(
        df_raw,
        target_dates=[datetime.strptime(ymd, "%Y-%m-%d").date() for ymd in processed_dates] if processed_dates else [datetime.strptime(fallback_ymd, "%Y-%m-%d").date()],
        report_name="검색어 보고서 업로드",
    )

    inserted_total = 0
    inserted_by_date: dict[str, int] = {}
    for ymd in processed_dates or [fallback_ymd]:
        part = df_norm[df_norm["일별"] == ymd].copy() if "일별" in df_norm.columns else df_norm.copy()
        n = upsert_searchword_daily_from_df(part, ymd, source="ui_csv_upload")
        inserted_total += int(n or 0)
        inserted_by_date[ymd] = int(n or 0)

    return {
        "ok": True,
        "date": processed_dates[0] if len(processed_dates) == 1 else date,
        "requested_date": date,
        "processed_dates": processed_dates or [fallback_ymd],
        "inserted_by_date": inserted_by_date,
        "insertedSearchword": int(inserted_total or 0),
    }


@app.get("/ads/debug-report", response_model=dict)
def debug_ads_report(
    report_tp: str = Query("AD", description="예: AD, SEARCH"),
    date: str = Query(..., description="YYYY-MM-DD"),
    levels: str | None = Query(None, description="콤마(,)로 구분된 level 리스트 (예: keyword / CAMPAIGN,ADGROUP,KEYWORD)"),
    fields: str | None = Query(None, description="콤마(,)로 구분된 fields 리스트 (예: impCnt,clkCnt,salesAmt)"),
):
    """
    SearchAd stat-reports 응답(일부 샘플)을 확인하기 위한 디버그 엔드포인트.
    - 민감정보(키/시크릿)는 반환하지 않는다.
    """
    tp = (report_tp or "").strip().upper()
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", (date or "").strip()):
        raise HTTPException(status_code=400, detail="date must be YYYY-MM-DD")

    # 현재 구현에서 사용하는 기본 조합을 그대로 호출하되, 실패 시 에러 본문을 반환한다.
    try:
        if levels and str(levels).strip():
            levels_list = [s.strip() for s in str(levels).split(",") if s.strip()]
        else:
            levels_list = ["keyword"] if tp == "AD" else ["query"]

        if fields and str(fields).strip():
            fields_list = [s.strip() for s in str(fields).split(",") if s.strip()]
        else:
            fields_list = ["impCnt", "clkCnt", "salesAmt", "convCnt", "convAmt"] if tp == "AD" else ["impCnt", "clkCnt", "salesAmt"]

        rows = _searchad_fetch_report_rows(report_tp=tp, date_ymd=date, levels=levels_list, fields=fields_list)
        sample = [r for r in rows[:3] if isinstance(r, dict)]
        keys = sorted(list(sample[0].keys())) if sample else []
        return {
            "ok": True,
            "reportTp": tp,
            "date": date,
            "levels": levels_list,
            "fields": fields_list,
            "rowCount": len(rows),
            "sampleKeys": keys,
            "sampleRows": sample,
        }
    except HTTPException as he:
        return {"ok": False, "reportTp": tp, "date": date, "detail": he.detail}
    except Exception as e:
        return {"ok": False, "reportTp": tp, "date": date, "detail": str(e)}


@app.get("/ads/debug-report-raw", response_model=dict)
def debug_ads_report_raw(
    report_tp: str = Query("EXPKEYWORD", description="예: AD, EXPKEYWORD"),
    date: str = Query(..., description="YYYY-MM-DD"),
):
    """
    stat-reports 다운로드 원문(앞부분) 확인용 디버그.
    - 파싱 문제(컬럼 순서/헤더 유무) 진단에 사용하여, 오인 파싱을 구조적으로 제거한다.
    - 민감정보(키/시크릿)는 반환하지 않는다.
    """
    tp = (report_tp or "").strip().upper()
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", (date or "").strip()):
        raise HTTPException(status_code=400, detail="date must be YYYY-MM-DD")
    try:
        # 기본값은 debug-report와 동일 규칙
        levels_list = ["keyword"] if tp == "AD" else ["query"]
        fields_list = ["impCnt", "clkCnt", "salesAmt", "convCnt", "convAmt"] if tp == "AD" else ["impCnt", "clkCnt", "salesAmt"]

        stat_dt = _searchad_stat_dt(date)
        created = _searchad_create_report(report_tp=tp, stat_dt=stat_dt, levels=levels_list, fields=fields_list)
        dl = created.get("downloadUrl")
        rid = created.get("reportJobId") or created.get("id")
        if (not dl) and rid:
            dl = _searchad_wait_report(str(rid), timeout_sec=60, interval_sec=3)
        if not dl:
            return {"ok": False, "reportTp": tp, "date": date, "detail": "no downloadUrl"}

        raw = str(dl).strip()
        parsed = urlparse(raw)
        if parsed.scheme and parsed.netloc:
            uri = parsed.path
            url = raw
        else:
            uri = raw if raw.startswith("/") else f"/{raw}"
            url = f"{_searchad_base_url()}{uri}"
        headers = _searchad_headers(method="GET", uri=uri)
        resp = requests.get(url, headers=headers, timeout=30)
        txt = resp.text or ""
        lines = [ln for ln in txt.splitlines() if ln.strip()]
        non_zero = ""
        try:
            for ln in lines[:2000]:
                parts = [p.strip() for p in ln.split("\t")]
                # 숫자처럼 보이는 값 중 하나라도 0이 아니면 샘플로 채택
                for p in parts[-6:]:
                    s = str(p or "").strip()
                    if not s:
                        continue
                    if re.match(r"^-?\d+(\.\d+)?$", s) and s not in ("0", "0.0", "-0", "-0.0", "1", "1.0"):
                        non_zero = ln
                        break
                if non_zero:
                    break
        except Exception:
            non_zero = ""
        return {
            "ok": resp.status_code < 400,
            "reportTp": tp,
            "date": date,
            "httpStatus": resp.status_code,
            "lineCount": len(lines),
            "firstLine": lines[0] if lines else "",
            "secondLine": lines[1] if len(lines) > 1 else "",
            "sampleNonZeroLine": non_zero,
        }
    except HTTPException as he:
        return {"ok": False, "reportTp": tp, "date": date, "detail": he.detail}
    except Exception as e:
        return {"ok": False, "reportTp": tp, "date": date, "detail": str(e)}


@app.get("/research/keyword-insights", response_model=dict)
def keyword_insights(
    keyword: str = Query(..., description="분석할 키워드"),
    date_from: str = Query(..., description="YYYY-MM-DD"),
    date_to: str = Query(..., description="YYYY-MM-DD"),
    shopping_category: str | None = Query(None, description="DataLab 쇼핑 분포에 사용할 쇼핑 카테고리 ID (예: 50000000)"),
    force: bool = Query(False, description="true면 서버 캐시를 무시하고 다시 수집/계산"),
):
    """
    menu5-research > 키워드 리서치/전략 화면에서 사용하는 '키워드 인사이트' API.

    - 트렌드: DataLab search
    - 검색 비율(성별/연령/디바이스): DataLab shopping (카테고리 기반)
    - 연관 키워드: SearchAd keywordstool (자격증명 없으면 relatedKeywords는 빈 배열)
    - 상품수/카테고리: 쇼핑 검색 페이지(비공식 HTML 파싱)
    """
    # 단순 포맷 검증
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", date_from) or not re.match(
        r"^\d{4}-\d{2}-\d{2}$", date_to
    ):
        raise HTTPException(status_code=400, detail="date_from/date_to must be YYYY-MM-DD")
    return _build_keyword_insights(
        keyword=keyword,
        date_from=date_from,
        date_to=date_to,
        shopping_category=shopping_category,
        force=bool(force),
    )


@app.get("/research/seo-suggestions", response_model=dict)
def seo_suggestions(
    keyword: str = Query(..., description="기준 키워드(상품 SEO 세팅 기준)"),
    date_from: str = Query(..., description="YYYY-MM-DD"),
    date_to: str = Query(..., description="YYYY-MM-DD"),
    max_products: int = Query(20, ge=1, le=50, description="상위 상품 타이틀 수집 개수(기본 20)"),
    candidates: int = Query(10, ge=1, le=30, description="추천 상품명 후보 개수(기본 10)"),
    tokens_per_name: int = Query(6, ge=3, le=8, description="상품명에 추가할 토큰 개수(기본 6)"),
    max_tokens_total: int = Query(8, ge=4, le=12, description="상품명 토큰 최대 개수(기본 8)"),
    include_hashtags: bool = Query(True, description="true면 상위 상품 페이지에서 해시태그를 추출"),
    hashtags_top: int = Query(10, ge=3, le=30, description="추천 해시태그 개수(기본 10)"),
    hashtag_products: int = Query(8, ge=1, le=20, description="해시태그 추출에 사용할 상위 상품 페이지 개수(기본 8)"),
    include_autocomplete: bool = Query(True, description="true면 멀티 플랫폼 자동완성을 통합"),
    use_browser: bool = Query(False, description="true면 차단 시 Playwright 세션(캡차 풀이용) 재사용을 시도"),
):
    """
    menu5(키워드 리서치/전략)의 'SEO 세팅 최적화' 기능:
    - 상위 상품 타이틀(기본 20개)에서 토큰 후보를 추출
    - DataLab 평균 ratio로 토큰 점수화(상대 비교)
    - 기준 키워드 + 토큰(5~6개, 최대 8개)로 추천 상품명 후보 생성
    - (옵션) 실제 노출 해시태그(best-effort) Top N 추출
    - (옵션) Google/Naver/NaverShopping/Coupang 자동완성 통합
    """
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", date_from) or not re.match(r"^\d{4}-\d{2}-\d{2}$", date_to):
        raise HTTPException(status_code=400, detail="date_from/date_to must be YYYY-MM-DD")

    base = (keyword or "").strip()
    if not base:
        raise HTTPException(status_code=400, detail="keyword_required")

    # 1) 상위 상품 타이틀/링크 수집(현재: Naver shop.json 기준)
    shop = _fetch_naver_shop_top_products(keyword=base, display=max_products)
    items: list[dict] = shop.get("items") or []
    titles = [str(it.get("title") or "").strip() for it in items if str(it.get("title") or "").strip()]
    links = [str(it.get("link") or "").strip() for it in items if str(it.get("link") or "").strip()]

    # 2) 토큰 점수화(빈도 + DataLab 평균 ratio)
    scored_tokens = _score_tokens_from_titles(base_keyword=base, titles=titles, date_from=date_from, date_to=date_to, top_k=40)

    # 3) 상품명 후보 생성
    name_candidates = _build_product_name_candidates(
        base_keyword=base,
        scored_tokens=scored_tokens,
        candidates=candidates,
        tokens_per_name=tokens_per_name,
        max_tokens_total=max_tokens_total,
    )

    # 4) 해시태그 TopN
    hashtags: list[dict] = []
    hashtag_debug: dict = {"blocked": 0, "fetched": 0, "usedBrowser": bool(use_browser)}
    if include_hashtags:
        top_links = links[: max(1, min(int(hashtag_products), len(links)))] if links else []
        counts: dict[str, int] = {}
        blocked_any = False
        for u in top_links:
            html_text, dbg = _fetch_html_best_effort(url=u, use_browser=bool(use_browser))
            hashtag_debug["fetched"] = int(hashtag_debug.get("fetched") or 0) + 1
            if dbg.get("blocked"):
                blocked_any = True
                hashtag_debug["blocked"] = int(hashtag_debug.get("blocked") or 0) + 1
            if not html_text:
                continue
            for tag in _extract_hashtags_from_html(html_text=html_text):
                counts[tag] = counts.get(tag, 0) + 1
        # 빈도 순으로 정렬
        rows = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[: max(1, int(hashtags_top))]
        hashtags = [{"tag": k, "count": int(v)} for (k, v) in rows]
        hashtag_debug["needsCaptcha"] = bool(blocked_any and not use_browser)
        if bool(blocked_any):
            hashtag_debug.update(_current_devtools_urls(match_url_contains="smartstore.naver.com"))

    # 5) 자동완성 통합
    autocomplete: dict = {}
    if include_autocomplete:
        google = _fetch_google_suggest(keyword=base, limit=20)
        naver = _fetch_naver_autocomplete(keyword=base, limit=20)
        naver_shop = _fetch_naver_shopping_autocomplete(keyword=base, limit=20)
        coupang = _fetch_coupang_autocomplete(keyword=base, limit=20)

        # merge + dedupe + 원천 표시
        merged: dict[str, set[str]] = {}
        for src, arr in (
            ("google", google),
            ("naver", naver),
            ("naverShopping", naver_shop),
            ("coupang", coupang),
        ):
            for s in arr:
                t = (s or "").strip()
                if not t:
                    continue
                merged.setdefault(t, set()).add(src)

        merged_rows = [{"keyword": k, "sources": sorted(list(v))} for k, v in merged.items()]
        # 소스가 많은 것 우선, 그 다음 가나다
        merged_rows.sort(key=lambda x: (-len(x["sources"]), x["keyword"]))
        autocomplete = {
            "bySource": {
                "google": google,
                "naver": naver,
                "naverShopping": naver_shop,
                "coupang": coupang,
            },
            "merged": merged_rows[:60],
        }

    return {
        "keyword": base,
        "dateFrom": date_from,
        "dateTo": date_to,
        "sources": {
            "topProducts": {
                "provider": "naver_shop_openapi",
                "count": len(titles),
                "error": shop.get("error"),
            },
            "tokenScoring": {
                "provider": "datalab_search",
                "note": "meanRatio는 DataLab 상대지수의 기간 평균(절대 검색량 아님)입니다.",
            },
        },
        "topProducts": items[: max(0, min(len(items), max_products))],
        "tokenScores": scored_tokens[:50],
        "productNameCandidates": name_candidates,
        "hashtags": hashtags,
        "hashtagDebug": hashtag_debug,
        "autocomplete": autocomplete,
    }


@app.get("/research/seo/hashtag-audit", response_model=dict)
def seo_hashtag_audit(
    keyword: str = Query(..., description="검색 키워드"),
    max_products: int = Query(40, ge=5, le=60, description="쇼핑 검색에서 확인할 상품 개수(기본 40)"),
    use_browser: bool = Query(False, description="차단 시 Playwright 세션(캡차) 재사용 시도"),
    tag_limit_per_product: int = Query(30, ge=5, le=60, description="상품별 표시할 해시태그 최대 개수"),
    scrape_products: int = Query(
        12,
        ge=1,
        le=60,
        description="태그 추출을 위해 실제로 상품 페이지를 열어볼 최대 개수(기본 12). Top 상품 목록(max_products)은 그대로 반환.",
    ),
    fast: bool = Query(
        True,
        description="true면 빠른 추출(#태그 + manuTag 부분 파싱) 경로를 우선 사용해 지연을 줄입니다.",
    ),
):
    """
    해시태그 SEO(5-2):
    1) 쇼핑 검색 Top N 상품(title/link) 수집
    2) 각 상품 페이지에서 hashtags(노출)와 manuTag(필터 통과)를 분리 추출
    3) hashtags 중 manuTag에 남아있으면 ok(녹색), 아니면 filtered(빨강)로 분류
    4) 전체 상품의 '정상 노출 태그(manuTag)'를 합산/중복제거하여 최종 리스트 제공
    """
    base = (keyword or "").strip()
    if not base:
        raise HTTPException(status_code=400, detail="keyword_required")

    shop = _fetch_naver_shop_top_products(keyword=base, display=int(max_products))
    items: list[dict] = shop.get("items") or []
    items = [it for it in items if isinstance(it, dict)]

    debug: dict = {"blocked": 0, "fetched": 0, "usedBrowser": bool(use_browser), "fast": bool(fast)}
    blocked_any = False
    blocked_reason: str | None = None

    ok_counts: dict[str, int] = {}
    filtered_counts: dict[str, int] = {}
    products: list[dict] = []
    limited = items[: max(0, min(len(items), int(max_products)))]

    # 1) Top 상품 목록은 항상 즉시 구성해서 반환할 준비를 해둔다(UX: 3분 대기 방지).
    for idx, it in enumerate(limited):
        title = str(it.get("title") or "").strip() or "-"
        link = str(it.get("link") or "").strip() or None
        mall = str(it.get("mallName") or "").strip() or None
        products.append(
            {
                "rank": idx + 1,
                "title": title,
                "link": link,
                "mallName": mall,
                "hashtags": [],
                "manuTags": [],
                "fetchDebug": {"skipped": True, "reason": "not_scraped_yet"},
            }
        )

    # 2) 실제 상품 페이지 접근은 최대 N개만 시도한다(기본 12).
    #    캡차/차단이 감지되면 더 이상 반복 접근하지 않고 즉시 중단(차단 악화 방지).
    to_scrape = max(0, min(len(products), int(scrape_products)))
    for i in range(to_scrape):
        p = products[i]
        link = str(p.get("link") or "").strip() or None
        if not link:
            p["fetchDebug"] = {"skipped": True, "reason": "no_link"}
            continue

        html_text, fetch_dbg = _fetch_html_best_effort(url=link, use_browser=bool(use_browser))
        debug["fetched"] = int(debug.get("fetched") or 0) + 1

        err_s = str(fetch_dbg.get("error") or "")
        is_rate_limited = ("http_429" in err_s) or ("http_403" in err_s) or ("http_401" in err_s)
        if fetch_dbg.get("blocked") or is_rate_limited:
            blocked_any = True
            debug["blocked"] = int(debug.get("blocked") or 0) + 1
            blocked_reason = str(fetch_dbg.get("blockReason") or "") or blocked_reason
            # 캡차/접속제한은 추가 접근이 의미 없고 차단을 더 악화시킬 수 있어 즉시 중단한다.
            if blocked_reason in ("captcha", "access_limited") or fetch_dbg.get("blockReason") in ("captcha", "access_limited"):
                p["fetchDebug"] = fetch_dbg
                p["hashtags"] = []
                p["manuTags"] = []
                # 남은 항목들은 "차단 감지로 인해 스킵"으로 표시
                for j in range(i + 1, to_scrape):
                    products[j]["fetchDebug"] = {"skipped": True, "reason": "blocked_detected_early"}
                break

        hashtags: list[str] = []
        manu_tags: list[str] = []
        if html_text:
            if bool(fast):
                # 1) (빠른 경로) manuTag는 부분 파싱, 노출 해시태그는 제공고시 주변 '#태그'만
                manu_tags = _extract_manutags_fast_from_html(html_text=html_text)
                visible = _extract_visible_hashtags_fast_from_html(html_text=html_text)
                hashtags = visible
                # 2) fast 추출이 비었는데 __NEXT_DATA__가 존재하면 기존 안정 로직으로 보강(HTML은 이미 확보됨)
                if (not manu_tags and not hashtags) and ("__NEXT_DATA__" in html_text):
                    hashtags2, manu2 = _extract_hashtags_and_manutags_from_html(html_text=html_text)
                    if hashtags2:
                        hashtags = hashtags2
                    if manu2:
                        manu_tags = manu2
            else:
                hashtags, manu_tags = _extract_hashtags_and_manutags_from_html(html_text=html_text)

        manu_set = {t.lower() for t in manu_tags}
        tag_rows: list[dict] = []
        for t in hashtags[: max(1, int(tag_limit_per_product))]:
            ok = t.lower() in manu_set
            tag_rows.append({"tag": t, "ok": bool(ok)})
            if ok:
                ok_counts[t] = ok_counts.get(t, 0) + 1
            else:
                filtered_counts[t] = filtered_counts.get(t, 0) + 1

        for t in manu_tags:
            ok_counts[t] = ok_counts.get(t, 0) + 1

        p["hashtags"] = tag_rows
        p["manuTags"] = manu_tags
        p["fetchDebug"] = fetch_dbg

        time.sleep(0.02)

    ok_rows = [{"tag": k, "count": int(v)} for (k, v) in sorted(ok_counts.items(), key=lambda kv: (-kv[1], kv[0]))]
    filtered_rows = [{"tag": k, "count": int(v)} for (k, v) in sorted(filtered_counts.items(), key=lambda kv: (-kv[1], kv[0]))]

    # use_browser=true 여도 실제로 캡차/차단이 감지되면 사용자 해결이 필요하므로 needsCaptcha=true로 둔다.
    debug["needsCaptcha"] = bool(blocked_any)
    if bool(blocked_any):
        debug.update(_current_devtools_urls(match_url_contains="smartstore.naver.com"))
    debug["scrapeProducts"] = int(to_scrape)

    return {
        "keyword": base,
        "productCount": len(products),
        "products": products,
        "summary": {
            "okTags": ok_rows[:300],
            "filteredTags": filtered_rows[:300],
        },
        "source": {"provider": "naver_shop_openapi", "error": shop.get("error")},
        "debug": debug,
    }


@app.get("/research/seo/shopping-tags", response_model=dict)
def seo_shopping_tags(
    keyword: str = Query(..., description="검색 키워드"),
    limit: int = Query(40, ge=5, le=60, description="검색 결과에서 확인할 상품 개수(기본 40)"),
    scrape_products: int = Query(
        12,
        ge=0,
        le=60,
        description="(fallback) search/all API가 418/403/429로 막힐 때, OpenAPI Top 상품 링크를 기반으로 상품 페이지에서 #태그를 추출할 개수(기본 12)",
    ),
):
    """
    1단계: '상품 해시태그(tags)'만 빠르게 제공.
    - 쇼핑 검색 페이지를 열어 세션을 확보한 뒤, 같은 세션에서 /api/search/all을 호출한다.
    - 상세 페이지를 열지 않는다(빠름/차단 위험 감소).
    """
    q = (keyword or "").strip()
    if not q:
        raise HTTPException(status_code=400, detail="keyword_required")

    debug: dict = {"limit": int(limit)}
    products: list[dict] = []
    err: str | None = None

    if not _playwright_enabled():
        # Playwright가 없으면 OpenAPI(shop.json)로 링크/제목만 제공하고 tags는 비울 수밖에 없다.
        fb = _fetch_naver_shop_top_products(keyword=q, display=int(max(1, min(limit, 100))))
        items = fb.get("items") or []
        out = []
        for it in items:
            if not isinstance(it, dict):
                continue
            title = str(it.get("title") or "").strip()
            link = str(it.get("link") or "").strip() or None
            if title:
                out.append({"title": re.sub(r"<[^>]+>", "", html.unescape(title)).strip(), "tags": [], "link": link})
        products = out[: int(limit)]
        debug.update({"fallback": "shop.json", "error": fb.get("error")})
        return {"keyword": q, "productCount": len(products), "products": [{"rank": i + 1, **p} for i, p in enumerate(products)], "debug": debug}

    def _collect() -> tuple[list[dict], str | None, dict]:
        ctx = _ensure_pw_context()
        search_url = "https://search.shopping.naver.com/search/all?" + urllib.parse.urlencode({"query": q})

        used_existing = False
        page = None
        try:
            # (최우선) 사용자가 캡차를 풀어둔 탭(SHOPPING_SEARCH_PAGE)을 재사용한다.
            # 중요: open 엔드포인트에서 418이면 seed(스마트스토어)로 우회할 수 있는데,
            # 그 경우에도 "동일 탭/세션"을 유지한 채 다시 search_url로 이동해야 한다.
            global SHOPPING_SEARCH_PAGE
            if SHOPPING_SEARCH_PAGE is not None:
                try:
                    if hasattr(SHOPPING_SEARCH_PAGE, "is_closed") and SHOPPING_SEARCH_PAGE.is_closed():  # type: ignore[attr-defined]
                        SHOPPING_SEARCH_PAGE = None
                    else:
                        # search.shopping / smartstore(시드) 어느 쪽이든 재사용한다.
                        page = SHOPPING_SEARCH_PAGE
                        used_existing = True
                except Exception:
                    SHOPPING_SEARCH_PAGE = None
                    page = None
                    used_existing = False
        except Exception:
            page = None
            used_existing = False

        if page is None:
            page = ctx.new_page()

        try:
            # 🔴 중요: 사용자가 캡차를 입력 중인 탭을 "조회"가 덮어써서 캡차 화면이 사라지는 문제가 있었다.
            # 따라서 재사용 탭(used_existing)에서 현재 화면이 캡차/보안확인(=blockReason=captcha)이라면
            # 절대 navigation(goto)을 하지 않고 즉시 needsCaptcha로 반환한다.
            # -> 사용자는 열린 탭에서 캡차를 끝까지 풀 수 있고, 풀고 나서 다시 조회하면 된다.
            if used_existing:
                try:
                    current_url0 = str(getattr(page, "url", "") or "")
                except Exception:
                    current_url0 = ""
                page_html0 = ""
                try:
                    # content()가 느릴 수 있으니 예외는 무시하고 빈 문자열 처리
                    page_html0 = page.content() or ""
                except Exception:
                    page_html0 = ""
                try:
                    if page_html0 and _is_shopping_block_html(page_html0) and (_shopping_block_reason(page_html0) == "captcha"):
                        dbg0 = {
                            "apiStatus": 418,
                            "textLen": 0,
                            "usedExistingPage": True,
                            "mode": _pw_runtime_mode(),
                            "pageUrl": current_url0,
                            "pageHtmlLen": len(page_html0 or ""),
                            "pageBlocked": True,
                            "blockReason": "captcha",
                        }
                        # 캡차 풀이를 방해하지 않도록 여기서 종료
                        return ([], "captcha_pending", dbg0)
                except Exception:
                    pass

            # 기존 탭 재사용이면 불필요한 navigation은 피하되,
            # 탭이 다른 페이지에 있는 경우에만 search_url로 이동한다.
            try:
                current_url = str(getattr(page, "url", "") or "")
            except Exception:
                current_url = ""
            if (not used_existing) or ("search.shopping.naver.com" not in current_url):
                try:
                    page.goto(search_url, wait_until="domcontentloaded", timeout=60000)
                except Exception:
                    pass
                try:
                    page.wait_for_load_state("networkidle", timeout=15000)
                except Exception:
                    pass

            status, text = _shopping_api_fetch_via_page(page, q)
            api_url = "https://search.shopping.naver.com/api/search/all?" + urllib.parse.urlencode(
                {
                    "query": q,
                    "pagingIndex": "1",
                    "pagingSize": "40",
                    "viewType": "list",
                    "sort": "rel",
                }
            )
            dbg = {
                "apiStatus": status,
                "textLen": len(text or ""),
                "usedExistingPage": bool(used_existing),
                "mode": _pw_runtime_mode(),
                "apiUrl": api_url,
                "apiVia": "page_fetch",
            }
            try:
                dbg["apiTextSample"] = str(text or "")[:200]
            except Exception:
                dbg["apiTextSample"] = None
            # 418 응답이 JSON이 아니라 HTML로 오는 경우가 많아, 차단 성격을 추론해 디버그에 남긴다.
            try:
                if isinstance(status, int) and status >= 400 and isinstance(text, str) and "<!doctype" in text.lower():
                    dbg["apiHtmlTitle"] = _html_title(text)
                    dbg["apiBlocked"] = bool(_is_shopping_block_html(text))
                    dbg["apiBlockReason"] = _shopping_block_reason(text)
                    dbg["apiBodyTextSample"] = _html_body_text_sample(text)
            except Exception:
                pass
            try:
                dbg["pageUrl"] = str(getattr(page, "url", "") or "")
            except Exception:
                dbg["pageUrl"] = None

            if status != 200:
                # (fallback) page.fetch가 막히는 경우 ctx.request로 재시도
                try:
                    st2, txt2 = _shopping_api_fetch_via_context_request(ctx, q)
                except Exception:
                    st2, txt2 = (None, "")
                try:
                    dbg["ctxApiStatus"] = st2
                    dbg["ctxApiVia"] = "ctx_request"
                    dbg["ctxApiTextSample"] = str(txt2 or "")[:200]
                    if isinstance(st2, int) and st2 >= 400 and isinstance(txt2, str) and "<!doctype" in txt2.lower():
                        dbg["ctxApiHtmlTitle"] = _html_title(txt2)
                        dbg["ctxApiBlocked"] = bool(_is_shopping_block_html(txt2))
                        dbg["ctxApiBlockReason"] = _shopping_block_reason(txt2)
                        dbg["ctxApiBodyTextSample"] = _html_body_text_sample(txt2)
                except Exception:
                    pass
                if st2 == 200 and txt2:
                    try:
                        data2 = json.loads(txt2)
                        rows2 = _extract_products_with_tags_from_shopping_api_response(data2)
                        if rows2:
                            dbg["apiStatus"] = st2
                            dbg["textLen"] = len(txt2 or "")
                            dbg["apiVia"] = "ctx_request"
                            try:
                                dbg["apiTextSample"] = str(txt2 or "")[:200]
                            except Exception:
                                dbg["apiTextSample"] = None
                            return (rows2[: int(limit)], None, dbg)
                    except Exception:
                        pass
                # (중요 fallback) API는 막혀도 페이지 HTML은 정상인 경우가 있어 __NEXT_DATA__에서 tags를 추출한다.
                try:
                    page_html = page.content() or ""
                except Exception:
                    page_html = ""
                dbg["pageHtmlLen"] = len(page_html or "")
                try:
                    dbg["pageBlocked"] = bool(_is_shopping_block_html(page_html))
                except Exception:
                    dbg["pageBlocked"] = None
                if page_html and not _is_shopping_block_html(page_html):
                    rows_html = _extract_products_with_tags_from_shopping_search_html(html_text=page_html)
                    if rows_html:
                        dbg["tagsVia"] = "search_html_next_data"
                        dbg["htmlExtractedCount"] = int(len(rows_html))
                        return (rows_html[: int(limit)], None, dbg)
                return ([], f"shopping_api_status:{status}", dbg)
            try:
                data = json.loads(text)
            except Exception:
                # (fallback) page.fetch parse 실패 시 ctx.request로 복구 시도
                try:
                    st2, txt2 = _shopping_api_fetch_via_context_request(ctx, q)
                except Exception:
                    st2, txt2 = (None, "")
                if st2 == 200 and txt2:
                    try:
                        data2 = json.loads(txt2)
                        rows2 = _extract_products_with_tags_from_shopping_api_response(data2)
                        if rows2:
                            dbg["apiStatus"] = st2
                            dbg["textLen"] = len(txt2 or "")
                            dbg["apiVia"] = "ctx_request"
                            try:
                                dbg["apiTextSample"] = str(txt2 or "")[:200]
                            except Exception:
                                dbg["apiTextSample"] = None
                            return (rows2[: int(limit)], None, dbg)
                    except Exception:
                        pass
                # parse가 깨져도 HTML에서 복구를 시도
                try:
                    page_html = page.content() or ""
                except Exception:
                    page_html = ""
                dbg["pageHtmlLen"] = len(page_html or "")
                if page_html and not _is_shopping_block_html(page_html):
                    rows_html = _extract_products_with_tags_from_shopping_search_html(html_text=page_html)
                    if rows_html:
                        dbg["tagsVia"] = "search_html_next_data"
                        dbg["htmlExtractedCount"] = int(len(rows_html))
                        return (rows_html[: int(limit)], None, dbg)
                return ([], "shopping_api_parse_failed", dbg)
            rows = _extract_products_with_tags_from_shopping_api_response(data)
            return (rows[: int(limit)], None, dbg)
        finally:
            # 재사용 탭은 닫지 않는다(캡차 세션 유지).
            if not used_existing:
                try:
                    page.close()
                except Exception:
                    pass

    if not _pw_in_worker_thread():
        products, err, dbg = _pw_call(lambda: _collect())
    else:
        products, err, dbg = _collect()

    debug.update(dbg or {})
    if err:
        debug["error"] = err
        if "418" in err or "403" in err or "captcha" in err:
            try:
                mode = _pw_runtime_mode()
                debug.update(
                    _host_cdp_devtools_urls(match_url_contains="search.shopping.naver.com")
                    if mode == "host_cdp"
                    else _current_devtools_urls(match_url_contains="search.shopping.naver.com")
                )
            except Exception:
                pass

        # 1단계 UX: 쇼핑 검색 API가 막혀도 Top 상품 리스트는 OpenAPI(shop.json)로 보여준다.
        try:
            fb = _fetch_naver_shop_top_products(keyword=q, display=int(max(1, min(limit, 100))))
            items = fb.get("items") or []
            out: list[dict] = []
            for it in items:
                if not isinstance(it, dict):
                    continue
                title = str(it.get("title") or "").strip()
                link = str(it.get("link") or "").strip() or None
                mall = str(it.get("mallName") or "").strip() or None
                if title:
                    out.append({"title": re.sub(r"<[^>]+>", "", html.unescape(title)).strip(), "tags": [], "link": link, "mallName": mall})
            if out:
                products = out[: int(limit)]
                debug["fallbackProducts"] = "naver_shop_openapi"
                debug["fallbackError"] = fb.get("error")
        except Exception:
            pass

        # NOTE:
        # tags 모드는 '검색결과의 tags'를 목표로 한다.
        # 상품 상세 페이지에서 '#태그'를 긁는 방식은 결과가 불안정하고(없는 상품도 많음) 오해를 만들 수 있어 제거했다.
        # (/api/search/all이 막히는 경우는 캡차/접속제한을 해결한 뒤, 동일 세션에서 다시 호출해야 한다.)

    # UI/진단용: 쇼핑 검색 API 차단(418/403/429)은 '캡차 필요'로 간주한다.
    needs = False
    try:
        st = debug.get("apiStatus")
        if isinstance(st, int) and st in (418, 403, 429):
            needs = True
    except Exception:
        needs = False
    try:
        if err and any(x in err for x in ("418", "403", "captcha", "rate")):
            needs = True
    except Exception:
        pass
    debug["needsCaptcha"] = bool(needs)
    debug["stage"] = "shopping_search_api"

    out_products = []
    for i, p in enumerate(products[: int(limit)]):
        out_products.append(
            {
                "rank": i + 1,
                "title": str(p.get("title") or "-"),
                "tags": p.get("tags") or [],
                "link": p.get("link"),
                "mallName": p.get("mallName"),
            }
        )

    return {
        "keyword": q,
        "productCount": len(out_products),
        "products": out_products,
        "debug": debug,
    }


@app.post("/research/seo/keyword-metrics", response_model=dict)
def seo_keyword_metrics(payload: dict = Body(...)):
    """
    해시태그(=키워드) 리스트에 대해 SearchAd keywordstool 지표(월검색량/CTR)를 배치로 조회한다.
    - 입력: { "keywords": ["오늘출발", "#무료반품", ...] }
    - 출력: { "keywords": [...], "metrics": { "오늘출발": {totalSearch, avgCtr, pcSearch, mobileSearch, pcCtr, mobileCtr}, ... }, "error": optional }
    """
    global KW_METRICS_COOLDOWN_UNTIL
    try:
        raw = payload.get("keywords") if isinstance(payload, dict) else None
    except Exception:
        raw = None
    if not isinstance(raw, list):
        raise HTTPException(status_code=400, detail="keywords_required")

    # 호출 폭주 방지: 한 번에 너무 많이 요청하면 429가 쉽게 발생한다.
    max_keywords = 50
    try:
        max_keywords = int(payload.get("max_keywords") or 50)
    except Exception:
        max_keywords = 50
    max_keywords = max(1, min(max_keywords, 200))

    cleaned: list[str] = []
    seen = set()
    for k in raw:
        s = str(k or "").strip()
        if not s:
            continue
        s = re.sub(r"^#+", "", s).strip()
        if not s:
            continue
        if s in seen:
            continue
        seen.add(s)
        cleaned.append(s)
        if len(cleaned) >= 200:
            break

    if not cleaned:
        return {"keywords": [], "metrics": {}}

    truncated = False
    if len(cleaned) > max_keywords:
        cleaned = cleaned[:max_keywords]
        truncated = True

    # 1) 서버 캐시(12h) 우선 적용: 이미 조회한 키워드는 SearchAd를 다시 치지 않는다.
    now = time.time()
    cached: dict[str, dict] = {}
    to_fetch: list[str] = []
    with KW_METRICS_LOCK:
        for k in cleaned:
            ent = KW_METRICS_CACHE.get(k)
            try:
                ts = float(ent.get("ts")) if isinstance(ent, dict) and ent.get("ts") is not None else None
            except Exception:
                ts = None
            if ts is not None and (now - ts) <= float(KW_METRICS_TTL_SEC):
                cached[k] = ent.get("metric") if isinstance(ent.get("metric"), dict) else {}
            else:
                to_fetch.append(k)

    # 2) 전역 쿨다운 중이면 SearchAd 호출 금지(악화 방지) → 캐시만 반환
    with KW_METRICS_LOCK:
        cooldown_until = float(KW_METRICS_COOLDOWN_UNTIL or 0.0)
    if now < cooldown_until:
        retry_after_sec = int(max(1.0, cooldown_until - now))
        metrics = {**{k: cached.get(k, {}) for k in cleaned}}
        # 누락은 null로 채워 UI가 구분 가능하게
        for k in cleaned:
            if not metrics.get(k):
                metrics[k] = {"pcSearch": None, "mobileSearch": None, "totalSearch": None, "pcCtr": None, "mobileCtr": None, "avgCtr": None}
        out = {"keywords": cleaned, "metrics": metrics, "error": "SearchAd cooldown(429)", "retryAfterSec": retry_after_sec, "cachedOnly": True}
        if truncated:
            out["truncated"] = True
            out["maxKeywords"] = max_keywords
        return out

    # keywordstool 비용/제한 고려: 5개 단위로 쪼개서 hintKeywords 호출
    batch_size = 5
    requested = set(cleaned)
    metrics: dict[str, dict] = {k: cached.get(k, {}) for k in cleaned}
    first_err: str | None = None
    retry_after_sec: int | None = None

    for i in range(0, len(to_fetch), batch_size):
        chunk = to_fetch[i : i + batch_size]
        rows, err = _searchad_keywordstool_hint_many(chunk)
        if err and not first_err:
            first_err = err
        # 429가 뜨면 추가 호출이 의미 없고 차단을 악화시킬 수 있어 즉시 중단
        if err and "429" in str(err):
            retry_after_sec = 120
            with KW_METRICS_LOCK:
                KW_METRICS_COOLDOWN_UNTIL = time.time() + float(retry_after_sec)
            break
        for r in rows or []:
            if not isinstance(r, dict):
                continue
            kw = str(r.get("relKeyword") or "").strip()
            if not kw or kw not in requested:
                continue
            mrow = {
                "pcSearch": int(r.get("monthlyPcQcCnt") or 0),
                "mobileSearch": int(r.get("monthlyMobileQcCnt") or 0),
                "totalSearch": int(r.get("totalSearchQcCnt") or 0),
                "pcCtr": r.get("monthlyAvePcCtr"),
                "mobileCtr": r.get("monthlyAveMobileCtr"),
                "avgCtr": r.get("avgCtr"),
            }
            metrics[kw] = mrow
            # 캐시 저장
            with KW_METRICS_LOCK:
                KW_METRICS_CACHE[kw] = {"metric": mrow, "ts": time.time(), "fetchedAt": datetime.utcnow().isoformat() + "Z"}

    # 누락 키워드는 null로 채워 UI가 "미집계"로 구분할 수 있게 한다.
    for k in cleaned:
        if k not in metrics:
            metrics[k] = {"pcSearch": None, "mobileSearch": None, "totalSearch": None, "pcCtr": None, "mobileCtr": None, "avgCtr": None}

    out = {"keywords": cleaned, "metrics": metrics}
    if first_err:
        out["error"] = first_err
    if retry_after_sec is not None:
        out["retryAfterSec"] = retry_after_sec
    if truncated:
        out["truncated"] = True
        out["maxKeywords"] = max_keywords
    return out


@app.post("/research/seo/title-optimizer", response_model=dict)
def seo_title_optimizer(
    product_name: str = Query(..., description="상품명 prefix(맨 앞에 고정 노출)"),
    category_id: str = Query(..., description="DataLab 쇼핑 상세 카테고리 ID"),
    category_path: str = Query(..., description="선택한 카테고리 경로(표시용)"),
    main_keyword: str = Query(..., description="메인 키워드(분석 기준)"),
    date_from: str = Query(..., description="YYYY-MM-DD (점수화 기준 기간)"),
    date_to: str = Query(..., description="YYYY-MM-DD (점수화 기준 기간)"),
    limit_titles: int = Query(40, ge=10, le=80, description="쇼핑 검색에서 추출할 타이틀 개수(기본 40)"),
    candidate_count: int = Query(20, ge=10, le=40, description="후보 키워드 리스트 개수(기본 20)"),
    combo_count: int = Query(10, ge=5, le=20, description="추천 조합 후보 개수(기본 10)"),
    max_tokens_total: int = Query(8, ge=5, le=12, description="상품명 토큰 최대 개수(기본 8)"),
    include_autocomplete: bool = Query(False, description="자동완성 키워드 포함 여부(기본: 수동 확인 유도)"),
):
    """
    메뉴5(SEO 최적화) v2:
    1) 쇼핑 검색(쿼리 포함 URL)에서 Top40 상품명을 추출(Playwright 세션 기반 /api/search/all)
    2) 상품명 타이틀에서 토큰 빈도 집계
    3) SearchAd keywordstool(메인키워드)로 연관 키워드를 가져와 totalSearch/compIdx/CTR 결합
    4) 자동완성(옵션)과 매칭 여부를 포함해 후보 리스트(15~20개)를 만들고 1~10점 점수화
    5) 상품명 prefix + 키워드(5~8, max 8) 기준 추천 조합 10개 생성
    """
    # 기본 검증
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", date_from) or not re.match(r"^\d{4}-\d{2}-\d{2}$", date_to):
        raise HTTPException(status_code=400, detail="date_from/date_to must be YYYY-MM-DD")
    pn = (product_name or "").strip()
    mk = (main_keyword or "").strip()
    cid = (category_id or "").strip()
    cpath = (category_path or "").strip()
    if not pn:
        raise HTTPException(status_code=400, detail="product_name_required")
    if not mk:
        raise HTTPException(status_code=400, detail="main_keyword_required")
    if not cid.isdigit():
        raise HTTPException(status_code=400, detail="category_id_must_be_digits")

    # 1) 쇼핑 Top 타이틀 40개
    titles, title_err, title_dbg = _shopping_top_titles_via_playwright(keyword=mk, limit=int(limit_titles))
    needs_captcha = bool(title_err and ("418" in title_err or "403" in title_err or "captcha" in title_err))

    # 2) 토큰 빈도
    freq: dict[str, int] = {}
    for t in titles:
        for tok in _tokenize_title(t):
            if tok == mk:
                continue
            freq[tok] = freq.get(tok, 0) + 1
    token_rows = [{"token": k, "freq": int(v)} for (k, v) in sorted(freq.items(), key=lambda kv: (-kv[1], kv[0]))]

    # 3) SearchAd keywordstool(메인 키워드)
    related, rel_err = _searchad_keywordstool(mk)
    # relKeyword -> row
    rel_map: dict[str, dict] = {}
    for r in related or []:
        if isinstance(r, dict):
            k = str(r.get("relKeyword") or "").strip()
            if k:
                rel_map[k] = r

    # 4) 자동완성(옵션)
    auto_list: list[str] = []
    auto_sources: dict[str, list[str]] | None = None
    if include_autocomplete:
        google = _fetch_google_suggest(keyword=mk, limit=20)
        naver = _fetch_naver_autocomplete(keyword=mk, limit=20)
        naver_shop = _fetch_naver_shopping_autocomplete(keyword=mk, limit=20)
        coupang = _fetch_coupang_autocomplete(keyword=mk, limit=20)
        auto_sources = {"google": google, "naver": naver, "naverShopping": naver_shop, "coupang": coupang}
        merged = []
        seen = set()
        for arr in (google, naver, naver_shop, coupang):
            for s in arr:
                if not s or s in seen:
                    continue
                seen.add(s)
                merged.append(s)
        auto_list = merged

    # 후보 풀(토큰 + searchad relKeyword + autocomplete)
    pool: dict[str, dict] = {}
    # 토큰은 "한 단어" 성격이 강하니 우선 포함
    for k, v in freq.items():
        pool.setdefault(k, {"keyword": k})["titleFreq"] = int(v)
    for k, r in rel_map.items():
        pool.setdefault(k, {"keyword": k})["searchAd"] = r
    for k in auto_list:
        pool.setdefault(k, {"keyword": k})["autoMatch"] = True

    # (보강) SearchAd 연관검색어 목록에 없어서 지표가 비는 케이스를 줄이기 위해,
    # Top40 토큰/자동완성 키워드 중 일부를 hintKeywords로 추가 조회한다.
    enriched_cnt, enrich_errs = _searchad_enrich_pool_with_hint_keywords(pool, max_hint_keywords=30, batch_size=5)
    if enrich_errs and not rel_err:
        # 기존 rel_err가 없을 때만 메시지를 보강(프론트 표시 안정성)
        rel_err = " | ".join(enrich_errs[:2])

    # 후보 리스트 구성(메인키워드 자체는 제외하지 않고, 점수에서 과도 중복만 방지)
    candidates: list[dict] = []
    for k, meta in pool.items():
        title_freq = int(meta.get("titleFreq") or 0)
        ad = meta.get("searchAd") if isinstance(meta.get("searchAd"), dict) else None
        total_q = int((ad.get("totalSearchQcCnt") or 0)) if ad else 0
        comp = ad.get("compIdx") if ad else None
        avg_ctr = ad.get("avgCtr") if ad else None
        try:
            avg_ctr_f = float(avg_ctr) if avg_ctr is not None else None
        except Exception:
            avg_ctr_f = None
        candidates.append(
            {
                "keyword": k,
                "titleFreq": title_freq,
                "totalSearchQcCnt": total_q if total_q > 0 else None,
                "compIdx": comp,
                "avgCtr": avg_ctr_f,
                "autoMatch": bool(meta.get("autoMatch")),
            }
        )

    # --- 점수화(1~10) ---
    # freq ranking
    by_freq = sorted(candidates, key=lambda x: (-(x.get("titleFreq") or 0), x["keyword"]))
    freq_rank = {x["keyword"]: i for i, x in enumerate(by_freq)}
    # search volume ranking
    by_search = sorted(candidates, key=lambda x: (-(x.get("totalSearchQcCnt") or 0), x["keyword"]))
    search_rank = {x["keyword"]: i for i, x in enumerate(by_search)}
    # ctr ranking(없으면 맨 뒤)
    by_ctr = sorted(
        candidates,
        key=lambda x: (-(x.get("avgCtr") or -1.0), x["keyword"]),
    )
    ctr_rank = {x["keyword"]: i for i, x in enumerate(by_ctr)}

    total_n = max(len(candidates), 1)
    for c in candidates:
        k = c["keyword"]
        fs = _score_to_1_10_from_rank(rank_index=freq_rank.get(k, total_n - 1), total=total_n) if (c.get("titleFreq") or 0) > 0 else 1
        ss = _score_to_1_10_from_rank(rank_index=search_rank.get(k, total_n - 1), total=total_n) if (c.get("totalSearchQcCnt") or 0) > 0 else 1
        cs = _score_comp_idx_1_10(c.get("compIdx"))
        ts = _score_to_1_10_from_rank(rank_index=ctr_rank.get(k, total_n - 1), total=total_n) if c.get("avgCtr") is not None else 1
        # 자동완성은 "단일키워드 판별"의 핵심 신호지만,
        # 서버가 자동으로 판단(수집/해석)하기보다 사용자가 직접 확인하도록 유도한다.
        as_ = 10 if c.get("autoMatch") else 1
        # 가중 합(0~10대) -> 1~10 클램프
        # (자동 판별) 상위상품명 빈도 + SearchAd(검색량/경쟁/CTR)만 사용
        weighted = (0.30 * fs) + (0.45 * ss) + (0.15 * cs) + (0.10 * ts)
        total_score = max(1.0, min(10.0, round(weighted, 2)))
        c["scores"] = {
            "freq": fs,
            "search": ss,
            "competition": cs,
            "ctr": ts,
            "autocomplete": as_,
            "total": total_score,
        }

    # top N 후보 선택(요청 15~20)
    candidates.sort(key=lambda x: (-(x.get("scores") or {}).get("total", 0.0), -(x.get("totalSearchQcCnt") or 0), -(x.get("titleFreq") or 0), x["keyword"]))
    candidates = candidates[: int(candidate_count)]

    # --- 추천 조합 생성(상품명 prefix + 키워드 5~8, max 8) ---
    prefix_tokens = [t for t in str(pn).split() if t]
    # 메인 키워드는 항상 포함(중복이면 제외)
    base_tokens = prefix_tokens[:]
    if mk not in base_tokens:
        base_tokens.append(mk)

    def can_add(tok: str, cur: list[str]) -> bool:
        if not tok:
            return False
        if tok in cur:
            return False
        if len(cur) + 1 > int(max_tokens_total):
            return False
        return True

    combos: list[dict] = []
    used_names = set()
    # 다양성 확보를 위해 시작 오프셋을 바꿔가며 생성
    for start in range(0, min(len(candidates), int(combo_count) * 2)):
        cur = base_tokens[:]
        for i in range(start, len(candidates)):
            tok = str(candidates[i].get("keyword") or "").strip()
            # prefix에 이미 포함되어 있거나, 메인키워드와 동일하면 skip
            if tok in prefix_tokens or tok == mk:
                continue
            # 토큰이 너무 길면(문장형 자동완성) 제목엔 과하므로 skip
            if len(tok) > 20:
                continue
            if can_add(tok, cur):
                cur.append(tok)
            if len(cur) >= int(max_tokens_total):
                break
        name = " ".join(cur).strip()
        if not name or name in used_names:
            continue
        used_names.add(name)
        combos.append({"name": name, "tokens": cur})
        if len(combos) >= int(combo_count):
            break

    return {
        "productName": pn,
        "category": {"id": cid, "path": cpath},
        "mainKeyword": mk,
        "dateFrom": date_from,
        "dateTo": date_to,
        "shopping": {
            "needsCaptcha": needs_captcha,
            "error": title_err,
            "debug": title_dbg,
            "titles": titles,
        },
        "titleTokens": token_rows[:200],
        "searchAd": {
            "error": rel_err,
            "related": related[:300] if isinstance(related, list) else [],
        },
        "autocomplete": {"enabled": bool(include_autocomplete), "bySource": auto_sources, "merged": auto_list[:80]} if include_autocomplete else {"enabled": False},
        "candidates": candidates,
        "recommendedCombos": combos,
        "constraints": {"maxTokensTotal": int(max_tokens_total)},
        "scoringPolicy": {
            "note": "자동 점수는 Top 상품명 패턴 + SearchAd 신호만 사용합니다. 자동완성/공식 키워드툴 확인은 사용자 수동 체크를 권장합니다.",
            "weights": {"freq": 0.30, "search": 0.45, "competition": 0.15, "ctr": 0.10, "autocomplete": 0.0},
        },
    }


@app.get("/keywords/daily", response_model=List[KeywordDaily])
def list_keyword_daily(
    date_from: date,
    date_to: Optional[date] = None,
    campaign: Optional[str] = None,
    adgroup: Optional[str] = None,
    campaign_kind: Optional[str] = Query(None, description="powerlink | shopping | non_powerlink"),
    infer_missing_keyword: bool = Query(
        False,
        description="(비권장) keyword가 비어있을 때 광고그룹명 기반으로 추정해 응답에만 채웁니다. 기본값 false(추측으로 데이터 왜곡 방지).",
    ),
    limit: int = Query(1000, ge=1, le=20000),
    offset: int = Query(0, ge=0),
    db: Session = Depends(get_db),
):
    """
    일자/캠페인/광고그룹 조건으로 `naver_ad_keyword_daily` 를 조회한다.

    - 기본 정렬: `date DESC`, `cost DESC`, `impressions DESC`
    - Analytics Web(5188)에서 키워드 탭의 기본 데이터 소스로 사용 예정
    """
    if date_to is None:
        date_to = date_from

    q = (
        db.query(NaverAdKeywordDaily)
        .filter(NaverAdKeywordDaily.date >= date_from, NaverAdKeywordDaily.date <= date_to)
    )
    q = _apply_campaign_kind_filter(q, NaverAdKeywordDaily, str(campaign_kind or ""))
    if campaign:
        vs = _expand_campaign_names({str(campaign).strip()})
        q = q.filter(NaverAdKeywordDaily.campaign_name.in_(vs)) if vs else q
    if adgroup:
        q = q.filter(NaverAdKeywordDaily.adgroup_name == adgroup)

    rows = (
        q.order_by(
            NaverAdKeywordDaily.date.desc(),
            NaverAdKeywordDaily.cost.desc(),
            NaverAdKeywordDaily.impressions.desc(),
        )
        .offset(offset)
        .limit(limit)
        .all()
    )

    # 중요(정확도): keyword/searchword는 원본 리포트 값 그대로 노출하는 것을 기본으로 한다.
    # 과거에는 쇼핑검색/브랜드에서 keyword가 "-"로 내려오는 경우를 화면에서 "안 비어 보이게" 하기 위해
    # 광고그룹명 기반 추정을 응답에 섞었지만, 이는 사용자가 캠페인/그룹명을 키워드로 오인하는 데이터 왜곡을 유발한다.
    # - 기본값: infer_missing_keyword=False (추측 금지)
    if infer_missing_keyword:
        ck = str(campaign_kind or "").strip().lower()
        for r in rows or []:
            try:
                kw = str(getattr(r, "keyword", "") or "").strip()
                if kw not in ("", "-", "UNKNOWN_KEYWORD"):
                    continue
                camp_name = str(getattr(r, "campaign_name", "") or "").strip()
                grp_name = str(getattr(r, "adgroup_name", "") or "").strip()
                # campaign_kind가 명시되면 그 값을 우선 사용하고,
                # 미지정이면 캠페인명 패턴으로 파워링크 여부를 판정한다.
                is_non_powerlink = (ck in ("shopping", "non_powerlink")) or (ck == "" and not _is_powerlink_campaign_name_text(camp_name))
                if not is_non_powerlink:
                    continue
                inferred = _infer_keyword_from_adgroup_name(grp_name)
                if inferred:
                    setattr(r, "keyword", inferred)
            except Exception:
                continue

    return rows


def _apply_campaign_kind_filter(q, Model, campaign_kind: str):
    """
    캠페인명을 기반으로 "파워링크" vs "쇼핑검색+브랜드(SB 포함)"를 분리한다.
    - 현재 스키마에 campaign_type 컬럼이 없어서 네이밍(prefix/키워드) 기반으로 best-effort 처리한다.
    """
    ck = str(campaign_kind or "").strip().lower()
    if ck not in ("powerlink", "shopping", "non_powerlink"):
        return q

    powerlink_cond = or_(
        Model.campaign_name.startswith("#SA_"),
        Model.campaign_name.startswith("SA_"),
        Model.campaign_name.ilike("%파워링크%"),
        Model.campaign_name.startswith("#P"),
        Model.campaign_name.ilike("%P01_파워링크%"),
    )

    # 정확도 우선: campaign_kind 컬럼이 존재하고 값이 채워진 경우에는 그 값을 1순위로 사용한다.
    # (과거 데이터/미채움 데이터는 기존 네이밍 기반 best-effort로 폴백)
    has_kind_col = hasattr(Model, "campaign_kind")
    if has_kind_col:
        kind_col = getattr(Model, "campaign_kind")

    if ck == "powerlink":
        if has_kind_col:
            return q.filter(or_(kind_col == "powerlink", and_(kind_col.is_(None), powerlink_cond)))
        return q.filter(powerlink_cond)

    if ck == "non_powerlink":
        # 파워링크가 아닌 모든 캠페인(쇼핑검색 + 브랜드 + 기타 포함)
        if has_kind_col:
            return q.filter(or_(kind_col.in_(("shopping", "non_powerlink")), and_(kind_col.is_(None), not_(powerlink_cond))))
        return q.filter(not_(powerlink_cond))

    # shopping: 쇼핑검색 + 브랜드(네이밍 기반 best-effort)
    shopping_cond = or_(
        Model.campaign_name.startswith("#SS"),
        Model.campaign_name.startswith("SS"),
        Model.campaign_name.startswith("#SB"),
        Model.campaign_name.startswith("SB"),
        Model.campaign_name.ilike("%쇼핑%"),
        Model.campaign_name.ilike("%브랜드%"),
    )
    if has_kind_col:
        return q.filter(or_(kind_col == "shopping", and_(kind_col.is_(None), shopping_cond)))
    return q.filter(shopping_cond)


def _is_powerlink_campaign_name_text(name: str) -> bool:
    """
    DB row(문자열) 기준으로 파워링크 캠페인인지 판정한다.
    - SQLAlchemy 조건식이 아닌, Python 문자열 판정 버전
    """
    s = str(name or "").strip()
    if not s:
        return False
    if s.startswith("#SA_") or s.startswith("SA_"):
        return True
    if s.startswith("#P"):
        return True
    if "파워링크" in s:
        return True
    if "P01_파워링크" in s:
        return True
    return False


def _infer_keyword_from_adgroup_name(adgroup_name: str) -> str | None:
    """
    쇼핑검색/브랜드 캠페인의 stat-reports(AD)에는 keywordId가 '-'로 내려오는 케이스가 있어,
    UI에서 "키워드가 비어 보이는" 문제를 완화하기 위해 광고그룹명에서 best-effort로 키워드를 유추한다.
    """
    s = str(adgroup_name or "").strip()
    if not s:
        return None
    s = s.lstrip("#").strip()
    if not s:
        return None
    # 흔한 광고그룹 네이밍: MO_키워드, MO_카테고리_키워드 등
    parts = [p for p in re.split(r"[\s_]+", s) if p and str(p).strip()]
    if not parts:
        return None
    head = str(parts[0] or "").strip().upper()
    if head in ("MO", "M", "MOBILE", "PC", "P", "DESKTOP", "AOS", "IOS", "ANDROID", "IPHONE"):
        parts = parts[1:]
    parts = [p.strip() for p in parts if p and p.strip()]
    if not parts:
        return None
    return " ".join(parts).strip() or None


def _list_searchword_daily_rows(
    db: Session,
    *,
    date_from: date,
    date_to: Optional[date] = None,
    campaign: Optional[str] = None,
    adgroup: Optional[str] = None,
    campaign_kind: Optional[str] = None,
    source: str = "combined",
    limit: int | None = 1000,
    offset: int = 0,
) -> list[NaverAdSearchwordDaily]:
    if date_to is None:
        date_to = date_from

    q = (
        db.query(NaverAdSearchwordDaily)
        .filter(NaverAdSearchwordDaily.date >= date_from, NaverAdSearchwordDaily.date <= date_to)
    )
    src = (source or "combined").strip().lower()
    allowed_sources = {"combined", "ui_csv_upload", "searchad_api", "all"}
    if src not in allowed_sources:
        raise HTTPException(status_code=400, detail="source must be combined|ui_csv_upload|searchad_api|all")
    if src in {"ui_csv_upload", "searchad_api"}:
        q = q.filter(NaverAdSearchwordDaily.source == src)
    elif src == "combined":
        q = q.filter(NaverAdSearchwordDaily.source.in_(("ui_csv_upload", "searchad_api")))
    q = _apply_campaign_kind_filter(q, NaverAdSearchwordDaily, str(campaign_kind or ""))
    if campaign:
        vs = _expand_campaign_names({str(campaign).strip()})
        q = q.filter(NaverAdSearchwordDaily.campaign_name.in_(vs)) if vs else q
    if adgroup:
        q = q.filter(NaverAdSearchwordDaily.adgroup_name == adgroup)

    if src == "combined":
        raw_rows = (
            q.order_by(
                NaverAdSearchwordDaily.date.desc(),
                NaverAdSearchwordDaily.cost.desc(),
                NaverAdSearchwordDaily.impressions.desc(),
                NaverAdSearchwordDaily.campaign_name.asc(),
                NaverAdSearchwordDaily.adgroup_name.asc(),
                NaverAdSearchwordDaily.searchword.asc(),
                NaverAdSearchwordDaily.device.asc(),
            )
            .all()
        )

        def _norm_key_part(v: object) -> str:
            return re.sub(r"\s+", " ", str(v or "").strip()).lower()

        def _merge_key(row: NaverAdSearchwordDaily) -> tuple:
            return (
                row.date,
                _norm_key_part(getattr(row, "campaign_name", "")),
                _norm_key_part(getattr(row, "adgroup_name", "")),
                _norm_key_part(getattr(row, "searchword", "")),
                _norm_key_part(getattr(row, "device", "") or "ALL"),
            )

        merged: dict[tuple, NaverAdSearchwordDaily] = {}
        for row in raw_rows:
            key = _merge_key(row)
            current = merged.get(key)
            row_source = str(getattr(row, "source", "") or "").strip()
            current_source = str(getattr(current, "source", "") or "").strip() if current is not None else ""
            # 동일 검색어 행은 전환매출이 포함된 광고센터 엑셀 업로드값을 우선한다.
            if current is None or (row_source == "ui_csv_upload" and current_source != "ui_csv_upload"):
                merged[key] = row
        rows = sorted(
            merged.values(),
            key=lambda r: (
                getattr(r, "date", date.min) or date.min,
                int(getattr(r, "cost", 0) or 0),
                int(getattr(r, "impressions", 0) or 0),
                str(getattr(r, "campaign_name", "") or ""),
                str(getattr(r, "adgroup_name", "") or ""),
                str(getattr(r, "searchword", "") or ""),
                str(getattr(r, "device", "") or ""),
            ),
            reverse=True,
        )
        if limit is None:
            return rows[offset:]
        return rows[offset : offset + limit]

    q = q.order_by(
        NaverAdSearchwordDaily.date.desc(),
        NaverAdSearchwordDaily.cost.desc(),
        NaverAdSearchwordDaily.impressions.desc(),
        NaverAdSearchwordDaily.campaign_name.asc(),
        NaverAdSearchwordDaily.adgroup_name.asc(),
        NaverAdSearchwordDaily.searchword.asc(),
        NaverAdSearchwordDaily.device.asc(),
    )
    if offset:
        q = q.offset(offset)
    if limit is not None:
        q = q.limit(limit)
    rows = q.all()
    return rows


@app.get("/searchwords/daily", response_model=List[SearchwordDaily])
def list_searchword_daily(
    date_from: date,
    date_to: Optional[date] = None,
    campaign: Optional[str] = None,
    adgroup: Optional[str] = None,
    campaign_kind: Optional[str] = Query(None, description="powerlink | shopping | non_powerlink"),
    source: str = Query("combined", description="combined | ui_csv_upload | searchad_api | all"),
    limit: int = Query(1000, ge=1, le=20000),
    offset: int = Query(0, ge=0),
    db: Session = Depends(get_db),
):
    """
    일자/캠페인/광고그룹 조건으로 `naver_ad_searchword_daily` 를 조회한다.

    - Analytics Web 검색어 탭의 기본 데이터 소스
    - 화면 성능을 위해 limit/offset을 적용한다.
    """
    return _list_searchword_daily_rows(
        db,
        date_from=date_from,
        date_to=date_to,
        campaign=campaign,
        adgroup=adgroup,
        campaign_kind=campaign_kind,
        source=source,
        limit=limit,
        offset=offset,
    )


@app.get("/searchwords/daily/export", response_model=List[SearchwordDaily])
def export_searchword_daily(
    date_from: date,
    date_to: Optional[date] = None,
    campaign: Optional[str] = None,
    adgroup: Optional[str] = None,
    campaign_kind: Optional[str] = Query(None, description="powerlink | shopping | non_powerlink"),
    source: str = Query("combined", description="combined | ui_csv_upload | searchad_api | all"),
    db: Session = Depends(get_db),
):
    """
    광고 검색어 분석 Excel 다운로드 전용 조회 API.

    화면 표시 제한과 분리해 현재 검색 조건의 DB 결과 전체를 반환한다.
    """
    return _list_searchword_daily_rows(
        db,
        date_from=date_from,
        date_to=date_to,
        campaign=campaign,
        adgroup=adgroup,
        campaign_kind=campaign_kind,
        source=source,
        limit=None,
        offset=0,
    )


@app.get("/ads/availability", response_model=dict)
def ads_availability(
    kind: str = Query(..., description="keyword | searchword | campaign | adgroup | creative"),
    date_from: date = Query(...),
    date_to: Optional[date] = Query(None),
    campaign_kind: Optional[str] = Query(None, description="powerlink | shopping | non_powerlink"),
    db: Session = Depends(get_db),
):
    """
    특정 기간에 Daily 테이블 데이터가 존재하는지/어떤 날짜가 누락인지 빠르게 확인한다.
    - UI에서 날짜 선택 시: 데이터가 있으면 그대로 조회, 없으면 /ads/collect를 자동 호출하기 위한 용도.
    """
    k = (kind or "").strip().lower()
    if k in ("campaign", "adgroup"):
        k = "keyword"  # 메뉴3은 keyword daily 집계가 소스
    if k not in ("keyword", "searchword", "creative"):
        raise HTTPException(status_code=400, detail="kind must be keyword|searchword|campaign|adgroup|creative")

    dt = date_to or date_from
    if dt < date_from:
        date_from, dt = dt, date_from

    # 자동 수집은 UX 상 너무 큰 범위를 피한다.
    days = (dt - date_from).days + 1
    if days > 62:
        raise HTTPException(status_code=400, detail="date range too large (max 62 days)")

    Model = (
        NaverAdKeywordDaily
        if k == "keyword"
        else NaverAdSearchwordDaily
        if k == "searchword"
        else NaverAdCreativeDaily
    )

    existing_rows = (
        _apply_campaign_kind_filter(db.query(Model.date), Model, str(campaign_kind or ""))
        .filter(Model.date >= date_from, Model.date <= dt)
        .distinct()
        .all()
    )
    existing_dates = {r[0].strftime("%Y-%m-%d") for r in existing_rows if r and r[0]}

    expected_dates: list[str] = []
    cur = date_from
    while cur <= dt:
        expected_dates.append(cur.strftime("%Y-%m-%d"))
        cur = cur + timedelta(days=1)

    missing_dates = [d for d in expected_dates if d not in existing_dates]

    return {
        "ok": True,
        "kind": k,
        "from": date_from.strftime("%Y-%m-%d"),
        "to": dt.strftime("%Y-%m-%d"),
        "hasAny": len(existing_dates) > 0,
        "missingDates": missing_dates,
    }


@app.get("/ads/storage/size", response_model=dict)
def ads_storage_size(
    kind: str = Query("keyword", description="keyword | searchword | creative"),
    db: Session = Depends(get_db),
):
    """
    광고 데이터 테이블의 현재 저장 용량(bytes)을 조회한다.
    - 진행률(용량 기반) 표시를 위해 프론트가 1초 단위로 폴링할 수 있다.
    """
    k = (kind or "").strip().lower()
    if k not in ("keyword", "searchword", "creative"):
        raise HTTPException(status_code=400, detail="kind must be keyword|searchword|creative")

    # 테스트/비-Postgres 환경에서는 size를 정확히 알 수 없으므로 0을 반환한다.
    try:
        if str(db.bind.dialect.name) != "postgresql":  # type: ignore[union-attr]
            return {"ok": True, "kind": k, "supported": False, "bytes": 0}
    except Exception:
        return {"ok": True, "kind": k, "supported": False, "bytes": 0}

    table = (
        "naver_ad_keyword_daily"
        if k == "keyword"
        else "naver_ad_searchword_daily"
        if k == "searchword"
        else "naver_ad_creative_daily"
    )

    # regclass 인젝션을 피하기 위해 테이블명은 화이트리스트에서만 선택한다.
    sql = text(f"select pg_total_relation_size('public.{table}')::bigint as bytes")
    try:
        row = db.execute(sql).first()
        b = int(row[0] or 0) if row else 0
    except Exception:
        b = 0
    return {"ok": True, "kind": k, "supported": True, "bytes": b, "table": table}


@app.get("/ads/storage/estimate", response_model=dict)
def ads_storage_estimate(
    kind: str = Query("keyword", description="keyword | searchword | creative"),
    missing_days: int = Query(..., ge=0, le=4000, description="이번 호출로 DB에 추가될 것으로 예상되는 누락 일수"),
    db: Session = Depends(get_db),
):
    """
    "호출해서 가져와야 하는 전체 DB 용량(예상)"을 산정한다.
    - 정확한 바이트는 수집/다운로드 전에는 확정 불가하므로, DB의 최근 평균(행/일 × 평균 행 크기)을 이용한 추정치다.
    - 프론트는 baseline_bytes/estimated_delta_bytes를 이용해 (현재 bytes - baseline) / estimated_delta 로 진행률을 만든다.
    """
    k = (kind or "").strip().lower()
    if k not in ("keyword", "searchword", "creative"):
        raise HTTPException(status_code=400, detail="kind must be keyword|searchword|creative")

    try:
        if str(db.bind.dialect.name) != "postgresql":  # type: ignore[union-attr]
            return {"ok": True, "kind": k, "supported": False, "baseline_bytes": 0, "estimated_delta_bytes": 0}
    except Exception:
        return {"ok": True, "kind": k, "supported": False, "baseline_bytes": 0, "estimated_delta_bytes": 0}

    table = (
        "naver_ad_keyword_daily"
        if k == "keyword"
        else "naver_ad_searchword_daily"
        if k == "searchword"
        else "naver_ad_creative_daily"
    )

    # baseline (현재 테이블 용량)
    baseline_sql = text(f"select pg_total_relation_size('public.{table}')::bigint as bytes")
    baseline_row = db.execute(baseline_sql).first()
    baseline_bytes = int(baseline_row[0] or 0) if baseline_row else 0

    # reltuples 기반 대략적인 행 수(통계)
    rel_sql = text("select greatest(reltuples::bigint, 1) from pg_class where relname = :name")
    rel_row = db.execute(rel_sql, {"name": table}).first()
    approx_rows_total = int(rel_row[0] or 1) if rel_row else 1
    avg_row_bytes = float(baseline_bytes) / float(max(1, approx_rows_total))

    # 최근 7일의 "일자별 행수" 평균 (없으면 전체 평균으로 폴백)
    try:
        avg_rows_sql = text(
            f"""
            with daily as (
              select date, count(*)::bigint as cnt
              from public.{table}
              where date >= (current_date - interval '7 days')
              group by date
            )
            select coalesce(avg(cnt)::float, 0.0) from daily
            """
        )
        avg_rows_per_day_row = db.execute(avg_rows_sql).first()
        avg_rows_per_day = float(avg_rows_per_day_row[0] or 0.0) if avg_rows_per_day_row else 0.0
    except Exception:
        avg_rows_per_day = 0.0

    if avg_rows_per_day <= 0:
        # 최근 데이터가 없으면 전체 행 수를 기간으로 나눌 수 없으므로, 보수적으로 0으로 둔다.
        avg_rows_per_day = 0.0

    estimated_delta_bytes = int(round(float(missing_days) * float(avg_rows_per_day) * float(avg_row_bytes)))
    estimated_final_bytes = int(baseline_bytes + max(0, estimated_delta_bytes))

    return {
        "ok": True,
        "kind": k,
        "supported": True,
        "table": table,
        "baseline_bytes": baseline_bytes,
        "estimated_delta_bytes": max(0, estimated_delta_bytes),
        "estimated_final_bytes": estimated_final_bytes,
        "assumptions": {
            "avg_rows_per_day_7d": avg_rows_per_day,
            "avg_row_bytes_est": avg_row_bytes,
        },
    }


class GfaCreativeMetaPayload(BaseModel):
    creative_name: str | None = None
    image_path: str | None = None
    appeal_points: list[str] | None = None
    image_type: str | None = None
    message_type: str | None = None
    notes: str | None = None


def _gfa_metric_bucket() -> dict:
    return {
        "impressions": 0,
        "clicks": 0,
        "cost": 0,
        "conversions": 0,
        "revenue": 0,
        "cart_conversions": 0,
        "cart_revenue": 0,
        "purchase_conversions": 0,
        "purchase_revenue": 0,
    }


def _gfa_add_metrics(bucket: dict, row: NaverGfaDaily) -> None:
    bucket["impressions"] += int(row.impressions or 0)
    bucket["clicks"] += int(row.clicks or 0)
    bucket["cost"] += int(row.cost or 0)
    bucket["conversions"] += int(row.conversions or 0)
    bucket["revenue"] += int(row.revenue or 0)
    bucket["cart_conversions"] += int(row.cart_conversions or 0)
    bucket["cart_revenue"] += int(row.cart_revenue or 0)
    bucket["purchase_conversions"] += int(row.purchase_conversions or 0)
    bucket["purchase_revenue"] += int(row.purchase_revenue or 0)


def _gfa_finalize_metrics(bucket: dict) -> dict:
    impressions = int(bucket.get("impressions") or 0)
    clicks = int(bucket.get("clicks") or 0)
    cost = int(bucket.get("cost") or 0)
    conversions = int(bucket.get("conversions") or 0)
    revenue = int(bucket.get("revenue") or 0)
    purchase_revenue = int(bucket.get("purchase_revenue") or 0)
    cart_revenue = int(bucket.get("cart_revenue") or 0)
    return {
        **bucket,
        "total_purchase_value": purchase_revenue + cart_revenue,
        "ctr": (clicks / impressions * 100.0) if impressions > 0 else 0.0,
        "cpc": (cost / clicks) if clicks > 0 else 0.0,
        "cvr": (conversions / clicks * 100.0) if clicks > 0 else 0.0,
        "roas": (revenue / cost * 100.0) if cost > 0 else 0.0,
    }


def _gfa_status_from_ended_on(ended_on: str | None, performance_date: date | None = None) -> tuple[str | None, bool | None, str | None]:
    label = str(ended_on or "").strip() or None
    if not label:
        return "운영중", True, "ended_on_empty"
    compact = re.sub(r"\s+", "", label)
    if compact in {"진행중", "운영중"}:
        return "운영중", True, "collected_snapshot"
    ended_iso = _gfa_csv_date(label)
    ended_date = _collection_parse_date(ended_iso)
    if ended_date is not None and performance_date is not None:
        active = performance_date <= ended_date
        return "운영중" if active else "중지", active, "ended_on_date"
    return label, False, "ended_on_raw"


def _gfa_raw_status_label(ended_on: str | None) -> str:
    label = str(ended_on or "").strip()
    if not label:
        return "운영중"
    compact = re.sub(r"\s+", "", label)
    if compact in {"진행중", "운영중"}:
        return "운영중"
    ended_iso = _gfa_csv_date(label)
    return ended_iso or label


def _gfa_apply_row_status(bucket: dict, row: NaverGfaDaily, *, level: str) -> None:
    label, active, basis = _gfa_status_from_ended_on(row.ended_on, row.date)
    if label is None:
        return
    if level == "campaign":
        bucket["campaign_status"] = label
        bucket["campaign_status_basis"] = basis
    elif level == "adgroup":
        bucket["adgroup_status"] = label
        bucket["adgroup_status_basis"] = basis
    bucket["is_active"] = active
    if row.collected_at is not None:
        bucket["status_collected_at"] = row.collected_at


def _gfa_status_reference_date(db: Session) -> date:
    _ = db
    return _today_kst() - timedelta(days=1)


def _gfa_entity_status_key(
    *,
    level: str,
    campaign_id: str | None,
    campaign_name: str | None,
    adgroup_id: str | None = None,
    adgroup_name: str | None = None,
    creative_id: str | None = None,
) -> str | None:
    campaign_key = str(campaign_id or "").strip() or str(campaign_name or "").strip()
    if level == "campaign":
        return campaign_key or None
    adgroup_key = str(adgroup_id or "").strip() or str(adgroup_name or "").strip()
    if level == "adgroup":
        if not campaign_key or not adgroup_key:
            return None
        return f"{campaign_key}||{adgroup_key}"
    creative_key = str(creative_id or "").strip()
    if level == "creative":
        if not campaign_key or not adgroup_key or not creative_key:
            return None
        return f"{campaign_key}||{adgroup_key}||{creative_key}"
    return None


def _gfa_current_status_snapshot_map(
    db: Session,
    *,
    level: str,
    reference_date: date,
    entity_keys: set[str] | None = None,
) -> dict[str, dict]:
    if entity_keys is not None and len(entity_keys) == 0:
        return {}
    q = _gfa_base_query(
        db,
        date(2024, 1, 1),
        reference_date,
        sources=GFA_CONVERSION_COMPLETE_SOURCES,
    )
    if entity_keys is not None:
        keys = {str(k or "").strip() for k in entity_keys if str(k or "").strip()}
        if not keys:
            return {}
        if level == "campaign":
            q = q.filter(or_(NaverGfaDaily.campaign_id.in_(keys), NaverGfaDaily.campaign_name.in_(keys)))
        elif level == "adgroup":
            campaign_keys: set[str] = set()
            adgroup_keys: set[str] = set()
            for key in keys:
                parts = key.split("||")
                if len(parts) >= 2:
                    campaign_keys.add(parts[0])
                    adgroup_keys.add(parts[1])
            if not campaign_keys or not adgroup_keys:
                return {}
            q = q.filter(
                or_(NaverGfaDaily.campaign_id.in_(campaign_keys), NaverGfaDaily.campaign_name.in_(campaign_keys)),
                or_(NaverGfaDaily.adgroup_id.in_(adgroup_keys), NaverGfaDaily.adgroup_name.in_(adgroup_keys)),
            )
        elif level == "creative":
            creative_keys: set[str] = set()
            for key in keys:
                parts = key.split("||")
                if len(parts) >= 3 and str(parts[2] or "").strip():
                    creative_keys.add(parts[2])
            if not creative_keys:
                return {}
            q = q.filter(NaverGfaDaily.creative_id.in_(creative_keys))
    rows = q.all()
    out: dict[str, dict] = {}
    for row in rows:
        key = _gfa_entity_status_key(
            level=level,
            campaign_id=row.campaign_id,
            campaign_name=row.campaign_name,
            adgroup_id=row.adgroup_id,
            adgroup_name=row.adgroup_name,
            creative_id=row.creative_id,
        )
        if not key or (entity_keys is not None and key not in entity_keys):
            continue
        priority = _gfa_source_priority(row.source, level)
        if priority <= 0:
            continue
        bucket = out.setdefault(
            key,
            {
                "has_reference_data": False,
                "has_reference_signal": False,
                "latest_date": date(1900, 1, 1),
                "latest_priority": 0,
                "latest_collected_at": None,
                "latest_open_ended_on": None,
                "latest_open_date": date(1900, 1, 1),
                "latest_ended_on": None,
                "latest_ended_on_date": None,
                "latest_ended_on_row_date": date(1900, 1, 1),
                "status_collected_at": None,
            },
        )
        row_collected_at = row.collected_at or datetime.min
        row_ended_on = str(row.ended_on or "").strip() or None
        row_ended_iso = _gfa_csv_date(row_ended_on)
        row_ended_date = _collection_parse_date(row_ended_iso)
        is_open_status = False
        if row_ended_on:
            compact = re.sub(r"\s+", "", row_ended_on)
            is_open_status = compact in {"진행중", "운영중"}
        else:
            is_open_status = True

        if row.date == reference_date:
            bucket["has_reference_data"] = True
            if int(row.cost or 0) > 0 or int(row.impressions or 0) > 0 or int(row.clicks or 0) > 0:
                bucket["has_reference_signal"] = True
            current_ref_priority = int(bucket.get("reference_priority") or 0)
            current_ref_collected_at = bucket.get("status_collected_at") or datetime.min
            if priority > current_ref_priority or (priority == current_ref_priority and row_collected_at >= current_ref_collected_at):
                bucket["status_collected_at"] = row.collected_at
                bucket["reference_priority"] = priority

        current_latest_date = bucket.get("latest_date") or date(1900, 1, 1)
        current_latest_priority = int(bucket.get("latest_priority") or 0)
        current_latest_collected_at = bucket.get("latest_collected_at") or datetime.min
        if (
            row.date > current_latest_date
            or (row.date == current_latest_date and priority > current_latest_priority)
            or (row.date == current_latest_date and priority == current_latest_priority and row_collected_at >= current_latest_collected_at)
        ):
            bucket["latest_date"] = row.date
            bucket["latest_priority"] = priority
            bucket["latest_collected_at"] = row.collected_at

        if is_open_status:
            current_open_date = bucket.get("latest_open_date") or date(1900, 1, 1)
            current_open_collected_at = bucket.get("latest_open_collected_at") or datetime.min
            current_open_priority = int(bucket.get("latest_open_priority") or 0)
            if (
                row.date > current_open_date
                or (row.date == current_open_date and priority > current_open_priority)
                or (row.date == current_open_date and priority == current_open_priority and row_collected_at >= current_open_collected_at)
            ):
                bucket["latest_open_date"] = row.date
                bucket["latest_open_priority"] = priority
                bucket["latest_open_collected_at"] = row.collected_at
                bucket["latest_open_ended_on"] = row_ended_on

        if row_ended_date is not None:
            current_ended_date = bucket.get("latest_ended_on_date")
            current_ended_row_date = bucket.get("latest_ended_on_row_date") or date(1900, 1, 1)
            current_ended_collected_at = bucket.get("latest_ended_on_collected_at") or datetime.min
            if (
                current_ended_date is None
                or row_ended_date > current_ended_date
                or (row_ended_date == current_ended_date and row.date > current_ended_row_date)
                or (row_ended_date == current_ended_date and row.date == current_ended_row_date and row_collected_at >= current_ended_collected_at)
            ):
                bucket["latest_ended_on"] = row_ended_iso or row_ended_on
                bucket["latest_ended_on_date"] = row_ended_date
                bucket["latest_ended_on_row_date"] = row.date
                bucket["latest_ended_on_collected_at"] = row.collected_at

    finalized: dict[str, dict] = {}
    for key, bucket in out.items():
        ended_on_value = bucket.get("latest_ended_on") or bucket.get("latest_open_ended_on")
        if bool(bucket.get("has_reference_signal")):
            finalized[key] = {
                "label": "운영중",
                "active": True,
                "ended_on": ended_on_value,
                "basis": "reference_date_data",
                "collected_at": bucket.get("status_collected_at") or bucket.get("latest_collected_at"),
            }
            continue
        if bool(bucket.get("has_reference_data")):
            finalized[key] = {
                "label": "종료",
                "active": False,
                "ended_on": ended_on_value,
                "basis": "reference_date_zero_metrics",
                "collected_at": bucket.get("status_collected_at") or bucket.get("latest_collected_at"),
            }
            continue
        if bucket.get("latest_ended_on_date") is not None:
            finalized[key] = {
                "label": "종료",
                "active": False,
                "ended_on": bucket.get("latest_ended_on"),
                "basis": "historical_ended_on",
                "collected_at": bucket.get("latest_ended_on_collected_at") or bucket.get("latest_collected_at"),
            }
            continue
        finalized[key] = {
            "label": "종료",
            "active": False,
            "ended_on": ended_on_value,
            "basis": "reference_date_missing",
            "collected_at": bucket.get("latest_collected_at"),
        }
    return finalized


def _gfa_apply_status_snapshot(bucket: dict, snapshot: dict | None, *, level: str) -> None:
    if not snapshot:
        return
    if level == "campaign":
        bucket["campaign_status"] = snapshot.get("label")
        bucket["campaign_status_basis"] = snapshot.get("basis")
    elif level == "adgroup":
        bucket["adgroup_status"] = snapshot.get("label")
        bucket["adgroup_status_basis"] = snapshot.get("basis")
    bucket["ended_on"] = snapshot.get("ended_on")
    bucket["is_active"] = snapshot.get("active")
    if snapshot.get("collected_at") is not None:
        bucket["status_collected_at"] = snapshot.get("collected_at")


def _gfa_source_priority(source: str | None, level: str) -> int:
    s = str(source or "")
    if level == "campaign" and s == GFA_CONVERSION_COMPLETE_SOURCE_CAMPAIGN:
        return 30
    if level == "adgroup" and s == GFA_CONVERSION_COMPLETE_SOURCE_ASSET_GROUP:
        return 30
    if s in {GFA_CONVERSION_COMPLETE_SOURCE_CREATIVE, GFA_CONVERSION_COMPLETE_SOURCE}:
        return 10
    return 0


def _gfa_reset_group_bucket(
    bucket: dict,
    *,
    date_value: date,
    campaign_name: str,
    campaign_id: str | None = None,
    adgroup_name: str | None = None,
    adgroup_id: str | None = None,
    source: str | None = None,
    source_priority: int = 0,
) -> None:
    bucket.clear()
    bucket.update(
        {
            "date": date_value,
            "campaign_name": campaign_name,
            "campaign_id": str(campaign_id or "").strip() or None,
            "source": source or "",
            "_source_priority": source_priority,
            **_gfa_metric_bucket(),
        }
    )
    if adgroup_name is not None:
        bucket["adgroup_name"] = adgroup_name
    if adgroup_id is not None:
        bucket["adgroup_id"] = str(adgroup_id or "").strip() or None


def _gfa_base_query(
    db: Session,
    date_from: date,
    date_to: date | None,
    campaign: str | None = None,
    adgroup: str | None = None,
    sources: tuple[str, ...] | None = None,
):
    dt = date_to or date_from
    if dt < date_from:
        date_from, dt = dt, date_from
    q = db.query(NaverGfaDaily).filter(NaverGfaDaily.date >= date_from, NaverGfaDaily.date <= dt)
    q = q.filter(NaverGfaDaily.campaign_id != "__no_data__")
    if sources:
        q = q.filter(NaverGfaDaily.source.in_(list(sources)))
    if campaign:
        q = q.filter(NaverGfaDaily.campaign_name == str(campaign).strip())
    if adgroup:
        q = q.filter(NaverGfaDaily.adgroup_name == str(adgroup).strip())
    return q


@app.get("/gfa/ads/availability", response_model=dict)
def gfa_ads_availability(
    kind: str = Query(..., description="campaign | adgroup | creative"),
    date_from: date = Query(...),
    date_to: date = Query(...),
    db: Session = Depends(get_db),
):
    k = str(kind or "").strip().lower()
    if k not in ("campaign", "adgroup", "creative"):
        raise HTTPException(status_code=400, detail="kind must be campaign|adgroup|creative")
    if date_to < date_from:
        date_from, date_to = date_to, date_from
    if (date_to - date_from).days > 62:
        raise HTTPException(status_code=400, detail="date range too large (max 62 days)")

    rows = (
        db.query(NaverGfaDaily.date)
        .filter(NaverGfaDaily.date >= date_from, NaverGfaDaily.date <= date_to)
        .distinct()
        .all()
    )
    present = {r[0] for r in rows if r and r[0]}
    missing: list[str] = []
    cur = date_from
    while cur <= date_to:
        if cur not in present:
            missing.append(cur.strftime("%Y-%m-%d"))
        cur = cur + timedelta(days=1)
    return {"ok": True, "kind": k, "from": date_from, "to": date_to, "hasAny": bool(present), "missingDates": missing}


