def _gfa_inventory_campaign_key(campaign_id: object, campaign_name: object) -> str:
    cid = str(campaign_id or "").strip()
    if cid:
        return cid
    name = str(campaign_name or "").strip()
    return re.sub(r"\s+", " ", name).strip()


def _gfa_inventory_adgroup_key(campaign_id: object, campaign_name: object, adgroup_id: object, adgroup_name: object) -> str:
    cid = str(campaign_id or "").strip()
    gid = str(adgroup_id or "").strip()
    if gid:
        return f"{cid}::{gid}" if cid else gid
    campaign_part = re.sub(r"\s+", " ", str(campaign_name or "").strip())
    adgroup_part = re.sub(r"\s+", " ", str(adgroup_name or "").strip())
    return f"{campaign_part}::{adgroup_part}" if campaign_part and adgroup_part else ""


def _gfa_inventory_status_active(status: object, onoff: object = None) -> bool | None:
    status_text = re.sub(r"\s+", "", str(status or ""))
    onoff_text = re.sub(r"\s+", "", str(onoff or "")).lower()
    if onoff_text in {"on", "true", "1", "운영", "켜짐"}:
        return True
    if onoff_text in {"off", "false", "0", "중지", "꺼짐"}:
        return False
    if not status_text:
        return None
    if status_text in {"운영가능", "운영중", "진행중"}:
        return True
    if status_text in {"중지", "종료", "삭제", "운영불가"}:
        return False
    return None


@app.post("/gfa/campaigns/inventory/snapshot", response_model=dict)
def upsert_gfa_campaign_inventory_snapshot(
    payload: GfaCampaignInventorySnapshotPayload,
    db: Session = Depends(get_db),
):
    ad_account_no = re.sub(r"[^\d]", "", str(payload.ad_account_no or os.getenv("NAVER_GFA_AD_ACCOUNT_NO") or "48224"))
    campaign_type_default = str(payload.campaign_type or "").strip() or "unknown"
    menu_label_default = str(payload.menu_label or "").strip() or None
    collected_at = payload.collected_at or datetime.now(ZoneInfo("UTC"))
    saved = 0
    skipped = 0
    for item in payload.items or []:
        campaign_name = str(item.campaign_name or "").strip()
        campaign_id = str(item.campaign_id or "").strip()
        if not campaign_name and not campaign_id:
            skipped += 1
            continue
        campaign_key = _gfa_inventory_campaign_key(campaign_id, campaign_name)
        if not campaign_key:
            skipped += 1
            continue
        campaign_type = str(item.campaign_type or campaign_type_default).strip() or "unknown"
        row = NaverGfaCampaignInventory(
            ad_account_no=ad_account_no,
            campaign_type=campaign_type,
            campaign_key=campaign_key,
            campaign_id=campaign_id or None,
            campaign_name=campaign_name or campaign_key,
            menu_label=str(item.menu_label or menu_label_default or "").strip() or None,
            status=str(item.status or "").strip() or None,
            onoff=str(item.onoff or "").strip() or None,
            daily_budget=str(item.daily_budget or "").strip() or None,
            objective=str(item.objective or "").strip() or None,
            raw_payload_json=json.dumps(item.raw_payload or item.model_dump(mode="json"), ensure_ascii=False, default=str),
            collected_at=collected_at,
            updated_at=datetime.now(ZoneInfo("UTC")),
        )
        db.merge(row)
        saved += 1
    db.commit()
    return {
        "ok": True,
        "saved": saved,
        "skipped": skipped,
        "ad_account_no": ad_account_no,
        "campaign_type": campaign_type_default,
        "collected_at": collected_at.isoformat(),
    }


