@app.get("/gfa/campaigns/inventory", response_model=List[CampaignInventoryItem])
def list_gfa_campaign_inventory(
    campaign: Optional[str] = None,
    limit: int = Query(5000, ge=1, le=20000),
    offset: int = Query(0, ge=0),
    include_status_snapshot: bool = Query(True),
    db: Session = Depends(get_db),
):
    item_by_key: dict[str, dict] = {}
    stored_q = db.query(NaverGfaCampaignInventory)
    if campaign:
        stored_q = stored_q.filter(NaverGfaCampaignInventory.campaign_name == str(campaign).strip())
    for row in stored_q.all():
        key = _gfa_entity_status_key(
            level="campaign",
            campaign_id=row.campaign_id,
            campaign_name=row.campaign_name,
        ) or str(row.campaign_key or "").strip()
        if not key:
            continue
        active = _gfa_inventory_status_active(row.status, row.onoff)
        item_by_key[key] = {
            "campaign_id": str(row.campaign_id or "").strip() or None,
            "campaign_name": str(row.campaign_name or "").strip() or key,
            "campaign_type": str(row.campaign_type or "").strip() or None,
            "menu_label": str(row.menu_label or "").strip() or None,
            "onoff": str(row.onoff or "").strip() or None,
            "daily_budget": str(row.daily_budget or "").strip() or None,
            "campaign_status": str(row.status or "").strip() or None,
            "campaign_status_basis": "ad_center_inventory",
            "status_collected_at": row.collected_at,
            "is_active": active,
        }

    q = (
        db.query(NaverGfaDaily.campaign_id, NaverGfaDaily.campaign_name)
        .filter(NaverGfaDaily.campaign_id != "__no_data__")
        .filter(NaverGfaDaily.source.in_(list(GFA_CONVERSION_COMPLETE_SOURCES)))
    )
    if campaign:
        q = q.filter(NaverGfaDaily.campaign_name == str(campaign).strip())
    identity_rows = q.distinct().all()
    for campaign_id, campaign_name in identity_rows:
        key = _gfa_entity_status_key(
            level="campaign",
            campaign_id=campaign_id,
            campaign_name=campaign_name,
        )
        if not key:
            continue
        current = item_by_key.get(key)
        next_name = str(campaign_name or "").strip() or str(campaign_id or "").strip()
        if current is None:
            item_by_key[key] = {
                "campaign_id": str(campaign_id or "").strip() or None,
                "campaign_name": next_name or key,
            }
            continue
        if not current.get("campaign_id") and str(campaign_id or "").strip():
            current["campaign_id"] = str(campaign_id or "").strip()
        if (not str(current.get("campaign_name") or "").strip()) and next_name:
            current["campaign_name"] = next_name

    reference_date = _gfa_status_reference_date(db)
    snapshot_map = _gfa_current_status_snapshot_map(
        db,
        level="campaign",
        reference_date=reference_date,
        entity_keys=set(item_by_key.keys()),
    ) if include_status_snapshot else {}
    items: list[dict] = []
    for key, item in item_by_key.items():
        bucket = {
            "campaign_id": item.get("campaign_id"),
            "campaign_name": item.get("campaign_name") or key,
            "campaign_type": item.get("campaign_type"),
            "menu_label": item.get("menu_label"),
            "onoff": item.get("onoff"),
            "daily_budget": item.get("daily_budget"),
        }
        snapshot = snapshot_map.get(key)
        if snapshot:
            _gfa_apply_status_snapshot(bucket, snapshot, level="campaign")
        else:
            bucket["campaign_status"] = item.get("campaign_status")
            bucket["campaign_status_basis"] = item.get("campaign_status_basis")
            bucket["status_collected_at"] = item.get("status_collected_at")
            bucket["is_active"] = item.get("is_active")
        items.append(bucket)
    items.sort(
        key=lambda x: (
            0 if x.get("is_active") is True else 1,
            str(x.get("campaign_name") or "").strip(),
        )
    )
    sliced = items[offset : offset + limit]
    return [CampaignInventoryItem(**item) for item in sliced]


@app.get("/gfa/campaigns/daily", response_model=List[CampaignDailyAgg])
def list_gfa_campaign_daily(
    date_from: date,
    date_to: Optional[date] = None,
    campaign: Optional[str] = None,
    limit: int = Query(500, ge=1, le=2000),
    offset: int = Query(0, ge=0),
    include_status_snapshot: bool = Query(True),
    db: Session = Depends(get_db),
):
    grouped: dict[tuple, dict] = {}
    for r in _gfa_base_query(db, date_from, date_to, campaign=campaign, sources=GFA_CONVERSION_COMPLETE_SOURCES).all():
        key = (r.date, r.campaign_name or r.campaign_id)
        priority = _gfa_source_priority(r.source, "campaign")
        if priority <= 0:
            continue
        bucket = grouped.get(key)
        if bucket is None:
            bucket = {}
            grouped[key] = bucket
            _gfa_reset_group_bucket(
                bucket,
                date_value=r.date,
                campaign_name=r.campaign_name or r.campaign_id,
                campaign_id=r.campaign_id,
                source=r.source,
                source_priority=priority,
            )
        elif priority > int(bucket.get("_source_priority") or 0):
            _gfa_reset_group_bucket(
                bucket,
                date_value=r.date,
                campaign_name=r.campaign_name or r.campaign_id,
                campaign_id=r.campaign_id,
                source=r.source,
                source_priority=priority,
            )
        elif priority < int(bucket.get("_source_priority") or 0):
            continue
        _gfa_add_metrics(bucket, r)
        if not include_status_snapshot:
            _gfa_apply_row_status(bucket, r, level="campaign")
    if include_status_snapshot:
        reference_date = _gfa_status_reference_date(db)
        campaign_keys = {
            key
            for key in (
                _gfa_entity_status_key(
                    level="campaign",
                    campaign_id=row.get("campaign_id"),
                    campaign_name=row.get("campaign_name"),
                )
                for row in grouped.values()
            )
            if key
        }
        snapshot_map = _gfa_current_status_snapshot_map(db, level="campaign", reference_date=reference_date, entity_keys=campaign_keys)
        for bucket in grouped.values():
            bucket_key = _gfa_entity_status_key(
                level="campaign",
                campaign_id=bucket.get("campaign_id"),
                campaign_name=bucket.get("campaign_name"),
            )
            _gfa_apply_status_snapshot(bucket, snapshot_map.get(bucket_key) if bucket_key else None, level="campaign")
    rows = sorted(grouped.values(), key=lambda x: (x["date"], x["cost"], x["impressions"]), reverse=True)[offset : offset + limit]
    return [CampaignDailyAgg(**_gfa_finalize_metrics({k: v for k, v in row.items() if not str(k).startswith("_")})) for row in rows]


@app.get("/gfa/adgroups/inventory", response_model=List[AdgroupInventoryItem])
def list_gfa_adgroup_inventory(
    campaign: Optional[str] = None,
    adgroup: Optional[str] = None,
    limit: int = Query(10000, ge=1, le=30000),
    offset: int = Query(0, ge=0),
    include_status_snapshot: bool = Query(True),
    db: Session = Depends(get_db),
):
    item_by_key: dict[str, dict] = {}
    campaign_keys: set[str] = set()
    stored_q = db.query(NaverGfaAdgroupInventory)
    if campaign:
        stored_q = stored_q.filter(NaverGfaAdgroupInventory.campaign_name == str(campaign).strip())
    if adgroup:
        stored_q = stored_q.filter(NaverGfaAdgroupInventory.adgroup_name == str(adgroup).strip())
    for row in stored_q.all():
        key = _gfa_entity_status_key(
            level="adgroup",
            campaign_id=row.campaign_id,
            campaign_name=row.campaign_name,
            adgroup_id=row.adgroup_id,
            adgroup_name=row.adgroup_name,
        ) or str(row.adgroup_key or "").strip()
        if not key:
            continue
        campaign_key = _gfa_entity_status_key(
            level="campaign",
            campaign_id=row.campaign_id,
            campaign_name=row.campaign_name,
        )
        if campaign_key:
            campaign_keys.add(campaign_key)
        active = _gfa_inventory_status_active(row.status, row.onoff)
        item_by_key[key] = {
            "campaign_id": str(row.campaign_id or "").strip() or None,
            "campaign_name": str(row.campaign_name or "").strip() or campaign_key or key,
            "adgroup_id": str(row.adgroup_id or "").strip() or None,
            "adgroup_name": str(row.adgroup_name or "").strip() or key,
            "campaign_type": str(row.campaign_type or "").strip() or None,
            "menu_label": str(row.menu_label or "").strip() or None,
            "onoff": str(row.onoff or "").strip() or None,
            "daily_budget": str(row.daily_budget or "").strip() or None,
            "adgroup_status": str(row.status or "").strip() or None,
            "adgroup_status_basis": "ad_center_inventory",
            "status_collected_at": row.collected_at,
            "is_active": active,
        }

    q = (
        db.query(
            NaverGfaDaily.campaign_id,
            NaverGfaDaily.campaign_name,
            NaverGfaDaily.adgroup_id,
            NaverGfaDaily.adgroup_name,
        )
        .filter(NaverGfaDaily.campaign_id != "__no_data__")
        .filter(NaverGfaDaily.source.in_(list(GFA_CONVERSION_COMPLETE_SOURCES)))
    )
    if campaign:
        q = q.filter(NaverGfaDaily.campaign_name == str(campaign).strip())
    if adgroup:
        q = q.filter(NaverGfaDaily.adgroup_name == str(adgroup).strip())
    fallback_limit = min(30000, max(limit + offset, limit, 1))
    identity_rows = q.distinct().limit(fallback_limit).all()
    for campaign_id, campaign_name, adgroup_id, adgroup_name in identity_rows:
        key = _gfa_entity_status_key(
            level="adgroup",
            campaign_id=campaign_id,
            campaign_name=campaign_name,
            adgroup_id=adgroup_id,
            adgroup_name=adgroup_name,
        )
        if not key:
            continue
        campaign_key = _gfa_entity_status_key(
            level="campaign",
            campaign_id=campaign_id,
            campaign_name=campaign_name,
        )
        if campaign_key:
            campaign_keys.add(campaign_key)
        current = item_by_key.get(key)
        next_campaign_name = str(campaign_name or "").strip() or str(campaign_id or "").strip()
        next_adgroup_name = str(adgroup_name or "").strip() or str(adgroup_id or "").strip()
        if current is None:
            item_by_key[key] = {
                "campaign_id": str(campaign_id or "").strip() or None,
                "campaign_name": next_campaign_name or campaign_key or key,
                "adgroup_id": str(adgroup_id or "").strip() or None,
                "adgroup_name": next_adgroup_name or key,
            }
            continue
        if not current.get("campaign_id") and str(campaign_id or "").strip():
            current["campaign_id"] = str(campaign_id or "").strip()
        if not current.get("adgroup_id") and str(adgroup_id or "").strip():
            current["adgroup_id"] = str(adgroup_id or "").strip()
        if (not str(current.get("campaign_name") or "").strip()) and next_campaign_name:
            current["campaign_name"] = next_campaign_name
        if (not str(current.get("adgroup_name") or "").strip()) and next_adgroup_name:
            current["adgroup_name"] = next_adgroup_name

    reference_date = _gfa_status_reference_date(db)
    adgroup_snapshot_map = _gfa_current_status_snapshot_map(
        db,
        level="adgroup",
        reference_date=reference_date,
        entity_keys=set(item_by_key.keys()),
    ) if include_status_snapshot else {}
    campaign_snapshot_map = _gfa_current_status_snapshot_map(
        db,
        level="campaign",
        reference_date=reference_date,
        entity_keys=campaign_keys,
    ) if include_status_snapshot else {}
    items: list[dict] = []
    for key, item in item_by_key.items():
        bucket = {
            "campaign_id": item.get("campaign_id"),
            "campaign_name": item.get("campaign_name") or key,
            "adgroup_id": item.get("adgroup_id"),
            "adgroup_name": item.get("adgroup_name") or key,
            "campaign_type": item.get("campaign_type"),
            "menu_label": item.get("menu_label"),
            "onoff": item.get("onoff"),
            "daily_budget": item.get("daily_budget"),
            "adgroup_status": item.get("adgroup_status"),
            "adgroup_status_basis": item.get("adgroup_status_basis"),
            "status_collected_at": item.get("status_collected_at"),
            "is_active": item.get("is_active"),
        }
        campaign_key = _gfa_entity_status_key(
            level="campaign",
            campaign_id=bucket.get("campaign_id"),
            campaign_name=bucket.get("campaign_name"),
        )
        campaign_snapshot = campaign_snapshot_map.get(campaign_key) if campaign_key else None
        if campaign_snapshot:
            bucket["campaign_status"] = campaign_snapshot.get("label")
        _gfa_apply_status_snapshot(bucket, adgroup_snapshot_map.get(key), level="adgroup")
        items.append(bucket)
    items.sort(
        key=lambda x: (
            0 if x.get("is_active") is True else 1,
            str(x.get("campaign_name") or "").strip(),
            str(x.get("adgroup_name") or "").strip(),
        )
    )
    sliced = items[offset : offset + limit]
    return [AdgroupInventoryItem(**item) for item in sliced]


