@app.get("/search-rank/products", response_model=List[ProductRankDaily])
def list_product_rank_daily(
    keyword: str,
    date_from: date,
    date_to: Optional[date] = None,
    limit: int = Query(500, ge=1, le=2000),
    offset: int = Query(0, ge=0),
    db: Session = Depends(get_db),
):
    """
    네이버 쇼핑 검색 결과 기반 상품 순위 일간 스냅샷.

    - menu4(검색 순위 분석) 화면에서 사용하는 기본 API
    - `naver_product_rank_daily` 테이블을 그대로 조회하며,
      날짜 역순 → 순위 오름차순으로 정렬한다.
    """
    if date_to is None:
        date_to = date_from

    q = (
        db.query(NaverProductRankDaily)
        .filter(
            NaverProductRankDaily.keyword == keyword,
            NaverProductRankDaily.date >= date_from,
            NaverProductRankDaily.date <= date_to,
        )
        .order_by(
            NaverProductRankDaily.date.desc(),
            NaverProductRankDaily.rank.asc(),
        )
    )

    rows = q.offset(offset).limit(limit).all()
    return rows


def build_product_rank_history(
    rows: List[NaverProductRankDaily],
) -> ProductRankHistory:
    """
    `naver_product_rank_daily` 행 리스트를
    메뉴4 '순위 변화' 화면에서 사용하기 좋은 구조로 집계한다.

    - 자사 브랜드(`is_our_brand=True`) 행만 포함
    - 같은 날짜/키워드에 여러 상품이 있을 경우 **최소 순위(가장 상위 상품)** 로 대표값을 사용
    """
    if not rows:
        return ProductRankHistory(dates=[], series=[])

    # 1) 자사 브랜드가 있으면 우선 사용, 없으면 전체 행을 사용
    our_rows = [r for r in rows if getattr(r, "is_our_brand", False)]
    filtered = our_rows if our_rows else rows

    # 2) 날짜 축 구성 (오름차순)
    date_set = {r.date for r in filtered}
    dates = sorted(date_set)

    # 3) 키워드별 {date -> best_rank} 맵 구축
    by_keyword: dict[str, dict[date, int]] = {}
    for r in filtered:
        kw = r.keyword
        d = r.date
        rank = int(r.rank or 0)
        if kw not in by_keyword:
            by_keyword[kw] = {d: rank}
            continue
        current = by_keyword[kw].get(d)
        if current is None or (rank > 0 and rank < current):
            by_keyword[kw][d] = rank

    # 4) Pydantic 시리즈로 변환
    series_list: List[ProductRankSeries] = []
    for kw, date_map in sorted(by_keyword.items(), key=lambda item: item[0]):
        points: List[ProductRankPoint] = []
        for d in dates:
            if d in date_map:
                points.append(ProductRankPoint(date=d, rank=date_map[d]))
        if points:
            series_list.append(ProductRankSeries(keyword=kw, series=points))

    return ProductRankHistory(dates=dates, series=series_list)


def build_product_comparison_history(
    rows: List[NaverProductRankDaily],
    competitors: List[TrackedCompetitorProduct],
    our_label: str = "내 상품",
) -> ComparisonHistory:
    """
    `naver_product_rank_daily` 행과 경쟁 상품 정의 리스트를 받아
    내 상품 vs 경쟁 상품별 날짜별 순위 비교 히스토리를 생성한다.

    - 내 상품: is_our_brand=True 인 행들 중 날짜별 최소 순위 사용
    - 경쟁 상품: 각 competitor.match_text 가 mall_name 또는 product_title 에 포함된 행만 사용
    """
    if not rows:
        return ComparisonHistory(dates=[], products=[])

    dates = sorted({r.date for r in rows})

    def build_series_for_filter(predicate) -> List[ProductRankPoint]:
        by_date: dict[date, int] = {}
        for r in rows:
            if not predicate(r):
                continue
            d = r.date
            rank = int(r.rank or 0)
            if rank <= 0:
                continue
            current = by_date.get(d)
            if current is None or rank < current:
                by_date[d] = rank
        result: List[ProductRankPoint] = []
        for d in dates:
            if d in by_date:
                result.append(ProductRankPoint(date=d, rank=by_date[d]))
        return result

    products: List[ComparisonSeries] = []

    # 1) 내 상품 시리즈
    our_points = build_series_for_filter(lambda r: getattr(r, "is_our_brand", False))
    if our_points:
        products.append(
            ComparisonSeries(label=our_label, kind="our", series=our_points),
        )

    # 2) 경쟁 상품 시리즈
    for comp in competitors:
        text = (comp.match_text or "").strip()
        if not text:
            continue

        def predicate(row: NaverProductRankDaily, needle: str = text) -> bool:
            if getattr(row, "is_our_brand", False):
                return False
            mall = (row.mall_name or "") if hasattr(row, "mall_name") else ""
            title = (row.product_title or "") if hasattr(row, "product_title") else ""
            return needle in mall or needle in title

        points = build_series_for_filter(predicate)
        if not points:
            continue
        products.append(
            ComparisonSeries(label=comp.name, kind="competitor", series=points),
        )

    if not products:
        return ComparisonHistory(dates=[], products=[])

    return ComparisonHistory(dates=dates, products=products)


@app.get("/search-rank/history", response_model=ProductRankHistory)
def get_product_rank_history(
    days: int = Query(7, ge=1, le=365),
    product_url: Optional[str] = Query(
        None,
        description=(
            "특정 상품의 순위 변화만 보고 싶을 때 사용하는 상품 URL "
            "(예: 스마트스토어 URL, 선택값)"
        ),
    ),
    keyword_scope: Optional[str] = Query(
        None,
        description=(
            "키워드 범위 필터.\n"
            "- core: auto-tracked(core) 키워드만(리스트 초기 로딩 최적화)\n"
            "- all(기본): 전체 키워드"
        ),
    ),
    db: Session = Depends(get_db),
):
    """
    자사 브랜드/특정 상품 기준으로 키워드별 쇼핑 검색 순위 변화를 집계한다.

    - 기간: 오늘 기준 `days` 일 전부터 오늘까지 (기본 7일)
    - 데이터 소스: `naver_product_rank_daily`
    - product_url 이 주어지면, 해당 URL 에서 추출한 productId 에 해당하는
      상품의 행만 필터링해서 히스토리를 생성한다.
    """
    today = _today_kst()
    date_from = today - timedelta(days=days - 1)

    scope = str(keyword_scope or "").strip().lower()
    core_keywords: list[str] = []
    if scope == "core" and product_url:
        try:
            filters = _smartstore_product_url_filters(TrackedProductAutoKeyword, product_url=product_url)
            core_keywords = (
                db.query(TrackedProductAutoKeyword.keyword)
                .filter(
                    or_(*filters),
                    TrackedProductAutoKeyword.is_active.is_(True),
                    TrackedProductAutoKeyword.group_type == "core",
                )
                .order_by(TrackedProductAutoKeyword.keyword.asc())
                .all()
            )
            # SQLAlchemy returns list[tuple] for single column select
            core_keywords = [str(t[0]).strip() for t in (core_keywords or []) if str(t[0] or "").strip()]
        except Exception:
            core_keywords = []

    # (선택) product_url 이 주어지면 productId 를 추출해 해당 상품만 필터링
    pid_int: Optional[int] = None
    pid_str = _canonical_product_id(product_url)
    if pid_str is not None:
        try:
            pid_int = int(pid_str)
        except ValueError:
            pid_int = None

    # 0) (선택) product_url 이 주어진 경우:
    # - 공식 엑셀 업로드(tracked_product_rank_daily)가 있으면 이를 우선 사용한다.
    # - 다만 엑셀 업로드는 '부분 기간'일 수 있어, OpenAPI 스냅샷으로 빈 날짜를 보완한다.
    tracked_rows: list[TrackedProductRankDaily] | None = None
    if product_url:
        # IMPORTANT:
        # - tracked_product_rank_daily는 product_url을 PK로 사용한다.
        # - 하지만 UI/사용자 입력 URL에는 쿼리스트링/인코딩/정규화 차이(NaPm, utm 등)가 섞여
        #   "문자열 완전일치"가 깨질 수 있다.
        # - 따라서 가능하면 productId(스마트스토어 URL의 마지막 숫자)를 기준으로도 매칭한다.
        #   (상품ID는 충분히 길어 substring 충돌 가능성이 낮다)
        filters = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=product_url)

        tracked_rows = (
            db.query(TrackedProductRankDaily)
            .filter(
                or_(*filters),
                TrackedProductRankDaily.date >= date_from,
                TrackedProductRankDaily.date <= today,
                *( [TrackedProductRankDaily.keyword.in_(core_keywords)] if core_keywords else [] ),
            )
            .order_by(
                TrackedProductRankDaily.date.asc(),
                TrackedProductRankDaily.keyword.asc(),
            )
            .all()
        )

        # productId가 URL에서 추출되지 않으면, URL 기반 메타테이블의 catalog productId를 fallback으로 사용
        if pid_int is None:
            try:
                meta = (
                    db.query(TrackedProductMeta)
                    .filter(TrackedProductMeta.product_url == product_url)
                    .order_by(TrackedProductMeta.updated_at.desc())
                    .limit(1)
                    .one_or_none()
                )
                if meta is not None and getattr(meta, "product_id_catalog", None) is not None:
                    pid_int = int(meta.product_id_catalog)
            except Exception:
                pass

    def base_query():
        q = db.query(NaverProductRankDaily)
        if pid_int is not None:
            q = q.filter(NaverProductRankDaily.product_id == pid_int)
        if core_keywords:
            q = q.filter(NaverProductRankDaily.keyword.in_(core_keywords))
        return q

    openapi_rows = (
        base_query()
        .filter(
            NaverProductRankDaily.date >= date_from,
            NaverProductRankDaily.date <= today,
        )
        .order_by(
            NaverProductRankDaily.date.asc(),
            NaverProductRankDaily.rank.asc(),
        )
        .all()
    )

    # product_url 케이스: tracked + openapi 병합(오늘 데이터 누락 방지)
    if product_url and (tracked_rows or openapi_rows):
        return build_merged_rank_history(tracked_rows=tracked_rows, openapi_rows=openapi_rows)

    rows = openapi_rows

    # 선택한 기간 내에 데이터가 하나도 없으면, 전체 기간 데이터를 사용해 히스토리를 구성한다.
    if not rows:
        rows = (
            base_query()
            .order_by(
                NaverProductRankDaily.date.asc(),
                NaverProductRankDaily.rank.asc(),
            )
            .all()
        )

    return build_product_rank_history(rows)


@app.post("/search-rank/history/batch", response_model=Dict[str, Optional[ProductRankHistory]])
def get_product_rank_history_batch(
    req: ProductRankHistoryBatchRequest = Body(...),
    days: int = Query(7, ge=1, le=365),
    keyword_scope: Optional[str] = Query(
        None,
        description="키워드 범위 필터(core|all). 기본 all",
    ),
    db: Session = Depends(get_db),
):
    """
    내 상품 추적(리스트) 진입 성능 개선을 위한 배치 조회.
    - 기존: 상품 수만큼 /search-rank/history 를 N번 호출(HTTP 오버헤드 + 병렬 DB 부하)
    - 개선: 1번 호출로 id -> ProductRankHistory 매핑을 반환
    """
    out: Dict[str, Optional[ProductRankHistory]] = {}
    for it in (req.items or []):
        try:
            pid = str(getattr(it, "id", "") or "").strip()
            url = str(getattr(it, "product_url", "") or "").strip()
            if not pid:
                continue
            if not url or url == "N/A":
                out[pid] = None
                continue
            out[pid] = get_product_rank_history(
                days=days,
                product_url=url,
                keyword_scope=keyword_scope,
                db=db,
            )
        except Exception:
            # 배치에서 한 항목 실패가 전체 실패로 이어지지 않도록 방어
            try:
                if getattr(it, "id", None):
                    out[str(getattr(it, "id"))] = None
            except Exception:
                pass
    return out


@app.get("/search-rank/history/manual", response_model=ProductRankHistory)
def get_product_manual_rank_history(
    days: int = Query(7, ge=1, le=365),
    product_url: Optional[str] = Query(
        None,
        description="수기 입력(source='text') 순위만 조회할 때 사용하는 상품 URL",
    ),
    db: Session = Depends(get_db),
):
    """
    수기 입력(source='text')으로 저장된 tracked_product_rank_daily 만 조회한다.
    - 기존 /search-rank/history 는 (tracked excel/text + openapi) 병합이라 source 구분이 불가능함
    - 상세 화면의 '수기 입력 키워드' 데일리 표는 이 엔드포인트를 사용해 안정적으로 구성한다.
    """
    if not product_url:
        return ProductRankHistory(dates=[], series=[])

    today = _today_kst()
    date_from = today - timedelta(days=days - 1)

    filters = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=product_url)

    rows = (
        db.query(TrackedProductRankDaily)
        .filter(
            or_(*filters),
            TrackedProductRankDaily.source == "text",
            TrackedProductRankDaily.date >= date_from,
            TrackedProductRankDaily.date <= today,
        )
        .order_by(
            TrackedProductRankDaily.date.asc(),
            TrackedProductRankDaily.keyword.asc(),
        )
        .all()
    )
    return build_tracked_rank_history(rows)


@app.get("/search-rank/history/manual-keywords", response_model=ProductRankHistory)
def get_product_manual_keywords_rank_history(
    days: int = Query(7, ge=1, le=365),
    product_url: Optional[str] = Query(
        None,
        description="수기 키워드(월검색량) 목록 기준으로 (text + crawl_category) 순위를 조회할 때 사용하는 상품 URL",
    ),
    db: Session = Depends(get_db),
):
    """
    수기 키워드(후보) 목록(tracked_product_manual_keyword)을 기준으로,
    해당 키워드들의 '일자별 순위 스냅샷'을 조회한다.

    포함 source:
    - text: 사용자가 직접 입력한 수기 순위
    - openapi: 네이버 쇼핑 검색 OpenAPI(shop.json) 기반 수집 순위

    배경:
    - 현재 환경에서 쇼핑 내부 API(/api/search/all)가 418(access_limited)로 막히는 경우가 있어도,
      크롤러는 검색 페이지 HTML(__NEXT_DATA__) 기반으로 일부 순위를 저장할 수 있다.
    - 상세 화면의 '수기 키워드 데일리 표'는 이 endpoint로 조회해야 crawl 결과가 반영된다.
    """
    if not product_url:
        return ProductRankHistory(dates=[], series=[])

    today = _today_kst()
    date_from = today - timedelta(days=days - 1)

    url_filters = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=product_url)
    mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=product_url)
    tk_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=product_url)

    # OpenAPI(fetch-today) 스냅샷은 naver_product_rank_daily(product_id 기반)로 저장되므로,
    # product_url → productId 변환을 구성한다.
    pid_int: Optional[int] = None
    pid_str = _canonical_product_id(product_url)
    if pid_str is not None:
        try:
            pid_int = int(pid_str)
        except ValueError:
            pid_int = None
    if pid_int is None:
        # URL에서 추출되지 않으면, meta 테이블의 catalog productId로 폴백한다.
        try:
            meta_filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=product_url)
            meta = (
                db.query(TrackedProductMeta)
                .filter(or_(*meta_filters))
                .order_by(TrackedProductMeta.updated_at.desc())
                .limit(1)
                .one_or_none()
            )
            if meta is not None and getattr(meta, "product_id_catalog", None) is not None:
                pid_int = int(meta.product_id_catalog)
        except Exception:
            pid_int = None

    # 1) 후보 키워드 목록
    kw_rows = (
        db.query(TrackedProductManualKeyword.keyword)
        .filter(or_(*mk_filters), TrackedProductManualKeyword.is_active.is_(True))
        .all()
    )
    tracked_kw_rows = (
        db.query(TrackedProductKeyword.keyword)
        .filter(or_(*tk_filters), TrackedProductKeyword.is_active.is_(True))
        .all()
    )
    # 수기 키워드(월검색량) + 추적 키워드 모두를 "수기 표"에 함께 보여준다.
    keywords = sorted(
        {
            str(x[0] or "").strip()
            for x in (kw_rows or [])
            if x and str(x[0] or "").strip()
        }
        | {
            str(x[0] or "").strip()
            for x in (tracked_kw_rows or [])
            if x and str(x[0] or "").strip()
        }
    )
    if not keywords:
        return ProductRankHistory(dates=[], series=[])

    # 2) (A) tracked_product_rank_daily: 업로드(excel) + 수기(text) + 수집(openapi/crawl_category) 스냅샷
    tracked_rows = (
        db.query(TrackedProductRankDaily)
        .filter(
            or_(*url_filters),
            TrackedProductRankDaily.keyword.in_(keywords),
            # 수기 키워드 데일리 표는 "저장된 이력"을 보여줘야 하므로,
            # 수집 경로(openapi/crawl_category) + 업로드(excel) + 수기(text)를 모두 포함한다.
            TrackedProductRankDaily.source.in_(["text", "openapi", "crawl_category", "excel"]),
            TrackedProductRankDaily.date >= date_from,
            TrackedProductRankDaily.date <= today,
        )
        .order_by(
            TrackedProductRankDaily.date.asc(),
            TrackedProductRankDaily.keyword.asc(),
        )
        .all()
    )

    # 2) (B) naver_product_rank_daily: fetch-today(OpenAPI) 일간 스냅샷
    openapi_rows: list[NaverProductRankDaily] | None = None
    if pid_int is not None:
        openapi_rows = (
            db.query(NaverProductRankDaily)
            .filter(
                NaverProductRankDaily.product_id == pid_int,
                NaverProductRankDaily.keyword.in_(keywords),
                NaverProductRankDaily.date >= date_from,
                NaverProductRankDaily.date <= today,
            )
            .order_by(NaverProductRankDaily.date.asc(), NaverProductRankDaily.rank.asc())
            .all()
        )
    return build_merged_rank_history(tracked_rows=tracked_rows, openapi_rows=openapi_rows)


@app.post("/search-rank/manual-keywords/delete", response_model=ManualKeywordsDeleteResponse)
def delete_manual_keywords(
    payload: ManualKeywordsDeleteRequest,
    db: Session = Depends(get_db),
):
    """
    상세 화면의 '수기 입력 키워드'에서 선택한 키워드를 삭제한다.

    - tracked_product_rank_daily 중 source='text' 행만 삭제한다.
    - 키워드 단위 삭제(해당 키워드의 모든 일자 기록 삭제)
    - product_url 정규화 차이 대응을 위해 productId 기반 like 매칭도 함께 사용한다.
    """
    product_url = str(getattr(payload, "product_url", "") or "").strip()
    if not product_url:
        raise HTTPException(status_code=400, detail="product_url is required")

    keywords_raw = getattr(payload, "keywords", None) or []
    keywords = sorted({str(k or "").strip() for k in keywords_raw if str(k or "").strip()})
    if not keywords:
        return ManualKeywordsDeleteResponse(deleted=0)

    filters = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=product_url)

    deleted = (
        db.query(TrackedProductRankDaily)
        .filter(
            or_(*filters),
            TrackedProductRankDaily.source == "text",
            TrackedProductRankDaily.keyword.in_(keywords),
        )
        .delete(synchronize_session=False)
    )
    db.commit()
    return ManualKeywordsDeleteResponse(deleted=int(deleted or 0))


@app.get("/search-rank/manual-keywords", response_model=list[ManualKeywordsListResponseItem])
def list_manual_keywords(
    product_url: Optional[str] = Query(None, description="상품 URL"),
    db: Session = Depends(get_db),
):
    """
    상세 화면에서 사용하는 '수기 키워드(후보) + 월검색량' 리스트를 조회한다.
    """
    if not product_url:
        return []
    product_url = str(product_url or "").strip()
    if not product_url:
        return []
    filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=product_url)
    rows = (
        db.query(TrackedProductManualKeyword)
        .filter(or_(*filters), TrackedProductManualKeyword.is_active.is_(True))
        .order_by(TrackedProductManualKeyword.keyword.asc())
        .all()
    )
    if not rows:
        # (중요) 수기 키워드가 0개일 때의 의미는 2가지다.
        # 1) 신규 상품: 아직 월검색량 메타가 한 번도 저장된 적이 없음 → tracked 키워드로 자동 시드
        # 2) 사용자가 "전부 삭제": 메타는 존재하지만 모두 inactive → 자동 시드하면 삭제가 되돌아온 것처럼 보임
        if not _manual_keyword_meta_exists_any(db, product_url=product_url):
            try:
                _seed_manual_keywords_from_tracked(db, product_url=product_url)
            except Exception:
                pass
            rows = (
                db.query(TrackedProductManualKeyword)
                .filter(or_(*filters), TrackedProductManualKeyword.is_active.is_(True))
                .order_by(TrackedProductManualKeyword.keyword.asc())
                .all()
            )
    return rows


@app.get("/search-rank/manual-keywords/crawl-today", response_model=ManualKeywordsCrawlTodayResponse)
def get_manual_keywords_crawl_today(
    product_url: str = Query(..., description="기준 상품 URL"),
    target_date: Optional[date] = Query(None, alias="date", description="조회 일자(미입력 시 오늘)"),
    db: Session = Depends(get_db),
):
    """
    상세/모달의 "등록된 키워드" 목록을 기준으로,
    오늘자(OpenAPI, source='openapi') 순위 스냅샷을 키워드별로 조회한다(0 포함).

    - 목적: "미노출(0/없음) 키워드만 재수집" 같은 UX 구현을 위해, 프론트가 빠르게 상태를 계산할 수 있게 한다.

    등록된 키워드 기준(중요):
    - 수기 키워드(월검색량) 메타: tracked_product_manual_keyword (active)
    - 내 상품 추적 키워드(핵심/그룹): tracked_product_keyword (active)

    이유:
    - UI에서는 두 영역 모두를 "등록 키워드"로 인식한다.
    - 한쪽만 기준으로 삼으면, 등록되어 있는 키워드가 수집 대상에서 빠져 '-'로 보이는 혼란이 발생한다.
    """
    seed = str(product_url or "").strip()
    if not seed:
        raise HTTPException(status_code=400, detail="product_url is required")

    d = target_date or _today_kst()
    if isinstance(d, datetime):
        d = d.date()

    mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=seed)
    rank_filters = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=seed)

    kw_rows = (
        db.query(TrackedProductManualKeyword.keyword)
        .filter(or_(*mk_filters), TrackedProductManualKeyword.is_active.is_(True))
        .all()
    )
    manual_keywords = [str(x[0] or "").strip() for x in kw_rows if x and str(x[0] or "").strip()]
    manual_keywords = list(dict.fromkeys(manual_keywords))
    if not manual_keywords:
        # (중요) 자동 시드는 신규 상품에만 허용한다.
        # 사용자가 "전부 삭제"한 상품까지 자동 시드를 하면 삭제가 되돌아온 것으로 인지된다.
        if not _manual_keyword_meta_exists_any(db, product_url=seed):
            try:
                _seed_manual_keywords_from_tracked(db, product_url=seed)
            except Exception:
                pass
            kw_rows = (
                db.query(TrackedProductManualKeyword.keyword)
                .filter(or_(*mk_filters), TrackedProductManualKeyword.is_active.is_(True))
                .all()
            )
            manual_keywords = [str(x[0] or "").strip() for x in kw_rows if x and str(x[0] or "").strip()]
            manual_keywords = list(dict.fromkeys(manual_keywords))

    # tracked 키워드도 합친다(수기 키워드가 존재하더라도 tracked 키워드가 별도로 등록될 수 있음)
    tracked_keywords: list[str] = []
    try:
        tk_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=seed)
        if tk_filters:
            tk_rows = (
                db.query(TrackedProductKeyword.keyword)
                .filter(or_(*tk_filters), TrackedProductKeyword.is_active.is_(True))
                .all()
            )
            tracked_keywords = [str(x[0] or "").strip() for x in tk_rows if x and str(x[0] or "").strip()]
            tracked_keywords = list(dict.fromkeys(tracked_keywords))
    except Exception:
        tracked_keywords = []

    keywords = sorted(list(dict.fromkeys([*manual_keywords, *tracked_keywords])))
    if not keywords:
        return ManualKeywordsCrawlTodayResponse(
            product_url=seed,
            target_date=d.strftime("%Y-%m-%d"),
            total_keywords=0,
            crawled_keywords=0,
            found_keywords=0,
            missing_keywords=0,
            items=[],
        )

    rows = (
        db.query(TrackedProductRankDaily)
        .filter(
            or_(*rank_filters),
            TrackedProductRankDaily.date == d,
            TrackedProductRankDaily.source == "openapi",
            TrackedProductRankDaily.keyword.in_(keywords),
        )
        .order_by(TrackedProductRankDaily.keyword.asc())
        .all()
    )
    by_kw: dict[str, TrackedProductRankDaily] = {}
    for r in rows:
        k = str(getattr(r, "keyword", "") or "").strip()
        if not k:
            continue
        prev = by_kw.get(k)
        if prev is None:
            by_kw[k] = r
            continue
        try:
            rk = int(getattr(r, "rank", 0) or 0)
            pk = int(getattr(prev, "rank", 0) or 0)
            if pk <= 0 and rk > 0:
                by_kw[k] = r
            elif rk > 0 and rk < pk:
                by_kw[k] = r
        except Exception:
            pass

    items: list[ManualKeywordsCrawlTodayItem] = []
    crawled = 0
    found = 0
    missing = 0
    for k in keywords:
        r = by_kw.get(k)
        if r is None:
            items.append(ManualKeywordsCrawlTodayItem(keyword=k, rank=None, source=None))
            missing += 1
            continue
        crawled += 1
        try:
            rk = int(getattr(r, "rank", 0) or 0)
        except Exception:
            rk = 0
        if rk > 0:
            found += 1
        else:
            missing += 1
        items.append(ManualKeywordsCrawlTodayItem(keyword=k, rank=rk, source=str(getattr(r, "source", None) or None)))

    return ManualKeywordsCrawlTodayResponse(
        product_url=seed,
        target_date=d.strftime("%Y-%m-%d"),
        total_keywords=len(keywords),
        crawled_keywords=crawled,
        found_keywords=found,
        missing_keywords=missing,
        items=items,
    )


@app.post("/search-rank/manual-keywords/import", response_model=ManualKeywordsImportResponse)
def import_manual_keywords(
    payload: ManualKeywordsImportRequest,
    db: Session = Depends(get_db),
):
    """
    수기 키워드(후보) + 월검색량을 저장한다.
    - 저장은 `tracked_product_manual_keyword`에 upsert한다.
    """
    # smartstore URL은 query/hash가 붙어도 동일 상품으로 취급되어야 하므로, 저장 시엔 canonical(base)로 정규화한다.
    raw_url = str(getattr(payload, "product_url", "") or "").strip()
    product_url = _canonicalize_smartstore_base_url(raw_url)
    if not product_url:
        raise HTTPException(status_code=400, detail="product_url is required")

    mode = str(getattr(payload, "mode", "replace") or "replace").strip().lower()
    if mode not in ("replace", "append"):
        mode = "replace"

    items_raw = getattr(payload, "items", None) or []
    norm_items: list[tuple[str, int | None, str | None]] = []
    for it in items_raw:
        kw = str(getattr(it, "keyword", "") or "").strip()
        if not kw:
            continue
        v = getattr(it, "monthly_search_volume", None)
        label = getattr(it, "monthly_search_volume_label", None)
        vol: int | None = None
        if v is not None:
            try:
                vol = int(v)
                if vol < 0:
                    vol = None
            except Exception:
                vol = None
        lab = str(label).strip() if label is not None and str(label).strip() else None
        norm_items.append((kw, vol, lab))

    # dedupe(키워드 중복 시 마지막 값 유지)
    dedup: dict[str, tuple[int | None, str | None]] = {}
    for kw, vol, lab in norm_items:
        dedup[kw] = (vol, lab)

    if mode == "replace":
        # 기존 active 모두 비활성화
        # - URL 쿼리스트링/NaPm 등으로 product_url이 달라질 수 있으므로 productId 기반 like도 함께 비활성화한다.
        filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=product_url)
        db.query(TrackedProductManualKeyword).filter(
            or_(*filters),
            TrackedProductManualKeyword.is_active.is_(True),
        ).update({"is_active": False}, synchronize_session=False)

    saved = 0
    now = datetime.utcnow()
    for kw, (vol, lab) in dedup.items():
        row = TrackedProductManualKeyword(
            product_url=product_url,
            keyword=kw,
            monthly_search_volume=vol,
            monthly_search_volume_label=lab,
            is_active=True,
            updated_at=now,
        )
        db.merge(row)
        saved += 1

    db.commit()
    # URL 정규화 차이(쿼리스트링 등)로 인해 exact match만 쓰면 "저장 후 0개"처럼 보일 수 있다.
    # 조회/수집 판정과 동일하게 안전 필터를 사용한다.
    filters2 = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=product_url)
    total_active = (
        db.query(TrackedProductManualKeyword)
        .filter(or_(*filters2), TrackedProductManualKeyword.is_active.is_(True))
        .count()
    )
    return ManualKeywordsImportResponse(saved=saved, total_active=int(total_active or 0))


@app.post("/search-rank/manual-keywords/delete-meta", response_model=ManualKeywordsMetaDeleteResponse)
def delete_manual_keyword_meta(
    payload: ManualKeywordsMetaDeleteRequest,
    db: Session = Depends(get_db),
):
    """
    수기 키워드(후보) 메타(월검색량) 리스트에서 선택 삭제.

    - `tracked_product_manual_keyword`에서 is_active=false 처리(순위 스냅샷은 건드리지 않음)
    - product_url 정규화 차이 대응을 위해 productId 기반 like 매칭도 함께 사용한다.
    """
    product_url = str(getattr(payload, "product_url", "") or "").strip()
    if not product_url:
        raise HTTPException(status_code=400, detail="product_url is required")

    keywords_raw = getattr(payload, "keywords", None) or []
    keywords = sorted({str(k or "").strip() for k in keywords_raw if str(k or "").strip()})
    if not keywords:
        return ManualKeywordsMetaDeleteResponse(deleted=0)

    filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=product_url)

    # 어떤 키워드가 실제로 매칭/삭제되었는지 반환(삭제 UX 디버깅용)
    matched_keywords: set[str] = set()
    try:
        rows = (
            db.query(TrackedProductManualKeyword.keyword)
            .filter(or_(*filters), TrackedProductManualKeyword.is_active.is_(True), TrackedProductManualKeyword.keyword.in_(keywords))
            .all()
        )
        for x in rows or []:
            k0 = str(x[0] or "").strip() if x else ""
            if k0:
                matched_keywords.add(k0)
    except Exception:
        matched_keywords = set()

    deleted = (
        db.query(TrackedProductManualKeyword)
        .filter(or_(*filters), TrackedProductManualKeyword.is_active.is_(True), TrackedProductManualKeyword.keyword.in_(keywords))
        .update({"is_active": False, "updated_at": datetime.utcnow()}, synchronize_session=False)
    )
    db.commit()
    deleted_cnt = int(deleted or 0)
    requested = [str(k) for k in keywords]
    deleted_list = sorted(list(matched_keywords))
    not_found = sorted([k for k in requested if k not in matched_keywords])
    return ManualKeywordsMetaDeleteResponse(
        deleted=deleted_cnt,
        requested_keywords=requested,
        deleted_keywords=deleted_list,
        not_found_keywords=not_found,
    )


@app.post("/search-rank/crawl/category/delete-today", response_model=CategoryCrawlTodayDeleteResponse)
def delete_category_crawl_today(
    payload: CategoryCrawlTodayDeleteRequest,
    db: Session = Depends(get_db),
):
    """
    오늘자(OpenAPI 기반, source='openapi') 수집 결과를 초기화한다.
    - 오매칭/차단 등으로 '오늘 데이터가 섞인 상태'를 빠르게 복구하기 위한 운영 기능.
    """
    urls_raw = getattr(payload, "product_urls", None) or []
    urls = [str(u or "").strip() for u in urls_raw if str(u or "").strip()]
    if not urls:
        raise HTTPException(status_code=400, detail="product_urls is required")

    d = getattr(payload, "target_date", None) or _today_kst()
    if isinstance(d, datetime):
        d = d.date()

    delete_filters: list[object] = []
    for u in urls:
        delete_filters.extend(_smartstore_product_url_filters(TrackedProductRankDaily, product_url=u))

    deleted = (
        db.query(TrackedProductRankDaily)
        .filter(
            TrackedProductRankDaily.date == d,
            TrackedProductRankDaily.source == "openapi",
            or_(*delete_filters),
        )
        .delete(synchronize_session=False)
    )
    db.commit()
    return CategoryCrawlTodayDeleteResponse(deleted=int(deleted or 0))


@app.post("/search-rank/manual-keywords/apply", response_model=ManualKeywordsApplyResponse)
def apply_manual_keywords_to_products(
    payload: ManualKeywordsApplyRequest,
    db: Session = Depends(get_db),
):
    """
    기준 상품(source)의 수기 키워드(월검색량) 목록을 대상 상품들에 동일하게 적용한다.
    - 대상 상품의 기존 active 수기 키워드는 비활성화(replace) 후, source 목록을 활성 upsert 한다.
    """
    src = str(getattr(payload, "source_product_url", "") or "").strip()
    targets_raw = getattr(payload, "target_product_urls", None) or []
    targets = [str(u or "").strip() for u in targets_raw if str(u or "").strip()]
    # 중복 제거 + source 제외
    targets = sorted({u for u in targets if u and u != src})
    if not src:
        raise HTTPException(status_code=400, detail="source_product_url is required")
    if not targets:
        return ManualKeywordsApplyResponse(applied_products=0, keywords=0)

    # source 목록 조회
    src_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=src)
    src_rows = (
        db.query(TrackedProductManualKeyword)
        .filter(or_(*src_filters), TrackedProductManualKeyword.is_active.is_(True))
        .order_by(TrackedProductManualKeyword.keyword.asc())
        .all()
    )
    if not src_rows:
        return ManualKeywordsApplyResponse(applied_products=0, keywords=0)

    dedup: dict[str, tuple[int | None, str | None]] = {}
    for r in src_rows:
        kw = str(getattr(r, "keyword", "") or "").strip()
        if not kw:
            continue
        dedup[kw] = (
            getattr(r, "monthly_search_volume", None),
            getattr(r, "monthly_search_volume_label", None),
        )
    if not dedup:
        return ManualKeywordsApplyResponse(applied_products=0, keywords=0)

    now = datetime.utcnow()
    applied = 0
    for t in targets:
        filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=t)
        # 기존 active 비활성화
        db.query(TrackedProductManualKeyword).filter(or_(*filters), TrackedProductManualKeyword.is_active.is_(True)).update(
            {"is_active": False, "updated_at": now},
            synchronize_session=False,
        )
        # source 목록 upsert
        for kw, (vol, lab) in dedup.items():
            row = TrackedProductManualKeyword(
                product_url=t,
                keyword=kw,
                monthly_search_volume=vol,
                monthly_search_volume_label=(str(lab).strip() if lab is not None and str(lab).strip() else None),
                is_active=True,
                updated_at=now,
            )
            db.merge(row)
        applied += 1

    db.commit()
    return ManualKeywordsApplyResponse(applied_products=applied, keywords=len(dedup))


def build_tracked_rank_history(rows: list[TrackedProductRankDaily]) -> ProductRankHistory:
    """
    `tracked_product_rank_daily` 행 리스트를
    메뉴4 '순위 변화' 화면에서 사용하기 좋은 구조로 집계한다.
    (키워드×일자 1셀 = 1행)
    """
    if not rows:
        return ProductRankHistory(dates=[], series=[])

    dates = sorted({r.date for r in rows})
    by_keyword: dict[str, dict[date, int]] = {}
    for r in rows:
        kw = (r.keyword or "").strip()
        if not kw:
            continue
        rk = int(getattr(r, "rank", 0) or 0)
        if rk <= 0:
            continue
        if kw not in by_keyword:
            by_keyword[kw] = {r.date: rk}
            continue
        cur = by_keyword[kw].get(r.date)
        if cur is None or rk < cur:
            by_keyword[kw][r.date] = rk

    series_list: list[ProductRankSeries] = []
    for kw, dm in sorted(by_keyword.items(), key=lambda item: item[0]):
        pts: list[ProductRankPoint] = []
        for d in dates:
            if d in dm:
                pts.append(ProductRankPoint(date=d, rank=dm[d]))
        if pts:
            series_list.append(ProductRankSeries(keyword=kw, series=pts))

    return ProductRankHistory(dates=dates, series=series_list)


def _rank_source_priority(source: object) -> int:
    s = str(source or "").strip().lower()
    if s == "excel":
        return 40
    if s == "text":
        return 30
    if s in {"crawl_category", "openapi"}:
        return 20
    return 0


def _rank_rows_to_map(rows) -> dict[str, dict[date, int]]:
    """
    (keyword, date) -> rank 로 정규화한다.
    - 동일 키워드/일자에 여러 값이 들어오면 더 좋은 순위(작은 값)를 채택한다.
    - rank <= 0 은 무시한다.
    """
    by_keyword: dict[str, dict[date, int]] = {}
    by_priority: dict[str, dict[date, int]] = {}
    for r in rows or []:
        kw = (getattr(r, "keyword", None) or "").strip()
        if not kw:
            continue
        d = getattr(r, "date", None)
        if not isinstance(d, date):
            continue
        try:
            rk = int(getattr(r, "rank", 0) or 0)
        except Exception:
            rk = 0
        if rk <= 0:
            continue
        priority = _rank_source_priority(getattr(r, "source", None))
        if kw not in by_keyword:
            by_keyword[kw] = {d: rk}
            by_priority[kw] = {d: priority}
            continue
        cur = by_keyword[kw].get(d)
        cur_priority = by_priority.get(kw, {}).get(d, -1)
        if cur is None or priority > cur_priority or (priority == cur_priority and rk < cur):
            by_keyword[kw][d] = rk
            by_priority.setdefault(kw, {})[d] = priority
    return by_keyword


def _rank_map_to_history(by_keyword: dict[str, dict[date, int]]) -> ProductRankHistory:
    if not by_keyword:
        return ProductRankHistory(dates=[], series=[])
    dates = sorted({d for dm in by_keyword.values() for d in dm.keys()})
    series_list: list[ProductRankSeries] = []
    for kw in sorted(by_keyword.keys()):
        dm = by_keyword.get(kw) or {}
        pts: list[ProductRankPoint] = []
        for d in dates:
            if d in dm:
                pts.append(ProductRankPoint(date=d, rank=dm[d]))
        if pts:
            series_list.append(ProductRankSeries(keyword=kw, series=pts))
    return ProductRankHistory(dates=dates, series=series_list)


def build_merged_rank_history(
    *,
    tracked_rows: list[TrackedProductRankDaily] | None,
    openapi_rows: list[NaverProductRankDaily] | None,
) -> ProductRankHistory:
    """
    '내 상품 추적' 상세 화면에서 사용하는 병합 정책.

    - tracked_rows(공식 엑셀 업로드)가 있으면 해당 값을 최우선으로 사용
    - 다만 tracked_rows는 "부분 기간"일 수 있으므로,
      openapi_rows(네이버 쇼핑 OpenAPI 스냅샷)로 빈 날짜를 보완한다.
    """
    m_open = _rank_rows_to_map(openapi_rows or [])
    m_tracked = _rank_rows_to_map(tracked_rows or [])

    # tracked 우선(override)
    merged: dict[str, dict[date, int]] = {}
    for kw, dm in m_open.items():
        merged[kw] = dict(dm)
    for kw, dm in m_tracked.items():
        if kw not in merged:
            merged[kw] = dict(dm)
        else:
            merged[kw].update(dm)

    return _rank_map_to_history(merged)


@app.post("/search-rank/ranks/import", response_model=TrackedRankUploadResponse)
def import_tracked_ranks_from_excel(
    payload: TrackedRankUploadRequest,
    db: Session = Depends(get_db),
):
    """
    공식 사이트 엑셀 업로드 결과(키워드·일자·순위)를 DB에 저장한다.

    정책:
    - 전체 키워드 풀: `tracked_product_manual_keyword` (PK: product_url+keyword)
    - 순위 스냅샷: `tracked_product_rank_daily` (PK: date+product_url+keyword)
    - 엑셀 업로드는 추적 키워드 정의(`tracked_product_keyword`)를 직접 변경하지 않는다.
      집중단계 추적 키워드는 광고/구매 조건 계산 후 `tracked_product_auto_keyword`로 별도 반영된다.
    """
    product_url_raw = (payload.product_url or "").strip()
    if not product_url_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    product_url = _canonicalize_smartstore_base_url(product_url_raw) or product_url_raw

    # keyword_meta(검색량) 맵 구성
    meta_map: dict[str, int] = {}
    try:
        for m in (getattr(payload, "keyword_meta", None) or []):
            kw = str(m.get("keyword") or "").strip()
            if not kw:
                continue
            v = m.get("monthly_search_volume")
            if v is None:
                continue
            try:
                iv = int(v)
            except Exception:
                continue
            if iv > 0:
                meta_map[kw] = iv
    except Exception:
        meta_map = {}

    # 1) 입력 정리
    # 같은 파일 안에 동일 셀(date+product_url+keyword)이 반복될 수 있다.
    # Postgres는 동일 bulk statement 안의 중복 PK를 허용하지 않으므로 먼저 접는다.
    normalized_by_key: dict[tuple[date, str], int] = {}
    for it in payload.items or []:
        kw = (it.keyword or "").strip()
        if not kw:
            continue
        rk = int(it.rank or 0)
        if rk < 0:
            continue
        normalized_by_key[(it.date, kw)] = rk
    normalized_items = [(kw, d, rk) for (d, kw), rk in normalized_by_key.items()]

    if not normalized_items:
        return TrackedRankUploadResponse(saved=0, added_keywords=[])

    # 2) 업로드된 키워드는 "전체 후보 키워드 풀"에 먼저 저장한다.
    #    기존 정책처럼 추적 키워드 미등록 여부로 업로드를 막지 않는다.
    mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=product_url)
    incoming_set = {kw for (kw, _, _) in normalized_items}
    manual_existing_rows = (
        db.query(TrackedProductManualKeyword)
        .filter(
            or_(*mk_filters),
            TrackedProductManualKeyword.keyword.in_(incoming_set),
        )
        .all()
    )
    manual_existing_by_kw = {
        str(r.keyword or "").strip(): r
        for r in manual_existing_rows
        if str(r.keyword or "").strip()
    }
    added_keywords: list[str] = []
    now = datetime.utcnow()
    for kw in sorted(incoming_set):
        row = manual_existing_by_kw.get(kw)
        was_active = bool(getattr(row, "is_active", False)) if row is not None else False
        if row is None:
            row = TrackedProductManualKeyword(product_url=product_url, keyword=kw)
            added_keywords.append(kw)
        elif not was_active:
            added_keywords.append(kw)
        row.product_url = product_url
        row.keyword = kw
        row.is_active = True
        row.updated_at = now
        if kw in meta_map:
            try:
                row.monthly_search_volume = int(meta_map[kw])
            except Exception:
                pass
        db.merge(row)
    db.commit()

    # 3) 순위 데이터 upsert (PK: date + product_url + keyword)
    uploaded_at = datetime.utcnow()
    records = [
        {
            "date": d,
            "product_url": product_url,
            "keyword": kw,
            "rank": rk,
            "source": "excel",
            "updated_at": uploaded_at,
        }
        for (kw, d, rk) in normalized_items
    ]
    stmt = insert(TrackedProductRankDaily).values(records)
    upsert_stmt = stmt.on_conflict_do_update(
        index_elements=[
            TrackedProductRankDaily.date,
            TrackedProductRankDaily.product_url,
            TrackedProductRankDaily.keyword,
        ],
        set_={
            "rank": stmt.excluded.rank,
            "source": stmt.excluded.source,
            "updated_at": stmt.excluded.updated_at,
        },
    )
    db.execute(upsert_stmt)
    db.commit()
    return TrackedRankUploadResponse(saved=len(records), added_keywords=added_keywords)


def _parse_rank_text_pairs(text: str) -> list[tuple[str, int]]:
    """
    사용자가 붙여넣는 텍스트에서 (keyword, rank)를 추출한다.
    예: "부드러운머릿결저자극염색약 / 1위\t두피영양새치 / 198위 ..."
    - 구분: 줄바꿈/탭/복수 공백 혼용 가능
    - 형식: "<키워드> / <숫자>위"
    """
    s = str(text or "")
    # 1) 우선 탭/개행 기준으로 쪼갠 뒤, 각 조각에서 패턴 매칭
    parts = re.split(r"[\t\r\n]+", s)
    out: dict[str, int] = {}
    pat = re.compile(r"^\s*(.+?)\s*/\s*(\d+)\s*위\s*$")
    for p in parts:
        p = (p or "").strip()
        if not p:
            continue
        m = pat.match(p)
        if not m:
            # 일부 사용자는 한 줄에 여러 항목을 공백으로 붙일 수 있어, fallback으로 finditer 수행
            for mm in re.finditer(r"(.+?)\s*/\s*(\d+)\s*위", p):
                kw = (mm.group(1) or "").strip()
                rk = int(mm.group(2) or 0)
                if not kw or rk <= 0:
                    continue
                cur = out.get(kw)
                if cur is None or rk < cur:
                    out[kw] = rk
            continue
        kw = (m.group(1) or "").strip()
        rk = int(m.group(2) or 0)
        if not kw or rk <= 0:
            continue
        cur = out.get(kw)
        # 동일 키워드가 여러 번 있으면 더 좋은 순위(작은 값) 채택
        if cur is None or rk < cur:
            out[kw] = rk
    return [(k, out[k]) for k in sorted(out.keys())]


def _today_kst_date_str() -> str:
    return _today_kst().strftime("%Y-%m-%d")


@app.post("/search-rank/ranks/import-text", response_model=TrackedRankTextImportResponse)
def import_tracked_ranks_from_text(
    payload: TrackedRankTextImportRequest,
    db: Session = Depends(get_db),
):
    """
    상세 화면 하단에서 사용자가 붙여넣는 '키워드 / n위' 텍스트를
    tracked_product_rank_daily에 저장한다.

    정책:
    - 키워드가 추적 키워드가 아니어도 저장은 허용한다(수기 입력 키워드는 크롤링 대상이 아님).
    - 저장은 tracked_product_rank_daily에 upsert하며 source='text'로 표기한다.
    - (완료 판정) 추적 키워드가 모두 포함되어 저장되었으면 is_tracked_complete=true 반환.
    """
    product_url = (payload.product_url or "").strip()
    if not product_url:
        raise HTTPException(status_code=400, detail="product_url is required")

    pairs = _parse_rank_text_pairs(payload.text)
    if not pairs:
        return TrackedRankTextImportResponse(
            saved=0,
            date=(payload.target_date.strftime("%Y-%m-%d") if payload.target_date else _today_kst_date_str()),
            tracked_keywords_total=0,
            tracked_keywords_covered=0,
            is_tracked_complete=False,
            missing_tracked_keywords=[],
        )

    d = payload.target_date if payload.target_date is not None else _today_kst()

    saved = 0
    for (kw, rk) in pairs:
        obj = TrackedProductRankDaily(
            date=d,
            product_url=product_url,
            keyword=kw,
            rank=int(rk),
            source="text",
        )
        if hasattr(db, "merge"):
            db.merge(obj)  # type: ignore[attr-defined]
        else:
            db.add(obj)
        saved += 1
    db.commit()

    # 완료 판정: 해당 상품의 추적 키워드가 모두 (오늘 날짜에) 저장되어 있는지 확인
    existing = (
        db.query(TrackedProductKeyword)
        .filter(
            TrackedProductKeyword.is_active.is_(True),
            TrackedProductKeyword.product_url == product_url,
        )
        .order_by(TrackedProductKeyword.created_at.asc())
        .all()
    )
    tracked = sorted({str(r.keyword or "").strip() for r in existing if str(r.keyword or "").strip()})
    tracked_total = len(tracked)
    covered = 0
    missing: list[str] = []
    incoming_map = {kw: rk for (kw, rk) in pairs}
    for kw in tracked:
        if kw in incoming_map and int(incoming_map[kw] or 0) > 0:
            covered += 1
        else:
            missing.append(kw)

    is_complete = tracked_total > 0 and covered == tracked_total
    return TrackedRankTextImportResponse(
        saved=saved,
        date=d.strftime("%Y-%m-%d"),
        tracked_keywords_total=tracked_total,
        tracked_keywords_covered=covered,
        is_tracked_complete=is_complete,
        missing_tracked_keywords=missing,
    )


@app.post("/search-rank/keyword-volumes", response_model=list[KeywordVolumeItem])
def get_keyword_monthly_volumes(
    payload: KeywordVolumesRequest,
):
    """
    SearchAd keywordstool 기반으로 키워드 월검색량(PC+Mobile)을 조회한다.
    - 대량(최대 수백개) 입력을 고려해 서버에서 chunking하여 호출한다.
    """
    kws = [str(k or "").strip() for k in (payload.keywords or [])]
    kws = [k for k in kws if k]
    if not kws:
        return []

    global KW_METRICS_COOLDOWN_UNTIL

    # NOTE:
    # - keywordstool(hintKeywords=콤마 join) 결과에는 "입력 키워드 자체"가 누락되는 경우가 있어
    #   (특히 100개+ 대량 입력 시) 입력 키워드의 월검색량이 모두 0으로 보일 수 있다.
    # - 따라서 1) 캐시(12h) 우선 2) hint_many로 빠른 경로 3) 누락 키워드만 단건 fallback 으로 보강한다.

    # 1) 캐시
    now = time.time()
    cached_total: dict[str, int] = {}
    cached_label: dict[str, str] = {}
    to_fetch: list[str] = []
    with KW_METRICS_LOCK:
        for k in kws:
            ent = KW_METRICS_CACHE.get(k)
            try:
                ts = float(ent.get("ts")) if isinstance(ent, dict) and ent.get("ts") is not None else None
            except Exception:
                ts = None
            if ts is not None and (now - ts) <= float(KW_METRICS_TTL_SEC):
                metric = ent.get("metric") if isinstance(ent, dict) else None
                label = (metric or {}).get("totalSearchLabel") if isinstance(metric, dict) else None
                if label is not None and str(label).strip():
                    cached_label[k] = str(label).strip()
                else:
                    try:
                        total = int((metric or {}).get("totalSearch") or 0)
                    except Exception:
                        total = 0
                    cached_total[k] = total
            else:
                to_fetch.append(k)

    def _total_label_from_flags(pc_v: int | None, mo_v: int | None, pc_lt: bool, mo_lt: bool) -> tuple[int | None, str | None]:
        # 둘 다 확정값이면 합계 숫자
        if not pc_lt and not mo_lt and pc_v is not None and mo_v is not None:
            return (int(pc_v) + int(mo_v), None)
        # 둘 다 <10 → total <20
        if pc_lt and mo_lt:
            return (None, "<20")
        # 한쪽만 <10 → total < (확정값 + 10)
        if pc_lt and (mo_v is not None) and not mo_lt:
            return (None, f"<{int(mo_v) + 10}")
        if mo_lt and (pc_v is not None) and not pc_lt:
            return (None, f"<{int(pc_v) + 10}")
        return (None, None)

    # 2) 빠른 경로: hint_many (5개 단위) → 입력 키워드(relKeyword==k)만 반영
    fetched_total: dict[str, int] = {}
    fetched_label: dict[str, str] = {}
    cooldown_hit = False
    batch_size = 5
    requested = set(to_fetch)
    for i in range(0, len(to_fetch), batch_size):
        chunk = to_fetch[i : i + batch_size]
        rows, err = _searchad_keywordstool_hint_many(chunk)
        # 429면 무리하게 추가 호출하지 않는다(쿨다운 악화 방지)
        if err and "429" in str(err):
            with KW_METRICS_LOCK:
                KW_METRICS_COOLDOWN_UNTIL = time.time() + 120.0
            cooldown_hit = True
            break
        for r in rows or []:
            if not isinstance(r, dict):
                continue
            kw = str(r.get("relKeyword") or "").strip()
            if not kw or kw not in requested:
                continue
            pc_lt = bool(r.get("monthlyPcQcCntIsLt"))
            mo_lt = bool(r.get("monthlyMobileQcCntIsLt"))
            pc_v = r.get("monthlyPcQcCnt")
            mo_v = r.get("monthlyMobileQcCnt")
            try:
                pc_v = int(pc_v) if pc_v is not None else None
            except Exception:
                pc_v = None
            try:
                mo_v = int(mo_v) if mo_v is not None else None
            except Exception:
                mo_v = None

            total, label = _total_label_from_flags(pc_v, mo_v, pc_lt, mo_lt)
            if total is not None:
                fetched_total[kw] = int(total)
            elif label:
                fetched_label[kw] = str(label)
            # 캐시 저장
            with KW_METRICS_LOCK:
                KW_METRICS_CACHE[kw] = {
                    "metric": {
                        "pcSearch": pc_v if not pc_lt else None,
                        "mobileSearch": mo_v if not mo_lt else None,
                        "totalSearch": int(total) if total is not None else None,
                        "totalSearchLabel": label,
                        "pcCtr": r.get("monthlyAvePcCtr"),
                        "mobileCtr": r.get("monthlyAveMobileCtr"),
                        "avgCtr": r.get("avgCtr"),
                    },
                    "ts": time.time(),
                    "fetchedAt": datetime.utcnow().isoformat() + "Z",
                }

    # 3) 누락 보강: 단건 호출로 "정확히 동일 키워드" 행을 찾아 totalSearch 산출
    # - 대량 입력(100~200)에서는 단건을 모두 치면 429가 쉽게 발생하므로 상한을 둔다.
    remaining = [k for k in to_fetch if k not in fetched_total]
    # 입력이 100~200개까지 올 수 있어, 누락 보강을 너무 낮게 잡으면
    # "20개만 조회됨"처럼 보일 수 있다. (단, 429 시 즉시 중단)
    max_single_fallback = 200
    remaining = remaining[:max_single_fallback]
    for k in remaining:
        # 전역 쿨다운이면 더 이상 외부 호출하지 않는다.
        with KW_METRICS_LOCK:
            cooldown_until = float(KW_METRICS_COOLDOWN_UNTIL or 0.0)
        if time.time() < cooldown_until:
            cooldown_hit = True
            break
        # 과도한 폭주 방지(429 완화): 단건 호출 사이에 짧게 쉬어준다.
        try:
            time.sleep(0.03)
        except Exception:
            pass
        rows, err = _searchad_keywordstool(k)
        if err and "429" in str(err):
            with KW_METRICS_LOCK:
                KW_METRICS_COOLDOWN_UNTIL = time.time() + 120.0
            cooldown_hit = True
            break
        # keywordstool 결과에서 입력 키워드와 정확히 같은 relKeyword를 찾는다.
        exact = None
        for r in rows or []:
            try:
                if str(r.get("relKeyword") or "").strip() == k:
                    exact = r
                    break
            except Exception:
                continue
        if exact is None:
            # SearchAd가 해당 키워드의 정확 행을 주지 않는 케이스(연관키워드만 반환) → UI에 원인 표기
            fetched_label[k] = "미매칭"
            continue

        pc_lt = bool((exact or {}).get("monthlyPcQcCntIsLt")) if isinstance(exact, dict) else False
        mo_lt = bool((exact or {}).get("monthlyMobileQcCntIsLt")) if isinstance(exact, dict) else False
        pc_v = (exact or {}).get("monthlyPcQcCnt") if isinstance(exact, dict) else None
        mo_v = (exact or {}).get("monthlyMobileQcCnt") if isinstance(exact, dict) else None
        try:
            pc_v = int(pc_v) if pc_v is not None else None
        except Exception:
            pc_v = None
        try:
            mo_v = int(mo_v) if mo_v is not None else None
        except Exception:
            mo_v = None

        total, label = _total_label_from_flags(pc_v, mo_v, pc_lt, mo_lt)
        if total is not None:
            fetched_total[k] = int(total)
        elif label:
            fetched_label[k] = str(label)
        with KW_METRICS_LOCK:
            KW_METRICS_CACHE[k] = {
                "metric": {
                    "pcSearch": pc_v if not pc_lt else None,
                    "mobileSearch": mo_v if not mo_lt else None,
                    "totalSearch": int(total) if total is not None else None,
                    "totalSearchLabel": label,
                    "pcCtr": (exact or {}).get("monthlyAvePcCtr") if isinstance(exact, dict) else None,
                    "mobileCtr": (exact or {}).get("monthlyAveMobileCtr") if isinstance(exact, dict) else None,
                    "avgCtr": (exact or {}).get("avgCtr") if isinstance(exact, dict) else None,
                },
                "ts": time.time(),
                "fetchedAt": datetime.utcnow().isoformat() + "Z",
            }

    out: list[KeywordVolumeItem] = []
    for k in kws:
        if k in cached_label:
            out.append(KeywordVolumeItem(keyword=k, monthly_search_volume=None, monthly_search_volume_label=str(cached_label[k])))
        elif k in cached_total:
            out.append(KeywordVolumeItem(keyword=k, monthly_search_volume=int(cached_total[k] or 0)))
        elif k in fetched_total:
            out.append(KeywordVolumeItem(keyword=k, monthly_search_volume=int(fetched_total[k] or 0)))
        elif k in fetched_label:
            out.append(KeywordVolumeItem(keyword=k, monthly_search_volume=None, monthly_search_volume_label=str(fetched_label[k])))
        else:
            # 남은 미집계: 쿨다운이면 원인 표기, 아니면 미집계로 표시
            if cooldown_hit:
                out.append(KeywordVolumeItem(keyword=k, monthly_search_volume=None, monthly_search_volume_label="쿨다운"))
            else:
                out.append(KeywordVolumeItem(keyword=k, monthly_search_volume=None, monthly_search_volume_label="미집계"))
    return out


@app.get("/search-rank/product-summary", response_model=ProductSummary)
def get_product_summary(
    keyword: str = Query(..., description="상품을 대표하는 검색 키워드"),
    product_url: Optional[str] = Query(
        None, description="스마트스토어 상품 URL (productId 매칭용, 선택)"
    ),
    db: Session = Depends(get_db),
):
    """
    특정 키워드에 대해 **자사 브랜드(is_our_brand=True)** 상품의 최신 스냅샷을 기준으로
    상세 화면 상단에 표시할 상품 메타 정보를 반환한다.

    - 소스 테이블: `naver_product_rank_daily`
    - 정렬: date DESC, rank ASC (가장 최근 날짜 + 가장 좋은 순위 1건)
    """

    # (선택) product_url 이 주어지면 **해당 상품**만 반환해야 한다.
    # - SmartStore URL(/products/<id>)의 숫자는 "몰상품ID" 계열이고,
    #   OpenAPI `naver_product_rank_daily.product_id`는 "쇼핑 카탈로그 productId" 계열이다.
    # - 과거 로직처럼 SmartStore productId를 그대로 rank_daily.product_id에 매칭하면
    #   우연히 같은 숫자를 가진 "다른 상품"이 매칭되어 가격/리뷰가 섞이는 치명적 오염이 발생할 수 있다.
    # - 따라서 SmartStore URL은 tracked_product_meta.product_id_catalog(=카탈로그 ID)를 통해서만 매칭한다.
    row: Optional[NaverProductRankDaily] = None
    pid_int: int | None = None
    if product_url:
        try:
            parsed = urlparse(str(product_url))
            is_smartstore = str(parsed.netloc or "").lower().endswith("smartstore.naver.com")
        except Exception:
            is_smartstore = False

        if is_smartstore:
            base_url = _canonicalize_smartstore_base_url(product_url)
            meta: TrackedProductMeta | None = (
                db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url == base_url).one_or_none()
            )
            if meta is not None and getattr(meta, "product_id_catalog", None) is not None:
                try:
                    pid_int = int(meta.product_id_catalog)
                except Exception:
                    pid_int = None
        else:
            # 비 smartstore URL은 기존 productId 추출 로직을 유지한다(카탈로그/링크 기반).
            product_id = _extract_product_id_from_url(product_url)
            if product_id is not None:
                try:
                    pid_int = int(product_id)
                except ValueError:
                    pid_int = None

        if pid_int is not None:
            row = (
                db.query(NaverProductRankDaily)
                .filter(NaverProductRankDaily.product_id == pid_int)
                .order_by(
                    NaverProductRankDaily.date.desc(),
                    NaverProductRankDaily.rank.asc(),
                )
                .limit(1)
                .one_or_none()
            )
        # IMPORTANT:
        # - product_url 이 주어진 경우, "해당 상품"을 못 찾았다고 해서
        #   키워드 상위 1개(다른 상품)로 대체하면 UI가 오염된다.
        # - 따라서 product_url 기반 조회가 실패하면 기본값을 반환한다.
        if row is None:
            inferred = _infer_smartstore_mall_name(product_url)
            fallback_title = ""
            return ProductSummary(
                keyword=keyword,
                # 구조적 원칙:
                # - URL 기준으로 해당 상품을 찾지 못했으면 "대표 키워드"를 상품명처럼 노출하지 않는다.
                # - ProductSummary 스키마는 문자열을 요구하므로 빈 문자열로 내려 UI가 URL/메타 fallback을 쓰게 한다.
                product_title=fallback_title,
                mall_name=inferred or "",
                price=0,
                purchase_cnt=0,
                product_id=None,
                image_url=None,
                category_path=None,
                brand=None,
                maker=None,
            )

    # 1차: 위에서 product_id 기반으로 찾지 못했으면 자사 브랜드(is_our_brand=True) 기준으로 조회
    if row is None:
        row = (
            db.query(NaverProductRankDaily)
            .filter(
                NaverProductRankDaily.keyword == keyword,
                NaverProductRankDaily.is_our_brand.is_(True),
            )
            .order_by(
                NaverProductRankDaily.date.desc(),
                NaverProductRankDaily.rank.asc(),
            )
            .limit(1)
            .one_or_none()
        )

    # 2차: 자사 브랜드 데이터가 없으면, 동일 키워드의 모든 상품 중 최신/최상위 순위 1건을 사용
    if row is None:
        row = (
            db.query(NaverProductRankDaily)
            .filter(NaverProductRankDaily.keyword == keyword)
            .order_by(
                NaverProductRankDaily.date.desc(),
                NaverProductRankDaily.rank.asc(),
            )
            .limit(1)
            .one_or_none()
        )

    if row is None:
        # 랭킹 스냅샷이 완전히 없으면 404 대신 기본값을 반환해 UI 에러를 피한다.
        return ProductSummary(
            keyword=keyword,
            product_title=keyword,
            mall_name="",
            price=0,
            purchase_cnt=0,
            product_id=None,
            image_url=None,
            category_path=None,
            brand=None,
            maker=None,
        )

    # 카테고리 경로 문자열 생성 (category1 > category2 > ...)
    categories = []
    for attr in ("category1", "category2", "category3", "category4"):
        if hasattr(row, attr):
            val = getattr(row, attr)
            if val:
                categories.append(val)
    category_path = " > ".join(categories) if categories else None

    return ProductSummary(
        keyword=keyword,
        product_title=str(row.product_title or "").strip(),
        mall_name=str(row.mall_name or "").strip(),
        price=int(row.price or 0),
        purchase_cnt=int(row.purchase_cnt or 0),
        product_id=getattr(row, "product_id", None),
        image_url=getattr(row, "image_url", None),
        category_path=category_path,
        brand=getattr(row, "brand", None),
        maker=getattr(row, "maker", None),
    )


@app.post("/search-rank/product-summary/batch", response_model=Dict[str, Optional[ProductSummary]])
def get_product_summary_batch(
    req: ProductSummaryBatchRequest = Body(...),
    db: Session = Depends(get_db),
):
    """
    내 상품 추적(리스트) 진입 성능 개선을 위한 배치 조회.
    - id -> ProductSummary 매핑을 반환
    """
    out: Dict[str, Optional[ProductSummary]] = {}
    for it in (req.items or []):
        try:
            pid = str(getattr(it, "id", "") or "").strip()
            kw = str(getattr(it, "keyword", "") or "").strip()
            url = str(getattr(it, "product_url", "") or "").strip()
            if not pid:
                continue
            if not kw:
                out[pid] = None
                continue
            out[pid] = get_product_summary(keyword=kw, product_url=(url or None), db=db)
        except Exception:
            try:
                if getattr(it, "id", None):
                    out[str(getattr(it, "id"))] = None
            except Exception:
                pass
    return out


def _extract_meta(html_text: str, prop: str) -> Optional[str]:
    """
    매우 단순한 정규식 기반 메타 태그 추출 유틸리티.

    - property="og:image", content="..." 와 같은 패턴을 찾아 content 값을 반환한다.
    """

    pattern = re.compile(
        r'<meta[^>]+property=[\'"]' + re.escape(prop) + r'[\'"][^>]*content=[\'"]([^\'"]+)[\'"]',
        re.IGNORECASE,
    )
    m = pattern.search(html_text)
    if not m:
        return None
    return html.unescape(m.group(1))


def _strip_html_tags(value: str | None) -> str | None:
    """
    쇼핑 검색 API의 title 필드는 <b> 태그 등 HTML이 섞여 있으므로
    간단한 정규식으로 태그를 제거하고 HTML 엔티티를 디코딩한다.
    """
    if not value:
        return None
    # 태그 제거
    no_tags = re.sub(r"<[^>]+>", "", value)
    # HTML 엔티티 디코드
    return html.unescape(no_tags).strip() or None


def _extract_product_id_from_url(url: str | None) -> Optional[str]:
    """
    스마트스토어 상품 URL 에서 productId 를 추출한다.

    예) https://smartstore.naver.com/thesujata/products/11043833896 → "11043833896"
    """
    if not url:
        return None
    u = str(url or "").strip()
    if not u:
        return None
    try:
        parsed = urlparse(u)
        host = str(parsed.netloc or "").lower()
        path = str(parsed.path or "")
    except Exception:
        return None

    # 1) smartstore canonical: /<mall>/products/<digits>
    m = re.search(r"/products/([0-9]{5,})", path)
    if m:
        return m.group(1)

    # 2) fallback은 smartstore 도메인에서만 허용(그 외 URL의 숫자(catalogId 등)를 productId로 오인 방지)
    if "smartstore.naver.com" not in host:
        return None

    parts = [p for p in path.split("/") if p]
    if not parts:
        return None
    last = parts[-1]
    return last if last.isdigit() else None


def _extract_product_id_path_only(url: str | None) -> Optional[str]:
    """
    스마트스토어 상품 URL에서 productId를 **path 기준으로만** 추출한다.

    배경:
    - querystring 안에 다른 URL(originUrl=...)이 포함될 수 있다.
    - 전체 문자열에서 /products/<id>를 찾으면 "다른 상품 id"를 잘못 추출할 수 있어
      메타/요약/삭제 필터가 엉뚱한 상품으로 튀는 치명적 문제가 생긴다.
    """
    if not url:
        return None
    u = str(url or "").strip()
    if not u:
        return None
    try:
        parsed = urlparse(u)
        path = str(parsed.path or "")
    except Exception:
        path = ""
    base = path if path else u
    m = re.search(r"/products/([0-9]{5,})", base)
    if m:
        return m.group(1)
    return None


def _extract_ranked_product_ids_from_shopping_api_response(data: object) -> list[str]:
    """
    /api/search/all 응답(JSON)에서 "상품 ID"를 랭킹 순서대로 추출한다.
    - 우선순위: mallProductId -> productId -> link(/products/<id>만 인정)
    - 목적: 링크/카탈로그ID 혼선으로 인한 '오매칭'을 구조적으로 차단
    """
    def looks_like_product(d: dict) -> bool:
        title_ok = False
        for k in ("productTitle", "productName", "mallProductTitle", "title", "name"):
            v = d.get(k)
            if isinstance(v, str) and v.strip():
                title_ok = True
                break
        if not title_ok:
            return False
        id_ok = bool(d.get("mallProductId") or d.get("productId"))
        url_ok = False
        for k in ("mallProductUrl", "productUrl", "link", "url"):
            v = d.get(k)
            if isinstance(v, str) and v.strip().startswith("http"):
                url_ok = True
                break
        it = d.get("item")
        if (not url_ok) and isinstance(it, dict):
            for k in ("mallProductUrl", "productUrl", "link", "url"):
                v = it.get(k)
                if isinstance(v, str) and v.strip().startswith("http"):
                    url_ok = True
                    break
        return bool(id_ok or url_ok)

    def pick_any_link(d: dict) -> str | None:
        for k in ("mallProductUrl", "productUrl", "link", "url"):
            v = d.get(k)
            if isinstance(v, str) and v.strip().startswith("http"):
                return v.strip()
        it = d.get("item")
        if isinstance(it, dict):
            for k in ("mallProductUrl", "productUrl", "link", "url"):
                v = it.get(k)
                if isinstance(v, str) and v.strip().startswith("http"):
                    return v.strip()
        return None

    def pick_id(d: dict) -> str | None:
        for k in ("mallProductId", "productId"):
            v = d.get(k)
            if isinstance(v, (int, str)):
                s = str(v).strip()
                if s.isdigit():
                    return s
        it = d.get("item")
        if isinstance(it, dict):
            for k in ("mallProductId", "productId"):
                v = it.get(k)
                if isinstance(v, (int, str)):
                    s = str(v).strip()
                    if s.isdigit():
                        return s
        # link fallback: only accept /products/<digits> (catalogId 오인 방지)
        link = pick_any_link(d)
        if link:
            pid = _canonical_product_id(link)
            if pid:
                return pid
        return None

    # 가장 '상품 리스트'로 보이는 list를 찾는다(상품-like dict 비율이 높은 리스트)
    best_list: list[dict] | None = None
    best_score = 0

    def walk(obj: object) -> None:
        nonlocal best_list, best_score
        if obj is None:
            return
        if isinstance(obj, list):
            prod_like = 0
            sample = obj[:120]
            for it in sample:
                if isinstance(it, dict) and looks_like_product(it):
                    prod_like += 1
            if prod_like > best_score:
                best_score = prod_like
                best_list = [it for it in obj if isinstance(it, dict)]
            for it in obj:
                walk(it)
            return
        if isinstance(obj, dict):
            for _k, v in obj.items():
                walk(v)

    walk(data)

    rows = best_list or []
    out: list[str] = []
    seen: set[str] = set()
    for d in rows:
        if not looks_like_product(d):
            continue
        pid = pick_id(d)
        if not pid:
            continue
        if pid in seen:
            continue
        seen.add(pid)
        out.append(pid)
    return out


def _extract_jsonld_objects(page_html: str) -> list[object]:
    """
    HTML 내 application/ld+json 스크립트를 찾아 JSON 객체(들)로 파싱한다.
    BeautifulSoup 없이도 동작하도록 정규식 기반으로 구현한다.
    """
    if not page_html:
        return []
    out: list[object] = []
    for m in re.finditer(
        r"<script[^>]*type=[\"']application/ld\+json[\"'][^>]*>(.*?)</script>",
        page_html,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        raw = (m.group(1) or "").strip()
        if not raw:
            continue
        try:
            parsed = json.loads(raw)
        except Exception:
            # 일부 페이지는 jsonld가 깨져있을 수 있음
            continue
        out.append(parsed)
    return out


def _extract_next_data(page_html: str) -> Optional[object]:
    """
    Next.js 기반 페이지의 __NEXT_DATA__ JSON을 추출한다.
    (네이버/스마트스토어 계열 페이지에서 비교적 안정적으로 존재하는 편)
    """
    if not page_html:
        return None
    m = re.search(
        r"<script[^>]*id=[\"']__NEXT_DATA__[\"'][^>]*>(.*?)</script>",
        page_html,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if not m:
        return None
    raw = (m.group(1) or "").strip()
    if not raw:
        return None
    try:
        return json.loads(raw)
    except Exception:
        return None


def _extract_next_data_from_page(page) -> Optional[object]:
    """
    Playwright page에서 렌더링 이후의 __NEXT_DATA__를 최대한 안정적으로 추출한다.
    - 1) script#__NEXT_DATA__ textContent
    - 2) window.__NEXT_DATA__
    """
    # 1) DOM에 script 태그가 있는지 먼저 확인
    try:
        raw = page.eval_on_selector("script#__NEXT_DATA__", "el => el.textContent")  # type: ignore[attr-defined]
        raw = (raw or "").strip()
        if raw:
            return json.loads(raw)
    except Exception:
        pass
    # 2) Next.js가 전역에 올려둔 경우
    try:
        return page.evaluate("() => (window.__NEXT_DATA__ || null)")  # type: ignore[attr-defined]
    except Exception:
        return None


def _regex_pick_first_int(text_: str, pattern: str) -> Optional[int]:
    m = re.search(pattern, text_, flags=re.IGNORECASE)
    if not m:
        return None
    try:
        raw = str(m.group(1))
        raw = raw.replace(",", "").replace(" ", "").strip()
        return int(raw)
    except Exception:
        return None


def _regex_pick_first_float(text_: str, pattern: str) -> Optional[float]:
    m = re.search(pattern, text_, flags=re.IGNORECASE)
    if not m:
        return None
    try:
        return float(m.group(1))
    except Exception:
        return None


def _regex_pick_first_date(text_: str, pattern: str) -> Optional[date]:
    """
    정규식으로 날짜 문자열(YYYY.MM.DD 또는 YYYY-MM-DD)을 뽑아 date로 변환한다.
    - group(1)이 날짜 문자열이어야 한다.
    """
    m = re.search(pattern, text_, flags=re.IGNORECASE)
    if not m:
        return None
    raw = str(m.group(1) or "").strip()
    if not raw:
        return None
    s = raw.strip()
    # "2021.10." 같이 끝에 '.'가 붙는 케이스 방어
    while s.endswith(".") or s.endswith("-") or s.endswith("/"):
        s = s[:-1]
    s = s.replace(".", "-").replace("/", "-").strip()
    try:
        # YYYY-MM 형태(일 없음)는 1일로 정규화한다.
        if re.match(r"^\d{4}-\d{2}$", s):
            s = s + "-01"
        # YYYY-MM-DD 또는 YYYY-MM-DDTHH:MM:SS 같은 ISO 일부도 대응
        if "T" in s:
            s = s.split("T", 1)[0]
        d = datetime.strptime(s, "%Y-%m-%d").date()
        # 비정상 범위 방어(오탐/깨진 텍스트)
        if d.year < 1990 or d.year > 2100:
            return None
        return d
    except Exception:
        return None


def _pick_int_near_needle(text_: str, *, needle: str, pattern: str) -> Optional[int]:
    """
    큰 blob(예: __NEXT_DATA__)에서 특정 상품 식별자(needle) 근처의 값을 우선적으로 고른다.
    - 여러 상품이 한 blob에 들어있는 경우(추천/리스트/캐러셀) 오탐을 줄이기 위한 안전장치.
    """
    t = str(text_ or "")
    n = str(needle or "").strip()
    if not t or not n:
        return None
    # needle이 아예 없으면 의미 없음
    if n not in t:
        return None
    # needle 위치들(너무 많아지면 비용↑ → 앞쪽 일부만)
    needle_positions: list[int] = []
    start = 0
    for _ in range(40):
        i = t.find(n, start)
        if i < 0:
            break
        needle_positions.append(i)
        start = i + len(n)
    if not needle_positions:
        return None
    best_val: Optional[int] = None
    best_dist: Optional[int] = None
    for m in re.finditer(pattern, t, flags=re.IGNORECASE):
        try:
            raw = str(m.group(1) or "")
            val = int(raw.replace(",", "").replace(" ", "").strip())
        except Exception:
            continue
        pos = int(m.start())
        # 가장 가까운 needle과의 거리
        dist = min(abs(pos - np) for np in needle_positions)
        if best_dist is None or dist < best_dist:
            best_dist = dist
            best_val = val
    return best_val


def _parse_recent_purchase_badges(text_: str) -> dict:
    """
    상품 상세 페이지에서 잠깐 노출되는 배지 텍스트에서 '최근 구매/재구매' 수치를 추출한다.
    예)
    - "최근 1주간 109명 구매"
    - "최근 3개월간 95명 재구매"

    주의:
    - 노출 항목이 랜덤/일시적일 수 있으므로, 파서는 best-effort다.
    """
    t = str(text_ or "").strip()
    if not t:
        return {
            "purchase_count": None,
            "purchase_window": None,
            "purchase_label": None,
            "repurchase_count": None,
            "repurchase_window": None,
            "repurchase_label": None,
            "matched_texts": [],
        }

    # 공백/줄바꿈 혼합에 강하게
    t2 = re.sub(r"\s+", " ", t)
    # 패턴 A: "최근 {n}{unit}(간) {count}(명/건) (재)구매"
    pat = re.compile(
        r"최근\s*(?P<n>[0-9]+)\s*(?P<unit>일|주(?:간)?|개월)\s*(?:간)?\s*(?P<count>[0-9][0-9,]*)\s*(?:명|건)?\s*(?P<kind>재구매|구매)",
        flags=re.IGNORECASE,
    )
    # 패턴 B(ItemScout 등): "예상판매량(7일) 233건" / "예상판매량(7일) 1,234건"
    pat_itemscout_7d = re.compile(
        r"예상\s*판매\s*량\s*\(\s*(?P<n>[0-9]+)\s*일\s*\)\s*(?P<count>[0-9][0-9,]*)\s*(?:건|명)?",
        flags=re.IGNORECASE,
    )

    purchase_candidates: list[dict] = []
    repurchase_candidates: list[dict] = []
    matched_texts: list[str] = []

    def norm_window(n: int, unit_raw: str) -> str | None:
        u = str(unit_raw or "").lower()
        if "개월" in u:
            return f"{n}m"
        if "주" in u:
            return f"{n * 7}d"
        if "일" in u:
            return f"{n}d"
        return None

    def window_to_days(win: str | None) -> int:
        """
        윈도우 비교를 위한 가중치(작을수록 우선).
        - d(일): 그대로
        - m(개월): 30일 환산(근사)
        """
        s = str(win or "").strip().lower()
        if not s:
            return 10**9
        m = re.match(r"^(\d+)\s*d$", s)
        if m:
            try:
                return int(m.group(1))
            except Exception:
                return 10**9
        m2 = re.match(r"^(\d+)\s*m$", s)
        if m2:
            try:
                return int(m2.group(1)) * 30
            except Exception:
                return 10**9
        return 10**9

    def pick_best(cands: list[dict]) -> tuple[Optional[int], Optional[str], Optional[str]]:
        if not cands:
            return None, None, None
        # "최근 1주" 같은 더 짧은 기간을 우선(연산에 쓰는 '구매'는 특히 중요)
        best = min(
            cands,
            key=lambda x: (
                window_to_days(x.get("window")),
                # 동일 윈도우에서는 count가 큰 것을 우선(표본성 노이즈 완화)
                -(int(x.get("count") or 0)),
            ),
        )
        try:
            cnt = int(best.get("count")) if best.get("count") is not None else None
        except Exception:
            cnt = None
        win = best.get("window")
        lab = best.get("label")
        return cnt, win, lab

    for m in pat.finditer(t2):
        raw = m.group(0).strip()
        matched_texts.append(raw)
        try:
            n = int(m.group("n"))
        except Exception:
            n = 0
        unit = m.group("unit") or ""
        win = norm_window(n, unit)
        try:
            cnt = int(str(m.group("count") or "0").replace(",", ""))
        except Exception:
            cnt = None
        kind = str(m.group("kind") or "")

        if cnt is None:
            continue
        if "재구매" in kind:
            repurchase_candidates.append({"count": cnt, "window": win, "label": raw})
        else:
            purchase_candidates.append({"count": cnt, "window": win, "label": raw})

    # ItemScout(예상판매량(7일) ...)도 "구매(판매)" 후보로 취급한다.
    for m in pat_itemscout_7d.finditer(t2):
        raw = m.group(0).strip()
        matched_texts.append(raw)
        try:
            n = int(m.group("n"))
        except Exception:
            n = 0
        try:
            cnt = int(str(m.group("count") or "0").replace(",", ""))
        except Exception:
            cnt = None
        if cnt is None or cnt < 0:
            continue
        # 7일(또는 n일) 고정 window
        win = f"{max(0, n)}d" if n > 0 else "7d"
        purchase_candidates.append({"count": cnt, "window": win, "label": raw})

    purchase_count, purchase_window, purchase_label = pick_best(purchase_candidates)
    repurchase_count, repurchase_window, repurchase_label = pick_best(repurchase_candidates)

    return {
        "purchase_count": purchase_count,
        "purchase_window": purchase_window,
        "purchase_label": purchase_label,
        "repurchase_count": repurchase_count,
        "repurchase_window": repurchase_window,
        "repurchase_label": repurchase_label,
        "matched_texts": matched_texts,
        # 참고/디버그 및 "다중 윈도우" 지원(필요 시 UI/연산에서 선택 가능)
        "purchase_candidates": purchase_candidates,
        "repurchase_candidates": repurchase_candidates,
    }


def _find_product_jsonld(obj: object) -> Optional[dict]:
    """
    jsonld 객체(또는 리스트)에서 Product 타입을 best-effort로 찾는다.
    """
    if obj is None:
        return None
    if isinstance(obj, dict):
        # @graph 형태
        if "@graph" in obj and isinstance(obj.get("@graph"), list):
            for item in obj.get("@graph") or []:
                found = _find_product_jsonld(item)
                if found:
                    return found
        t = obj.get("@type") or obj.get("['@type']")
        if isinstance(t, list):
            if any(isinstance(x, str) and x.lower() == "product" for x in t):
                return obj
        if isinstance(t, str) and t.lower() == "product":
            return obj
        return None
    if isinstance(obj, list):
        for item in obj:
            found = _find_product_jsonld(item)
            if found:
                return found
    return None


def _scrape_product_page_metrics(
    url: str,
    *,
    search_title: Optional[str] = None,
    search_catalog_id: Optional[str] = None,
) -> dict:
    """
    로그인 없이 접근 가능한 상품 상세 페이지에서, json-ld 기반으로 메타/리뷰/평점 정보를 추출한다.
    """
    global CAPTCHA_SHARED_PAGE
    # Playwright(sync) 호출은 전용 스레드에서만 안전하다.
    # (FastAPI sync endpoint는 threadpool에서 실행되어 스레드가 바뀔 수 있음)
    if _playwright_enabled() and not _pw_in_worker_thread():
        return _pw_call(
            lambda: _scrape_product_page_metrics(
                url,
                search_title=search_title,
                search_catalog_id=search_catalog_id,
            )
        )
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36",
        "Accept-Language": "ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7",
    }
    # Playwright Chromium으로 먼저 시도(브라우저 지문/세션/쿠키 유지)
    # NOTE: "페이지는 정상인데 파싱이 전부 None" 케이스가 있어, 렌더링 이후 __NEXT_DATA__도 함께 읽는다.
    debug: dict = {"mode": None, "cdp": None}
    next_data_obj: Optional[object] = None
    status = None
    body_text_full: str = ""
    html_text: str = ""
    badge = {
        "recent_purchase_count": None,
        "recent_purchase_window": None,
        "recent_purchase_status": None,
        "recent_purchase_7d_count": None,
        "recent_repurchase_count": None,
        "recent_repurchase_window": None,
        "recent_repurchase_3m_count": None,
        "recent_badge_text": None,
        "debug": None,
    }

    def _detect_sales_keys(*, nd: object | None, html: str, body_text: str) -> dict:
        """
        '판매/구매 관련 누적값'이 페이지/NextData에 존재하는지 빠르게 판별한다.
        - 목표: "존재 여부" 우선 확인(계산/저장/추정은 다음 단계)
        """
        candidates = [
            "purchaseCount",
            "totalSaleCount",
            "totalSoldCount",
            "saleCount",
            "orderCount",
            "buyCount",
            "purchaseCnt",
            "soldCount",
            "totalPurchaseCount",
        ]
        present: dict[str, bool] = {k: False for k in candidates}
        values: dict[str, int] = {}

        blob = ""
        src = None
        if nd is not None:
            try:
                blob = json.dumps(nd, ensure_ascii=False)
                src = "next_data"
            except Exception:
                blob = ""
        if not blob:
            blob = (html or "") + "\n" + (body_text or "")
            src = "html"

        if not blob:
            return {"present": present, "values": values, "source": None}

        for k in candidates:
            try:
                if f"\"{k}\"" in blob or k in blob:
                    present[k] = True
                m = re.search(rf"\"{re.escape(k)}\"\\s*:\\s*\"?([0-9][0-9,]*)\"?", blob, flags=re.IGNORECASE)
                if m:
                    values[k] = int(str(m.group(1)).replace(",", ""))
            except Exception:
                continue
        return {"present": present, "values": values, "source": src}

    def _sample_recent_badges_from_page(page_obj) -> tuple[str, dict]:
        """
        '잠깐(1~2초) 노출 후 사라지는' 구매/재구매 배지를 잡기 위해 body.innerText를 짧게 샘플링한다.
        - 최대 약 1.8초 동안 200ms 간격으로 샘플링
        - 구매/재구매 모두 잡히면 조기 종료
        """
        best_text = ""
        # 랜덤 노출 대응: 샘플들을 합쳐 "구매/재구매" 후보 문구를 최대한 많이 모은다.
        merged_matched: list[str] = []
        samples: list[str] = []
        tries = 0
        # NOTE:
        # - 확장프로그램(ItemScout 등) UI는 페이지 로드 이후 "늦게" 렌더될 수 있다.
        # - 짧은 샘플링(<=2~3초)만으로는 놓치는 경우가 있어, 상한을 조금 늘린다.
        # - 조기 종료 조건(구매/재구매 감지 시 break)이 있어, 실제 지연은 보통 훨씬 짧다.
        # 기본 ~3.6초(18회*200ms) + 최대 ~6.0초(30회*200ms)
        max_tries = 30
        for i in range(max_tries):
            tries += 1
            txt = ""
            badge_texts: list[str] = []
            try:
                payload = page_obj.evaluate(  # type: ignore[attr-defined]
                    """() => {
                      try {
                        const texts = [];
                        const els = Array.from(document.querySelectorAll('span, div, p, li'));
                        for (const el of els) {
                          const v = (el && (el.innerText || el.textContent) || '').trim();
                          if (!v) continue;
                          const hasRecent = v.includes('최근') && (v.includes('구매') || v.includes('재구매'));
                          const hasItemscout7d = (v.includes('예상판매량') && v.includes('7')) || (v.includes('예상 판매량') && v.includes('7'));
                          // "최근 구매/재구매" 또는 "예상판매량(7일)" 계열만 수집 후보로 본다.
                          if (!(hasRecent || hasItemscout7d)) continue;
                          // 너무 긴 덩어리는 제외(페이지 전체 텍스트 등)
                          if (v.length > 80) continue;
                          texts.push(v);
                        }
                        // uniq
                        const uniq = [];
                        const seen = new Set();
                        for (const v of texts) {
                          const k = v.replace(/\\s+/g,' ').trim();
                          if (!k) continue;
                          if (seen.has(k)) continue;
                          seen.add(k);
                          uniq.push(k);
                        }
                        return { badges: uniq.slice(0, 10), body: (document.body?.innerText || '').slice(0, 5000) };
                      } catch (e) {
                        return { badges: [], body: '' };
                      }
                    }"""
                )
                if isinstance(payload, dict):
                    bt = payload.get("badges")
                    if isinstance(bt, list):
                        badge_texts = [str(x) for x in bt if str(x).strip()]
                    txt = str(payload.get("body") or "")
            except Exception:
                txt = ""
                badge_texts = []

            # 배지 후보만 우선 파싱, 없으면 body 텍스트로 폴백
            joined = " ".join(badge_texts).strip()
            p = _parse_recent_purchase_badges(joined or txt)

            # 1) 샘플별 결과를 누적(문구 단위)
            for mt in (p.get("matched_texts") or []) if isinstance(p.get("matched_texts"), list) else []:
                s = str(mt or "").strip()
                if s and s not in merged_matched:
                    merged_matched.append(s)

            # 2) 디버그/표기용 best_text는 가장 짧은 배지 후보(joined)를 우선 사용
            if joined and (not best_text or len(joined) < len(best_text)):
                best_text = joined
            elif (not best_text) and txt:
                best_text = txt

            # 샘플은 디버깅용으로 소량만 보관
            if len(samples) < 3:
                if badge_texts:
                    samples.append(" | ".join(badge_texts[:3])[:200])
            # 조기 종료 조건:
            # - 구매/재구매 둘 다 잡혔으면 즉시 종료
            # - 구매가 잡혔으면(핵심) 일정 횟수(>=9) 이후에는 종료(성능/속도 균형)
            try:
                has_purchase = p.get("purchase_count") is not None
                has_repurchase = p.get("repurchase_count") is not None
            except Exception:
                has_purchase = False
                has_repurchase = False
            if has_purchase and has_repurchase:
                break
            if has_purchase and i >= 8:
                break
            try:
                page_obj.wait_for_timeout(200)  # type: ignore[attr-defined]
            except Exception:
                pass
        # 2) 최종 파싱은 "모아둔 문구"를 기반으로 수행한다.
        combined = " ".join(merged_matched).strip()
        parsed = _parse_recent_purchase_badges(combined or best_text)
        out = {
            "parsed": parsed,
            "score": int(parsed.get("purchase_count") is not None) + int(parsed.get("repurchase_count") is not None),
            "tries": tries,
            "samples": samples,
        }
        return best_text, out
